window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_002"]={"n":"胡应麟","dyn":"明","poems":[{"t":"塞上曲八首 其六","f":"七言绝句","c":["平沙一望陇云开，玉笛飞声夜转哀。","万里朔风吹不断，梅花齐落李陵台。"]},{"t":"塞上曲八首 其二","f":"七言绝句","c":["紫电花骢白玉鞭，远从都护出居延。","清秋不辨龙城色，一片黄云瀚海前。"]},{"t":"拟大明铙歌曲十八首 黄河清 其一","f":"古风","c":["黄河清，圣人出。","应昌期，诞至德。","著戎衣，奋三尺。","靖四方，建都邑。","干戈偃，弧矢戢。","统九有，主社稷。","神与鬼，咸受职。","烽烟扫，爝火熄。","维大明，照中国。","万千祀，与天一。"]},{"t":"拟大明铙歌曲十八首 其二 凤之翔","f":"古风","c":["凤之翔，在濠梁。","义师起，帝网张。","二十四将驱天狼，兵锋所指定四方。","薄海内外以莫不来王，威加六合返旧疆。","徵歌悉发诸儿郎，复彼人民世世无有所与为我沐与汤。","击筑大风云飞扬，千秋万岁乐未央。"]},{"t":"拟大明铙歌曲十八首 其三 揽群雄","f":"古风","c":["揽群雄，盗如猬。","大圣握符起淮汭，与神为谋蓄锋锐，提三尺剑驱海内。","驱海内，揽群雄。","真人出，天下同。","四方六合咸景从，如风从虎云从龙。","汛扫大漠如飞蓬，扶桑曈曈朝日红。","驱海内，揽群雄。"]},{"t":"拟大明铙歌曲十八首 其四 克建业","f":"古风","c":["克建业，定皇畿。","皇畿定，举义旗。","天兵百万任所之。","东吴南汉西蜀七闽六诏从风靡。","天下大定一戎衣。"]},{"t":"拟大明铙歌曲十八首 其五 婺归德","f":"七言古诗","c":["天兵十万下东国，婺以先宁驻皇跸。","景星荧荧耀城邑，我战则胜攻则克。","四海从风靡弗一，势如破竹烽燧息。","天命曷归归有德。"]},{"t":"拟大明铙歌曲十八首 其六 四友","f":"古风","c":["于维文王，是亲四友。","疏附后先，以翼元首。","峨峨高踪，异代曷有。","天威是临，匍匐奔走。","猗与圣祖，广延群雄。","如天如海，为万物宗。","王师所向，六合景从。","爰率车徒，以定浙东。","浙东底平，大统未集。","蚤作暮思，思布文德。","曰基曰濂，曰琛曰溢。","玄纁奕奕，交布东国。","曰四先生，论道经邦。","坐而弗名，匡朕弗遑。","呜呼盛节，庆流无疆。","德六五帝，功百三王。"]},{"t":"拟大明铙歌曲十八首 其七 战鄱阳","f":"古风","c":["明日大战战鄱阳，简师料徒百万强。","烈风吹沙湖水扬，烟焰涨天焚大航。","三十六将死康郎，再战湖口歼馀皇。","我舟胶沙敌尚强，疾呼奋臂来冲撞。","鲸鲵蔽空云日黄，拍江巨浪何茫茫，如血钜鹿尸昆阳。","维天命我明，车轮碎螳螂。","百矢定边背若芒，一矢贯睛谅死亡。","谅死亡，理出降。","威加四海，莫不来王。"]},{"t":"拟大明铙歌曲十八首 其八 盘门入","f":"古风","c":["盘门入，士诚泣。","前歌后舞大师集，兵不血刃下城邑。","谁其帅者公魏国，归市弗止廛弗易。","万姓欢呼颂皇德，二敌既歼皇之土东极。","沧溟南亘楚长驱，入中原孰敢余阻。"]},{"t":"拟大明铙歌曲十八首 其九 降谷珍","f":"古风","c":["方谷珍，起盗薮。","乘元之乱，窃据一方地如斗。","耗金币，大官酒。","海上时时飞且走，如鬼如蜮鸡与狗。","大明当空烛九有，举宗乞命窜海口。","帝悯其愚印加肘，以较群雄最小丑。"]},{"t":"拟大明铙歌曲十八首 其十 七闽","f":"五言古诗","c":["七闽保岩阻，连亘皆山梁。","友定据其巢，负固如金汤。","我皇命将谕，谕以开茅疆。","自谓故元臣，负义不肯降。","王师十万下，戈船逐长江。","兵入如破竹，如虎吞群羊。","委身系尺组，支体磔分张。","自谓故元臣，守节甘丧亡。","大都以沦覆，谁为招国殇。"]},{"t":"拟大明铙歌曲十八首 其十一 维中国","f":"古风","c":["维中国，帝王所自立。","欃枪遍郊原，天地黯无色。","天重开，地重辟。","扶桑荧荧日月出。","照八荒，烂九域。","芟夷祸难四海一。","神龙夹助正统集。","帝悯边尘扰中国。","诏下大将军，达副将军遇春提兵九十六万，戈鋋甲胄如浮云。","命词臣濂草檄谕彼中华民。","长驱入河洛，壶浆箪食来成群。"]},{"t":"拟大明铙歌曲十八首 其十二 大都走","f":"古风","c":["元都平，四海清。","神鬼受职万方庭。","列大藩，置神京。","汛扫烽烟混一区寓，再造华夏开文明。"]},{"t":"拟大明铙歌曲十八首 其十三 库库","f":"古风","c":["察罕起元末，举代推鹰扬。","天命去胜国，剚刃争战场。","维库库，察罕子复良。","下益都，伐洮阳。","驱兵出没观以望。","帝三谕，弥陆梁。","执囚我行人，怒臂如螳螂。","命大将，统武骁。","北征陇右一战捣其巢。","捣其巢，万骑突至如风飙。","赖傅颍公却前茅。","两军就舍不得交。","夜分劫营，足纳一靴身骑骟马逃。","骟马逃，绝大漠。","我军四十万，胜负互相角。","巨网漏吞舟，竟死蕃部落。","帝称好男子，维库库。"]},{"t":"拟大明铙歌曲十八首 其十四 升面缚","f":"古风","c":["升面缚，出成都。","母子哑哑啼路途。","父旻玉珍一目枯。","贪饕乱亡起雄图。","不久身殉留遗孤。","大明区寓至化敷。","屡使遣谕如追逋。","犷兵悍将骄相扶。","骄相扶，守瞿塘。","帝命颍国公东瓯王。","伐山通道开战场。","直捣阶文溃腹心，腹心溃，肝胆亡。","母子舆榇大道旁。","升也肉袒仍牵羊。","侯以归义戒杀降。","高皇帝德洪虞唐。","唐高宋武如豺狼。"]},{"t":"拟大明铙歌曲十八首 其十五 北征","f":"古风","c":["明受命，海宇一。","前元馀属负固北庭保其宅。","团结党类以俟我衅隙，为我子孙慝。","皇帝遐思勿姑息。","乃眷西顾以北征。","桓桓大将，统兵亿万犁其庭。","犁其庭，心胆落。","单于遁，绝大漠。"]},{"t":"拟大明铙歌曲十八首 其十六 纳噶楚","f":"古风","c":["纳噶楚，居金山。","二十馀万众，虎视一何眈眈。","帝命上公冯，统兵出全燕。","天威所震慑，敌骑不敢驰，敌弓不敢弯。","二十馀万众，一时赴长安。","摐金伐鼓壮士欢，筑三受降玉门关。"]},{"t":"拟大明铙歌曲十八首 其十七 六诏","f":"古风","c":["六诏天西南，惟滇号最钜。","残元历数尽，遗孽犹虎踞。","帝悯绝塞民，使命驰风尘。","彼昏不奉诏，虔刘我信臣。","皇赫斯怒命黔宁，艨艟巨舶浮昆明。","昆明水涸歼长鲸，碧鸡金马入我版图四海平。"]},{"t":"拟大明铙歌曲十八首 其十八 受天命","f":"古风","c":["受天命，定四方。","干戈偃，鈇钺藏。","轶大武，驾成汤。","媲轩辕，俪虞唐。","扩地万里居中央。","整齐万国开明堂。","汉唐宋晋隋诸邦。","絜功比德如蜩螗。","万八千岁永无疆。"]},{"t":"汉铙歌十八首 其一 朱鹭","f":"古风","c":["朱鹭下，汉道昌。","一双羽翮云中合沓而飞翔。","合沓而飞翔，在我庭户。","以建华鼓导大辂。","鱼鱼雅雅，诧彼行路。","朝食沆瀣，夜濯风以露。","应期出世所慕。","五帝三皇巍巍福我祚。"]},{"t":"汉铙歌十八首 其二 艾如张","f":"古风","c":["艾如张，张四维。","击高钲，悬大旗。","戈鋋甲胄光陆离。","千灵从，七校移。","虞人杂沓冠以皮。","臂苍走黄当路岐。","南山有虎豹北山，鹿麋狐兔若丘山，缩足不敢驰。","我欲上天，天门九重。","我欲入渊，血肉喂蛟鱼龙。","王者合三驱，百兽一一归我樊笼。","不见青冥，冥冥者鸿。","耸六翮，乘长风。","游赤霄，入无穷。","虽有矰缴罗网将安庸。"]},{"t":"汉铙歌十八首 其三 思悲翁","f":"古风","c":["思悲翁，气结不能言。","儿长翁为娶妇，思得奉晨昏，白头以团栾。","妇恶如豺狼，入门作灾患。","牝翼鸣前庭，举室怆以烦。","知交各各缩舌，亲戚断往还。","我有壶浆，翁饥不得餐。","我有裳衣，翁体不得完。","思悲翁，气结不能言。","我欲诉上帝，天门九重入以难。","我欲诉司命，司命徘徊以盘桓。","念欲以高飞，无羽翰以负翁去。","体毛何摧残，不若城上乌反哺。","翁残年，思悲翁，气结不能言。","安得天雨雹，霹雳震长夏。","雷霆半空下，永永戒来者。"]},{"t":"汉铙歌十八首 其四 翁离","f":"古风","c":["翁离趾中可筑室，何用葺之桂若兰。","翁离趾中可筑宫，何用涂之椒以檀。","修竹夹广除，一何檀栾。","千乘万骑缤纷哉，往以还。","左长杨，右甘泉。","汾阴后，泰畤前。","黄鹄高飞极云天。","词臣献赋陛下之寿三千年。"]},{"t":"汉铙歌十八首 其五 上之回","f":"古风","c":["上之回，祀甘泉。","金支飏，翠旄旋。","雨师后，风伯前。","鼓钟管吹，声何填骈。","东达扶桑，南逮于阗。","西径流沙，北讫祈连。","天出景星，地产醴泉。","报庆成，致精虔。","肃雍哉，怆以严。","五帝三皇，享亿万斯年。"]},{"t":"汉铙歌十八首 其六 战城南","f":"古风","c":["战城南，日无色。","壮士长征死，愿作乌鸢食。","请谓乌与鸢：“壮士死，国家委。","身丧其元，汝食其肉，一胡忍且残。","世有大豪元恶巨奸，杀公吏，探赤丸，暴戾恣睢脍人肝。","一旦祸机发，横尸道旁，血如流泉，腐肉如丘山。","汝胡不食，甘此忍且残。","”请为乌与鸢答君子：“言世有大豪元恶巨奸，司命不敢录，司败不敢拘，司隶不敢纠弹。","十九老死牖下，子孙贵盛，冢墓象祈连。","彼虽有肉血，我安得餐。","壮士不自惜，委身徇国家，丧其元，我固当得食，彼复何言。","”"]},{"t":"汉铙歌十八首 其七 巫山高","f":"古风","c":["巫山高，高望不可极。","日月蔽亏云雨出。","入有美一人，曰维神女。","朝为行云，暮为行雨。","泠然入余梦，贻我以翠羽。","郁陶乎，余心将以畴语。","将舍余国都，以往从女。","朝朝暮暮，为云为雨。"]},{"t":"汉铙歌十八首 其八 上陵","f":"古风","c":["上陵一何崔嵬。","宫殿若云屯，观者为徘徊。","门有车马客，驾言上陵回。","千乘万骑，宵行烈风雷。","我欲遐征，憩望金银台。","封泰山，禅梁父，登日观，观蓬莱。","蓬莱东，见朝旭。","芝草丛生，醴泉满谷。","七十二家著编录。"]},{"t":"汉铙歌十八首 其九 将进酒","f":"古风","c":["将进酒，乘乘黄。","列鼓吹，呜笙簧。","齐姜楚姬列两傍。","卫女秦娥左右以成行。","挟安陵，戏龙阳。","拥长剑，佩琳琅。","缤哉纷，盈高堂。","烹大彘，炙肥羊。","五音和，八珍良。","天瓢甘露臣以尝。","千秋百岁逍遥以徜徉。"]},{"t":"汉铙歌十八首 其十 有所思","f":"古风","c":["有所思，思美人，美人渺何许，大海天东南。","曷不往从彼游，路途险且艰。","弱水不容舟，三山郁㠝岏。","宫阙冠巨鳌，遥遥极青天。","美人在其上，三山高以寒。","我为钓巨鳌，截竹为长竿。","持竿坐沧海，大水何漫漫。","巨鳌牵不动，但见一双鲤鱼遥堕青云端。","呼童剖此鲤，中有美人尺素翰。","前有长相思，后有劝加餐。","徘徊感此意，踯躅不能言。"]},{"t":"汉铙歌十八首 其十一 雉子斑","f":"古风","c":["雉子斑，雉子斑，一雄一雌，抱子田野边。","雄飞摩天去不还，孤雌养雏寄草间。","养雏寄草间，乳哺一何艰。","夜不遑寝，昼不及餐。","毛羽既长成，五色丽且鲜。","一鸣举世惊，一飞上冲天。","回头顾视我母，六翮何阑珊。","老病倏已至，恹恹向重渊。","有子不得养，恸哭摧心肝。","有子不得养，恸哭摧心肝。"]},{"t":"汉铙歌十八首 其十二 君马黄","f":"古风","c":["君马黄，臣马苍。","飞轩蹀躞大道旁。","旁人顾见臣马，以莫不谓良。","一朝中涓下明堂。","君马入天闲，意气何扬扬。","臣马老伏枥，伶俜瘦骨，朝逐水草，暮逐斜阳。","背负盐车，以西上太行。","路逢伯乐造父王良。","停车振策，为我彷徨。","念欲剪拂我，以登明堂。","嗟筋力已尽，莫能腾骧。","长鸣短号，断绝中肠。"]},{"t":"汉铙歌十八首 其十三 芳树","f":"古风","c":["芳树芳树，扬春华，结秋实，东风历乱而飞扬。","容色在朝夕，美人坐高堂。","兀兀愁蛾眉，君心为他人，冶艳能几时。","春华讵能久，秋实那可期。","普天之下，悠悠畴非轻薄儿。","班姬与陈后，解事一何迟。","黄金买词赋，徒为世主疑。","不见芳树枝，荣瘁各有时。","端居任大化，何用戚戚颦蛾眉。"]},{"t":"汉铙歌十八首 其十四 圣人出","f":"古风","c":["圣人出，明光宫，万乘千骑升回中。","望祀天地，禋于六宗。","百神来享，以莫不肃雍。","肃肃雍雍，四方同风。","唐虞之世，比屋皆可封。","浩浩大化，与天地无终。"]},{"t":"汉铙歌十八首 其十五 上邪","f":"古风","c":["上邪，我与君输肝委膈，他人那得闻。","急难各相护救，决绝妻子如浮云。","中心耿耿金石，百年以为邻。","巢由抚六合，尧舜下阊阖。","山崩石烂河枮海水竭，十日并出天地裂，我与君，好永不绝。"]},{"t":"汉铙歌十八首 其十六 临高台","f":"古风","c":["临高台，望长安。","飞甍画楝嵯峨峭崒而㠝岏。","苍龙九斿限重关。","我欲谒天阍，一觐上帝颜。","手持长生药，以奉心所欢。","上帝肯听臣，亿万千斯年。","苍龙九斿限重关。","限重关，使我欲进心茫然。","临高台，望长安。","抚膺三叹行路难。"]},{"t":"汉铙歌十八首 其十七 远如期","f":"楚辞体","c":["远如期，游四方。","北碣石，南潇湘。","西太华，东扶桑。","凿混沌窍燕中央。","饮则食兮乐而康。","以寻列仙拾金光。","飞翔八极行七襄。","驰驱绝冥观大荒。","千秋万祀寿未央。","男儿堕地桑弧蓬矢射四方。","安得老死一丘，局促若辕下驹守故乡。"]},{"t":"汉铙歌十八首 其十八 石流","f":"楚辞体","c":["石流，南山有石，北涧有流。","石何齿齿，流何汤汤。","石以枕我，流以漱我肠。","幽兰哉，夹岸芬以芳。","芬以芳，顺风扬。","彼美人兮天一方。","安得寄此永永长相望。"]},{"t":"补蜀汉铙歌十二首 其一 帝车见","f":"古风","c":["帝车见，涿鹿墟。","童童立，五丈馀。","千灵卫，七圣趋。","飏金支，翼翠旟。","雨师道，风伯驱。","气如龙，殷里闾。","真人起，握斗枢。","奠汉鼎，抚皇舆。","炎精曜，火德嘘。","亿万载，帝方隅。"]},{"t":"补蜀汉铙歌十二首 其二 顾隆中","f":"古风","c":["顾隆中，一顾再顾三顾何从容。","千秋载睹明扬风。","君臣契合鱼水同。","莘野币交汤匪躬。","渭川一见罗非熊。","何如三顾勤隆中。","惜哉炎烬嘘残虹。","创业未半中道终。","三分鼎足宁称雄。"]},{"t":"补蜀汉铙歌十二首 其三 克老瞒","f":"古风","c":["克老瞒，厥功不可量。","瞒挟天子令四方。","以暴如虎贪如狼。","既定荆州下长江。","并兵八十三万强。","凶威所指横以张。","所触者碎当者亡。","遣军师亮谕孙权。","权奉命，发兵助我屯江干。","桓桓烈炬战舰轰，将士大呼冲敌坚。","贼兵百万尸如山。","操走乌林四海安。"]},{"t":"补蜀汉铙歌十二首 其四 权进妹","f":"古风","c":["权进妹，托同仇。","外戚内疏谐孙刘。","包藏祸心蓄愆尤。","床帷甲第图淹留。","戈鋋矛戟纷相求。","帝握大机与神游。","与神游，众叵测。","刘郎欢，孙郎泣。","周郎唇乾口燥呼不得。","以头抢地长太息。","千秋齿冷笑吴国。"]},{"t":"补蜀汉铙歌十二首 其五 定两川","f":"古风","c":["定两川，皇图赫赫帝业安。","成都破竹万姓欢。","壶浆夹道食以箪。","西指定军夺前山。","夏侯来争馘斩渊。","馘斩渊，众大崩，合也弃马亡心魂。","操慑首鼠抱头奔。","抱头奔，两川一顺，天应人即。","皇帝位新万国。"]},{"t":"补蜀汉铙歌十二首 其六 讨汉贼","f":"古风","c":["讨汉贼，屯猇亭。","屯猇亭，皇赫斯怒以亲征。","嗟关侯，率众围樊城。","七军夜渰师徒崩。","操慑大威如雷霆。","贼权惴惴怖且惊。","怖且惊，谋吕蒙。","逞虐焰，乘奸凶。","为鬼为蜮蠛与蠓。","遂亡荆州丧大功。","踰月蒙死尸流虫。","皇赫斯怒离巴中。","离巴中，以亲征。","破秭归，震夷陵。","蒙贼既死，逊贼复兴。","嗟嗟昊穹，汉事坏垂成。"]},{"t":"补蜀汉铙歌十二首 其七 渡泸","f":"古风","c":["渡泸师徒一何劳。","五月盛暑深入不毛。","托孤寄命，予惟伊咎陶。","劳实在予，予曷敢逃。","五月盛暑深入不毛。","获彼大酋以令群豪。","七纵七擒，俾返其巢。","众慑天威，永戴大朝。","振旅而还，徒御弗号。","雍雍旆旌，肃肃羽旄。","文德诞敷，爰格有苗。","千秋两阶，载睹唐尧。"]},{"t":"补蜀汉铙歌十二首 其八 祁山","f":"古风","c":["祁山出，汉贼惊。","创业未半先帝崩。","丞相匪躬夜弗宁。","上表师师东乡征。","卒徒十万如风霆。","潜张箕谷为疑兵。","身率大众屯街亭。","三郡响答如流星。","惜哉马谡毁垂成。","毁垂成，载出军。","王双枭，郭淮遁。","拔武都阴，平魏大震。"]},{"t":"补蜀汉铙歌十二首 其九 馘张合","f":"古风","c":["馘张合，在卤城。","蜀人欢忻魏震惊。","魏兵百万乘蜀营。","司马披甲仍先登。","我师一出歼长鲸。","卒徒贾勇懿大奔，积甲三千若丘陵。","司马匍匐亡旄旌。","贼徒合，追木门。","万弩射合褫合魂。","馘之不异鸡与豚。","桓桓八阵孰敢婴。","所当者破击者平。","如汤如武，天下无敌十一征。"]},{"t":"补蜀汉铙歌十二首 其十 蜀如虎","f":"古风","c":["蜀如虎，师甚武。","熊罴十万下天府。","仁义礼乐为盾橹。","奸雄闭穴气销沮。","甘受巾帼呼老姥。","嗟嗟，懿如鼠，亮如龙，蜀如虎。"]},{"t":"补蜀汉铙歌十二首 其十一 五丈原","f":"古风","c":["五丈原，驻三师。","三代以还仅睹兹。","滨渭杂耕军无私。","刍粮百万饶馀赀。","中原克复功须斯。","功须斯，定关洛。","灭魏斩睿枭懿殛。","权混一，四海兴礼乐。"]},{"t":"补蜀汉铙歌十二首 其十二 馀威慑","f":"古风","c":["馀威慑，走仲达。","胡天弗吊丧诸葛。","大星煌煌殒天末。","我师反旆丧不发。","魏人欢呼夜来蹑。","鸣金展帜雷电掣。","懿也狼奔胆欲裂。","千秋壮士赞诸葛。","死诸葛走生仲达。"]},{"t":"拟汉郊祀歌十九首 其一 练时日","f":"古风","c":["练时日，候阴阳。","郊圆丘，祀明堂。","焄哉蒿，荐上帝。","灵来思，思弗替。","灵之驾，六飞龙。","天门开，詄九重。","灵之旟，翼神鱼。","乘罡风，载行厨。","灵之裳，曳三光。","烂虹霓，象玄黄。","灵之佩，建苍玉。","锵太虚，答穷谷。","灵之下，赴阊阖。","洋洋如，走六合。","灵之歆，稷用登。","告特牲，报维馨。","灵之留，驻苍虬。","纷万舞，结绸缪。","灵之往，遗肸蚃。","俨若思，企馀想。","奏咸池，舞韶箾。","缤纷哉，灵之乐。","臣八荒，驭九夷。","岁千亿，灵之贻。"]},{"t":"拟汉郊祀歌十九首 其二 帝临","f":"古风","c":["帝临中央，以运四方。","苞孕万汇，协和三光。","厥服载黄，厥数载五。","克配上帝，维我后土。","皇皇后土，德周遍咸。","百谷告成，大有斯年。"]},{"t":"拟汉郊祀歌十九首 其三 青阳","f":"古风","c":["青阳载临，万物敷荣。","勾萌甲坼，惷动含灵。","雷乃发声，云行雨施。","大造之仁，品汇华滋。","跂行喙息，繄以畴息。","东皇太乙，莫匪尔德。"]},{"t":"拟汉郊祀歌十九首 其四 朱明","f":"古风","c":["朱明烨烨，品汇嘉悦。","鲜洁齐均，以莫不达。","祝融司造，薰风维时。","皇人法天，南面象离。","万物相见，茂昭大夏。","昭告昊穹，百神来下。"]},{"t":"拟汉郊祀歌十九首 其五 西颢","f":"古风","c":["西颢金方，蓐收是秉。","卉木变衰，霜露凄紧。","既蓘既穮，我稼我苗。","实颖告成，硕彼东郊。","爰馨黍稷，殷荐上帝。","于亿千年，永矢弗替。"]},{"t":"拟汉郊祀歌十九首 其六 玄冥","f":"古风","c":["玄冥水伯，载司寒冱。","殒霜杀草，昆虫闭户。","北风宵厉，飞霰昼零。","木脱水涸，雷蛰无声。","岁运既徂，阳和在候。","万宝既成，敢告明后。"]},{"t":"拟汉郊祀歌十九首 其七 维泰元","f":"古风","c":["于维泰元，象帝之先。","纲纪三才，遍周八埏。","皇皇天地，畴阖畴辟。","于维泰元，潜运无极。","风雨雷露，维日月星。","咸若其时，克顺克成。","胎卵湿化，生育孳遂。","灭除灾凶，增长福艾。","四序既宜，八表既安。","孰司其柄，于维泰元。","嘉牲烨烨，陶匏涓洁。","聿来骏奔，灵爽斯达。","以莫不虔，以莫不馨。","元化絪缊，泰阶底平。"]},{"t":"拟汉郊祀歌十九首 其八 天地","f":"楚辞体","c":["维天维地，协尊并巨。","嘏余一人，六合和豫。","皇皇斋宫，穆与神通。","臣邻景从，肃肃雍雍。","报圜丘兮祀后土。","千童罗列讴且舞。","曳击笙镛鸣琳球。","神如有知俨来游。","大小诸秩，咸敬厥职。","整齐服章，骏奔翼翼。","群公秉德，毋怠毋忽。","大君恭默，式于列辟。","降天神兮下地祗。","朱雀为驾苍龙旗。","勾陈前导屏翳驰。","长剑幼艾纷陆离。","流商刻羽歌咸池。","神飙击毂河宿移。","箫韶九成凤来仪。","皇人万寿登维祺。"]},{"t":"拟汉郊祀歌十九首 其九 日出入","f":"古风","c":["日出入，旸谷扶桑间，一何迅且疾。","百年若电光，四序如风飘。","祝融驱火轮，蓐收乘斗杓。","羲和掣神鞭，玄冥扇狂飙。","安得驾六龙，游遨遍八极。","长生不复死，永永天地毕。"]},{"t":"拟汉郊祀歌十九首 其十 天马","f":"古风","c":["天马徕，自渥洼。","度月支，径流沙。","天马徕，以蹀躞。","骨权奇，汗维血。","天马来，骥为友。","丧骊黄，牝与牡。","天马来，蹑浮云。","日千里，空而群。","天马来，服帝闲。","从法驾，鸣和鸾。","天马来，兆有德。","瑞万方，景四国。"]},{"t":"拟汉郊祀歌十九首 其十一 天门","f":"楚辞体","c":["天门开，辟九重。","上帝居，百灵从。","瑶为台，璇为室。","枢紫贝，牖金碧。","吐望舒，宅曜灵。","建雷鼓，树霓旌。","左苍龙，右白虎。","守飞廉，卫玄武。","灵光被，六合周。","烛万景，洞九幽。","励精诚，荐嘉藻。","永如期，锡难老。","灵烂烂兮载扬光。","清飙激云下羽?。","牵牛织女行七襄。","蛾眉稚齿纷君堂。","灵目成兮悦而康。","合柷敔兮陈笙簧。","天门呀然豁扶桑。","双翼乘风朝紫皇。","揖西王母携东方。","食蟠桃实乘乘黄。","周历八纮度九域。","吐纳真精戏无极。"]},{"t":"拟汉郊祀歌十九首 其十二 景星","f":"古风","c":["景星见祠，神鼎载出。","煌煌赤文，以播有德。","经纬虹霓，屈蟠蛟螭。","魑魅魍魉，莫能逢之。","我鼎爰获，我号爰建。","以祀汾阴，光我大汉。","巍巍夏后，锡此实劳。","阅历商周，肇见我郊。","敢告上穹，肆逮下土。","作乐象成，百兽率舞。","享帝享亲，以莫弗歆。","甘露是凝，昭我万龄。"]},{"t":"拟汉郊祀歌十九首 其十三 后皇","f":"古风","c":["后皇降休，介我景福。","以玄以黄，黼黻章服。","靡迩弗洽，靡远弗蒙。","亿万兆庶，视此成功。"]},{"t":"拟汉郊祀歌十九首 其十四 斋房","f":"古风","c":["斋房三秀，柯叶九茎。","煜煜皇皇，太和是蒸。","亭云烂霞，嘘日月精。","句曲之天，金液玉英。","羽驾罡风，八翼上征。","春曲灵苗，维王国祯。","于铄我皇，祀亿万徵。"]},{"t":"拟汉郊祀歌十九首 其十五 华烨烨","f":"古风","c":["华烨烨，黍载馨。","延庶旄，驻翠旌。","神之来，七圣俱。","虹为马，蜺为车。","神之来，百灵萃。","风为裳，水为佩。","神之来，荐嘉豆。","八珍辐，众芳辏。","神之来，肆长筵。","雷大鼓，鸣钧天。","何以休，神之留。","赤凤至，黄麟游。","何以豫，神将遇。","庆云见，甘雨澍。","蹻鹿卢，綦星辰。","佐昊穹，佑下民。","酌斗杓，和沆瀣。","揄长蛾，拥幼艾。","日驰精，月扬光。","烂昭昭，乐未央。","昆崙墟，瀛海澨。","以余归，浩无际。"]},{"t":"拟汉郊祀歌十九首 其十六 五神","f":"古风","c":["维五神，五岳精。","德盛大，包群灵。","佐东皇，赞太乙。","报圭璋，达琮璧。","奠桂醑，以椒浆。","牲肥腯，韨斯皇。","女巫进，姹以丽。","回云旓，驻霞帜。","神偃仰，以徘徊。","历明堂，升帝台。","维光华，嘏大汉。","年岁登，永嘉荐。"]},{"t":"拟汉郊祀歌十九首 其十七 朝陇首","f":"古风","c":["朝陇首，游白麟。","显光华，辅一人。","灵昭昭，庆万国。","肇皇仁，祗帝德。","八蛮共，四夷王。","毋怠荒，纳嘉祥。","嬉余薮，服余辂。","浴和风，沐廿露。","左苍龙，右紫鸾。","文狸后，赤豹前。","图尔形，辑尔瑞。","五千历，视兹岁。"]},{"t":"拟汉郊祀歌十九首 其十八 象载瑜","f":"古风","c":["象载瑜，粲六牙。","至万里，自流沙。","入天闲，服舆皂。","扈法驾，彰大造。","翩翩哉，赤鸿来。","超虞罗，翔玉台。","翮五文，丽以鲜。","衔灵芝，咽醴泉。","兆嘉祥，禔景福。","八荒来，四夷服。"]},{"t":"拟汉郊祀歌十九首 其十九 赤蛟","f":"古风","c":["赤蛟下，苍龙游。","灵已醉，不可留。","赤蛟翔，彩虹驭。","灵欲归，不可驻。","灵之逝，观玉台。","戏阆风，宴蓬莱。","灵之升，上无极。","挟宇宙，傍日月。","灵般般，亦享余。","下神雀，降天厨。","灵殷殷，肆余佑。","亿万祀，永以寿。"]},{"t":"蒲梢歌","f":"楚辞体","c":["天马来兮涉玉门。","服天闲兮朝至尊。","驾余车兮上昆崙。","阅万国兮超乾坤。"]},{"t":"太乙歌","f":"楚辞体","c":["贡骅骝兮自太乙。","若灭没兮亡其一。","以龙为驹麟为匹。","历块万里昭帝德。"]},{"t":"灵芝歌","f":"楚辞体","c":["孕三秀兮毓灵芽。","承月精兮映日华。","烂辉光兮发云霞。","服紫茎兮咽胡麻。","乘赤霄兮上无涯。"]},{"t":"琴操十一首 其一 龟山操","f":"楚辞体","c":["龟之峻嶒兮望鲁之疆。","龟之凭陵兮蔽鲁之邦。","迟迟余行兮载贽于筐。","余怀以怦怦兮胡为去父母之乡。"]},{"t":"琴操十一首 其二 猗兰操","f":"古风","c":["汎汎崇兰，在彼空谷。","以芬以芳，达于平陆。","达于平陆，大国之香。","薄言掇之，以遗明王。","以遗明王，畴适逢世。","岁月行暮，芬芳将逝。","芬芳爰逝，羌不可留。","忡忡我心，曷维其忧。"]},{"t":"琴操十一首 其三 履霜操","f":"楚辞体","c":["嗟嗟皇考，放余于野兮。","凛凛严霜，雨雪交下兮。","雨雪交下，夐弗可留兮。","念欲自明，我维君忧兮。","我维君忧，逝将安适兮。","世岂有兹，无父之域兮。","无父之域，余曷以居兮。","茕茕上天，罪实在子兮。"]},{"t":"琴操十一首 其四 残形操","f":"楚辞体","c":["梦之憧憧兮，厥形维狸。","形之蛩蛩兮，胡首则遗。","茫茫吉凶兮，畴尅我期。","皇皇昊穹兮，庸豁我疑。","雉朝飞，雉雊于田号，维雌则随。","暮而无妃兮，入而安归。","忧心怦怦兮，将以告谁。","援琴而歌兮，以写我悲。"]},{"t":"琴操十一首 其五 采芝操","f":"古风","c":["煌煌紫芝，三秀五茎。","郁郁崇冈，巃嵷眇冥。","爰卧其巅，爰掇其英。","颜色丽鲜，以敷以荣。","身轻翼舒，游六合外。","驷马高盖，翳以畴赖。","巢哉由哉，寤言弗猜。","唐哉虞哉，亦已焉哉。"]},{"t":"琴操十一首 其六 秦女操","f":"楚辞体","c":["縠之襜襜兮，可裂而朽兮。","屏之岩岩兮，可越而走兮。","剑之巉巉兮，可捍匕首兮。"]},{"t":"琴操十一首 其七 八公操","f":"楚辞体","c":["煌煌八公下帝庭兮。","贻我大药登遐龄兮。","婴儿姹女相和鸣兮。","飞翔九垓羽翼成兮。","金支翠旂夹路迎兮。","万年不死居曾城兮。","俯视六合徒营营兮。","朝生夕枯如蠓螟兮。"]},{"t":"琴操十一首 其八 思归引","f":"楚辞体","c":["维鹿有由兮。","维鸠有仇兮。","尔徒余囚。","余宁尔留兮。"]},{"t":"琴操十一首 其九 别鹤操","f":"楚辞体","c":["羽翼双飞兮，中道当乖。","汝翔安适兮，余居曷谐。","彼忮则害兮，为家庭灾。","汝淑则慧兮，曷明余怀。"]},{"t":"琴操十一首 其十 牝晨操","f":"楚辞体","c":["维牝无晨兮。","尔胡以鸣兮。","维尔之鸣兮。","家胡以宁兮。","牝兮鸣兮。","鸣兮晨兮。","家兮庭兮。","怦兮营兮。","雷兮霆兮。"]},{"t":"琴操十一首 其十一 王子乔","f":"古风","c":["王子乔，玉笙霞佩长飘飖。","王子乔，玉笙霞佩长飘飖。","下游来，王子乔。","缑山万桃花，白日行逍遥。","倏忽上浮云，腾身还九霄。","足蹑一双凫，虚空以游遨。","顾视世间人，勿复劳相招。","蓬莱之水清且浅，金银楼殿一何岧峣。","三神之山连巨鳌。","仙圣亿万计，骖鸾跨凤纷纷而来朝。","苍龙为我车，乌鹊为我桥。","道逢王方平，拍手弹云璈。","麻姑十八九，红颜发垂腰。","要我擘麟脯，进药长生瓢。","顾视世间人，勿复劳相招。","今上神圣，海晏河清，曷不跨双凫，来觐汉家朝。","凝图奉箓，寿与天迢遥。","下游来，王子乔。"]},{"t":"桂之树","f":"古风","c":["桂之树，桂之树，轮囷偃蹇，寂寞山之阿。","山阿者谁，被薜荔，带女萝。","淹留桂树枝以婆娑。","以婆娑，岁月冉冉而蹉跎。","攀援桂树枝行且歌。","瞻彼桐柏之山，桂树丛生其上高嵯峨。","高嵯峨，吾欲采其实，荫其叶，憩其柯。","白日将暮，熊罴虎狼夹路当奈何。","白日将暮，熊罴虎狼夹路当柰何。"]},{"t":"猛虎行","f":"古风","c":["南山有猛虎，白额斑斓而锦文。","南山有猛虎，白额斑斓而锦文。","目睛铄雷电，齿牙决浮云。","出入乘风飙，威加百兽，熊罴豺狼狐兔，惕息莫敢与共群。","山头绝樵采，山底无四邻。","终朝攫取行旅食黎氓。","妇女小儿骨骸若丘山。","腥秽不忍闻。","谓虎汝胡不仁。","胡不学彼驺虞凤与麟。","百兽有恒食，胡汝好食人。","汝胡太不仁，吾将上诉汝，诉汝司命君。","唶司命君，不汝罪傅。","汝角张，汝翼砺。","汝爪距锋以锐。","俾汝飞而食，食人万里外。","食人以足，天道好还。","忽遇洛阳，三河少年。","贲戎发机，卞庄奋拳。","佽飞鼓刃，裴旻控弦。","击鼓鸣钲，张网树旗。","有角曷抵，有翼曷飞。","割裂其肉，寝处其皮。","以首承溺，为百兽嗤。","永戒后人，为恶勿长，为善勿疑。","彼不余信，请视此诗。"]},{"t":"乌生八九子","f":"古风","c":["峨峨秦氏高楼，桂树轮囷出云间。","上有一双头白乌，毛羽何摧残。","唶彼头白乌，生八九子，养雏坐树端。","八九子，乳哺亦诚难。","朝不得食，夜不得餐。","八九子，羽翼以长成，各各飞去忘来还。","唶彼头白乌，空腹坐树端。","饥饿顿欲死，泪下如流泉。","唶彼秦氏少年子，怒激壮士肝。","白玉为雕弓，黄金为弹丸。","一发中群雏，魂魄飞上天。","八九子，魂魄飞上天。","唶彼乌不反哺谁当怜。"]},{"t":"西门行","f":"古风","c":["綦隆世，化日舒，玉尊肴醴罗前除。","东邻子，燕赵姝，清歌妙舞扬罗襦。","贤豪过，驷马车，良辰日吉心相娱。","人命无百年，日月同斯须。","胡为自约束，怅怅常独居。","岂无仙人王子乔，驾六飞龙游太虚。","岂无仙人王子乔，驾六飞龙游太虚。","天地会有终，千秋万岁后仙圣同凡愚。","不如命我友，撞钟擂鼓鸣笙竽。"]},{"t":"东门行","f":"古风","c":["出东门，步且吁，时世混浊难共居。","我欲乘长风，东游扶桑西瑶池。","挥首向容成，亿万不相疑。","归来告妻子，牵衣蹬足长歔欷。","长歔欷，上有垂白亲，下有黄口儿。","孔雀东南飞，十步五步不相离。","君今独行安所之，君今独行安所之。","不如守穷巷，鸡鸣狗吠相因依。","不见伯夷叔齐，采西山蕨薇。","荣名被百世难等夷。"]},{"t":"顺东西门行","f":"古风","c":["岁行暮，时既昏，设我肴醴开玉尊。","乐亲故，延嘉宾，轩车杂沓徒在门。","列五鼎，罗八珍，甘嘉溢口呈芳新。","饮麻姑，招洛神，擘红虬脯羞黄麟。","琴瑟和，钟鼓陈，樗蒱六博何缤纷。","长袂掩，羞蛾颦，纤歌随风飘青云。","良夜半，星河倾，主人未醉客尚醒。","二难具，五福并，亿千万岁延遐龄。"]},{"t":"燕歌行","f":"七言古诗","c":["严霜萧萧白露漙。","三星在房月在天。","空闺思妇愁城南。","起看北斗何阑干。","楼头旅雁鸣飞翰。","口衔尺书下云端。","同心为结缄瑶函。","下有相忆上加餐。","何以寄情双玉环。","念欲报之青琅玕。","山高水长浩漫漫。","我欲从之途路难。","罗帷倚灯曙不眠。","秋风飒飒吹重关。","安得送我置汝前。"]},{"t":"平陵东","f":"古风","c":["平陵东，气郁葱。","大雷电，天以风。","启金縢，告元功。","谁其辅者安汉公。","安汉公，坐明堂。","发天兵，下咸阳。","讨贼盗，捕乱亡。","贼盗乱亡，畴则使东郡，太守翟氏子不量。","其力罔畏死，天兵桓桓孰敢当。","所击者破禦者殃。","烟尘扫荡清一方。","颈系诸累俘未央。","君不见翟义公，今日系。","安汉公，明日帝。","彼已之子甘若荠。","天凤改元易汉制。","白水真人从东来。","昆阳百万成沙灰。","坐倚斗柄临高台。","胡不再开金縢谕九垓。","胡不再开金縢谕九垓。"]},{"t":"鞠歌行","f":"古风","c":["携玉女，邀仙童，天门詄荡开九重。","揖金母，拜木公，蹻蹑鹿卢乘罡风。","飞廉导，屏翳从，周游八极骑茆龙。","乘元化，入无终，千秋万亿齐乔松。"]},{"t":"上留田","f":"古风","c":["噫嘻人世大难。","贵贱贫富相悬。","富贵阡陌绵延。","贫贱家无一廛。","四体衣襦不完。","毛翮凋疏摧残。","气息恹恹自怜。","赴诉司命君前。","我独胡为蹇连。","夙生期运致然。","饮泣吞声何言。"]},{"t":"董逃行","f":"古风","c":["东京城郭煌煌。","冠盖罗列成行。","天祸汉国彷徨。","白昼兵戈夺攘。","劫制天子侯王。","千乘万骑北邙。","焚烧廪庾糇粮。","郿坞黄金作墙。","天道好还有常。","司徒祓除不祥。","首恶刳胸裂肠。","膏血燃灯道傍。","百代箴规莫忘。","永戒贪饕陆梁。"]},{"t":"悲歌","f":"古风","c":["巫山之高，淮水汤汤。","我欲东归，洛大河无梁。","船道阻绝，登高以望故乡。","故乡不可见，熊罴虎狼夹路而成行。","狐兔失群，我与为侣。","日暮途远，傍无旅舍，悒郁谁语。","悲风动地，阴云四起。","仰天悲歌，泪堕不能止。"]},{"t":"前缓声歌","f":"古风","c":["缘木求鱼，譬彼入山采珠。","意气虽勤，奈此道路殊。","总角相亲，同室共居。","君心有他，如隔里闾。","身非草木根株。","他人有心，忖度在余。","欲见子都，乃值狂且。","嗟他心之人，虫鸟之弗如。"]},{"t":"蛱蝶行","f":"古风","c":["飞来双蛱蝶，羽翅一何翩翩。","掠春风而游东园，彼姝者子朱为颜。","年十四五，被发齐两肩。","忽来睹此双蛱蝶，心中以惨然。","春风浩浩，岁月行蹉跎。","我欲捉蝶以婆娑，蝶以双飞奈蝶何。"]},{"t":"满歌行","f":"古风","c":["嗟人世茕茕，若过隙驹。","百忧填中，当复谁与娱。","忆我年少时，慈亲大悯。","惜中遭荼毒，展转愁闷。","岁以为日，家室荆榛，牝鸡夺晨。","罹此悍虐，伶俜莫可告人。","彼妇之恶，为鬼为蜮。","潜行昏黑，无从方物。","彼妇之恶，为虺为蛇。","造作语言，鼓吻摇牙。","慈亲积戾，奄忽弃背。","黄口嗷嗷，舆埋山椒。","箠笞炮烙，凶威灼铄。","姬妾徬徨，进退错愕。","犹复蚤夜思，维图覆厥宗。","仰面叩天，无地自容。","密计深谋，狞不可近。","风波起咫尺，白昼为陷阱。","而家弗殃，彼念弗忘。","而家弗祸，彼业弗堕。","吞声饮泣以诉司命君，彼司命之君杳若弗闻。","悍妇持门户，胡以事严亲。","严亲七十馀，风烛暮逡巡。","安能舍之远去，去适沧海滨。","忧来起中夜，揽衣不及晨。","皇灵会动变，沴气干天阍。","大雷电风雨，永戒后世人。"]},{"t":"两头纤纤诗二首 其一","f":"七言绝句","c":["两头纤纤少妇眉，半白半黑枰中棋。","逼逼膊膊仓鼠驰，磊磊落落道傍梨。"]},{"t":"两头纤纤诗二首 其二","f":"七言绝句","c":["两头纤纤麋鹿角，半白半黑檐前鹊。","逼逼膊膊林鸦啄，磊磊落落荆山璞。"]},{"t":"五杂组诗二首 其一","f":"古风","c":["五杂组，中天霞。","往复还，贯月查。","不获已，遇龙蛇。"]},{"t":"五杂组诗二首 其二","f":"古风","c":["五杂组，芝为盖。","往复还，咸阳塞。","不获已，见褦襶。"]},{"t":"公无渡河三首 其一","f":"古风","c":["公无渡河，大河扬波。","长鲸如山，鬐鬣嵯峨。"]},{"t":"公无渡河三首 其二","f":"古风","c":["公无渡河，一苇奈何。","河水万丈，出没蛟鼍。"]},{"t":"公无渡河三首 其三","f":"古风","c":["公无渡河，谗言孔多。","不见申屠，负石投河。"]},{"t":"枯鱼过河泣二首 其一","f":"五言绝句","c":["枯鱼过河泣，宛转沙泥侧。","神龙处九渊，蝼蚁安能测。"]},{"t":"枯鱼过河泣二首 其二","f":"五言绝句","c":["枯鱼过河泣，定作盘中腊。","愿觅斗升水，为君赴溟渤。"]},{"t":"短歌行","f":"古风","c":["日吉时良，嘉宾满堂。","星河在天，蟋蟀在房。","欢娱易终，白发苦蚤。","金罍玉尊，长夜倾倒。","舞袖纷纭，兰膏载焚。","卫女齐姜，左右如云。","有美一人，稚齿倩盼。","携手同车，光华粲粲。","翩若游龙，遨嬉八埏。","荡意平心，永宅大年。"]},{"t":"善哉行","f":"古风","c":["来日大难，肠乾体疲。","今日不乐，岁月如驰。","访我亲知，总角燕好。","踰陌度阡，以赠芳草。","何以延宾，清酒百壶。","何以销忧，五木摴蒱。","美人满堂，巧笑便辟。","更长烛明，今夕何夕。","南箕在楹，北斗在檐。","星河陆离，肴醴汎澜。","忽逢安期，馈我灵药。","主客再拜，洗盏酬酢。","共饵大还，身轻翼舒。","乘云御龙，游戏六虚。"]},{"t":"日出东南隅行","f":"五言古诗","c":["日出东南隅，照我陌上桑。","峨峨秦氏楼，佳丽郁相望。","飞甍百馀尺，高栋五丈强。","琉璃为门限，桂树为中堂。","窈窕楼中女，容华世无双。","提篮向朝日，采桑大道傍。","腰悬琼瑜佩，耳缀珊瑚珰。","首戴金雀钗，足蹑双凤凰。","吴丝作中襦，蜀锦充下裳。","紫绮缘领巾，绿罗随风扬。","借问汝何名，罗敷秦女郎。","借问汝何居，第宅连明光。","问汝适何人，家令殿中郎。","问汝年几何，十五正相当。","行者观罗敷，五步一徬徨。","居者观罗敷，耒耜相扶将。","赵王暮登台，挟瑟奏笙簧。","侍从数百人，冠盖何煌煌。","举头见罗敷，顾盼自生光。","遣吏前致辞，可得充后房。","昔为千乘妻，辛苦行采桑。","今为万乘后，刍豢同匡床。","罗敷仰头答，君侯一何狂。","国主位虽尊，二八盈高堂。","家令位虽卑，糟糠亦难忘。","尊卑各有分，贵贱各有双。","君非秦王子，妾非邯郸倡。"]},{"t":"名都篇","f":"五言古诗","c":["三河聚年少，五都盛材雄。","倾赀灞上水，结客咸阳东。","呼鹰过长乐，走马游新丰。","左櫜插楛矢，右箙弯良弓。","控弦疾流星，鸣镝如追风。","穿杨竞百步，蹲甲洞七重。","仰面落九乌，俯身拾双鸿。","万夫为辟易，观者盈道中。","日暮还城郭，华筵撞笙镛。","屏间拥稚齿，坐右罗妖童。","烹鲜割翠缕，椎牛炙黄熊。","酣歌酌太白，慷慨嘘长虹。","呼卢列明烛，良夜未及终。","酒阑拔剑去，斜月犹朣胧。"]},{"t":"美女篇","f":"五言古诗","c":["长安出佳丽，宛洛多名姝。","游戏芳春日，踏青岐路隅。","银环约素手，玉佩飘华裾。","丹霞错绮袖，惠风扬罗襦。","悬腰灿火齐，充耳大秦珠。","珊瑚间四体，宝钗直万馀。","扬音若蕙兰，吹气胜芙蕖。","吴姬亮非偶，卫女焉得如。","众观共叹息，日暮罗长衢。","居者为忘飧，行者各踟蹰。","何来少年辈，三五乘骊驹。","倾城睹明艳，荡思欲忘躯。","岂无千金聘，谐此百岁娱。","畴为伯鸾匹，偃蹇宁独居。","寄声侠游子，相望徒区区。"]},{"t":"白马篇","f":"五言古诗","c":["白马谁家子，扬鞭大道傍。","银鞍耀明月，宝剑如秋霜。","十五隶金吾，二十拜龙骧。","百千聚游侠，百万要名娼。","斗鸡入南内，挟弹游平康。","京兆不敢呵，司隶为彷徨。","征尘际天起，边烽达长杨。","长揖大将军，慷慨事戎行。","横行绝大漠，虎啸临穷荒。","矫诏袭楼兰，飞书定朔方。","左射中休屠，右盼伏中行。","兵威慑绝塞，奏凯向咸阳。","献俘诣平乐，赐第连明光。","归来顾少妇，挟瑟宴华堂。"]},{"t":"升天行","f":"五言古诗","c":["九州非我宅，五岳不足居。","乘蹻蹑浮云，周览万里馀。","朝游昆崙顶，夕息瀛海隅。","举头见三山，城阙正逶纡。","圆峤耸巨鳌，方壶戴神鱼。","西行谒王母，置酒行天厨。","灵妃酌金液，玉女吹笙竽。","燕乐未及终，飞腾起太虚。","骖龙叩玉阙，驾凤翔灵旟。","长揖问轩辕，俯身拾帝车。","明霞为我佩，素霓为我裾。","飘飘谢尘世，万岁同斯须。"]},{"t":"仙人篇","f":"五言古诗","c":["我思忽不怿，投袂起行游。","担簦蹑芒履，去上嵩山丘。","王屋一何高，太行亦阻脩。","危峰冠浮云，巨石横道周。","青松数十围，枝叶自相樛。","上有千岁禽，下有万尺流。","矫矫浮丘公，吹笙跨灵虬。","投我不死药，携我升蓬丘。","丹霞起素壁，紫雾开琼楼。","横飞绝四海，高举临九州。","顾视世间人，局促安可留。","朝生等舜华，夕死同蜉蝣。"]},{"t":"相逢行","f":"五言古诗","c":["相逢狭路间，骑从一何都。","借问来者谁，中尉执金吾。","银鞍耀白日，宝剑佩昆吾。","英声走剧孟，勇气凌灌夫。","西征破大宛，北顾摧匈奴。","去年出湟中，一战定边隅。","归来报天子，赐第连皇都。","黄金为门限，白玉中堂铺。","堂上何所有，七尺红珊瑚。","十千治晨飧，百万当呼卢。","乐工高渐离，苍头冯子都。","长妇字莫愁，中妇名罗敷。","少妇何名字，顾盼日当垆。","弟兄八九人，各各列当涂。","炙手势可热，声焰绝代无。","行人但引避，无事劳追呼。"]},{"t":"门有车马客行","f":"五言古诗","c":["门有车马客，意气何扬扬。","千金饰玉鞭，百金宝剑装。","传呼动里闾，顾盼自生光。","长妇出迎客，问客来何方。","客言自幽蓟，乍者发渔阳。","道逢远征人，寄书来故乡。","开缄竟何道，细书八九行。","昔为丝与桐，今为参与商。","参商各异地，羽翼安得双。","长跪再拜客，邀客暂徜徉。","烹庖出丰膳，高宴罗酒浆。","愿为传语欢，努力莫相忘。"]},{"t":"远游篇","f":"五言古诗","c":["端居厌尘世，飞步凌大荒。","左挟青龙驰，右骖赤豹翔。","西游翳若木，东望穷扶桑。","竦身昆崙颠，息驾玄圃傍。","道逢安期生，托手共徜徉。","携我黄金台，坐我白玉床。","太虚为我宅，沆瀣为我浆。","俯仰竟百世，焉能辨彭殇。"]},{"t":"结客少年场行","f":"五言古诗","c":["长安富游侠，骑射出名都。","飞扬结壮士，慷慨聚屠沽。","百千市骏马，十千装辘轳。","朝游上林苑，暮宿卖酒庐。","赤丸报司隶，白刃戕金吾。","笑傲金张第，叱咤许史途。","盛年谅难再，壮志不可孤。","鸣弓向张掖，插羽飞平卢。","左发摧焉耆，右发中休屠。","死当画麒麟，生当雄万夫。"]},{"t":"箜篌引","f":"五言古诗","c":["良时率已迈，蟋蟀鸣我床。","眷言召亲友，旨酒罗中堂。","东邻饰妖女，南陌招名娼。","绡衣随风举，罗袜自飘扬。","秦声被金石，楚曲流宫商。","清谈蔚霞烂，妙舞若云翔。","颓阳倏西落，明月出东方。","飞轩历层囿，改席临洞房。","华灯吐芳焰，列宿澄清光。","齐心怀令德，四坐咸尽觞。","芳辰谅难再，嘉会讵可常。","人命一朝尽，奄速如秋霜。","乐哉今日宴，百岁遥相望。"]},{"t":"从军行","f":"五言古诗","c":["边尘起西北，敌骑日相望。","仗剑报明主，长揖辞故乡。","征行渡沙漠，慷慨隶戎行。","羽书昨夜至，匈奴寇渔阳。","吏士若云屯，我兵精且强。","扬旌耀汉月，吹角飞边霜。","一战摧月支，再战款名王。","弯弓月在手，鸣镝星流光。","勒功燕然石，传檄瀚海傍。","归来拜骠骑，恩宠冠长杨。"]},{"t":"置酒篇","f":"五言古诗","c":["端居观大运，去日常苦多。","幸有盈尊酒，宾朋各来过。","佳人出后房，被服绮与罗。","纤腰斗妙舞，皓齿扬清歌。","轻飙荡浮云，华星烂明河。","好鸟鸣高枝，文鱼翔素波。","百年若朝露，白日驰山阿。","乐哉今日宴，不饮复如何。"]},{"t":"君子行","f":"五言古诗","c":["呜呼大圣人，世或见疑猜。","周公被流言，仲尼困桓魋。","贤材实累身，忠信为祸媒。","苍蝇点白璧，蚊蚋嘘风雷。","麒麟匿郊薮，朱凤成摧颓。","仰天再叹息，沈忧热中怀。","扰扰蜗角争，忉怛劳形骸。","千秋万世后，愚智同尘埃。"]},{"t":"豫章行","f":"五言律诗","c":["螣蛇自有翼，未若应龙潜。","蠖屈重渊中，润泽被八埏。","宣尼浴沂水，武仲巢箕山。","于陵饿仲子，通国称其廉。"]},{"t":"孤儿行","f":"五言古诗","c":["步出北郭门，荆榛夹路齐。","悲风起白杨，叶落何凄凄。","道逢孤儿卧，肌肤若螬蛴。","伶俜瘦皮骨，却立忘东西。","对我但长跪，气咽不能啼。","自陈无罪过，父惑后娶妻。","夙昔千金爱，慈母娇提携。","高堂倏背弃，妖牝鸣晨鸡。","风波起骨肉，咫尺如秦齐。","终朝拾橡栗，薄暮餐黄齑。","箠笞动盈百，卒岁无领绨。","弃置田野间，冉冉白日低。","昔为掌上珍，今为浊水泥。","千秋履霜辙，永永戒前蹊。"]},{"t":"白头吟","f":"五言古诗","c":["结缡奉明德，精诚决浮云。","死生誓同穴，富贵安足论。","一朝事势异，缅邈若越秦。","风波起对面，谗慝来相仍。","盛衰捷反掌，爱憎一何频。","昔者寒炉火，今为甑下尘。","还君锦绣段，著我苧罗裙。","念彼求凰曲，恨恨不能陈。"]},{"t":"斗鸡曲","f":"五言古诗","c":["翩翩五陵少，挟弹游咸阳。","万钱饮侠客，千镒招名娼。","走马东郊外，斗鸡大道傍。","两雄昂然出，五色丽且光。","黄金介白羽，绿沈铸玄裳。","双眸炯相射，四距翼而张。","凭陵壮夫胆，激烈猛士肠。","俱呈庆忌捷，竞逞黑卵刚。","狞牙攫豹虎，怒臂撑螳螂。","先声骤恫喝，后举剧披猖。","朱冠碎靺鞨，彩颊掀琳琅。","宁论北宫挠，肯避平阳创。","回身角伎巧，耸翮驰精芒。","初交气方盛，再合势弥强。","捐生赴仇国，效命临战场。","纵横掣惊电，䟤跋挐秋霜。","摧锋若禦寇，逐北如擒王。","干旄助踊跃，钲鼓随腾骧。","天地黯无色，尘沙剧飞扬。","欢呼压廛市，登眺摧山冈。","中原逐秦鹿，大陆豗天狼。","雄雌久未决，转战益慨慷。","迟迟白日堕，两敌为彷徨。","安得鲁阳刃，一挥返扶桑。"]},{"t":"三妇艳二首 其一","f":"五言古诗","c":["大妇拂花笺，中妇理冰弦。","小妇学弹棋，夭桃斗春妍。","良人定睛觑，谁当最可怜。"]},{"t":"三妇艳二首 其二","f":"五言古诗","c":["大妇贴花钿，中妇理红妆。","小妇画蛾眉，含娇踏春阳。","良人试垂盼，良夜殊未央。"]},{"t":"广三妇艳四首 其一","f":"五言律诗","c":["大妇出姬姜，族望不可加。","中妇出燕赵，容色鲜如花。","小妇出吴越，盈盈娇浣纱。","丈人但安坐，四海方为家。"]},{"t":"广三妇艳四首 其二","f":"五言律诗","c":["大妇字若兰，深闺理流黄。","中妇字罗敷，陌上行采桑。","小妇字莫愁，盈盈居画堂。","丈人但安坐，满目饶春光。"]},{"t":"广三妇艳四首 其三","f":"五言律诗","c":["大妇出迎客，二十颇有馀。","中妇起持觞，二九曳罗襦。","小妇坐鸣筝，二八正敷腴。","丈人但行乐，南面安得如。"]},{"t":"广三妇艳四首 其四","f":"五言律诗","c":["大妇年十九，高堂坐摴蒱。","中妇方十七，明琼角呼卢。","小妇正十五，青春独当垆。","丈人但行乐，何羡执金吾。"]},{"t":"续三妇艳二首 其一","f":"五言律诗","c":["大妇处华堂，玉貌锦衣裳。","中妇处高楼，玉指拨箜篌。","小妇处金屋，玉簪髻初束。","白日欢未足，良夜更秉烛。"]},{"t":"续三妇艳二首 其二","f":"五言律诗","c":["大妇妆初成，一顾倾人城。","中妇妆乍毕，一盼倾人国。","少妇妆未己，一笑倾人主。","有酒清且旨，交加学连理。"]},{"t":"反三妇艳二首 其一","f":"五言律诗","c":["大妇吟白头，沟水东西流。","中妇歌懊侬，红颜空自红。","小妇咏团扇，辛苦郎自见。","莫誇三妇艳，丈人涕如霰。"]},{"t":"反三妇艳二首 其二","f":"五言律诗","c":["大妇气食牛，千唤不回头。","中妇愁绪萦，敢恕不敢嗔。","小妇诉卑贱，终朝泪洗面。","莫誇三妇艳，丈人肠欲断。"]},{"t":"远别离","f":"古风","c":["远别离，古有之。","不见牵牛星，荧荧河汉湄。","黄姑弄杼轴，锦石为支机。","招要自成匹，永永不相疑。","终朝卧阊阖，折花事游嬉。","逡巡怒上帝，立遣东西驰。","天孙尚尔尔，世人了可知。","酌君一杯酒，听我歌别离。","君不见重瞳堕地气食牛，扫除六合朝诸侯。","美人娇爱置金屋，彭城著绣誇遨游。","时危势屈走垓下，楚歌四面兴仇雠。","蛾眉倏忽化黄土，拔山力尽乌江头。","君不见隆准布衣奋三尺，蹙项诛秦四海一。","淮阴菹醢百虑空，掌上娇儿夜啼泣。","回身楚舞涕泗横，黄鹄摩天招不得。","未央美人居厕中，地下谁呼宠姬戚。","古来豪杰流，往往称二子。","裂眦摧天关，五岳任驱使。","徘徊一妇人，竟作别离死。","何况蚩蚩辈，畴能不罹此。","房帷仅咫尺，陷阱如丘山。","不信别离苦，焉知行路难。","荆榛莽闺闼，对面生尤愆。","逝将舍之去，去去适荆蛮。","荆蛮非我乡，念欲还长安。","载歌别离曲，使人叹息摧朱颜。","远别离，何匆匆。","浮世狭，难为容。","胡不醉我美酒三千钟。","蒲萄之酿紫花泼，绿尊翠杓春溶溶。","两手持蟹螯，拍浮玉缸中。","落叶有时合，明珠有时逢。","人生把酒当尽醉，回头万事成虚空。","项刘两竖子，龌龊非莫雄。","天孙与河鼓，儿女徒忡忡。","二妃从游已百岁，湘水底事流啼红。","屈原李白俱谩语，谑浪分明欺乃公。","大人虎变挟宇宙，傍日月驾双飞龙。","黄童姹女永相逐，周游八极乘罡风。","安能低眉折腰局促，相若辕下驹守樊笼。","远别离，何匆匆。","安能低眉折腰局促，相若辕下驹守樊笼。"]},{"t":"饮马长城窟","f":"古风","c":["饮马长城窟，长城多白骨。","白骨纵横如雪山，风吹飞沙马不前。","借问何人骸，暴露置其间。","云是当时秦王筑城卒，被驱什九亡黄泉。","膏血饲蝼蛄，肌肉喂乌鸢。","惟有白骨存，安能复持还。","歇马上长城，睹此重辛酸。","令我中气咽，徘徊不能言。","男儿立功名，介胄辞上官。","横行万里外，勒勋赴燕然。","黄金络马头，白玉饰马鞭。","胡不奋长剑，平沙漠，款服诸部落，勒石燕然入长安。","生封定远侯，冢墓象祁连。","胡为老死长城下，白骨支撑玉门关。","黄榆翳衰草，一望徒漫漫。","子孙不复知，悲鸣裂肠肝。","肠肝痛欲裂，子孙无柰何。","至今长城下，白骨年年多。","存亡信有命，壮士悲蹉跎。","闵彼长城卒，聊作长城歌。","长城歌，歌莫哀，秣余马，登轮台。","轮台浮云极天开，我马玄黄以豗尵。","当时班定远，鬓发焦黄埃。","皓首博侯封，慈亲溘蒿莱。","其人至今亦白骨，定远之荣安在哉。","何异长城卒，埋胔长城隈。","不如驱我马，舍之归去来。","五花一掷换美酒，竹林痛饮忘疑猜。","双眼瞢腾向天白，飞行八极骑龙媒。"]},{"t":"登高丘而望远海和李白","f":"古风","c":["登高丘，望远海，海水何茫茫。","齐州九点渺空阔，东西日月悬扶桑。","扶桑宫阙连蓬莱，白虹照耀中天台。","六鳌赑屃负圆峤，群帝百千亿万纷纷跨鹤游崔嵬。","峨岢大舶走徐市，安期一去无时回。","我笑秦王乏灵骨，人言汉武非仙才。","登高丘，望远海，海水茫茫接天回，使我极目心悠哉。","心悠哉，以彷徨。","何来龙伯人，濯足临扶桑。","一钓连六鳌，揽之不盈筐。","煮鳌为臛充余粮，鳌骨如山今已霜。","我醉欲卧黄金床，呼吸灵和挟三光。","睥聣汉武嗤秦皇，周行八极还大荒。"]},{"t":"白纻四时词四首 其一","f":"七言古诗","c":["东园桃李争春阳，美人如花簇华堂。","弯弓舞袖搴罗裳，沈香亭北春茫茫。","东风吹歌绕画梁，回眸一盼神飞扬，我醉欲眠黄金床。"]},{"t":"白纻四时词四首 其二","f":"七言古诗","c":["南原日长蝴蝶飞，朱楼画阁临芳池。","美人含娇拂罗衣，歌喉宛转浮云驰。","流商刻羽知音稀，纤腰起舞光陆离，我醉欲罢黄金卮。"]},{"t":"白纻四时词四首 其三","f":"七言古诗","c":["西堂雨霜胡雁来，中天皎月璚云开。","纤歌遏云夜徘徊，美人击筑秋风哀。","华阳碣石俱蒿莱，荆卿渐离安在哉，我醉欲上黄金台。"]},{"t":"白纻四时词四首 其四","f":"七言古诗","c":["北风萧萧撼陵谷，白雪飘花满平陆。","何处阳春斗歌曲，云锦缠头舞鸲鹆。","美人修蛾无疹粟，素手垂垂照寒玉，我醉欲买黄金屋。"]},{"t":"虎穴行送曹秀才从军","f":"古风","c":["男儿堕地气压鳌，俯拾将相如鸿毛。","时来拥彗扫六合，云霞五色飞宫袍。","君不见苏秦微时皂貂泣，一朝金印都六国。","位高金多归故乡，妻嫂匍匐趋道傍。","一家骨肉尚如此，陌上行人谁家子。","丈夫耻作儿女悲，世路滔滔竞青紫。","酒酣愤歌歌激烈，双眼横天日星裂。","便从东海批龙鳞，更向南山搏虎穴。","宁能寂寂鸡鹜群，燕雀蝼蚁争纷纷。","金盘六博饮美酒，匣底芙蓉电光吼。","来朝挥戈大漠北，辟易咸阳万夫走。"]},{"t":"悲歌行","f":"古风","c":["滔滔百川逝还流，夸父逐日不回头。","秋风鸿雁春风燕，河东织女西牵牛。","牵牛织女不相见，一似秋鸿与春燕。","人生有钱付酒家，何用殷忧涕如霰。","君不见黄河奔流下太行，鲁阳难返九日光。","黄金可成脑可补，试问秦皇与汉武。"]},{"t":"长相思 其一","f":"古风","c":["长相思，久离别，单于台上秋草歇。","玉帐寒，朱旗折，三年灞陵梦，万古阴山雪。","边笳日暮起塞门，流水无声陇云咽。","长相思，久离别。"]},{"t":"长相思 其二","f":"古风","c":["长相思，路行难，玉关鸿雁何时还。","张雾幄，捲云鬟，青灯夜未灭，翠被晓犹寒。","荏苒红颜镜中老，空闺日日望刀环。","长相思，路行难。"]},{"t":"杨白花","f":"古风","c":["杨白花，随风漂泊天之涯。","深闺无人白日暮，金舆玉辇空咨嗟。","惟有旧时杨柳树，月明夜夜啼栖鸦。"]},{"t":"白鼻騧","f":"古风","c":["逢欢白鼻騧，驻妾青丝骑。","罗带结同心，留连合欢被。","君作干将佩，侬作莫邪钩。","雄雌两物巧相遇，安眠玉匣三千秋。"]},{"t":"拟李白蜀道难作梁父吟","f":"古风","c":["抱膝南阳庐，明时甘陆沈。","唐尧倦六合，飞书入深林。","颍川之水，咄嗟不足洗余耳，拂衣长啸直上岱宗之嵚岑。","岱宗高高不得上，卧龙之叟来相寻。","邀余憩梁父，重作梁父吟。","我吟梁父君莫猜，仰天叱咤浮云开。","晏婴侏儒忌贤哲，二三力士庸堪哀。","古来封禅之君七十二，其人一一俱尘埃。","请为梁父吟，我吟君莫猜。","梁父中天十万八千有馀丈，一柱亭亭迥出泰山上?砑。","巃嵷独立标乾坤，恍若元气浮昆崙。","龟蒙凫绎以东诸阜尽培塿，纷纭拜伏罗儿孙。","决眦断虹入，荡胸明霞屯。","手接飞鸟度，步学猿猱蹲。","竦身十八盘，象纬渐可扪。","黄河一线绕山麓，徂徕矫首势欲吞。","鹿卢之蹻抟旋撇捩不遑息，神人绝顶为我开天门。","开天门，阅仙籍，其间似有胡生名，谪向金华煮白石。","朝从天门卧，夜坐日观峰。","峰头望海色，灏灏连长空。","五城十二楼，嵯峨驾天风。","天鸡乱鸣不知夕，回飙忽卷大海立。","海水横飞十洲溢，滟滟扶桑吐朝日。","红轮轣辘碾太虚，我欲乘之走八极。","金银台殿咫尺间，玉女携余掉臂入。","掉臂入，谒元君，呵赤蜺，导黄麟。","右拍浮丘肩，左顾招广成。","神农以还九千九百九十有馀帝，扬雷掣电纷纷跨鹤而来迎。","鸟篆鸿章閟灵迹，仲尼扪崖怪难识。","蛟螭缺落狐兔跑，对此抚膺重叹息。","翠华茫茫杳何处，四顾中原日无色。","君不见秦祖龙，云亭柴望拥列辟，衣冠剑舄如云虹。","至今沦没尽荒草，故物但有当时松。","君不见汉孝武，驰驱栾大延文成，卤簿干旄照东鲁。","东方小儿弄乃公，寂寞荆榛翳抔土。","吁嗟乎，秦皇汉武真蜉蝣，我今胡为此滞留。","拂袖行歌下梁父，下山竟作齐东游。","齐东道上逢李白，飞扬跋扈心神投。","鹔鹴之裘五花马，一醉五月眠高楼。","吴钩如霜雪花落，纵横眼底无全牛。","我歌梁父属尔和，遥空立降双青虬。","世人拍手笑轻薄，我嗤人世真累囚。","渭滨老叟太多事，行年八十图封侯。","鄙哉齐国三竖子，沾沾一果同猕猴。","力排南山躯九尺，杀身反堕侏儒俦。","隆中释耒大星殒，人间事事当回头。","头上青丝一朝倏尔变白发，九州之伯四岳之长如悬疣。","梁父吟，歌莫愁，男儿有身睥睨六合追巢由。","不然淋漓大白扫椽笔，阳春百代鸣天球。","犹胜古来封禅之君七十二伐功，诩德誇蚩尤。","君不见七十二家文字总顽石，汉碣秦碑半颓泐。","惟有青莲居士梁父吟，万古长悬岱宗日。","惟有青莲居士梁父吟，万古长悬岱宗日。"]},{"t":"将进酒","f":"古风","c":["将进酒，乘飞龙，满引大白嘘长虹。","舜百石，尧千钟，北斗奉杓南斗从。","天瓢出沆瀣，大乐鸣笙镛。","绡衣万玉女，绿发双仙童。","左拍浮丘肩，侧睨容成公。","百年三万六千日，一日不醉令我行步如龙钟。","君不见泗上亭长隆准公，斩蛇逐鹿驱群雄。","鸿门高会割巴蜀，肝肠郁郁长思东。","结约五诸侯，伐楚彭城宫。","一朝项氏自东至，五十六万如飘风。","荥阳匍匐作降虏，何如饮酒来新丰。","信陵宾客但墟墓，古木荒榛穴狐兔。","平原毛遂骨已灰，黄金之馆生尘埃。","何如一笑饮美酒，白眼横吞三百杯。","长安桑落名最古，山东秋露清且苦。","曲米云安远难得，若下吴兴近堪数。","世人每病金华甘，此酒名高弘正间。","只今天下贵三白，积薪后者常居前。","盛衰好恶若反掌，时来不得论媸妍。","太白三闾岂庸俗，一醉一醒操行独。","醉者骑鲸上九天，醒者反葬蛟鼍腹。","刘伶阮籍双酒狂，竹林牛饮称高阳。","当时颇遭俗子骂，至今百代垂文章。","今晨何晨夕何夕，炰鳖烹熊众宾集。","觞行瑟作不暂停，玉椀银缸兴逾剧。","三星在檐河汉入，扶桑茫茫日东出。","安得八骏抟长风，烂醉瑶池三万日。"]},{"t":"行路难二首 其一","f":"古风","c":["君不见东家叟，昔日容华今老丑。","君不见西家翁，昔时豪富今贫穷。","盛衰美恶反覆掌，造化小儿剧罔两。","敝车羸马聊自储，荡意平心恣欢赏。","人心险阨如山川，行路之难君所谙。","有酒盈尊肉盈几，明日咸阳过赵李。"]},{"t":"行路难二首 其二","f":"古风","c":["君不见原上草，一夜霜飞净于扫。","君不见园中花，一朝风荡随泥沙。","男儿快意在行乐，何用营营逐飞藿。","白日苦短秉烛游，玉碗淋漓恣斟酌。","人心对面隔九疑，行路之难君所知。","速来就我饮斗酒，倏忽华颠壮夫丑。"]},{"t":"东飞伯劳歌","f":"七言古诗","c":["西飞者燕东伯劳，华堂锦帐生蓬蒿。","少年儿郎轻薄子，弃捐比翼如鸿毛。","咫尺天孙与河鼓，岁岁年年隔银浦。","一朝乌鹊来填桥，犹得相逢话辛苦。","脂车秣马夜不停，漂流南北如浮萍。","当时离别勿复道，悲风冉冉来长檠。","机上双鸾手中线，宛转流黄涕沾面。","铅华落尽君不见，东飞伯劳西飞燕。"]},{"t":"长安道","f":"五言古诗","c":["长安开大道，佳丽壮秦京。","帝座悬双阙，皇居控百城。","重关函谷气，夹岸渭川声。","冠盖凌云度，轩车耀日行。","新丰花簇骑，上苑树巢莺。","鼓吹元僚第，旌旗大将营。","狭斜何处是，北里近西清。"]},{"t":"黄鹄","f":"五言律诗","c":["何处双黄鹄，飞来自大荒。","声传北塞远，影落汉宫长。","咽露过平乐，衔云入建章。","谁同二千石，万寿献君王。"]},{"t":"雨雪","f":"五言律诗","c":["雨雪霏霏下，遥知行路难。","将军金甲重，战士铁衣寒。","落叶边淮尽，飞花度陇残。","城南有思妇，拥被独更阑。"]},{"t":"出塞","f":"五言律诗","c":["陇首雪花飘，征人出渭桥。","长城屯万骑，大碛下双雕。","闪月朱旗静，穿云画角遥。","横行榆塞外，一战静氛妖。"]},{"t":"梅花落","f":"五言律诗","c":["何处边声切，迢迢逐暮笳。","天山飞雪暗，万树落梅花。","度漠边云断，飘空汉月斜。","那能辽左客，此夜不思家。"]},{"t":"陇首","f":"五言律诗","c":["九月被毡裘，征人上陇头。","黄龙悬塞色，白马赴边愁。","陇坂高无极，寒泉咽不流。","梅花何处折，肠断在朱楼。"]},{"t":"入塞","f":"五言律诗","c":["九塞燧烟销，将军罢度辽。","前军严阵垒，大汉静氛嚣。","玉勒飞黄静，金戈太白遥。","塞门歌舞入，红旆暮飘飘。"]},{"t":"十五卢家女","f":"五言律诗","c":["十五卢家女，盈盈胜莫愁。","冰心持跳脱，玉腕拨箜篌。","拾翠游川上，流黄寄陇头。","生憎双语燕，比翼在青楼。"]},{"t":"折杨柳","f":"五言律诗","c":["送客灞陵桥，娼楼雪未消。","当垆年少女，十五正娇娆。","柳叶如垂手，杨枝似舞腰。","相看不忍别，折赠最长条。"]},{"t":"小垂手","f":"五言律诗","c":["锦帐出红绡，佳人斗步摇。","缠头矜稚齿，入掌妒纤腰。","帝子回鸾辂，天孙度鹊桥。","莫嫌银漏短，甲煎彻明烧。"]},{"t":"征妇怨","f":"五言律诗","c":["去年征钜鹿，今岁入卢龙。","玉塞莺声断，银河雁影重。","裁衣犹忆体，临镜懒窥容。","秋风起昨夜，床下又闻蛩。"]},{"t":"班婕妤","f":"五言律诗","c":["长门秋已到，昭阳欢未终。","绿苔积永巷，黄叶闭深宫。","啼红祗自惜，捣素为谁工。","惟将旧团扇，寂寂对西风。"]},{"t":"刘生","f":"五言律诗","c":["刘生何慷慨，任侠冠东平。","五侯前箸借，千乘下阶迎。","季布匿来久，陶朱名已成。","谁言一剧孟，能重亚夫营。"]},{"t":"明妃曲","f":"五言律诗","c":["骢马载蛾眉，明妆出帝畿。","含颦辞玉阙，结恨向金微。","月疑秦地镜，云忆汉宫衣。","传书寄鸿雁，一为报龙旂。"]},{"t":"后明妃曲","f":"五言律诗","c":["出塞涕沾襟，遥望阴山阴。","旧宠汉宫薄，新恩边地深。","紫骝涉长道，黄鹄寄哀音。","千载琵琶曲，谁明去住心。"]},{"t":"董娇娆","f":"五言律诗","c":["素手拨箜篌，盈盈在画楼。","玉钗翘紫燕，金盒贮红虬。","楚台行雨过，汉殿乘风游。","期门诸侠少，无处系骅骝。"]},{"t":"洛阳道","f":"五言律诗","c":["迢迢洛阳道，日暮正飞花。","公子青丝榼，王孙白鼻騧。","骑吹金张宅，歌钟赵李家。","遥传丽人至，偷眼七香车。"]},{"t":"秦王卷衣","f":"五言律诗","c":["春色醉秦楼，秦玉夜宴游。","銮舆回卤簿，凤管叶箜篌。","七宝流苏帐，千金集翠裘。","何人最承幸，卷赠龙阳侯。"]},{"t":"铜雀伎","f":"五言律诗","c":["松柏西陵路，君王不复游。","高台铜雀暮，故苑石麟秋。","舞将罗袖歇，歌倚穗帷愁。","浮云渺天末，漳水共悠悠。"]},{"t":"赋得盈盈楼上女","f":"五言律诗","c":["盈盈楼上女，十五正婵娟。","照胆秦宫镜，含情蜀国弦。","踏青回绮陌，拾翠傍晴川。","轻薄金吾子，无劳问少年。"]},{"t":"少年行","f":"五言律诗","c":["翩翩游侠客，结束自名邦。","过赵黄金百，游秦白璧双。","鸣鞭中贵避，插羽右贤降。","日暮名姬肆，飞花扑玉缸。"]},{"t":"紫骅骝","f":"五言律诗","c":["蹀躞天闲骑，曾从大宛来。","悬金当骏市，喷玉过龙堆。","伏枥心元壮，鸣鞭气不回。","何辞万里道，逐北向轮台。"]},{"t":"关山月","f":"五言律诗","c":["绝塞生秋早，空闺入夜愁。","光飞银阙上，影抱玉门流。","露气漙丝管，霜华拂锦裘。","征夫犹北戍，目断大刀头。"]},{"t":"剑侠行","f":"五言律诗","c":["少年学剑术，飞身游泬寥。","鹿卢云气拥，龙匣电光摇。","醉呵鲁句践，怒骂霍嫖姚。","夜来风雪猛，拂袖灞陵桥。"]},{"t":"骢马驱","f":"五言律诗","c":["骢马千金装，日夕过平康。","寸心重衡岱，片诺回沧桑。","白屋笑原季，青云轻赵张。","明朝砍文吏，竟夜赤丸光。"]},{"t":"公子行","f":"五言律诗","c":["新开平乐第，红妆簇画楼。","骅骝金作埒，鹦鹉玉为鞲。","汉宫鸣佩入，梁园挟弹游。","海棠花正发，选伎合梁州。"]},{"t":"侠少曲","f":"五言律诗","c":["鸣鞭白门道，新柳正藏鸦。","七宝装繁弱，千金散狭斜。","飞扬孟公坐，调笑季伦家。","夜夜双龙气，腰间挂赤霞。"]},{"t":"邯郸曲","f":"五言律诗","c":["夜宿邯郸花，朝扳灞陵柳。","五侯竞献鲭，七贵争持酒。","巨先胶漆契，翁伯金石友。","纵死咸阳宫，何负将军首。"]},{"t":"夜夜曲","f":"五言律诗","c":["褥隐芙蓉丽，筵开玳瑁频。","绣屏朝选伎，罗幌夜留宾。","艳曲梁间度，纤腰座里陈。","渐看银漏促，舄履杂华裀。"]},{"t":"采莲曲 其一","f":"五言律诗","c":["桂楫漾沙棠，向暮出横塘。","罗裙娇绿水，玉腕映红妆。","搴花怜盖弱，折藕爱丝长。","回桡弄斜影，惊起双鸳鸯。"]},{"t":"采莲曲 其二","f":"五言律诗","c":["飞身下七襄，骖驾六龙翔。","负局行中夏，携壶出大荒。","蓬莱千日酒，沆瀣万年浆。","勾漏砂如石，蓝桥玉作霜。"]},{"t":"爱妾换马","f":"五言律诗","c":["行雨蛾眉去，追风骏足来。","金羁沙苑秣，宝屧画廊苔。","太息专房艳，长鸣伏枥材。","何当效周穆，騄耳上瑶台。"]},{"t":"邯郸才人嫁为厮养卒妇二首 其一","f":"五言律诗","c":["乍辞鸾辂出，回望凤墀高。","幸脱君王难，宁忘厮养劳。","生轻惭比叶，命薄叹同蒿。","尚异乌孙贵，穷毡配二毛。"]},{"t":"邯郸才人嫁为厮养卒妇二首 其二","f":"五言律诗","c":["新恩偕伉俪，旧宠易累囚。","饮恨辞金屋，含悽下玉楼。","鸠巢元鹊憩，鱼服暂龙游。","不见平阳婿，次且择卫侯。"]},{"t":"巫山高","f":"五言律诗","c":["阳台出天半，高压大江湄。","暮雨连三峡，朝云合九疑。","猿啼青嶂急，鸟度翠屏迟。","莫作峰头梦，魂迷十二时。"]},{"t":"芳树","f":"五言律诗","c":["年年旧桃李，烂漫帝城阴。","结实当前殿，开花满上林。","香飞金谷早，影坠玉池深。","一曲山香罢，芳菲何处寻。"]},{"t":"蜀国弦","f":"五言律诗","c":["春风杜宇国，千载寄哀音。","水激巫娥佩，山鸣卓女琴。","铜梁朝日艳，玉垒暮云深。","浣花溪上宅，词人可重寻。"]},{"t":"邯郸行","f":"五言律诗","c":["狭斜连锦里，垂柳夹香堤。","绿绮千条润，青丝万树齐。","玉鞭骑过马，金距斗回鸡。","朝日红妆坐，流莺拂户啼。"]},{"t":"艳曲十首 其一","f":"五言古诗","c":["青楼开大道，翠馆接平阳。","柳拂葳蕤锁，花明玳瑁梁。","合欢年少客，新镂郁金床。"]},{"t":"艳曲十首 其二","f":"五言古诗","c":["画阁青门外，朱帘碧水浔。","绣衾描比翼，罗带结同心。","夜夜求凰意，无劳听玉琴。"]},{"t":"艳曲十首 其三","f":"五言古诗","c":["北陆歌钟起，东郊骑吹旋。","花香长乐外，草色未央前。","十万章台柳，玲珑拂翠钿。"]},{"t":"艳曲十首 其四","f":"五言古诗","c":["春光平乐近，胜事曲江留。","帝子联镳语，王孙挟弹游。","共邀金犊至，藉草大堤头。"]},{"t":"艳曲十首 其五","f":"五言古诗","c":["金羁连绮陌，玉佩照晴沙。","北极元僚第，南阳贵主家。","楼台七十二，日暮乱飞花。"]},{"t":"艳曲十首 其六","f":"五言古诗","c":["神女云为色，妖姬雪作歌。","三千回粉面，二八拥青蛾。","咸阳游冶客，赵李日经过。"]},{"t":"艳曲十首 其七","f":"五言古诗","c":["粉黛徵歌伎，腰肢斗舞人。","绿珠金谷艳，碧玉玳筵春。","珊瑚十万树，一一破瓜辰。"]},{"t":"艳曲十首 其八","f":"五言古诗","c":["明眸骄绮绣，皓齿粲琼瑰。","挟瑟燕姬肆，吹箫凤女台。","巫山何处是，指点片云来。"]},{"t":"艳曲十首 其九","f":"五言古诗","c":["宝帐连金屋，琼筵弄玉箫。","娇娆花作髻，静宛柳为腰。","当歌小垂手，烂漫雪花飘。"]},{"t":"艳曲十首 其十","f":"五言古诗","c":["渌水荡涟漪，江南日暮时。","吴姬木兰棹，越女竹枝词。","恼杀横塘下，纷纷轻薄儿。"]},{"t":"又六首 其一","f":"五言古诗","c":["金埒贮骅骝，银妆络马头。","相逢狭斜道，并倚大长秋。","何用知名姓，联翩入画楼。"]},{"t":"又六首 其二","f":"五言古诗","c":["博山银缕细，沈水玉壶香。","后院通韦曲，前除接建章。","名姝三百辈，月底诵灵光。"]},{"t":"又六首 其三","f":"五言古诗","c":["玛瑙妆为砌，珊瑚聚作林。","万钱编马埒，一脔试牛心。","向夕香风动，连车爇水沈。"]},{"t":"又六首 其四","f":"五言古诗","c":["乳燕穿朱屋，流莺啄画檐。","雾消云母帐，风动水晶帘。","遮莫嫦娥下，千花拂彩蟾。"]},{"t":"又六首 其五","f":"五言古诗","c":["朝朝呈翠黛，夜夜斗纤腰。","枕上偷金合，屏前弄玉箫。","罗衣三十院，无处觅红绡。"]},{"t":"又六首 其六","f":"五言古诗","c":["绮楼藏盼盼，罗幕贮盈盈。","雾袂空中举，霓裳月下行。","相看时一笑，若个不倾城。"]},{"t":"企喻歌四首 其一","f":"五言绝句","c":["双鞬铁裲裆，谁家大健儿。","蛇矛丈八盘，上马捷若飞。"]},{"t":"企喻歌四首 其二","f":"五言绝句","c":["腰间大羽箭，竖指百夫力。","突如飞天鹞，万鸟戢羽翼。"]},{"t":"企喻歌四首 其三","f":"五言绝句","c":["落日平原西，射雕控飞骑。","九种黑山戎，各各相引避。"]},{"t":"企喻歌四首 其四","f":"五言绝句","c":["天生健男子，何须多结伴。","独身取月支，降卒三十万。"]},{"t":"钜鹿公主歌 其一","f":"七言古诗","c":["油壁香车向何许，玉勒花骢汗红雨。"]},{"t":"钜鹿公主歌 其二","f":"七言古诗","c":["呵殿纵横灞陵渚，夹岸行人目相语。"]},{"t":"钜鹿公主歌 其三","f":"七言古诗","c":["新封大国钜鹿主，钜鹿为谁大家女。"]},{"t":"七夕夜女儿歌四首 其一","f":"五言绝句","c":["侬家白揄树，一年一开花。","郎如牵牛星，一年一来家。"]},{"t":"七夕夜女儿歌四首 其二","f":"五言绝句","c":["不恨欢意薄，但愿欢情长。","牵牛与织女，一年一成双。"]},{"t":"七夕夜女儿歌四首 其三","f":"五言绝句","c":["一年但一会，一夜一年周。","犹胜侬儿郎，十载客巴州。"]},{"t":"七夕夜女儿歌四首 其四","f":"五言绝句","c":["都将一年意，一夜申缱绻。","桥畔乌鹊声，天河渐清浅。"]},{"t":"碧玉歌二首 其一","f":"五言绝句","c":["莫嫌小家女，青春正十六。","新嫁琅琊王，娇爱比碧玉。"]},{"t":"碧玉歌二首 其二","f":"五言绝句","c":["恨无倾城色，不敢邀王怜。","相欢那在貌，动体生春妍。"]},{"t":"桃叶歌二首 其一","f":"五言绝句","c":["可怜王家郎，不解事桃叶。","清晨渡江去，日暮忘迎接。"]},{"t":"桃叶歌二首 其二","f":"五言绝句","c":["桃花作罗袖，桃叶为罗裙。","何似阿兄騃，终日怜此君。"]},{"t":"懊憹歌二首 其一","f":"五言绝句","c":["翩团黄犊车，载欢出城东。","看看白日堕，那能不懊憹。"]},{"t":"懊憹歌二首 其二","f":"五言绝句","c":["谁家娇女儿，三三复五五。","结伴邀欢行，今夜大辛苦。"]},{"t":"白团扇二首 其一","f":"古风","c":["白团扇，含情待郎来，不使路傍见。"]},{"t":"白团扇二首 其二","f":"古风","c":["白团扇，懊恨负情侬，手持不令见。"]},{"t":"华山畿","f":"古风","c":["华山畿，不愿生同栖，但愿死同止。","上有双比翼，下有双连理。"]},{"t":"安东平 其一","f":"古风","c":["严冬凛烈，北风雨霜。","河大水冰，断绝车航。"]},{"t":"安东平 其二","f":"古风","c":["客子远游，夐夐秦越。","囊无赀粮，带断裘结。"]},{"t":"安东平 其三","f":"古风","c":["我有绨袍，以遗故人。","物薄意厚，贵称君身。"]},{"t":"安东平 其四","f":"古风","c":["微物在机，是侬手织。","千缕一丈，三丈一袭。"]},{"t":"安东平 其五","f":"古风","c":["东平刘生，远持遗郎。","愿得邀郎，早还故乡。"]},{"t":"女儿子 其一","f":"七言古诗","c":["木兰歌声起两岸，江陵一夜肠欲断。"]},{"t":"女儿子 其二","f":"七言古诗","c":["估客年年下黄牛，巫山十二猿鸣愁。"]},{"t":"子夜四时歌 其一 春","f":"五言绝句","c":["大堤三月中，垂杨千万树。","郎骑白马来，堤上遥相遇。"]},{"t":"子夜四时歌 其二 夏","f":"五言绝句","c":["期欢大堤口，迟我采莲回。","向暮南风急，兰桡不敢开。"]},{"t":"子夜四时歌 其三 秋","f":"五言绝句","c":["人言秋日短，侬爱秋月光。","邀郎解衣坐，肌肤如雪霜。"]},{"t":"子夜四时歌 其四 冬","f":"五言绝句","c":["围炉然兽炭，为郎理瑶瑟。","不知重檐外，雪花厚三尺。"]},{"t":"子夜变歌","f":"五言绝句","c":["期欢半夜来，忽复月光晓。","九月芙蓉花，颜色讵长好。"]},{"t":"青骢白马","f":"七言律诗","c":["青骢白马娇成群，往来蹀躞如浮云。","系马高楼石城下，三百青铜莫论价。","七香炯炯并马行，卢家少妇车相迎。","郁金堂前双紫燕，白马青骢暮相见。"]},{"t":"寿阳乐","f":"古风","c":["妆楼百馀尺，寿阳开，白马从东来。"]},{"t":"石城乐四首 其一","f":"五言绝句","c":["欢居石城西，侬住石城东。","何愁不相见，一夜秦淮风。"]},{"t":"石城乐四首 其二","f":"五言绝句","c":["秦淮便风起，布帆疾如矢。","恨杀巴陵秋，洞庭八百里。"]},{"t":"石城乐四首 其三","f":"五言绝句","c":["洞庭八百里，一夜南风回。","送郎到长干，泊舟凤凰台。"]},{"t":"石城乐四首 其四","f":"五言绝句","c":["携手登高台，台荒半野草。","殷勤传语郎，莫忘石城好。"]},{"t":"莫愁乐二首 其一","f":"五言绝句","c":["莫愁在何处，石城西南弄。","手携卢家郎，吹箫跨双凤。"]},{"t":"莫愁乐二首 其二","f":"五言绝句","c":["昔为石城乡，今作莫愁里。","开门见所欢，容色艳桃李。"]},{"t":"襄阳曲","f":"五言绝句","c":["襄阳轻薄儿，挟弹出大堤。","嬉游向日暮，高唱白铜鞮。"]},{"t":"大堤女","f":"五言绝句","c":["大堤群女郎，各各自言好。","愁杀襄阳儿，白日情颠倒。"]},{"t":"长干行二首 其一","f":"五言绝句","c":["爷娘错嫁女，嫁与长干商。","今年发滟滪，明年发浔阳。"]},{"t":"长干行二首 其二","f":"五言绝句","c":["爷娘错嫁女，嫁与江陵贾。","八月下潇湘，九月下扬子。"]},{"t":"估客乐二首 其一","f":"五言绝句","c":["乐哉估客乐，黄金作铜使。","大艑乘长风，峨岢发扬子。"]},{"t":"估客乐二首 其二","f":"五言绝句","c":["乐哉估客乐，鱼虾贱如泥。","愁杀闺中妇，玉箸镇长啼。"]},{"t":"新估客乐二首 其一","f":"五言绝句","c":["不从估客游，不知估客乐。","百万扬州鹾，持筹胜骑鹤。"]},{"t":"新估客乐二首 其二","f":"五言绝句","c":["不乘估客舟，不知估客乐。","十万荆州娘，红妆照罗幕。"]},{"t":"大道曲","f":"五言绝句","c":["翠袖紫罗襦，胡床坐明玉。","相逢谢镇西，邀作大道曲。"]},{"t":"前溪歌","f":"五言绝句","c":["春蚕挂门口，抱丝向床前。","镜昏不见面，施朱红可怜。"]},{"t":"自君之出矣","f":"五言绝句","c":["自君之出矣，鸾镜黯无光。","不嫌红粉污，持底试新妆。"]},{"t":"娇女诗","f":"五言绝句","c":["莫愁年少女，十五嫁卢家。","雕梁双紫燕，白日坐飞花。"]},{"t":"江陵女","f":"五言绝句","c":["女郎大堤游，顾影各言好。","相逢平乐儿，班荆坐芳草。"]},{"t":"黄鹄歌二首 其一","f":"五言绝句","c":["黄鹄参天飞，高高上寥廓。","游戏青云中，那能顾燕雀。"]},{"t":"黄鹄歌二首 其二","f":"五言绝句","c":["黄鹄参天飞，九万忽如驰。","当时戢羽翼，燕雀那得知。"]},{"t":"石城曲二首 其一","f":"五言绝句","c":["踏青无限好，江头二三月。","恨杀浔阳风，吹郎下三峡。"]},{"t":"石城曲二首 其二","f":"五言绝句","c":["迎欢不下堂，送欢不出户。","生憎扬子潮，随郎过瓜步。"]},{"t":"清溪小姑","f":"五言古诗","c":["小姑青溪曲，大姑赤山矶，独处谁相依。"]},{"t":"白石郎","f":"古风","c":["侬居清溪，郎居白石。","途中相遇，宛若旧识。"]},{"t":"采莲曲四首 其一","f":"五言绝句","c":["采莲复采莲，摇荡木兰船。","日暮湖头雨，罗裙色倍鲜。"]},{"t":"采莲曲四首 其二","f":"五言绝句","c":["侬棹湖心舟，郎来湖北岸。","笑指双鸳鸯，戏掷黄金弹。"]},{"t":"采莲曲四首 其三","f":"五言绝句","c":["荷叶如侬衣，荷花似侬面。","舣棹向中流，欢来倩谁辨。"]},{"t":"采莲曲四首 其四","f":"五言绝句","c":["昨夜芙蓉花，缘堤一时发。","清波照玉腕，下有双罗袜。"]},{"t":"出塞曲五首 其一","f":"五言绝句","c":["大猎渔阳罢，椎牛上谷营。","酒阑飞骑去，夜夺受降城。"]},{"t":"出塞曲五首 其二","f":"五言绝句","c":["日暮寒风起，长城雪夜飞。","一军齐逐北，二鼓过金微。"]},{"t":"出塞曲五首 其三","f":"五言绝句","c":["拔剑追强敌，黄尘际碧天。","固原风雨黑，前队缚呼延。"]},{"t":"出塞曲五首 其四","f":"五言绝句","c":["汉壁风烟静，霜天帐幕低。","双雕何处落，大碛五原西。"]},{"t":"出塞曲五首 其五","f":"五言绝句","c":["画角霜天下，辕门彻夜开。","梅花飞不尽，月色满轮台。"]},{"t":"读曲歌四首 其一","f":"五言绝句","c":["窗前安石榴，花开正见汝。","百舌枝上啼，含情不得语。"]},{"t":"读曲歌四首 其二","f":"五言绝句","c":["园中樱桃熟，朝暮倩人守。","昨宵摘遗欢，累累不盈篓。"]},{"t":"读曲歌四首 其三","f":"五言绝句","c":["懊恼枇杷实，核多而肉少。","不疗腹中饥，那禁眼中饱。"]},{"t":"读曲歌四首 其四","f":"五言绝句","c":["郎遗佛手柑，馨香动弥月。","报郎红豆子，相思永无歇。"]},{"t":"秋闺曲二首 其一","f":"五言绝句","c":["八月秋风起，揄关正雪花。","何因吹妾梦，万里到龙沙。"]},{"t":"秋闺曲二首 其二","f":"五言绝句","c":["日把金钱卜，征人尚未还。","龙城五千里，目断望夫山。"]},{"t":"子夜歌四首 其一","f":"五言绝句","c":["开门得欢书，有鱼长尺一。","不知溪头鲤，认作潭中鲫。"]},{"t":"子夜歌四首 其二","f":"五言绝句","c":["子度饶芳香，子都好容鬓。","触目俱可怜，身今阿谁近。"]},{"t":"子夜歌四首 其三","f":"五言绝句","c":["懊恨负情侬，薄于下秋叶。","持刀截乱丝，肝肠中半裂。"]},{"t":"子夜歌四首 其四","f":"五言绝句","c":["灯前骤相见，含情不敢道。","乍可要郎眠，那能就郎抱。"]},{"t":"丁都护","f":"五言绝句","c":["徙倚木兰花，流光莫虚度。","人命无百年，听唱丁都护。"]},{"t":"明下童","f":"五言绝句","c":["谁家少儿郎，绿丝作单裤。","白马紫游缰，蹀躞长干路。"]},{"t":"欢闻变歌二首 其一","f":"五言绝句","c":["青梅绕树头，若个不作酸。","君行有两意，莫恋故所欢。"]},{"t":"欢闻变歌二首 其二","f":"五言绝句","c":["十月芙蓉花，九月杨柳树。","那得男儿心，长若初相遇。"]},{"t":"杨叛儿","f":"五言绝句","c":["可怜白门柳，依依二三月。","一曲杨叛儿，飞花乱如雪。"]},{"t":"江南乐","f":"五言绝句","c":["举头见欢来，回桡蔽莲叶。","不知湖心娘，湿透双罗袜。"]},{"t":"幽州马行客歌","f":"五言绝句","c":["恼杀燕台騧，发足千里远。","只解驮郎行，不解送郎转。"]},{"t":"阿子歌","f":"五言绝句","c":["阿子住东邻，自矜好颜色。","春风动罗帷，半夜邀欢入。"]},{"t":"湖就姑","f":"五言绝句","c":["大姑住湖口，便风渡浔阳。","小姑住湖心，月明就彭郎。"]},{"t":"上声歌","f":"五言绝句","c":["春蚕空有丝，不解双双眠。","垂杨空有丝，不绾别离船。"]},{"t":"折杨柳","f":"五言绝句","c":["恨杀城南柳，丝丝管离别。","殷勤折赠君，记取艳阳月。"]},{"t":"越城曲","f":"五言绝句","c":["矶头日浣纱，春波泻明玉。","指点苧罗村，侬家在山麓。"]},{"t":"春江行","f":"五言绝句","c":["一夜春江涨，江头浪拍天。","中流便风起，持底挽郎船。"]},{"t":"双行缠","f":"五言绝句","c":["绣作双行缠，步步娇春阳。","那知罗袜中，两足如秋霜。"]},{"t":"陇头歌五首 其一","f":"五言绝句","c":["尘起玉门关，雕弓马上弯。","身随汉飞将，乘月夺天山。"]},{"t":"陇头歌五首 其二","f":"古风","c":["番人吹筚?，汉女拨琵琶。","征人三十万，若个不思家。"]},{"t":"陇头歌五首 其三","f":"五言绝句","c":["绝塞少人行，萧萧过雁鸣。","征衣犹未寄，大雪满龙城。"]},{"t":"陇头歌五首 其四","f":"五言绝句","c":["欲寄征人信，难禁玉箸啼。","惟应纸上泪，点滴到辽西。"]},{"t":"陇头歌五首 其五","f":"五言绝句","c":["空闺一枕梦，杳杳边头去。","双弯不出门，也到黄花戍。"]},{"t":"从军五更转五首 其一","f":"五言绝句","c":["一更边月上，流影照长城。","营门击刁斗，万队寂无声。"]},{"t":"从军五更转五首 其二","f":"五言绝句","c":["二更边月高，战士揽征袍。","何时封定远，霜露湿弓刀。"]},{"t":"从军五更转五首 其三","f":"五言绝句","c":["三更边月斜，戍客夜思家。","瓜期殊未及，肠断听悲笳。"]},{"t":"从军五更转五首 其四","f":"五言绝句","c":["四更边月隐，征人梦初醒。","恨杀城南妇，流光伴孤枕。"]},{"t":"从军五更转五首 其五","f":"五言绝句","c":["五更边月落，晨起清油幕。","飞骑夺天山，王庭空大漠。"]},{"t":"长安四时辞四首 其一","f":"五言绝句","c":["携手七香车，春风向狭斜。","燕姬年二八，烂醉碧桃花。"]},{"t":"长安四时辞四首 其二","f":"五言绝句","c":["太液池边路，轻舟荡绿荷。","三千汉宫女，齐唱采莲歌。"]},{"t":"长安四时辞四首 其三","f":"五言绝句","c":["寂寂霜天下，寒砧捣月明。","长安十万户，一夜尽秋声。"]},{"t":"长安四时辞四首 其四","f":"五言绝句","c":["红袖炙瑶笙，夜醉平原馆。","拂曙共鸣珂，天街雪花满。"]},{"t":"燕京曲","f":"五言绝句","c":["绰约两青娥，一笑遥相遇。","何处问侬家，玉河双柳树。"]},{"t":"古意","f":"五言绝句","c":["玉帐结流苏，金鞭照春色。","二八艳名姝，尊前乍相识。"]},{"t":"侠少行二首 其一","f":"五言绝句","c":["白马跃金环，扬鞭大道间。","五陵春草色，日暮臂鹰还。"]},{"t":"侠少行二首 其二","f":"五言绝句","c":["呼卢夜来家，醉眠不知曙。","忽忆灞陵游，拔刀冲雪去。"]},{"t":"夜渡娘","f":"五言绝句","c":["翩翩桃叶舟，昏黑向江夏。","那怕狂风吹，佳期在梁下。"]},{"t":"江陵曲","f":"五言绝句","c":["恼欢青丝笮，凌晨只欲开。","狂风趁心起，四面石尤来。"]},{"t":"映江曲","f":"五言绝句","c":["夹岸千桃花，红晕双蛾绿。","恼杀冶游儿，丝鞭映江曲。"]},{"t":"青阳度","f":"五言绝句","c":["金犊游东郊，玉骢返西路。","相逢无一言，脉脉青阳度。"]},{"t":"长乐佳","f":"五言绝句","c":["深宫斗百草，嬉游共春日。","蝴蝶双飞来，故上搔头立。"]},{"t":"白符鸠","f":"五言绝句","c":["以我双碧桃，系欢双紫骝。","相逢那得去，听唱白符鸠。"]},{"t":"同生曲","f":"五言绝句","c":["妾貌娇如花，郎颜粲于玉。","妾年方二八，郎年正十六。"]},{"t":"来罗","f":"五言绝句","c":["池上双鸳鸯，钗头孤凤凰。","双飞太无赖，孤宿斗谁强。"]},{"t":"拔蒲","f":"五言绝句","c":["拔蒲复拔蒲，六月湖水中。","纤纤十春笋，不肯露青葱。"]},{"t":"孟珠","f":"五言绝句","c":["誇他孟珠富，却笑陶朱贫。","西施老归越，空作苧罗颦。"]},{"t":"黄淡思","f":"五言绝句","c":["今生作女郎，万恨攒眉头。","来生作儿郎，饥饿亦自由。"]},{"t":"白头吟四首 其一","f":"五言绝句","c":["巴江九曲流，不似儿郎心。","蜀魄千年啼，是侬白头吟。"]},{"t":"白头吟四首 其二","f":"五言绝句","c":["大车乘驷马，扬扬汉天使。","不记当垆日，辛苦临邛肆。"]},{"t":"白头吟四首 其三","f":"五言绝句","c":["箱中犊鼻裈，碎破不堪著。","回身掷向郎，将心自摸索。"]},{"t":"白头吟四首 其四","f":"五言绝句","c":["当日临邛妻，今朝茂陵妾。","金茎半勺露，那能救消渴。"]},{"t":"长史变二首 其一","f":"五言绝句","c":["懊恼爷娘痂，贪他门户热。","措大作官人，儿命薄于叶。"]},{"t":"长史变二首 其二","f":"五言绝句","c":["宁作中人妇，莫作上官妻。","风波起平地，山岳移东西。"]},{"t":"捉搦歌四首 其一","f":"五言绝句","c":["爷娘养女儿，但教学针线。","许嫁前溪郎，十五不相见。"]},{"t":"捉搦歌四首 其二","f":"五言绝句","c":["采桑南陌头，田间日来往。","傍人指笑侬，夫婿渐成长。"]},{"t":"捉搦歌四首 其三","f":"五言绝句","c":["阿母教女儿，殷勤候姑眠。","女儿问阿母，若为得欢怜。"]},{"t":"捉搦歌四首 其四","f":"五言绝句","c":["十四嫁官人，抱衾作小妻。","终朝大妇骂，眼泪洗面啼。"]},{"t":"采桑渡二首 其一","f":"五言绝句","c":["不采陌上桑，蚕在筐中饥。","欲采陌上桑，使君道傍嬉。"]},{"t":"采桑渡二首 其二","f":"五言绝句","c":["采桑作罗绮，总为他人忙。","不见长干娼，一曲衣盈箱。"]},{"t":"雀劳利二首 其一","f":"五言绝句","c":["禾傍雀啄啄，日暮不得饱。","人生无百年，别家太草草。"]},{"t":"雀劳利二首 其二","f":"五言绝句","c":["丈夫各有志，不作笼中鸡。","朝歌猛虎吟，暮从野雀栖。"]},{"t":"白铜鞮","f":"五言绝句","c":["郭郎巾折角，孟嘉帽频落。","底似山翁醉，接䍦翻转著。"]},{"t":"乌夜啼二首 其一","f":"五言绝句","c":["期欢中夜来，月光满庭柱。","展转天欲明，乌啼石城树。"]},{"t":"乌夜啼二首 其二","f":"五言绝句","c":["匆匆金犊车，上路正天晓。","不恨欢来迟，但恨欢去早。"]},{"t":"赵瑟曲","f":"古风","c":["轻盈窕窈邯郸姬，挟琴鸣弦声乍希，梁尘拂空霜霰飞。","霜霰飞，云雾集，月西沈，日东出。"]},{"t":"秦笙曲","f":"古风","c":["呼卢一掷百万强，妖姬如花出咸阳，筝声嘹呖夜何长。","夜何长，管弦列，遏流云，弄华月。"]},{"t":"江南弄","f":"古风","c":["秋江日暮天无云，兰舟桂楫何纷纷，美人如花簇罗裙。","簇罗裙，斗玉腕，歌采菱，归去晚。"]},{"t":"龙笛曲","f":"古风","c":["楚山修竹云团栾，伶伦截管飞青鸾，美人一曲凭雕阑。","凭雕阑，弄纤手，落梅花，折杨柳。"]},{"t":"凤笙曲","f":"古风","c":["红炉炽炭玉筦骄，谁其吹者王子乔，羽衣玉氅行逍遥。","行逍遥，听仙乐，万桃花，两玄鹤。"]},{"t":"乌栖曲五首 其一","f":"七言绝句","c":["步障华灯光照屋，质如轻云色如玉。","白马金环游狭斜，杨柳啼乌来妾家。"]},{"t":"乌栖曲五首 其二","f":"七言绝句","c":["郁金为堂玳瑁梁，床上流苏百合香。","同心宝带合欢结，携手邀郎拜明月。"]},{"t":"乌栖曲五首 其三","f":"七言绝句","c":["锦幔银屏张五采，华堂宿雾笼香霭。","此时心意两相怜，含娇顾影不自前。"]},{"t":"乌栖曲五首 其四","f":"七言绝句","c":["叠股钗横金凤凰，连环交结双鸳鸯。","啼乌哑哑楚天曙，荏苒容华逐郎去。"]},{"t":"乌栖曲五首 其五","f":"七言绝句","c":["玳筵张烛三星低，罗襟绣褥怯分携。","郎骑白马去关西，凤凰台前乌夜啼。"]},{"t":"塞上曲八首 其一","f":"七言绝句","c":["白草连天大漠秋，千家铙吹古梁州。","飞霜为洗燕然石，上客新从定远侯。"]},{"t":"塞上曲八首 其三","f":"七言绝句","c":["接天烽火照平卢，乍夜单于猎上都。","十万征人明月里，一时齐挽绣蝥弧。"]},{"t":"塞上曲八首 其四","f":"七言绝句","c":["绝碛霜飞塞草空，燕支晴色乱云中。","将军醉拥吴钩出，万里霜天照白虹。"]},{"t":"塞上曲八首 其五","f":"七言绝句","c":["冢上明妃草色青，征人立马问龙庭。","西风片月秦城下，愁绝胡笳几处听。"]},{"t":"塞上曲八首 其七","f":"七言绝句","c":["战马骄腾大漠间，遥看敌骑薄阴山。","横戈不待嫖姚令，静扫边尘入汉关。"]},{"t":"塞上曲八首 其八","f":"七言绝句","c":["边烽不动边尘收，刁斗无声夜色流。","醉杀歌姬油幕底，霜天遥按小凉州。"]},{"t":"春宫曲四首 其一","f":"七言绝句","c":["昨夜春风拂苑墙，三千南内斗红妆。","朝来凤辇花前过，报道君王入上阳。"]},{"t":"春宫曲四首 其二","f":"七言绝句","c":["残雪初消太液前，御沟晴日柳如烟。","披香殿上承恩早，千缕黄金拂御筵。"]},{"t":"春宫曲四首 其三","f":"七言绝句","c":["长门花满月华高，云锁珠帘护碧桃。","夜静南宫歌吹发，新声遥奏郁轮袍。"]},{"t":"春宫曲四首 其四","f":"七言绝句","c":["玉阶草色上窗纱，深锁葳蕤隔翠华。","添罢晚妆无一事，白樱桃下试琵琶。"]},{"t":"秋宫词","f":"七言绝句","c":["梧桐飞叶下银床，肠断秋声玉漏长。","三十六宫明月里，夜听弦管出朝阳。"]},{"t":"少年行五首 其一","f":"七言绝句","c":["匣底双龙斗色流，长安道上紫骅骝。","燕姬二八弹筝坐，千树垂杨拂酒楼。"]},{"t":"少年行五首 其二","f":"七言绝句","c":["平康归路欲黄昏，下马青蛾白玉尊。","一曲菱歌挥袂去，月明装束候期门。"]},{"t":"少年行五首 其三","f":"七言绝句","c":["五陵楼殿雪初消，玉勒翩翩意气骄。","落日万家春草外，呼鹰遥过灞陵桥。"]},{"t":"少年行五首 其四","f":"七言绝句","c":["甲第新开上苑边，满堂花色照婵娟。","醉携如意阶前舞，七尺珊瑚碎画筵。"]},{"t":"少年行五首 其五","f":"七言绝句","c":["调鞭徐傍夕阳亭，绣箙雕弧架雁翎。","夹路万人齐指处，碧天遥堕海东青。"]},{"t":"剑客行","f":"七言绝句","c":["双丸耳畔雪花明，九陌长安任意行。","片语楼中无处觅，夜飞龙蹻入青城。"]},{"t":"游仙词十首 其一","f":"七言绝句","c":["玉检金泥柱下藏，书成函谷暂徜徉。","流沙一望三千里，遥跨青牛出大荒。"]},{"t":"游仙词十首 其二","f":"七言绝句","c":["玄圃明霞望不穷，金银楼殿碧天中。","春风似识周王面，乍夜蟠桃万树红。"]},{"t":"游仙词十首 其三","f":"七言绝句","c":["百辟衣冠照鼎湖，轩辕台殿夕阳孤。","云间独跨双龙背，万顷天风堕鹿卢。"]},{"t":"游仙词十首 其四","f":"七言绝句","c":["七步文章焕斗牛，遮须聊作御风游。","狂挥大笔天河畔，题遍瑶京十二楼。"]},{"t":"游仙词十首 其五","f":"七言绝句","c":["羽盖如云下夕阳，俱言浮海谒东皇。","麻姑夜擘红虬脯，指爪偷看一尺长。"]},{"t":"游仙词十首 其六","f":"七言绝句","c":["采石船头月溅衣，长鲸高擘绛霞飞。","安期一见如相识，指点蓬莱万玉妃。"]},{"t":"游仙词十首 其七","f":"七言绝句","c":["洞里青霞照玉盘，飞星群洒石门寒。","桃花五报西池发，可奈峰头局未残。"]},{"t":"游仙词十首 其八","f":"七言绝句","c":["缥缈飞梁驾赤城，漫劳司马问初平。","金泥玉版长生籍，同向丹台列姓名。"]},{"t":"游仙词十首 其九","f":"七言绝句","c":["少室峰高接绛河，千秋词客斗嵯峨。","谁言不是灵仙骨，遥夜天姝出大罗。"]},{"t":"游仙词十首 其十","f":"七言绝句","c":["海上朱明碧雾流，五仙同跨五羊游。","何如野客金华洞，卧领群羊十万头。"]},{"t":"云龙引","f":"七言绝句","c":["芒砀秋空映赭袍，龙光云气与天高。","五湖何处无明月，斫竹南山坐钓鳌。"]},{"t":"后采莲曲二首 其一","f":"七言绝句","c":["画舫青丝荡绿油，罗裙玉腕坐中流。","生来菡萏元同蒂，若个芙蓉不并头。"]},{"t":"后采莲曲二首 其二","f":"七言绝句","c":["湖心涛浪拍天流，湖上王孙挟弹游。","一派莲歌何处起，大堤齐控紫骅骝。"]},{"t":"明妃曲","f":"七言绝句","c":["目断长安汉使来，五云何处是蓬莱。","龙沙月色三千里，独抱琵琶上紫台。"]},{"t":"凉州词","f":"七言绝句","c":["静夜流云拂画檐，微风不动水晶帘。","红牙拍按瑶台上，古调初翻昔昔盐。"]},{"t":"伊州曲","f":"七言绝句","c":["碧天如水暮云收，明月平铺翡翠楼。","楼上美人三十六，夜弹瑶瑟唱伊州。"]},{"t":"横江词二首 其一","f":"七言绝句","c":["结束腰肢赛水神，沙棠舟楫往来频。","江风日暮连天起，愁杀西陵破浪人。"]},{"t":"横江词二首 其二","f":"七言绝句","c":["扬子江头风色狂，白波如山五丈强。","自是吴姬惯迎客，来来去去木兰航。"]},{"t":"从军行五首 其一","f":"七言绝句","c":["大漠秋风吹铁衣，长城明月满征旗。","捷书飞奏明光殿，乍夜前军获郅支。"]},{"t":"从军行五首 其二","f":"七言绝句","c":["九月边头朔气残，贺兰山北望长安。","殷勤去雁传消息，欲寄征衣趁早寒。"]},{"t":"从军行五首 其三","f":"七言绝句","c":["寥天霜色暮凄凄，无定河边落日低。","欲问轮台前去路，黄云白草遍辽西。"]},{"t":"从军行五首 其四","f":"七言绝句","c":["吹笛关山月半痕，梅花无数落辕门。","不知何处旄头现，一夜渔阳万骑屯。"]},{"t":"从军行五首 其五","f":"七言绝句","c":["白马将军惯渡辽，笑提金勒扫氛嚣。","五千剑客当前队，尽款名王入汉朝。"]},{"t":"北院词八首 其一","f":"七言绝句","c":["紫燕双飞拂画梁，雕甍百尺隐垂杨。","东华门外诸年少，携手先过白玉堂。"]},{"t":"北院词八首 其二","f":"七言绝句","c":["西第千门簇五侯，御沟春水逐人流。","罘罳烂漫黄金色，遥指梳妆近妾楼。"]},{"t":"北院词八首 其三","f":"七言绝句","c":["金水桥边一百家，家家帘幕护桃花。","青衣日暮浓妆出，指点萧郎白鼻騧。"]},{"t":"北院词八首 其四","f":"七言绝句","c":["珠帘不动控银钩，内苑春光入画楼。","深夜月明弦管沸，露桃花下合梁州。"]},{"t":"北院词八首 其五","f":"七言绝句","c":["双双罗袜斗凌波，两两沙棠泛玉河。","日暮大堤流水急，回桡齐唱采莲歌。"]},{"t":"北院词八首 其六","f":"七言绝句","c":["别开金屋倚岧峣，白玉河边第二桥。","夹岸紫骝三十骑，花时齐过董娇娆。"]},{"t":"北院词八首 其七","f":"七言绝句","c":["绮陌东头接上阳，娉婷年少舞霓裳。","怪来香阁时常闭，尽日浓妆对海棠。"]},{"t":"北院词八首 其八","f":"七言绝句","c":["灵济宫前翠幕悬，平康门巷百花连。","西园公子携宾过，十六青娥舞玳筵。"]},{"t":"南院词八首 其一","f":"七言绝句","c":["浮云楼观接蓬莱，五岳三山大内开。","昨夜春风城外过，千花齐发凤凰台。"]},{"t":"南院词八首 其二","f":"七言绝句","c":["公子连翩挟弹游，垂杨偏拂紫骅骝。","长干巷里三千队，若个新妆是莫愁。"]},{"t":"南院词八首 其三","f":"七言绝句","c":["紫燕衔泥度夕阳，双飞南陌认雕梁。","高门不用寻王谢，卢女新开白玉堂。"]},{"t":"南院词八首 其四","f":"七言绝句","c":["欢作沈香侬博山，双烟一气紫霞间。","千门柳色啼鸦暮，自唤情人月下攀。"]},{"t":"南院词八首 其五","f":"七言绝句","c":["桃叶年方十五强，春波摇荡木兰航。","不知何事归来晚，狂杀王家白面郎。"]},{"t":"南院词八首 其六","f":"七言绝句","c":["万户千门玉作台，春风何地不徘徊。","乌衣巷口红妆亚，一路歌声斗草回。"]},{"t":"南院词八首 其七","f":"七言绝句","c":["垂杨千树拂红尘，压酒吴姬动绛唇。","日暮狂风连袂起，飞花愁杀渡江人。"]},{"t":"南院词八首 其八","f":"七言绝句","c":["城下春江抱石头，秣陵南下是瓜洲。","相邀女伴寻春去，共掷金钱赛蒋侯。"]},{"t":"燕京四时词四首 其一","f":"七言绝句","c":["帝阙皇居北斗间，春风长绕玉门关。","东郊昨夜桃花发，一树先开万岁山。"]},{"t":"燕京四时词四首 其二","f":"七言绝句","c":["沈李浮瓜燕玉台，冰山雪谷倚蓬莱。","珠帘百尺重重下，不放人间赤日来。"]},{"t":"燕京四时词四首 其三","f":"七言绝句","c":["千叶从风尽报秋，长门团扇迥添愁。","玉河桥畔东流水，几处题红出御沟。"]},{"t":"燕京四时词四首 其四","f":"七言绝句","c":["玉宇吹花度柏梁，千门飞雪夜茫茫。","银笙暗炙红炉畔，一曲阳春漏正长。"]},{"t":"长门怨四首 其一","f":"七言绝句","c":["罗幌飞萤玉露漙，珠帘不捲坐更阑。","昭阳月色浑无赖，才到长门特地寒。"]},{"t":"长门怨四首 其二","f":"七言绝句","c":["锁闭葳蕤绝履綦，宫花犹发万年枝。","沈香亭北无穷恨，尽在阑干独倚时。"]},{"t":"长门怨四首 其三","f":"七言绝句","c":["凤吹喧传隔彩霞，龙旂摇曳暮云斜。","预知行幸平阳宅，不用庭前望翠华。"]},{"t":"长门怨四首 其四","f":"七言绝句","c":["金屋妆成尽日閒，十年红粉误朱颜。","腰肢漫自誇纤细，管领华清是玉环。"]},{"t":"青楼曲八首 其一","f":"七言绝句","c":["十里秦楼近灞桥，箫声何处起岧峣。","珠帘百尺东风里，双凤联翩逐翠翘。"]},{"t":"青楼曲八首 其二","f":"七言绝句","c":["粉面三千照玉台，期门南去是蓬莱。","金鞭暮过张公子，一骑潜呼万乘来。"]},{"t":"青楼曲八首 其三","f":"七言绝句","c":["两浆频催过石城，沙棠摇曳画船明。","莫愁湖上千株柳，肠断王孙作队行。"]},{"t":"青楼曲八首 其四","f":"七言绝句","c":["一树含桃锁曲房，金笼鹦鹉唤斜阳。","霍家娘子新妆罢，拥髻来迎李十郎。"]},{"t":"青楼曲八首 其五","f":"七言绝句","c":["苏小妆楼隔画桥，涌金门外半兰桡。","相携女伴巫山去，昨夜钱塘正上潮。"]},{"t":"青楼曲八首 其六","f":"七言绝句","c":["指点平康宿暮鸦，妆台红粉簇明霞。","曲江筵上诸先辈，跃马争寻阿润家。"]},{"t":"青楼曲八首 其七","f":"七言绝句","c":["二八青衣彩袖悬，相逢如梦画堂前。","无端锦瑟撩春思，历乱东风五十弦。"]},{"t":"青楼曲八首 其八","f":"七言绝句","c":["银床梧叶堕高秋，良夜吹箫忆旧游。","二十四桥天似水，画船乘月下扬州。"]},{"t":"拟古二十首 其一","f":"五言古诗","c":["严霜结重阴，岁序忽已暮。","念子当远游，抗手即行路。","路行常苦远，客归尝苦晚。","浮云蔽关塞，白日不可挽。","昔为婚与姻，今为越与秦。","落叶随飘风，飞鸿辞故群。","君心岂难保，妾颜匪长好。","登高望平原，四顾尽衰草。","相思无朝夕，沈忧令人老。","愿为双车轮，随君万里道。"]},{"t":"拟古二十首 其二","f":"五言古诗","c":["郁郁城东门，盈盈桃与李。","抽条仲春月，秾艳若罗绮。","轩车竞采掇，日暮未言止。","如何秋风生，摇落自兹始。","寄语青楼倡，盛颜难久恃。"]},{"t":"拟古二十首 其三","f":"五言古诗","c":["清晨策驽马，整辔南山隅。","遥望长安城，飞观百尺馀。","峨峨青云端，甲第罗长衢。","华镳若流水，轩盖何威纡。","各骋要路津，盈盈道中趋。","人生若飞藿，奄忽随丘墟。","盛衰各有极，贵贱同斯须。","何如命我友，斗酒鸣笙竽。","逍遥放情志，卒岁聊自娱。"]},{"t":"拟古二十首 其四","f":"五言古诗","c":["令节怀嘉宾，亲友四面会。","轩车若云屯，高谈尽冠盖。","旨酒罗长筵，新声动环佩。","秦筝响未毕，楚袖盈庭内。","同心竞酬酢，羽觞互更代。","各言行乐殊，少壮不相待。","劳生徇荣华，日月忽已迈。","千秋万世尽，贤圣亦焉在。"]},{"t":"拟古二十首 其五","f":"五言古诗","c":["绮楼亘中天，窈窕百馀尺。","飞甍架复道，藻井纵横出。","上有双蛾眉，容华世无匹。","临风发皓齿，当户理瑶瑟。","新声入云汉，四座咸动色。","行人竞倾听，日暮不遑息。","但睹来者欢，谁明居者臆。","盛年处空闺，中夜起悽恻。"]},{"t":"拟古二十首 其六","f":"五言律诗","c":["采采丛兰花，美人隔江沚。","褰裳涉其波，舟楫谁为理。","回风动罗裳，日暮聊徒倚。","安得双鸳鸯，衔致箧中绮。"]},{"t":"拟古二十首 其七","f":"五言古诗","c":["客游异乡县，终岁怀苦辛。","忧思起长夜，展转不得晨。","举头望河汉，怅彼参与辰。","畴昔同盟友，金石偕交亲。","飞飞振六翮，弃我若途人。","我欲东归洛，日暮河无津。","徘徊入房中，涕泪沾衣巾。"]},{"t":"拟古二十首 其八","f":"五言古诗","c":["彼美东邻子，习礼明书诗。","十五登君堂，新婚谐结缡。","愿为双飞鸿，百岁不相离。","风波起中路，忽去天一涯。","不惜去日远，但恐欢爱移。","黄尘蔽关塞，会合无前期。","愿君策高足，努力趋明时。","生当聚华堂，死当长别离。"]},{"t":"拟古二十首 其九","f":"五言古诗","c":["灼灼芳树枝，敷荣一何早。","绿条被繁英，初日何杲杲。","感此芳春时，采掇寄远道。","馨香不终夕，零落随百草。","盛年处空闺，颜色为谁好。"]},{"t":"拟古二十首 其十","f":"五言古诗","c":["严霜瘁百草，节序忽复易。","噭噭双飞雁，云中各自适。","念我同衾人，索处异南北。","披衣望天宇，众星何历历。","牵牛隔河梁，织女限东壁。","徬徨间一水，欲往步难即。","同心复异地，何异不相识。"]},{"t":"拟古二十首 其十一","f":"五言古诗","c":["清晨出大梁，遥瞻北邙道。","野火烧平田，白杨半枯槁。","人生寄宇宙，忽若原上草。","去日常苦多，来日常苦少。","少者日以壮，壮者日趋老。","幻躯无百年，富贵何足保。","思为鲁中圣，万世同寿考。"]},{"t":"拟古二十首 其十二","f":"五言古诗","c":["高城跨东南，大道夷且直。","青楼间绮疏，曈曈照初日。","五陵侠少年，结束事游昵。","白马饰银鞍，连翩度阡陌。","美人遥目成，相对理瑶瑟。","十千轻一笑，百万当一掷。","为乐愿及晨，为欢愿及夕。","红颜匪百岁，何由保金石。"]},{"t":"拟古二十首 其十三","f":"五言古诗","c":["回车灞原上，白日忽将暮。","石门高崔嵬，悲风起长路。","借问何人阡，无乃前朝墓。","人生寄一世，奄忽迅朝露。","荒哉秦汉主，寻仙起遐慕。","弱水不可援，三山竟焉度。","玉碗出人间，徒为赤松误。","伤彼泉下人，喟焉策蹇步。","吹竽宴华堂，娱乐从所务。","飘飘极心志，千载为旦暮。"]},{"t":"拟古二十首 其十四","f":"五言古诗","c":["驱车越长道，还归故里闾。","少小客咸阳，今来廿载馀。","亲知半凋落，冢墓留村墟。","松柏俨成行，狐兔交路衢。","门巷寂无人，谁为问邻居。","停车再叹息，日暮长欷吁。","客行尽九州，不如守敝庐。"]},{"t":"拟古二十首 其十五","f":"五言古诗","c":["浮生若飞蓬，寄迹宇宙间。","万物皆有尽，胡为长苦颜。","旨酒列高台，嘉宾共盘桓。","夜阑当秉烛，日晏当沈酣。","人生无百年，譬彼东逝川。","生者不暂欢，死者宁复还。"]},{"t":"拟古二十首 其十六","f":"五言古诗","c":["昭昭三五夕，皎月流素光。","徘徊入高楼，照我罗衣裳。","揽衣坐叹息，起步仍徬徨。","良人怀远游，九载客他乡。","空闺知岁暮，独处知夜长。","嗷嗷云中雁，随风忽南翔。","安能假羽翼，万里来君傍。"]},{"t":"拟古二十首 其十七","f":"五言古诗","c":["凛凛北风至，霜雪零前除。","惜哉征人妇，岁宴恒寡娱。","夙昔奉衾裯，矢志誓不渝。","如何弃我去，悠悠长路隅。","思君隔天末，邈如秦与越。","欢爱宁复论，铅华为君绝。","君怀如明月，妾心如冰雪。","君怀有圆缺，妾心徒皎洁。"]},{"t":"拟古二十首 其十八","f":"五言古诗","c":["清晨启重关，有客千里至。","手携尺一书，言我故人寄。","长跪问故人，客亦无所言。","开缄读素书，宛若睹所欢。","上有金错刀，下有白玉环。","明月三五满，故人会当返。"]},{"t":"拟古二十首 其十九","f":"五言古诗","c":["仲秋凉气肃，呖呖雁南度。","北斗倚阑干，气运凄以暮。","悲来抚长剑，浩歌起庭户。","一为远方客，永别亲与故。","频夜梦室家，展转忽已寤。","念欲还故乡，按辔遵广路。","悠悠大河水，一苇安可渡。"]},{"t":"拟古二十首 其二十","f":"五言古诗","c":["亭亭孤桐树，托根峄山岑。","良工琢其枝，为我匣中琴。","胶漆相交结，珍重逾南金。","被以朱丝弦，弹以白雪吟。","清音顺风扬，四坐畴同心。","佳人隔天末，日暮涕沾襟。"]},{"t":"又拟古八首 其一","f":"五言古诗","c":["冉冉岁云暮，念君远别离。","浮云蔽原野，四顾白日驰。","夙昔幸同衾，欢爱誓不移。","如何百年好，去我忽若遗。","严风起天末，霜雪盈路歧。","晨起践关山，薄暮长抱饥。","音徽日夜隔，会合当何时。","恨无晨风翼，并起东南飞。"]},{"t":"又拟古八首 其二","f":"五言古诗","c":["高楼有思妇，被服姣且妍。","横琴理清曲，渌水被幽兰。","一弹浮云暮，再鼓流风旋。","哀音振林木，听者为忘餐。","借问何人妇，感叹停朱弦。","征夫越万里，一别岁载迁。","铅华坐销歇，太息空婵娟。"]},{"t":"又拟古八首 其三","f":"五言古诗","c":["灼灼园中花，盈盈道傍柳。","敷荣艳阳月，攀折佳人手。","秋风一朝至，容耀讵能久。","人生寄天地，聚散何不有。","俛仰百岁间，倏忽成老丑。","身名匪金石，富贵欲谁守。","怡我平生亲，独有盈尊酒。"]},{"t":"又拟古八首 其四","f":"五言古诗","c":["肃肃金风至，大火时西流。","游子异乡县，中夜怀百忧。","驱车驾言迈，奄忽岁已秋。","登高望故里，江汉何悠悠。","佳人在远道，欲济无轻舟。","同心日夜隔，涕泪纵横流。","愿为南飞翼，万里行相求。"]},{"t":"又拟古八首 其五","f":"五言古诗","c":["朝登北邙山，徘徊望陵谷。","荒坟何累累，狐兔自相触。","白杨夹修途，黄泉蔽层曲。","伤彼潜寐人，年命一何速。","生存宇宙间，行乐苦不足。","驱车暮归来，鸣筝燕华屋。","北里扬清音，南邻荐新曲。","亲知从我游，被御纨与縠。","相对各尽觞，良夜更秉烛。","荣名耀百代，转盼同初旭。","亮无乔松寿，谁能伤局促。"]},{"t":"又拟古八首 其六","f":"五言古诗","c":["青鸟从南来，翩翩随风翔。","口衔尺书至，乃自大海傍。","美人三岁别，沈忧热中肠。","织成机中锦，拂拭烂生光。","下为连理枝，上为双凤凰。","致之万里道，聊以充君床。","愿言勖斯义，旦夕毋相忘。"]},{"t":"又拟古八首 其七","f":"五言古诗","c":["回风吹转蓬，倏忽行万里。","游子怀山川，驱车暮不止。","荒郊四无人，日入断行旅。","熊罴向我啼，僮仆为我侣。","南望见故乡，失路空徙倚。","眷彼平生亲，气结不能语。"]},{"t":"又拟古八首 其八","f":"五言古诗","c":["东邻有美质，杂佩何缤纷。","明眸辉朝日，绝代少其伦。","结缡为君妇，婉娈日偕亲。","风波起闺闼，中道成荆榛。","君为东流水，妾若西路尘。","东西各相背，信誓何由闻。","红颜会当歇，岂不怀苦辛。","愿君企高节，贱妾宁复云。"]},{"t":"古离别二首 其一","f":"五言古诗","c":["戚戚远行子，驾言还旧疆。","脂车望关塞，愿逐晨风翔。","主人卜清夜，置酒临高堂。","妙伎出闺闼，纤腰移曲房。","当筵发皓齿，四坐流芬芳。","回飙袭绮户，飞霜飘长廊。","良宵一何促，瑶瑟无辉光。","征夫念明发，握手起徬徨。","仰视云中雁，三五各成行。","胡为双飞龙，羽翼多参商。","丈夫志万里，会晤安可常。","勖哉就长路，皓首期相望。"]},{"t":"古离别二首 其二","f":"五言古诗","c":["驱车出郭门，徘徊望都邑。","念我平生亲，聚散何仓卒。","白露涂中逵，清霜被原隰。","惊飙动地起，黄叶无宁夕。","羁禽怀故林，疲马倦行役。","群雁西南翔，哀音正嘹呖。","岂无盈尊酒，执手歧路侧。","飞觞属华筵，行子相向立。","别离在须臾，沈忧万端集。","去去勿复论，红颜中道掷。"]},{"t":"杂诗四首 其一","f":"五言古诗","c":["明河没天宇，白露晨为霜。","眷彼同心人，忽去天一方。","仓皇挈尊酒，送子河之梁。","登高望四野，川陆浩纵横。","岂无瑶华音，道远不得将。","揽衣入房户，驰念忽如伤。"]},{"t":"杂诗四首 其二","f":"五言古诗","c":["曜灵薄崦嵫，光景忽已夕。","圆魄犹未升，明星烂然出。","寒蛩号我前，蟋蟀鸣我侧。","凉风起庭户，树木何萧瑟。","佳人期不来，延伫空叹息。","宁知三岁心，为子长恻恻。"]},{"t":"杂诗四首 其三","f":"五言古诗","c":["冉冉西驰日，悠悠东逝川。","征夫怨长路，志士惜盛年。","长路行当归，盛年不再还。","寒暑互推移，阴阳浩无端。","凄风起帘幕，白露中夜漙。","美人坐高堂，投袂起长叹。"]},{"t":"杂诗四首 其四","f":"五言古诗","c":["穷阴亘晦朔，山谷多寒风。","悲哉客游子，旋足如转蓬。","昔行届长夏，今来值玄冬。","悠悠十年内，车辙穷寰中。","人生贵适意，遥役何憧憧。","逝将歌考槃，岩穴安微躬。"]},{"t":"寓怀十二首 其一","f":"五言古诗","c":["端居意不适，策杖起行游。","仙人八公侣，携我升蓬丘。","泠泠随风举，衣袂若云浮。","放歌昆崙顶，下视弱水流。","天都信寥廓，绛节聊淹留。","黄金被高馆，白玉开层楼。","乐哉瑶池上，一饮为千秋。"]},{"t":"寓怀十二首 其二","f":"五言古诗","c":["崇兰处深谷，绿叶凌朝阳。","回风一披拂，百里传芬芳。","惜哉丛林下，无人知国香。","烨烨桃李树，托根歧路傍。","飞花落闺闼，弄影临华堂。","讵以盛衰故，易此贞素常。","不见西山老，食薇终首阳。"]},{"t":"寓怀十二首 其三","f":"五言古诗","c":["飘飘穆天子，八骏乘风驰。","日行三万里，远道何不之。","西游见王母，宴饮登蓬池。","千秋蟠桃实，万仞扶桑枝。","寄言谢尘世，百代同须斯。"]},{"t":"寓怀十二首 其四","f":"五言古诗","c":["夷羿射九日，共工触不周。","龙伯连巨鳌，伯鲧湮洪流。","贪嗔起一念，乃与造化仇。","力穷固难继，身灭将谁尤。","巍巍轩辕帝，问道崆峒丘。","唐虞守无为，四灵毕来游。"]},{"t":"寓怀十二首 其五","f":"五言古诗","c":["亭亭孤松树，托根徂徕颠。","高枝翳白日，曲干临回川。","女萝蔚蒙笼，风雷岌相缠。","岂无明堂用，物性贵自然。","一为匠石顾，斤斧成灾患。","何如邓林下，寂寞全天年。"]},{"t":"寓怀十二首 其六","f":"五言古诗","c":["壶丘与天游，列子乘风行。","飘飘漆园吏，九万凌高冥。","胡为末世士，多歧日屏营。","蹻蹠死财利，夷齐徇空名。","宁知大道观，不异蜗与螟。","华胥有逸民，去去行相亲。"]},{"t":"寓怀十二首 其七","f":"五言古诗","c":["弱龄负奇尚，雅志诵坟史。","访岳怀尚生，浮湘慕迁史。","杖策游中原，邂逅二三子。","裘马何翩翩，招要共生死。","经过渐离辈，感激昭王士。","黄金空崔嵬，所愿非尺组。","长揖辞诸侯，归耕汶阳涘。"]},{"t":"寓怀十二首 其八","f":"五言古诗","c":["彼美倾城子，艳色明朝霞。","宝钗耀金雀，充耳佩琼珈。","相如既西席，宋玉仍东家。","春风起罗袂，琴瑟相交加。","但知良时乐，安睹白璧瑕。","托身一失所，百岁徒咨嗟。"]},{"t":"寓怀十二首 其九","f":"五言古诗","c":["昔有夸娥子，猛气雄千兵。","褰裳逞逸足，思欲追曜灵。","逡巡旸谷傍，道渴不任行。","投身死岩穴，骨肉盈林坰。","过浇篡夏室，莽卓乘炎精。","人谋岂不殚，天命俄已倾。","寄言雄图者，割据徒营营。"]},{"t":"寓怀十二首 其十","f":"五言古诗","c":["曰余负奇好，夙尚在髫龄。","礼乐观百王，诗书穷六经。","言乘休明会，将致海宇平。","如何岁年迈，依依卧柴荆。","亮乖四方志，永希千载名。","文章亦大业，富贵宁重轻。","勉哉事著述，三代追遗英。"]},{"t":"寓怀十二首 其十一","f":"五言古诗","c":["丹霞蔽岩谷，素雪霏林皋。","悠悠避世士，岁晏守蓬蒿。","箕山既纡郁，首阳何岧峣。","时偕沮溺侣，耦耕向南郊。","大厦匪安居，千驷为祸招。","悲哉路傍子，磬折方劳劳。"]},{"t":"寓怀十二首 其十二","f":"五言古诗","c":["有鸟从东来，游戏青云中。","朝翔阆风馆，夕息瑶池宫。","言欲览德辉，来下双梧桐。","摇摇荆棘枝，鸱枭宅其丛。","所嗜惟腐鼠，焉知彼所从。","竦身奋六合，将返昆崙东。"]},{"t":"咏史八首 其一","f":"五言古诗","c":["清时厌藜藿，挟策干承明。","肃肃中天宇，列宿悬神京。","衣冠萃阊阖，谒帝罗群英。","如何攀龙客，相弃若浮萍。","长啸出宛洛，驱车返柴荆。","升高望八荒，濯足临四溟。","商山岂不贵，畏垒岂不荣。","大哉鲁尼父，著作垂千龄。"]},{"t":"咏史八首 其二","f":"五言古诗","c":["鲲鱼产溟渤，鬐鬣如山丘。","朝行发碣石，暮宿昆崙陬。","竦身激巨浪，喷沫飞洪流。","倏忽化大鹏，九万乘风游。","翼若垂天云，众羽不敢侔。","一飞绝五岳，再举凌十州。","翩翩鸴鸠侣，榆枋自相求。","翱翔但咫尺，曷睹大化遒。"]},{"t":"咏史八首 其三","f":"五言古诗","c":["飘飘颍中客，黄屋若浮云。","矫矫严陵叟，垂竿卧江濆。","脱屣九州长，长揖万乘君。","弃瓢入深谷，举足动星文。","英风振薄俗，劲节凌高旻。","樊公信独往，周生亦离群。","一朝徇微禄，遗累流千春。"]},{"t":"咏史八首 其四","f":"五言古诗","c":["世途日纡局，达士随所遭。","侯生隐抱关，朱亥匿鼓刀。","鼓刀实贱役，抱关非崇寮。","煌煌魏公子，车骑来招要。","虚左大梁席，执辔夷门郊。","堂中众宾客，错愕起相嘲。","宁知救赵日，叱咤风云高。","窃符出中禁，奋椎夺前矛。","伟哉却秦绩，百代称雄豪。"]},{"t":"咏史八首 其五","f":"五言古诗","c":["虞卿本说客，著书自穷愁。","马迁下蚕室，史笔垂千秋。","楚泽放灵均，漆圆饿庄周。","伊人一何否，举足罹愆尤。","文章实大业，宁与富贵谋。","峨峨金张第，七叶开王侯。","一朝随物化，荣耀同蜉蝣。"]},{"t":"咏史八首 其六","f":"五言古诗","c":["伯夷饿空谷，务光沈清泠。","汤武首征诛，白公徇其名。","嗟哉古贤达，举足罹天刑。","茫茫大造间，遗迹若蟭螟。","升高望宇宙，摄衣御云軿。","追随广成子，乘化入瑶京。","九州一抔土，何以劳我精。","五岳一拳石，聊以栖吾形。"]},{"t":"咏史八首 其七","f":"五言古诗","c":["荆卿卧燕邸，屠狗相过从。","朝为太子客，暮出辽城东。","酣歌和渐离，壮士发尽冲。","前登咸阳殿，意气何其雄。","左操督亢图，右揕秦王胸。","剑术岂云疏，天运良已穷。","寥寥易水上，万古悲寒风。"]},{"t":"咏史八首 其八","f":"五言古诗","c":["田巴辨稷下，缓颊摧千人。","邹生馆碣石，五德何缤纷。","夸夫乐惊世，小人恒共群。","谁明白马喻，徒擅雕龙勤。","岂若鲁连子，笑谈却秦军。","成功不受赏，万乘如浮云。"]},{"t":"入新都访汪司马伯玉八首 其一","f":"五言古诗","c":["芳时忽不乐，怅然思美人。","美人天都上，宫阙何嶙峋。","手把瑶华草，远寄越江濆。","念欲往从之，弱水不可亲。","愧无晨风翼，寤寐怀苦辛。"]},{"t":"入新都访汪司马伯玉八首 其二","f":"五言古诗","c":["轩车何皇皇，东下武林驿。","冠盖罗长衢，嘉宾四面集。","伊余实驽蹇，喟焉伤伏枥。","一顾天闲空，高座倾四席。","眷眷忘年交，惓惓在兹夕。"]},{"t":"入新都访汪司马伯玉八首 其三","f":"五言古诗","c":["欢言奉尊酒，既登君子堂。","不惜罗衣襦，为君充下裳。","宁辞入宫妒，亭亭理红妆。","常恐朝露晞，欢爱不能长。","中宵起房室，引领情内伤。"]},{"t":"入新都访汪司马伯玉八首 其四","f":"五言古诗","c":["峨峨弇山堂，美人在其下。","脂车娄江涘，聊用息余驾。","烨烨双飞龙，连城讵论价。","咨嗟良宴会，朋旧半凋谢。","三星烂河汉，钧天在广厦。"]},{"t":"入新都访汪司马伯玉八首 其五","f":"五言古诗","c":["欢日苦不足，愁日苦有馀。","谈笑未及终，执手河山如。","蒹葭阻长道，渺邈天一隅。","殷忧见华发，岁暮空踟蹰。","焉得抟风翮，送我来枌榆。"]},{"t":"入新都访汪司马伯玉八首 其六","f":"五言古诗","c":["百年迅朝霜，奄忽越与楚。","郁郁琅琊坟，瞬息已千古。","河清邈难俟，中夜频起舞。","歧路安足论，暌离热肺腑。","明发戒沙棠，维梢瀫江浦。"]},{"t":"入新都访汪司马伯玉八首 其七","f":"五言古诗","c":["西上新安江，危滩峻浮云。","太函何巍巍，迥与上界邻。","苍龙守重关，鹓雏日为群。","美人坐金堂，一笑情内亲。","悲来话亲故，气结不能陈。"]},{"t":"入新都访汪司马伯玉八首 其八","f":"五言古诗","c":["往事去莫追，来欢倘可续。","金石诚匪坚，富贵焉所欲。","平原十日饮，岁月苦不足。","旨酒罗高堂，新声动丝肉。","令名敝天壤，何事伤局促。"]},{"t":"别司马汪公八首 其一","f":"五言古诗","c":["有鸟巢天都，自名为凤凰。","文章被六翮，五色河辉煌。","饮啄梧桐枝，矫翼临朝阳。","一鸣举世惊，清音杂琳琅。","云是王者瑞，千仞方高翔。"]},{"t":"别司马汪公八首 其二","f":"五言古诗","c":["高翔欲何为，浮云渺天末。","言欲揽德辉，翩翩下阊阖。","东海有鹓雏，孤鸣蔽林樾。","羽翼苦未长，天路迥难涉。","延颈望霄汉，邈若秦与越。"]},{"t":"别司马汪公八首 其三","f":"五言古诗","c":["丈夫重意气，焉论越与秦。","千里行相求，冈陵若云屯。","轻舟涉广汉，夹岸垂芳荪。","巨石何崔嵬，日夜飞流奔。","天都在咫尺，举头见龙门。"]},{"t":"别司马汪公八首 其四","f":"五言古诗","c":["龙门造中天，片刺亦何有。","清风惠然来，长揖把余手。","肝胆俨欲披，丰庖出旨酒。","广乐罗前庭，钧天在户牖。","一别已九春，相顾惊老丑。"]},{"t":"别司马汪公八首 其五","f":"五言古诗","c":["老丑讵足嗟，百年迅飞霞。","念彼弇山堂，缅邈天一涯。","佳人逝安适，相望徒蒹葭。","怅焉念长别，中肠结如麻。","今我不为乐，日月忽已遐。"]},{"t":"别司马汪公八首 其六","f":"五言古诗","c":["行乐当及时，百岁难为期。","铅华若流水，日夜东南驰。","夜长日苦短，秉烛游芳池。","明月出西园，众星何陆离。","顾视两天孙，冉冉云中嬉。"]},{"t":"别司马汪公八首 其七","f":"五言古诗","c":["嬉游亦何常，高谈蔚霞烂。","丝竹罗前庭，新声一何艳。","娥娥红粉妆，妖姬列如粲。","登彼幔亭峰，酣饮日方晏。","诘朝泛浮槎，遥遥上河汉。"]},{"t":"别司马汪公八首 其八","f":"五言古诗","c":["河汉杳无极，仙槎逝难留。","明发还旧疆，何以写我愁。","依依丈人行，倾盖为九州。","天都望威凤，八翼凌空游。","誓将振弱羽，岁岁行相求。"]},{"t":"东阳李茂才允达以古风六章杂诗一卷见投斗酒定交留连浃夕答赠四首 其一","f":"五言古诗","c":["首夏维清和，朱光何熠爝。","众木纷扶疏，朝阳翳林薄。","鸟雀罗前庭，飞鸣自相乐。","伊余怀一丘，索居卧层阁。","诵彼伐木章，喟焉伤寂寞。"]},{"t":"东阳李茂才允达以古风六章杂诗一卷见投斗酒定交留连浃夕答赠四首 其二","f":"五言古诗","c":["寂寞不可居，起坐弹鸣琴。","清风穆然至，之子贻好音。","自言长东郭，夙昔怀同衾。","丈夫重意气，焉论尺与寻。","飘然命余驾，信宿来兰阴。"]},{"t":"东阳李茂才允达以古风六章杂诗一卷见投斗酒定交留连浃夕答赠四首 其三","f":"五言古诗","c":["兰阴屹岧峣，双溪纡且郁。","蓬蒿蔽行径，倒屣为君出。","中厨呼斗酒，申盟指金石。","愿为双飞龙，霄汉长比翼。","良哉如渑燕，生平在今夕。"]},{"t":"东阳李茂才允达以古风六章杂诗一卷见投斗酒定交留连浃夕答赠四首 其四","f":"五言古诗","c":["今夕复何夕，燕婉难具陈。","三星烂东壁，皎月悬高旻。","朱弦从风发，四坐回阳春。","但言戒明德，努力希良辰。","千秋树大业，皓首以为邻。"]},{"t":"寄李惟寅欧祯伯四首 其一","f":"五言律诗","c":["迢迢牵牛星，乃在河汉旁。","织女处其东，脉脉徒相望。","鸳鸯失羽翼，乌鹊难为梁。","采采芙蓉花，道远不得将。"]},{"t":"寄李惟寅欧祯伯四首 其二","f":"五言律诗","c":["远道亦何思，美人在京洛。","白日丽中天，流云飘阿阁。","煌煌五侯宅，冠带日相索。","宁知瓮牖士，终岁长寂寞。"]},{"t":"寄李惟寅欧祯伯四首 其三","f":"五言律诗","c":["寂寞宁复陈，嗟此明盛年。","矫矫黄鹄姿，孤飞铩其翰。","山川郁以纡，道路长苦难。","顾视双游龙，叹息浮云端。"]},{"t":"寄李惟寅欧祯伯四首 其四","f":"五言律诗","c":["浮云不终朝，岁月忽复易。","岂伊岩廊慕，大业在金石。","缅怀同心侣，沈思无终极。","安得西飞鸿，假我双羽翼。"]},{"t":"寄邦相四首 其一","f":"五言律诗","c":["凉风倏以厉，日短夜苦长。","大火西南流，蟋蟀鸣我床。","徘徊起中夜，揽衣不及裳。","念彼同怀友，投袂忽如伤。"]},{"t":"寄邦相四首 其二","f":"五言律诗","c":["弱冠京华游，衣冠九衢列。","鞍马如浮云，与子独相狎。","灼灼桃李花，光华自怡悦。","飞沈一朝异，忽若吴与越。"]},{"t":"寄邦相四首 其三","f":"五言律诗","c":["与子别三载，中怀日熬煎。","岂不念同心，怅彼河与山。","赵璧有时合，隋珠有时迁。","安得晨风翼，送我置子前。"]},{"t":"寄邦相四首 其四","f":"五言律诗","c":["心悲亦何为，各愿加餐饭。","子游青云途，予守藜藿贱。","百代同音徽，何论异乡县。","黄发会有期，兹盟庶当践。"]},{"t":"送朱水部可大入都四首 其一","f":"五言古诗","c":["苍龙守阿阁，赤骥鸣天闲。","彼美承家子，被服都且妍。","飞飞振六翮，游戏青云端。","出入承明庐，行者夹道观。","朱弦顺风扬，四坐靡不欢。"]},{"t":"送朱水部可大入都四首 其二","f":"五言古诗","c":["矫矫孤飞鸿，明时策高步。","亮节难为容，浮云起中路。","层阴蔽白日，圆景忽将暮。","转蓬随长风，行行践霜露。","驱车大河涘，瀍洛莽回互。"]},{"t":"送朱水部可大入都四首 其三","f":"五言古诗","c":["王屋一何高，嵚岑蔽层云。","登高望宛洛，车马如游尘。","万象列毫端，抽思戾高旻。","仙人王子乔，转盼迹已陈。","三花满怀袖，寄我忽若新。"]},{"t":"送朱水部可大入都四首 其四","f":"五言古诗","c":["百里讵足栖，长途复当践。","帝优循良吏，召对明光殿。","羌子与我亲，绨袍长恋恋。","双凫一朝去，临风涕沾面。","努力崇千秋，慰此金石愿。"]},{"t":"别汪仲淹二首 其一","f":"五言古诗","c":["噭噭云间雁，飞鸣各有适。","翩翩水中凫，中道乖羽翼。","我当还故栖，子病卧蓬室。","明发从此辞，遥遥望乡国。","东顾临大江，波涛无终极。"]},{"t":"别汪仲淹二首 其二","f":"五言古诗","c":["大江岂不遐，一苇朝可航。","我友一为别，倏若逾三霜。","踟蹰念子病，送我濠之梁。","迟迟白日暮，车马为徬徨。","人命匪金石，暌离热中肠。","长当保玉体，百岁遥相望。"]},{"t":"娟娟苧萝女二首寄李生时秋试罢归 其一","f":"五言古诗","c":["娟娟苧萝女，艳色明朝霞。","珊瑚被玉体，璎珞相交加。","绮疏傍阿阁，高居临狭斜。","朝披越台锦，夕浣吴门纱。","一为白雪言，清音浩无涯。","哀思激云汉，行路咸咨嗟。","宁知中肠怨，愁结纷如麻。","芳春倏已尽，白露漙蒹葭。"]},{"t":"娟娟苧萝女二首寄李生时秋试罢归 其二","f":"五言古诗","c":["娟娟苧萝女，婉婉矜弱步。","浣纱越溪上，西施屡回顾。","罗袜扬轻尘，徘徊感行路。","但持双明珰，赠君比纨素。","灼灼桃李华，尝恐瘁霜露。","羞为倚门笑，宁为入宫妒。","亭亭处空闺，冉冉白日暮。"]},{"t":"己夘仲秋复当计偕北上以家母病不赴与诸友言别四首 其一","f":"五言古诗","c":["荏苒岁时迈，蟪蛄鸣前庭。","大火倏西流，白露中夜零。","公车有程期，仆夫戒我行。","州郡忝招邀，闾里相送迎。","肃肃同袍侣，命驾来林坰。","各言休明世，努力事遐征。","夕当辞室家，明当赴神京。"]},{"t":"己夘仲秋复当计偕北上以家母病不赴与诸友言别四首 其二","f":"五言古诗","c":["神京岂不遥，阊阖造中天。","金茎夹广陌，玉陛蒐群贤。","幸生唐虞代，况逢强盛年。","徘徊高堂病，一卧垂十年。","既无稚子娱，亦寡群从援。","椿庭渺何许，万里越南滇。","感此去住怀，戚戚摧心颜。"]},{"t":"己夘仲秋复当计偕北上以家母病不赴与诸友言别四首 其三","f":"五言古诗","c":["戚戚徒尔为，兴文各踟蹰。","夙昔慕巢由，散发箕颍隅。","矧兹乌鸟情，能不怀倚闾。","令伯惟承欢，王阳实回车。","亦知轩盖荣，方寸寡所愉。","愿言青云客，矫翼升天衢。","君子游岩廊，小人安敝庐。"]},{"t":"己夘仲秋复当计偕北上以家母病不赴与诸友言别四首 其四","f":"五言古诗","c":["敝庐亦何有，有稼复有萱。","旭日丽遥岑，清风濯林园。","问寝趣庭帏，进膳列芳鲜。","虽无黻冕贵，彩服欢慈颜。","板舆历高台，丝竹罗长筵。","踟蹰禽鸟声，映荫林木繁。","俯仰中所欲，百岁聊自全。"]},{"t":"寓怀三韵七首 其一","f":"五言古诗","c":["泛泛海上鸥，机忘意自适。","嗟嗟塞翁马，何失亦何得。","七日混沌死，哀哉倏与忽。"]},{"t":"寓怀三韵七首 其二","f":"五言古诗","c":["膏以明自煎，香以熏自燔。","葆光茹其和，乃可全天年。","巍巍广成公，千岁空同颠。"]},{"t":"寓怀三韵七首 其三","f":"五言古诗","c":["西方大圣人，国土名极乐。","万法同虚空，一尘安所著。","嗟嗟蛮触民，智勇困蜗角。"]},{"t":"寓怀三韵七首 其四","f":"五言古诗","c":["向长志五岳，宗炳卧一丘。","济胜苟无具，澄怀亦天游。","鸣琴一室内，万象同蜉蝣。"]},{"t":"寓怀三韵七首 其五","f":"五言古诗","c":["飞蛾赴明烛，徇利忘其身。","苍蝇集鼻端，高峻为祸因。","石户有遗民，古今称达人。"]},{"t":"寓怀三韵七首 其六","f":"五言古诗","c":["齐王本好瑟，东郭仍滥竽。","与世苦枘凿，独处恒嗟吁。","九州不足居，何况五亩庐。"]},{"t":"寓怀三韵七首 其七","f":"五言古诗","c":["世人竞巧知，逐逐如飞蝇。","井蛙亦诧海，夏虫曷语冰。","俟彼千秋人，陈迹异代论。"]},{"t":"秋日偕诸同志游金华二首 其一","f":"五言古诗","c":["屈子歌远游，尚平有遐慕。","顾谢青云人，言寻赤松路。","历览穷幽深，冥探惬情素。","涧壑扪嵚岑，林峦陟回互。","崖倾黄叶积，谷转垂萝护。","高峰散馀霭，峭壁屯寒雾。","娟娟初月升，隐隐微阳暮。","长谣钦昔踪，独往怀蹇步。","虑由忘物超，道以遗荣悟。","迹契容成公，神交子支父。","徘徊北山文，恻怆淮南赋。","眷彼丘中人，回镳对岩户。"]},{"t":"秋日偕诸同志游金华二首 其二","f":"五言古诗","c":["成羊閟昔踪，化鹤神遗迹。","曰余蹇劣姿，缅企灵仙窟。","时维仲秋暮，舂粮负瓢笠。","落叶纷前林，凄霜被长隰。","蹑履行翠微，扪萝上层壁。","岩峦莽回互，云霞屡兴没。","苍苍猿鼯啼，濯濯麇麚集。","乍闻帝鸿鼎，今见初平石。","芝田翳宿莽，玉灶埋金液。","羽驾何飘遥，人寰信超忽。","胡为七尺躯，甘此百年役。","去去从吾初，城东有黄石。"]},{"t":"仲夏至自京师作","f":"五言古诗","c":["人生如飞蓬，倏忽异乡县。","仆夫趣我游，肃驾向畿甸。","朝登太行岭，暮宿黄河岸。","荏苒踰修途，迟回陟层巘。","中林绝烟火，尘沙蔽颜面。","浮云翳荒垒，咫尺行莫辨。","遥遥至幽并，四顾见闾阎。","中天帝王宅，飞甍翼楼殿。","空怀稷契志，未遂夔龙愿。","辞非上林侈，赋岂河东擅。","长啸起拂衣，归来弄柔翰。","寄言达生者，骄人有贫贱。"]},{"t":"秋日携尊城东大寺山作","f":"五言古诗","c":["步出东郭门，骋望西山麓。","信足登其颠，聊怡白云目。","川原何逶迤，城邑自相属。","飞甍俨鳞次，万户列平陆。","高峰下牛羊，斜照散麋鹿。","苍苍瀫川流，靡靡兰皋绿。","列岫澄尘襟，清涟媚遐瞩。","契深浩忘言，虑澹信超俗。","载咏衡门诗，轩盖非所欲。"]},{"t":"九日喻邦相邀司马汪公洎诸君登高天竺属余尚留槜李不及会以遍插茱萸少一人插字为韵","f":"五言古诗","c":["霜露维深秋，木叶殆尽脱。","纷披时菊繁，憔悴兰芳歇。","上客怀登高，群公欣令节。","薄暮回轻桡，凌晨戒车辙。","窈窕度城闉，逶迤陟岩穴。","遐览穷八荒，轻举渺六合。","三竺凌层霄，双峰表天阙。","绿野名园开，朱宫梵筵列。","白云冒冈峦，丹霞冠林樾。","淅淅凉风生，隐隐微阳灭。","修鳞竞容与，平湖亦澄澈。","感此岁序更，羽觞共怡悦。","妙管激清商，流音回白雪。","解佩俱朝贤，衔卮并时哲。","言念同袍子，鸿飞渺天末。","醉把茱萸枝，徘徊不能插。"]},{"t":"与众宾游城西园亭作二首 其一","f":"五言古诗","c":["端居俟时命，日暮寡所欢。","眷言写忧思，散步游西园。","西园一何丽，薜荔交崇垣。","飞甍带层阁，曲榭临回轩。","丹霞吐岩岫，白云冠林峦。","灼灼芙蓉披，瀼瀼白露漙。","游鱼跃清波，好鸟鸣树端。","感兹动植情，悟彼节候迁。","百年亦瞬息，金石畴能坚。","念当命我友，肃驾开华筵。","悠然迟心赏，寓目双飞翰。"]},{"t":"与众宾游城西园亭作二首 其二","f":"五言古诗","c":["嘉宾既咸集，徒御何辉煌。","逶迤度飞观，置酒临回塘。","长渠激芳流，曲岸披丛篁。","齐瑟列前楹，秦筝鸣后堂。","燕姬发皓齿，越女呈红妆。","清音振林木，妙舞协宫商。","觥筹互交错，四座咸慨慷。","夜阑更秉烛，雕辇随风翔。","明月出云间，列宿正纵横。","四序忽若驰，行乐安可长。","申章纪良晤，无为歌太康。"]},{"t":"卧游室午睡起题","f":"五言古诗","c":["东方谈十洲，尚子怀五岳。","玄览岂不遐，浮踪竟安泊。","伊余实蹇劣，禀赋孱且弱。","迟回三十年，强半客京洛。","风沙蔽颜面，神明日凋落。","虽窃文苑声，未睹寰中乐。","朅来卧一丘，晨昏课耕凿。","卜居邻莽苍，筑室事恬漠。","轩窗不盈丈，周遭艺兰若。","游目惟图书，怡神匪丹雘。","时援白雪琴，三弄对猿鹤。","泠泠众山响，一一度林薄。","五鼎非我荣，万钟亦奚乐。","达哉宗炳言，先民有遗矱。"]},{"t":"将负瓢笠入金华从赤松三子游作","f":"五言古诗","c":["三十六洞天，金华亦奇绝。","古昔群真栖，云霞閟阊阖。","赤松乘紫烟，皇氏憩丹穴。","缅邈怀仙灵，栖迟表才杰。","奕奕孝标生，漂流寄东越。","长生本经世，不朽惟大业。","伊余后千载，束发慕贤达。","逝将辞垢氛，寻幽入林樾。","大药倘可逢，雄词冀颃颉。","异日骑双龙，携手轻六合。"]},{"t":"题陆信卿书屋二首 其一","f":"五言古诗","c":["五岳岂不遐，一丘良自适。","言从谷口居，永憩隆中膝。","结搆凌层霄，飞轩控奇石。","嵚岑带林峦，窈窕罗原隰。","轻飙回座隅，明霞护檐隙。","之子何逍遥，鸣琴坐幽寂。","列岫披琅函，遥峰映缃帙。","揽挈万古心，俯仰千秋迹。","白马穷妙诠，青牛探真籍。","神游羲禹庭，冥栖素王室。","伊余麋鹿踪，羡尔烟霞癖。","殷勤劳梦思，恻怆务晨夕。","何当辞世纷，相对扪萝薜。","散发翻金书，长歌抱琼笈。","一笑尘氛空，挥手凌八极。"]},{"t":"题陆信卿书屋二首 其二","f":"五言古诗","c":["大鹏抟九万，尺鴳翔榆枋。","远近各有适，逍遥固其常。","伊人励高躅，卜筑邻山岗。","四壁罗琬琰，五车插琳琅。","冥搜极浩渺，幽探穷微芒。","栖心丈室间，寄情八表傍。","丹霞入我牖，白云为我裳。","驭风学郑圃，弃瓢怀颍阳。","岂同渭川钓，耻为吴市藏。","一区足吟啸，万卷聊徜徉。","乐哉帷中子，岁年良可忘。"]},{"t":"仲秋十四夜同诸子携觞登一览亭玩月作","f":"五言古诗","c":["秋高桂华满，夜静兰膏歇。","素影流长空，寒光浸天阙。","孤城白露下，万户凉飙发。","置酒临高台，长歌对佳节。","忆别蓬莱宫，回首三千劫。","蹉跎落风尘，荏苒见华发。","举杯属嫦娥，乞我长生诀。","乘云朝太清，飞步还紫闼。","自按霓裳操，重翻羽衣阕。","愧彼尘世人，徘徊望圆缺。"]},{"t":"十五夜对月独酌有怀燕中诸君","f":"五言古诗","c":["佳期三五临，遥望挂圆璧。","皓魄扬清辉，亭亭堕檐隙。","揽衣步前庭，感此长叹息。","忆昔京华游，文儒盛东壁。","中宵蓟门燕，五夜甘泉集。","苍龙玉绳挂，露掌金波溢。","惜哉道路分，佳人遂南北。","寤寐安可凭，瑶华讵能即。","欲从万里天，持赠婵娟色。","愿言逐飞鸿，随风起双翮。"]},{"t":"登鹿田","f":"五言古诗","c":["日暮扪女萝，亭亭出危磴。","万壑来松风，飞云堕樵径。","行窥虎豹穴，侧并猿猱进。","及登众山颠，始觉天宇峻。","曾闻赤松子，兹域开灵胜。","丹砂信有术，尘虑了可竟。","伤哉缑山鹤，不返瑶池骏。","惆怅仍独歌，青霄落寒磬。"]},{"t":"家君北上半载不得问述怀","f":"五言古诗","c":["朝日照高台，清风被华池。","椿庭万里外，北望浮云飞。","岂不念行役，相携赴皇畿。","眷言高堂病，药石久告疲。","仰无令昆托，俯靡弱弟依。","以兹谢形役，息意掩荆扉。","朝掇南涧藻，夕采西山薇。","缅怀弹冠客，恻恻常抱饥。","天门九重辟，王路正逶迤。","轩车满京洛，鞍马如云驰。","穷年叫阊阖，当道饶狐狸。","积薪谅难守，岁暮空流离。","侧身起长望，涕泪沾裳衣。"]},{"t":"寄怀司马汪公","f":"五言古诗","c":["天游表龙德，水击知鹏抟。","矫矫司马公，伟度周八埏。","先驱既左马，缓步亦扬班。","伊余慕匠哲，邂逅自临安。","千秋默相许，片诺永不寒。","追随武林驿，挥袂弇山园。","黯黯临别怀，欲吐不得宣。","殷勤戒兹岁，瀫水仍周旋。","天台访大药，雁宕穷灵源。","春和届炎夏，寤寐来华轩。","愿当脱羁絷，一杖携名山。","雄章辟混沌，片碣三千年。"]},{"t":"闻大司空朱公讣志哀十二韵","f":"五言古诗","c":["匡庐摧大江，天柱折南岳。","涕泪盈九原，伊人岂重作。","桓桓大司空，束发仕台阁。","小心历四朝，姬旦恒惕若。","维昔嘉隆岁，河流泛大壑。","临轩万乘送，飞驭百灵愕。","八荒就疆理，四海安画诺。","晚遂莼鲈兴，高蹈游广莫。","裴公系安危，司马耽独乐。","方勤大廷诏，忽跨辽东鹤。","衣裳蹑箕尾，名姓悬海岳。","煌煌亿万载，禹功在河洛。"]},{"t":"祝贞妇诗","f":"五言古诗","c":["结发奉君子，欢爱两不疑。","如何高堂上，一旦生别离。","惊飙荡白日，去我忽若遗。","重泉逝将会，念此黄口儿。","皎皎匪石心，柏舟以自持。","绩纴度晨昏，卒岁恒抱饥。","穗帷下重关，荆棘盈柴扉。","冬半多烈风，憭慄中我肌。","顾瞻双鸳鸯，比翼东南飞。","岂无贤雄匹，再适匪所宜。","亮为南山松，安受雪霰欺。","愿当毕馀命，不愧死者知。","我闻再叹息，三叹怀令仪。","抽毫赋黄鹄，万古钦蛾眉。"]},{"t":"二酉园为陈玉叔京兆题","f":"五言古诗","c":["吾家二酉斋，斗室不盈掬。","何以称兹名，架上书万轴。","公家二酉园，大厦蔽陵谷。","何以称兹名，笔底珠万斛。","楼台瞰空起，云雾傍檐宿。","雕甍挟天柱，高栋擎岳麓。","轩窗洞庭叶，户牖云梦竹。","蜃鳄游长川，虎兕啸平陆。","岸芷纷葳蕤，汀兰互芳馥。","主人湖海豪，潇洒脱尘俗。","开襟跨寥廓，解带谢拘束。","三闾问灵均，九辩追宋玉。","名惊孟公座，梦启傅岩卜。","誓扫六合尘，一榻非所欲。","蜚声京兆里，张赵三鼎足。","至尊催赐金，上相待横玉。","异日休林泉，赐第镜湖曲。","华堂坐昼锦，饱看四野绿。","煌煌中令墅，烨烨魏公筑。","宁当卧二酉，卒岁事耕读。","好借胡生居，日餍蠹鱼腹。","携手崙昆丘，相将问周穆。"]},{"t":"大隐园为陈司理题","f":"五言古诗","c":["衡阳七十峰，洞庭八百里。","翛然五亩宅，结搆傍江汜。","仄径穿藤萝，层轩萟桃李。","白云何英英，丹霞亦靡靡。","空翠流重檐，林岚润湘几。","主人金闺彦，夙昔厌纨绮。","名家孟公后，侠气元龙侣。","高言和阳春，清响激流徵。","纵横彩毫落，烨烨隽声起。","朝辞蓟门燕，夕佐越台理。","騄骥游天闲，鸾凤出榛枳。","一丘宁独乐，十载旷栖止。","缅怀东方生，大隐帝乡迩。","聊用名吾园，归梦时徙倚。","伊余东海民，蚤岁群鹿豕。","孤悰托松桂，幽梦结兰芷。","侧闻辋川胜，佳兴浩难已。","冉冉携芳尊，悠悠负绿绮。","携我初平石，适君仲长里。","青鞋与布袜，行迈自兹始。"]},{"t":"心远堂为陈立父题","f":"五言古诗","c":["陶公住人境，心远地自偏。","陈侯服官政，结庐讵同然。","吾闻鲁仲尼，行止非一端。","寸心若太虚，龙蠖偕媸妍。","华堂搆空起，正对衡岳颠。","洞庭八百里，日夜浮朱栏。","鲸鲵跋高浪，蜃鳄游惊湍。","祝融及天柱，云密纷钩连。","回雁遏层霄，石廪屯飞烟。","奇峰七十二，一一罗堂前。","彼美堂中客，妙龄夙忘筌。","冰壶瑩尘表，玉笈开琅函。","携宾坐堂上，四面罗苍矸。","鸣琴憩深树，看奕垂疏帘。","目送双飞鸿，迢迢极云天。","心远室从迩，悠悠浩忘言。","兴文念朋好，一订柴桑缘。","殷勤沔阳约，尺素驰江干。","吾将负瓢笠，卜筑邻青山。","异时陈蕃榻，倘为孺子悬。"]},{"t":"送李子赴试钱塘","f":"五言古诗","c":["大梁本任侠，壁立逾千寻。","一遇昌谷生，握手为断金。","申台振高步，十载囊瑶琴。","中途遘君采，邈焉奏遐音。","声谐响必赴，异代犹沈吟。","矧兹百里壤，而不怀同心。","缅余起末学，努力搴词林。","遐思太古上，时俗非所钦。","栖栖卧一壑，委怀甘陆沈。","李生一何戆，物色来兰阴。","双溪入驰溯，三洞回登临。","清言吐肝肺，古色流衣襟。","吾宁负奇癖，尔亦饶书淫。","扬亭共寂寞，原巷偕萧森。","子迹尚霄汉，余踪久蹄涔。","他时树大业，盟言倘在今。"]},{"t":"七夕","f":"五言古诗","c":["昔余游天门，白榆正飘飖。","濯足银河水，惊飞乌鹊桥。","牵牛与织女，欲渡愁无聊。","相将忤上帝，谴谪离青霄。","骑鲸向东海，龙伯频招邀。","举足届五山，投竿连六鳌。","狂风鼓大壑，吹向西南郊。","青鞋曳布袜，濩落不得骄。","朅来三十载，食粟同曹交。","珠玑一万斛，散乱随尘坳。","猰㺄难共居，贪狼如猬毛。","苍蝇变白黑，鼠璞矜琼瑶。","回首望阊阖，双星正岧峣。","而我一何悲，偃伏同鹪鹩。","逝将脱尘网，天路长逍遥。","寄言夸毗子，役役徒为劳。"]},{"t":"余既不上春官燕中遂有传余病不起者孟韬方就试辄于院中大恸王次公过瀫水为余言之余闻剧喜命酒索笔赋此寄孟韬","f":"五言古诗","c":["漆园喻桑户，郑圃称杨朱。","岂无王者乐，孰与真人居。","大钧播群象，品汇盈寰区。","偶然值为人，禀此七尺躯。","营营一生内，十九婴忧虞。","欢爱苦不长，劳悴乃有馀。","冠裳槛沐猴，钟鼎罗爰居。","三旬亮已多，百年亦奚娱。","风霜遍项颔，尘垢盈眉须。","齿发谅非坚，金石犹可渝。","七十二圣君，百千亿庸愚。","参差就黄土，转盼随丘墟。","安期信茫昧，松子难觊觎。","何如一宿觉，大梦伸蘧庐。","陶公制哀挽，王孙却衣襦。","伟哉哲人见，我心获所如。","死生固有命，寿夭讵足虞。","戚戚儿女仁，毋乃曲士拘。","愿言勖明德，今古流芳誉。","乐哉白云丘，万代同斯须。"]},{"t":"夜梦裕卿惟寅觉赋此诗寄怀并呈邦相","f":"五言古诗","c":["康生秉侠烈，李子弘风流。","尘埃困鸿鹄，天厩储骅骝。","曰余抱微尚，弱冠羁皇州。","洛中富冠盖，一一俱琳球。","风尘片言合，把臂为千秋。","夜谈促瑶席，春燕开云楼。","飞蓬一朝散，抗袂还林丘。","道路阻且长，尺素安可求。","眼底孰同声，论心惟喻侯。","喻侯与康李，宿昔伸绸缪。","雄飞失天路，雌伏来山邮。","伊余实倾盖，契分逾白头。","笑谈乐新知，感激怀故俦。","中宵梦二子，宛若平生游。","慇勤十载别，不为终夜留。","觉来但长叹，坐失双吴钩。","乃知豪杰人，聚散俱萍浮。","申章示同好，咫尺毋悠悠。"]},{"t":"始入州谒宣尼庙二首 其一","f":"五言古诗","c":["猗欤大圣人，树建实高厚。","道苞羲农前，业擅尧舜右。","茫茫沧海水，涓滴靡不受。","俨若登岱宗，绝顶小宇宙。","于戏七雄降，生民失领袖。","九流竞纷纭，百氏互驰骤。","虚无驾犹龙，因果凿灵鹫。","骎寻天网缺，畴补坤轴漏。","龙飞歘淮甸，六合更造就。","车书焕一统，谱系明授受。","寰区设黉校，家掖仍户诱。","诗书被华貊，狐兔伏林岫。","遂令宣尼脉，炳耀绝先后。","伟哉成周基，八百衍潢胄。"]},{"t":"始入州谒宣尼庙二首 其二","f":"五言古诗","c":["厥初水精帝，肇迹维山东。","乡闾表凫绎，胤胄延龟蒙。","胡为姑蔑墟，亦有文宣宫。","时维赵宋末，兵戈竞华戎。","渡南实孔裔，大衍三衢宗。","精灵动世主，锡命传丰隆。","沿流洎明代，奕叶驰皇封。","创祠视曲阜，貤恩逮无穷。","清华世世及，岳降齐申崧。","两宗峙南北，辉赫罗章缝。","至今太末里，恍忽邹尼风。","我来谒遗像，三叹钦遐踪。","皇皇六萟轨，万古侔穹窿。"]},{"t":"始出西直门策蹇行堤上四十里暮抵碧云禅寺宿颙上人方丈中","f":"五言古诗","c":["尘氛翳京洛，客子悲途穷。","芒鞋出西郊，陡觉万虑空。","垂杨四十里，长堤跨游龙。","蹇驴负破帽，泠然若乘风。","平湖漾明镜，匝岸纷芙蓉。","源穷见大陆，平野罗千松。","环青障冥漠，积翠摩穹窿。","嵯峨众山顶，忽睹金银宫。","碧云际天出，气势何其雄。","栏杆冒白日，栋宇凌秋空。","飞泉绕重砌，漱玉声玲珑。","浮云出深涧，映树明遥峰。","山厨积古雪，石梁卧长虹。","始知五浊界，咫尺蓬莱通。","吾将结茅屋，一杖时过从。","徘徊不成梦，静夜闻微钟。"]},{"t":"早饭罢由碧云入香山山麓及颠俱有亭诸宫殿最古是胜国时遗搆","f":"五言古诗","c":["仄径缘藤萝，逶迤入深谷。","重阴夹磴道，弥望皆古木。","长松数百年，夭矫云际矗。","飞泉挂峰顶，蜿蜒出平陆。","石门森隧道，孤亭峙山足。","四天划然开，空洞豁尘目。","千崖布黄金，万仞嵌苍玉。","梵室缘危杉，禅关荫修竹。","圣果森菩提，昙花吐薝卜。","琳宫是何代，相传至元筑。","兹山迹最古，创始见身毒。","悠然念人代，累劫如转烛。","夜分息尘嚣，重展法华读。","何日归流沙，吾家旧天竺。"]},{"t":"来青馆夜分独坐题","f":"五言古诗","c":["昏黑登上方，遂抵兹轩宿。","遥峰过疏雨，众山若新沐。","晚凉凭阑坐，流萤出深竹。","明月东方生，依微隐乔木。","泠泠发孤啸，空响答岩谷。","山僧供伊蒲，饱饭禅堂浴。","微钟歇清夜，星斗烂可掬。","终南饶白云，暂此憩幽独。"]},{"t":"山左侧小径扪萝入红光寺寺僧尽出独坐赞公房题十韵壁间","f":"五言古诗","c":["西山四百寺，金银烂蓬岛。","红光据绝颠，迥出千岫杪。","香山既穷望，石磴上深杳。","奇峰刺天出，势欲截飞鸟。","凭高豁双眸，顿觉宇宙小。","危龛贮金粟，亿万恣围绕。","禅堂阒无人，黄叶净于扫。","昙花吐优钵，香气达萝茑。","悠然悟尘世，解脱何不早。","会当携瓢笠，一息万缘了。"]},{"t":"将登西山绝顶昏黑法华寺废址小憩","f":"五言古诗","c":["扪萝上层颠，石门嵌空立。","千嵓吹烈风，遗栋袅绝壁。","古佛颓苍藤，禅关尚双辟。","我行穷登顿，假此暂栖息。","残僧一二辈，破榻置瓢笠。","山魈供夜谈，木客伴朝汲。","岚光坏灶起，燐火断垣出。","虚牖号寒蝉，阴廊走伏翼。","梵天亦销歇，尘世几更易。","愀然发长啸，感此独悽恻。","桑田复沧海，浩浩无终极。","踟蹰白日暮，拂袖下昏黑。"]},{"t":"凌晨起梯鸟道抵玉岩寺望长安宫阙题","f":"五言古诗","c":["清晨馔伊蒲，饱饭扪石壁。","天风拍两袖，樵路尚昏黑。","微月耿嵓际，残星堕山脊。","明霞挂石梁，渐起赤城色。","仰攀猿鸟巢，俯瞰麋鹿窟。","山椒见台殿，经岁断人迹。","危梯雾半隐，古砌雪长积。","耸身上绝颠，河汉仅咫尺。","震旦隘目睫，宇宙转呼吸。","天门九重启，栋宇烂金碧。","仙姝十万辈，一一似相识。","胡为堕人世，甘此下方谪。","劳生四十年，营营若虮虱。","长谣归去来，香案玉皇侧。"]},{"t":"西山绝顶纵目诵供奉呼吸通帝座及拾遗焉能辩皇州二语临风咽桑落十数觥沈醉憩大磐石上昏黑乃下","f":"五言古诗","c":["燕山八万仞，楼台夹层嶂。","缅怀穷绝颠，揽此大千状。","时维九月暮，决策浣尘况。","蹇驴华严宿，凌晨策孤杖。","扪萝翠微半，亭午思挟纩。","石门排空入，猿鸟捷下上。","两岸夹霜枫，烨若锦步障。","凭高宇宙隔，陟险身世忘。","叠磴何岧峣，遥峰渐超旷。","披襟豁云雾，把袂狎星象。","皇都但一气，帝座屹相向。","九点分齐州，一一罗眺望。","颓然步空虚，嗒尔齐得丧。","吾将御风游，乘化入无量。"]},{"t":"翠岩寺在碧云左障蔽高崖层巘中最为幽绝余每过必留浃旬","f":"五言古诗","c":["碧云既钜丽，香山亦宏敞。","翠岩蔽层巘，车马或希往。","曰余负奇癖，一一恣探赏。","群峰障谷口，弥望悉林莽。","谽谺一线入，仄径若指掌。","危梯屡攀蹑，乔木时偃仰。","阴崖伏空洞，阳峤入宏敞。","俯窥地欲穷，上陟天转朗。","楼台互回合，金碧时惝恍。","虚檐织蛸蟏，画壁森罔两。","绳床败叶积，禅堂坏苔长。","悠悠石火身，兀兀挂世网。","向暮聊独唫，徘徊发深想。"]},{"t":"维摩庵又翠岩最幽绝处科头独坐万籁澄寂殆不复知有人间世因与山灵约异日者毕婚嫁愿携一钵安息此中","f":"五言古诗","c":["万峰人声绝，萝磴恣攀陟。","楼台跨深崦，尽纳众山色。","大地纷金银，遥天挂丹碧。","禅关面重壑，窈窕开丈室。","科头挟书坐，如面达摩壁。","五蕴穷真如，六根断情识。","将因抱华严，住此阿閦国。","他年号居士，说法嗣摩诘。"]},{"t":"山麓游卧佛寺寺极宏焕金银夺目画廊数百千尺图大雄氏显化颠末备详僧寮花木弥靓幽支枕敧卧不觉日晏","f":"五言古诗","c":["琳宫万山麓，势欲翔遥天。","金扉烨宏敞，玉栋纷钩连。","飞萝映禅室，古木藏玄关。","奇花及灵果，布列森祇园。","伟哉化人居，杰搆凌飞鸢。","金身丈六强，證果示涅槃。","修廊耀丹碧，粉墨流云烟。","始疑张僧繇，或诧吴道元。","穷源溯流派，一一图真诠。","天魔亦俛伏，外道纷缠绵。","感此三叹息，临风涕如潸。","猥以无涯智，逐兹有尽年。","何当蜡双屐，西入清凉山。","杳然绝人累，乘化归竺乾。"]},{"t":"出山投华严寺夜宿晨起游吕公洞曩同惟敬题名老衲炊黄梁作供忆邯郸枕上事怃然久之","f":"五言古诗","c":["夜宿华严堂，晨探吕公洞。","悬梯喷飞雪，流泉伏螮蝀。","星流坠幽壑，俯视势若动。","僧房云作关，禅宇石为栋。","雷轰苍崖裂，雾压翠峦重。","老衲炊黄梁，停午具清供。","毋疑邯郸生，至人久无梦。"]},{"t":"望湖亭亭午小酌空水明媚四山金碧倒浸澄波中芙蓉菡萏流芳吐艳杳然身在六桥孤屿间惜乏两沙棠艇子载吴娃十双耳","f":"五言古诗","c":["众山合长堤，空水相映带。","平湖漾明镜，秋色照眉黛。","中流赤栏起，亭亭列车盖。","琉璃十万顷，倒浸画檐外。","凭虚望寥廓，心赏剧堪快。","菡萏馀汀洲，芙蓉匝滩濑。","蛟龙伏空洞，鹳鹤摩远塞。","鱼游迥自得，鸥行豁无碍。","美人期不至，岂乏沙棠载。","吾将返若耶，夷光久相待。"]},{"t":"玄贞观高峙山颠孤峭突兀望之真中天积翠由飞梯左右数百级上有石坛宏敞可坐千人","f":"五言古诗","c":["四山抱若垣，苍翠照林樾。","中天峙栋宇，大地耸双阙。","穹阶百级上，左右互森列。","石栏层空立，瑶草纷可掇。","平台坐轩敞，高栋表巀嶪。","振策登翠微，朝元叩丹诀。","玉洞翻灵篇，人迹往来绝。","暗谷埋寒云，阴崖坠古雪。","明河漾花际，新月吐木末。","逝将遗世纷，永谢俗士辙。"]},{"t":"三大士殿","f":"五言古诗","c":["普贤肇峨眉，示迹惟西方。","文殊现五台，台殿俱清凉。","猗与观世音，普陀实吾乡。","胡为三大士，鼎足偕兹堂。","吾闻维摩室，方丈罗八荒。","须弥眇一芥，诸佛同行藏。","况兹三如来，功德侔三光。","秉心佐迦文，并起悬津梁。","青狮负璎珞，白象衔珠珰。","千亿昭化身，大悲浩难量。","区区南赡洲，勺水军持将。","杨枝洒甘露，涓滴回枯肠。","我来重瞻拜，感叹殊未央。","善才一童子，百十参慈航。","峨峨兜率天，不改帝释疆。","胡为滞五浊，尘土纷彷徨。","逝将去人世，谢此浮名缰。","他时会解脱，说法酬空王。"]},{"t":"大佛寺观释迦文佛金像题","f":"五言古诗","c":["峨峨蓟城西，飞观耸百级。","金身五千丈，照耀天北极。","画栋糜丹青，雕甍烂朱碧。","琪花烨如散，瑶草纷可拾。","耨水清六尘，雪山炯四壁。","广座陈香灯，长廊绘粉墨。","优钵梵筵启，伊蒲僧供出。","俗染汰欲空，净因了可觅。","香象来医王，天龙护帝释。","茫然小宇宙，一怆大雄力。"]},{"t":"寺后磊土山为十洞曲屈邃幽余尝纳凉其中杳若别有天地者","f":"五言古诗","c":["西山实佳丽，步步金银宫。","四百八十寺，穷极土木功。","或云寡岩穴，未若天南东。","异哉此丛林，制作侔鬼工。","块然一培塿，其下皆虚空。","十洞列左右，恍惚蓬莱峰。","地肺凿委羽，天窗移张公。","不假杖藜入，无俟乘舟通。","猗与造化力，播弄指掌中。","何因遘二女，刘阮追遐踪。","千秋饵灵药，绿发称仙翁。","桃花闭流水，绝胜丸泥封。"]},{"t":"高凉桥晚憩望新月作","f":"五言古诗","c":["入山路不迷，出岫兴弥远。","平桥带流水，乔木数家晚。","湖头雨初歇，沙际尘尚软。","彩云笼大堤，新月吐层巘。","金银耀梵刹，珠翠竞雕辇。","馥馥红蕖开，靡靡绿萍敛。","改席临菰蒲，携壶就葭菼。","吴歌起难遏，越调和仍缓。","把臂无求羊，同怀有嵇阮。","历落摧雄心，凭陵豁醉眼。","朱颜稍沦谢，白发且荏苒。","人生贵适志，对景聊引满。"]},{"t":"湖上菡萏盛开游人如织抵暮皆入郭余独往坐堤畔命小奚拨阮为吴歌","f":"五言古诗","c":["仲秋出湖阴，众芳亦未歇。","袅袅垂杨疏，翳翳浮萍合。","红蕖递芳馥，绿蒲可揽结。","游子饰金羁，美人竞罗袜。","笙歌夹岸起，箫鼓临流发。","日入息群嚣，长谣待新月。"]},{"t":"归途过真觉寺五招提突兀云际与帝城诸宫阙参差相望寺中车马旁午盖渐近国门云","f":"五言古诗","c":["真觉依帝城，参差仅十里。","削成五招提，如薄太清起。","凭高尽胡越，眺迥入箕尾。","七层际空遥，千级去天咫。","青霞湿衣袂，紫雾飘杖履。","羲和驭金轮，拘翼凭玉几。","俯身视尘闉，局促类蝼蚁。","何当八翼成，昏黑犹徙倚。"]},{"t":"谒观世音大士禅院院在高凉桥侧自汉唐下未尝称大士妇人盖宋元始讹谬王长公近作大士本纪辨析详至余复历据六朝及五代诸野史小说證验甚明后人当无词费矣","f":"五言古诗","c":["吾闻观世音，显化肇天竺。","发心救魔难，千亿现手目。","功德如丘山，圣愿肯自足。","遍观阎浮界，众生苦茕独。","嘘呵俨一气，阳春布穷谷。","凡人发善愿，一一遂所欲。","至仁形影彰，明效桴鼓速。","遂令南赡洲，夫妇蕃孳育。","我来载瞻拜，顶礼大悲足。","妙相呈十方，天人丽冠服。","胡为晚近代，姑妪谬称祝。","良哉弇州氏，雄辩破流俗。","中年窘嗣息，晚境冀多福。","愿言普慈施，世世事身毒。"]},{"t":"古意赠云间唐子四章 其一","f":"五言古诗","c":["飘飘云中鸿，口衔尺素书。","有美云间客，宛在天一隅。","兰台振高躅，青骢曳华裾。","初承百里命，栽花烂长衢。","鸣琴讼堂上，素幕垂清虚。","泠然念同调，发箧贻双鱼。","赠我金错刀，投我琅玕珠。","感子缱绻怀，殷勤系罗襦。","岂无倾城色，贵此无盐姝。","林风冉冉暮，岁晏羌何如。"]},{"t":"古意赠云间唐子四章 其二","f":"五言古诗","c":["哲人代沦谢，大雅谅难作。","世路日凌夷，词场巧枘凿。","睊睊郢都匠，戾目陵阳璞。","何彼金闺彦，高谊振顽薄。","尺书寄远道，论交慰离索。","风霜粲华缄，飒爽动林薄。","神剑贻雷张，仙舟伫李郭。","寥寥九成奏，孰振钧天乐。","千人失酬和，片语谢雕琢。","泠泠金石声，三叹起韶濩。"]},{"t":"古意赠云间唐子四章 其三","f":"五言古诗","c":["神交岂在面，片诺为生平。","缅彼古圣贤，立谈盖自倾。","伊人瑚琏器，光辉耀连城。","跫然穷谷中，晤言托同声。","朱弦久摧绝，为子绕夜鸣。","伤哉白日暮，俟彼黄河清。","金石有时泐，浮华安足营。","所希大业崇，努力追炎京。","百世犹比肩，千载垂令名。","区区九州内，胡惧不合并。"]},{"t":"古意赠云间唐子四章 其四","f":"五言古诗","c":["大江际天流，将子一苇航。","飞涛如雪山，日夜奔钱塘。","同心苦离索，泪目驰河梁。","岂无盈觞醪，我友不共尝。","蒹葭被白露，林叶何萎黄。","朱弦感人怀，怨彼离别长。","翩翩两龙剑，各逐晨风翔。","雄雌一朝合，紫气腾岩廊。","许身贵许心，片诺为肝肠。","寄谢久要客，形骸良可忘。"]},{"t":"赠吴生充二首 其一","f":"五言古诗","c":["季重方七才，子华侈八面。","承家得苗裔，甘守蓬藿贱。","世途尚豪侈，裘马互矜炫。","伊谁振大业，往往雠笔研。","翛然韦布中，嗒尔罢歆艳。","遁迹吴山阳，索居严陵岸。","千秋岂不劳，乐此琴书玩。"]},{"t":"赠吴生充二首 其二","f":"五言古诗","c":["一丘伴麋鹿，抱膝良堪多。","何来念同好，负笈攀藤萝。","先生久避世，白眼横庭柯。","乾坤莽寥廓，故交邈山河。","玄亭不盈丈，愧汝常经过。","矫矫侯芭生，抱饥习吟哦。","英词烂金石，激楚停阳阿。","黄鹄飞摩天，壮龄日蹉跎。","岂无朱弦瑟，为子回沈痾。","才人例百六，坎壈终如何。"]},{"t":"赠黄氏二仲诗二首 其一","f":"五言古诗","c":["括苍一抔土，遂安万山腹。","大泽生龙蛇，连城孕双玉。","俱操七寸管，并骛千里足。","邂逅钱塘涘，翩褼紫阳麓。","折齿师仲淹，和歌到穷谷。","眷言申末契，悠然味伐木。"]},{"t":"赠黄氏二仲诗二首 其二","f":"五言古诗","c":["孟阳诚哲昆，季方亦难弟。","矫矫江夏黄，联飞盛明世。","谈诗各起予，琳琅远公社。","双凤鸣云中，二龙语天际。","回首华阳宫，故交日殒逝。","晚合盖自倾，居然洞肝肺。","隋珠岂不耀，愧此荷裳系。","归与葺衡杜，白首期勿替。"]},{"t":"清华馆为程生元鲁题","f":"五言古诗","c":["大鄣擅幽奇，名园负东郭。","衡茅数十椽，轩敞带长薄。","林木何翳然，空庭散鸟雀。","清涟媚藻荇，绿波映蘅若。","夹岸芙蓉披，中流芰荷灼。","翩翻白羽下，拨剌紫鳞跃。","之子吟逍遥，饮泌自斟酌。","沾沾御元礼，亹亹献康乐。","问字开扬亭，校书闭刘阁。","丈人习名理，夙谙卧游乐。","观鱼失濠梁，骑马涉京索。","缁尘染衣袂，行行悔入洛。","何当筑土室，行坐此丘壑。","千秋三径中，求羊未寂寞。"]},{"t":"汪生惟德工奕而温然长者行持卷乞言为赋","f":"五言古诗","c":["汪生歙都彦，家世本阀阅。","总角游巴邛，邂逅四仙列。","龙肝窃馀剩，随风堕天末。","携书客武林，精心究图牒。","休仁迨仲甫，遗谱恣翻阅。","藏机玉局中，妙思鬼神协。","一廛据湖山，所当帜必拔。","九枰欲较王，半道祇输滑。","纱帽挈隐囊，翘然布衣侠。","高车长者聚，短巷俗流绝。","半轩风雨声，广武战初合。","奇谋骋六出，庙算穷七伐。","斜照委绿苔，残星蔽黄叶。","逡巡斧柯烂，惨淡烛花灭。","谁云奕小道，先生早䟤跋。","岁月赢二毛，悠悠茂弘业。","当今号国手，方吕蔡颃颉。","一匡方擅齐，偏霸汪表越。","吕蔡季孟间，吾评匪僭躐。","黄王及朱范，少俊互腾踏。","猗哉盛一时，挽近谅难越。","就中孰恂恂，生也最驯洽。","澄清叔度侣，谨畏伯高埒。","争先戒贪竞，殿后泯骄伐。","遇我吴峰巅，屡结丈人袜。","愿言丏只字，千秋耀眉睫。","年来谢笔研，推敲废颊舌。","参差宿习萌，把袂若中热。","为汝聊嗫嚅，毫端纵涂抹。","久矣忘成亏，谁云较优劣。","枯棋三百六，廿载闭空箧。","冉冉负局翁，骑云去阊阖。"]},{"t":"送林贞耀藩参之岭南 其一","f":"五言古诗","c":["晨餐怅不御，飞龙在河梁。","驾言奉王命，千骑巡东方。","材官负旌节，组练纷路傍。","还州震华鼓，里闬烂生光。","伟哉图南鹏，八翼顺风翔。","把袂即修途，行行涉炎荒。","岂无临歧戚，执手互徬徨。","与子异形骸，去住安得双。","丈夫志万里，六合如帷房。","勉哉策高足，铜柱流芬芳。"]},{"t":"送林贞耀藩参之岭南 其二","f":"五言古诗","c":["大荒极东南，山川莽回互。","四百罗浮峰，参差矗云雾。","关河信纡郁，人文亦横骛。","阛阓连城壁，吹嘘竞相慕。","兴言适远塞，甘棠夹广路。","猗与振大雅，始兴并风度。","落帆炎海陬，舍筏曹溪渡。","勾漏饶丹砂，行歌白日暮。","绝域宁久淹，金茎湛仙露。","万仞飞云巅，帝阍会平步。"]},{"t":"读林氏三世集寄贞耀参知天迪员外","f":"五言古诗","c":["峨峨晋安里，王谢惟高门。","三朝四八座，玉立辉乾坤。","木天何寥廓，金闺信沈沦。","云烟烂东序，河汉流西昆。","赓酬亦递唱，文采如云屯。","突兀黄金台，咫尺限帝阍。","川容卧辋水，山火歌陆浑。","花晨竞彩笔，雪夜携芳尊。","欢言颂遗藻，典刑俨生存。","良哉汗青业，奕叶垂云孙。"]},{"t":"乙未秋邂逅梅生泰符把臂甚昵同观涛江上别去未几则闻生病且殆俄闻生竟不起矣余再入武林检敝箧得生手书屡纸不胜山阳邻笛之怆爰赋二言投宛溪之上以吊之 其一","f":"五言古诗","c":["梅生宛陵秀，负笈来钱塘。","啸咏湖山间，咳唾驰琳琅。","一朝玉树亭，睹我神飞扬。","十载胡先生，姓名狎词场。","慕子如渴饥，戚戚萦中肠。","龙门屹造天，怨彼一水长。","班荆倏成故，愿得升君堂。","嗟余蹇且拙，历落如桓郎。","将汝缱绻怀，永夕连匡床。","观涛大江涘，海若为徬徨。","眷眷执手言，晨风发河梁。","将无绮语累，念子毛发黄。","愿言保玉体，百岁遥相望。"]},{"t":"乙未秋邂逅梅生泰符把臂甚昵同观涛江上别去未几则闻生病且殆俄闻生竟不起矣余再入武林检敝箧得生手书屡纸不胜山阳邻笛之怆爰赋二言投宛溪之上以吊之 其二","f":"五言古诗","c":["流光不相待，倏忽三岁久。","郁郁上东门，春风五杨柳。","端居感离索，念子成老丑。","何图羽翼乖，丧我同心友。","玉树埋地中，垂杨几生肘。","发函见君书，洒泪湿蓬牖。","天运阻百六，词人厄阳九。","劲风扫飞藿，弱质复何有。","伤哉大国赋，默默如渑酒。","遗篇烂金石，为汝藏二酉。","千秋宛溪上，不愧朗陵叟。"]},{"t":"玉楼篇题李能茂遗墨后","f":"五言古诗","c":["香山兜率宫，谯郡遮须国。","笙飞蜕子晋，楼成召长吉。","造物诚小儿，大块黯无色。","伤哉一抔土，瘗此连城壁。","矫矫东阳生，雕龙擅畴昔。","雄心万古挫，猛气千夫失。","踔厉无前修，精进寡俦匹。","双眸狭宇宙，今古照瞬息。","弹丸婆娑界，十指肯浪屈。","猥余一日长，闾阎复咫尺。","负笈来藤萝，披襟坐蓬荜。","长啸金华颠，大呼石羊窟。","操觚问真宰，惨淡白虹泣。","晚叩琅琊门，中郎倒屣出。","通家孔融后，下榻陈蕃侧。","如渑卜兴代，生花赠彩笔。","频窥慈氏阁，屡面初祖壁。","善才拜未终，慧可髓几得。","呜呼大雄逝，金棺拉摩诘。","一真返桑扈，三号吊秦失。","白日愁西南，浮云怅东北。","伯道无遗孩，梁鸿有陋室。","弱女涕泗横，孤嫠形影只。","蟪蛄集荒榛，狐兔入丛棘。","殡宫对棠梨，织乌伴于邑。","何人奠麦饭，有客叹陈迹。","高文汲冢殉，丽句紫薇缉。","粲烂流江河，纵横走都邑。","只字回彭殇，寸心炯得失。","荣华剧臭腐，眼底复何惜。","嗟余少濩落，狂名世争诎。","青衫二十载，穷愁仗汝释。","一朝断交臂，畴与豁胸臆。","闻笛时悲酸，横琴重悽恻。","粲粲白玉京，修文拜新职。","惟应大鹏辈，八表独挥斥。"]},{"t":"寄苏君禹二首 其一","f":"五言古诗","c":["转蓬亦有根，飘飖随长风。","游子岂无家，卒岁歌途穷。","宛宛同心人，咫尺钱塘东。","眷言赠芳草，轩车若游龙。","朝驰武林驿，夕止禦儿宫。","八翼排金门，双钩气如虹。","而我独何为，一室长忡忡。","伤彼四愁咏，目送寥天鸿。"]},{"t":"寄苏君禹二首 其二","f":"五言古诗","c":["桂林实奇秀，千峰矗云霄。","丈夫桑弧志，驱马万里遥。","曲江浣尘壒，愚溪涤烦嚣。","伐鼓震五岭，舞干洽三苗。","昔人读书台，突兀回霞标。","黄鹄一再举，宇宙参游遨。","鸿篇勒琬琰，姓字留荒要。","皇皇四门辟，柱石毗清朝。"]},{"t":"幔亭篇答黄文学尧衢","f":"五言古诗","c":["黄生起南服，摛藻自弱冠。","蝉噪薄隋梁，龙跃躏秦汉。","大言或元封，小咏亦贞观。","宛宛乐府词，珠玑烨璀璨。","畸游闽海上，独抱延平剑。","九曲浮清泠，九漈吟泮涣。","飞扬大江楫，踯躅广武战。","何哉九合勋，桓文谬推赞。","前茅受旗鼓，中权属坛坫。","穆穆清风颂，寄我剧三叹。","呜呼哲人颓，往事涕如霰。","琅琊玄草绝，丰社白榆散。","阳春怅谁和，长夜邈难旦。","灼灼倾城姝，昭阳擅飞燕。","凌云羽翮就，泽雾文彩变。","大鹏遇希有，八极眇一盼。","将无笑鸴鸠，会有嘲斥鴳。","俗士迷前筹，达人炳遐算。","奇峰三十六，一一造天半。","为报武夷君，广张幔亭燕。"]},{"t":"夜灯同永叔话旧仲子弼年十四于座中戏咏白石榴有霜寒秋色净明月挂枝头之句余嘉其风格朗朗赋此勖之","f":"五言古诗","c":["石梁驾丹壑，赤城横紫霄。","天台八万丈，的皪悬霞标。","司空毓灵秀，龙跃随神尧。","华名走绝域，茂实腾中朝。","郁郁庭阶树，三珠粲同胞。","青钱捷唾手，俯拾如承蜩。","高阳失才彦，颍上惭时髦。","文章聚花萼，薄海誇贤豪。","缅余识季公，把臂成久要。","古心出坟索，逸韵驰风骚。","矫矫八尺躯，耻偕儿女曹。","胸吞梦泽水，气折洪河涛。","雄飞邈广汉，雌伏怀穷交。","皇皇潞河涘，十口勤维梢。","空同倚长铗，函谷遗绨袍。","吹嘘及朽干，揽挈当前茅。","狂歌复痛饮，浩荡穷深宵。","呼卢堕明月，角奕流神飙。","情投俨胶漆，契合钧咸韶。","酒酣见仲子，烨若英琼瑶。","翩翻慕周孔，卓荦谭伊皋。","孤芳涤尘腻，五字驱炎嚣。","灵光诧授简，鹦鹉怜挥毫。","扬收劣加岁，子安正垂髫。","伊余越四十，兰玉殊凋萧。","对此重叹息，中肠热如焦。","于门一何盛，咄咄钟灵苗。","丹山讵凡翮，渥水真奇毛。","勉哉事大业，岁月如风飘。","无穷有令闻，不朽宁金貂。","下帏第发愤，惜阴竞蓬茅。","六经鼓元气，百氏罗秋毫。","馀皇破巨浪，繁弱联双雕。","祖孙及子父，奕叶驰华镳。","回首天台色，东南正寥寥。","惟应太原望，世世争岧峣。"]},{"t":"戒装武林别施蔡二生","f":"五言古诗","c":["施生赤城彦，蔡子黄岩英。","吞吐石梁霞，各著词苑声。","相逢武林道，握手盖自倾。","交孔竞持刺，识韩互班荆。","廿载龙门怀，一旦希合并。","空山咏伐木，求友何嘤嘤。","缅余朽且拙，蚓窍鸣舂莺。","翩翩两国士，立谈四座惊。","击筑邀渐离，脱剑遗荆卿。","河桥骤脂辖，立马言长行。","行行去吴会，望望投幽并。","屋梁梦颜色，落月悬高旌。","念彼新知乐，日夜肝肠撄。"]},{"t":"翠筠轩十六韵为姑蔑柴生起用题","f":"五言古诗","c":["仲蔚耽蓬蒿，陶公艺松菊。","何如三径中，翛然万竿绿。","掩映王猷居，蔽亏张廌屋。","夹砌澄清涟，捎檐洒飞瀑。","琤琮风乍鸣，葱茜雨新沐。","秀色分渭川，清阴散淇澳。","天寒白鹤下，日暮文鹓宿。","主人挟胡床，閒把道书读。","曳杖时科头，衔杯或坦腹。","裴李咸披襟，嵇阮互游目。","高秋横笛音，五夜洞箫曲。","嗟余罹世网，羡尔轶尘俗。","佳人隔翠袖，千里梦空谷。","将因挈枕簟，晚岁共幽独。"]},{"t":"题蔡稚含适适轩二首 其一","f":"五言古诗","c":["达人委元化，哲士戒迷涂。","一枝遂鹪鹩，九万匪所图。","乐志追仲长，潜耀希王符。","轩窗仅容膝，结搆临菰蒲。","座右横清琴，相对酒一壶。","客来但留酌，往往高阳徒。","俯仰宇宙中，倏若黄公垆。","秋色下前山，我醉君但扶。","不见南郭生，嗒然忘故吾。"]},{"t":"题蔡稚含适适轩二首 其二","f":"五言古诗","c":["忆昔金马门，执戟趋铜龙。","雄飞奋六翮，夭矫随天风。","一朝事势异，漂转如征蓬。","人生贵适意，大业宁三公。","开轩赤城畔，丹霞照帘栊。","图书不盈丈，有若蓬莱宫。","神游八极表，目送双飞鸿。","陋彼征西贵，柴棘盈胸中。","太虚为我宅，何事悲途穷。"]},{"t":"再送惟德使君挂冠还景陵","f":"五言古诗","c":["士有旷世志，宏览隘八荒。","烨如岐山凤，千仞常孤翔。","矫矫徐使君，束发趋明光。","高台骋骥足，绝栈逾羊肠。","淮圻缚猖獗，歙甸宁劻勷。","肤功勒琬琰，大业悬旂常。","洪流割淮泗，再起纾怀襄。","玄圭帝三锡，荐牍交岩廊。","皇皇神武门，振步皆康庄。","凉飙倏以厉，悲彼芰荷裳。","一朝返初服，挂冠出徐方。","父老涕泗横，蹩躠盈路傍。","勇退乘急流，永谢浮名缰。","咄咄邯郸翁，朝餐熟黄梁。","大千等梦幻，绿鬓俄秋霜。","逝将息埃壒，冲漠朝羲皇。","筑宫寄层巘，结宇临崇岗。","曳杖泰山颠，挂瓢颍水阳。","五湖笑鸱夷，六合追云将。","我友值明发，送子临河梁。","眷眷脱屣怀，大觉回沧桑。","高风凛百代，感叹徒彷徨。","伟哉扶摇翮，宇宙呈圆方。","他时挟鸡犬，拔宅升微茫。","金茎烂云际，甘露流天阊。","愿言洒病骨，馀沥沾枯肠。"]},{"t":"怀姑蔑柴生起用时生将谒余燕中","f":"五言古诗","c":["秦嘉滞府胥，常建窘邑尉。","良哉达人言，高才鲜贵位。","矫矫姑蔑墟，柴生出其类。","青云走牛马，白日侣蚊蚋。","案牍劳形神，刀笔记功罪。","八议权亲疏，五刑覈情伪。","宁怀张杜刻，敢冀萧曹会。","论交企兰荃，投诚密萧艾。","丽句蒐梁陈，遐思闯晋魏。","白雪流轻扬，丹霞献明媚。","沾沾太玄草，捧诵若金匮。","嗟余素寡合，念汝欲捐佩。","南山歌未阕，北陆盟忍背。","胜流实嵚崎，名士本憔悴。","浮踪自昔然，大业岂终累。","不见渔阳挝，正平兴弥锐。","至今鹦鹉篇，永拔词赋萃。"]},{"t":"挽宋西宁忠父","f":"五言古诗","c":["贤士悲龙蛇，才人困百六。","嗟嗟宋子侯，宛尔大夫玉。","夭矫珊瑚枝，光辉夺鱼目。","冲虚本天性，濡下甘自牧。","执辔道愈尊，结袜躬岂辱。","门庭聚四海，宾客互追逐。","飞觞不问主，洗盏辄更仆。","悲秋坐五夜，避暑卧三伏。","欢言讵知疲，豪举动惊俗。","才高世争妒，名成帝未录。","上谷无爰书，中山有谤牍。","一眚遗干城，寸朽弃良木。","长康笑黠痴，桓伦叹轣辘。","万钟亦何加，千秋会相属。","煌煌白玉楼，忽赴上清箓。","令威去辽阳，莫邪闭丰狱。","虚堂妖鵩鸣，荒冢孽狐伏。","河山怨离索，宇宙恨幽独。","白杨翳泉台，青藜熄天禄。","寥寥郢中赋，悽怆不堪读。"]},{"t":"方母孀节诗为厥子伯苓题","f":"五言古诗","c":["烨烨新都媛，修蛾粲明珰。","十三字君室，十五登君堂。","良辰一以醮，中厨奉姑嫜。","眷言拂巾席，皓首偕匡床。","风波起中路，庭树飞秋霜。","青铜掷妆阁，碎裂罗衣裳。","剖心慰夫婿，截发藏筐箱。","空闺抚弱息，血泪横枯肠。","松关白日暮，永夜啼寒螀。","抱影三十年，哀哀称未亡。","缅怀励高节，泚笔题篇章。","他时继黄鹄，万古明天常。"]},{"t":"宝剑篇 其一","f":"五言古诗","c":["司空两龙剑，紫气何煌煌。","雄雌闭石匣，万古垂精光。","忆昔初铸时，乃在越溪傍。","谁能为此技，莫耶与干将。","百鍊就镡锷，千鍊成锋芒。","风波起长路，出处俄参商。","一飞九天外，八翼游岩廊。","一沈九地中，悲鸣和寒螀。","时命固大谬，分违亦其常。","与子匪一身，尔我安得双。"]},{"t":"宝剑篇 其二 天马咏","f":"五言古诗","c":["天马汗血驹，騀駊出湟中。","一鸣伯乐顾，再鸣冀北空。","何来市骏者，相值华阳宫。","黄金百万镒，玉勒驰青骢。","飞行历九陌，畴不怜追风。","悲哉照夜足，踯躅太行东。","岂无烈士肠，岁年倏成翁。","徒令厮养卒，执策嗤龙钟。"]},{"t":"宝剑篇 其三 豫章行","f":"五言古诗","c":["亭亭孤生木，厥惟豫章材。","苍龙蛰岩穴，鳞甲缠莓苔。","一朝鲁班氏，伐至秦王台。","中天悬高栋，有若登蓬莱。","万间碍星月，九级披云霾。","金银互文饰，朽栎庸堪偕。","宁知大椿树，广莫甘尘埋。","春秋八千计，逍遥卧无怀。"]},{"t":"二难双美诗为大参张公赋","f":"五言古诗","c":["猗欤三百篇，张仲颛孝友。","四姓雄金阊，吴趋实材薮。","森森五丹桂，扬芳赞皇囿。","惟时疫疠侵，高堂阨阳九。","饔飧滞床笫，汤药盈鬲卣。","诸昆竞扶侍，昏旦递奔走。","叔也尤徬徨，虮虱生带纽。","露祷临中逵，恍惚心语口。","母算倘可延，儿躬曷遑有。","昊天若倾听，冥冥肯其首。","沈疴遽霍然，衰札起蒲柳。","一死全吾心，庸恤近与久。","飞腾属少公，万卷穷二酉。","大孝昭显扬，龙章焕星斗。","元方操实奇，季方遇宁偶。","峨峨二难列，异代同不朽。","二难既表吴，双美尤擅越。","缅怀神仙尉，微官寄太末。","束带见督邮，甘等绛灌列。","去思二十载，高风柳下颉。","积庆流参知，振代睹人杰。","诗礼闻家庭，颂赋起岩穴。","读书直中秘，五车恣渔猎。","升沈递扬历，显晦互更涉。","直声耸庙堂，上考奏藩臬。","大旆翔三衢，棠阴半姑蔑。","遗民泣往躅，故老颂休烈。","厅事垂双松，步武俨对越。","熙朝述盛事，名宦祠世业。","至行通神明，清芬播齿舌。","弟昆洎父子，后先迥光绝。","令誉收一门，千古垂阀阅。"]},{"t":"饭惟寅白雪山房话旧","f":"五言古诗","c":["错落双龙剑，寒芒凌素秋。","紫气烛丰城，射彼斗与牛。","一朝遇司空，发函佩吴钩。","风霜划相妒，坐拆苍精虬。","雄飞渺北极，雌伏还南州。","山川莽寥廓，哀鸣互相求。","霜华粲中夜，索处声啁啾。","何意长安陌，相逢重夷犹。","一见喜且惊，倒屣罗珍馐。","高堂把桑落，历数平生游。","弹指三十年，震旦若浮沤。","夙昔红颜子，参差俱白头。","升沈间存没，万感盈荒丘。","缅邈同心人，中原聚名流。","琅琊失麟凤，岭表埋黎欧。","突兀鲁灵光，寥寥见君侯。","头风汝旋愈，肺病余宁忧。","惟应委元化，百龄暮优游。","安期下玉舄，赤松驻瀛洲。","仙飙载羽翼，八极朝宸旒。"]},{"t":"惟寅以书贶驰使潞河适媵人偶举一子走笔赋答","f":"古风","c":["惊尘荡白日，羸马驰郊墟。","怅彼同心人，缅邈百里馀。","举头云中翮，有鸟衔尺书。","粲粲瑶华札，开缄照衡庐。","慰我加餐饭，问我何方居。","十口寄他乡，晨餐食无鱼。","芒鞋役款段，谁为供高车。","感此长太息，临风重踟蹰。","肮脏宇宙间，畸游抱琴书。","朱门盛先达，落落穷相如。","夙昔逢君侯，青骢曳华裾。","情亲四十载，胶漆垂桑榆。","缠绵国士念，涸辙频吹嘘。","岂忘木桃报，再拜惭庭除。","中闺夜得雄，旅抱偶一舒。","眷言骨肉友，卧起同徐于。","持此答芳讯，聊用当璚琚。","颓然定一笑，为我掀?毹。"]},{"t":"题瞿令人册为茂才绍曾","f":"五言古诗","c":["妇惟丁生母，卓行超人寰。","笄岁适名门，婉若蕙与兰。","结缡讵云久，灾氛岌相缠。","良人遘奇疾，百体纷摧残。","心神忽眩瞑，手足时颠连。","欢娱掷中道，畴不虞红颜。","母也执高节，涕泗如流泉。","呼天誓同穴，肯析双飞翰。","一身委床笫，药物长周旋。","肝肠绝怨怼，面目忘媸妍。","仰事头白姑，頫鞠黄口男。","家徒四壁立，辟纑夜灯前。","拮据度荒馑，永昼怀饥寒。","彼苍鉴明德，绕膝森鹓鸾。","矫矫汗血驹，励志游天闲。","劬劳念母氏，赋咏蒐名贤。","我闻载叹息，踊跃操如椽。","偷生信为易，蹈死亮非难。","厄哉斯人遇，毕世罹忧患。","贞心既不毁，淑问仍终完。","夫存子亦树，晚节聊蝉联。","宁知处困怀，荼毒穷当年。","凛凛铁石肠，兴彼懦与顽。","裁诗颂令哲，史笔千秋传。"]},{"t":"谒关忠义庙作","f":"五言古诗","c":["中原遘百六，汉鼎分三雄。","矫矫忠义侯，挺身出蒲东。","草茅识先主，仗剑扶真龙。","间关袁吕营，百折明丹衷。","飞扬白马战，锐气嘘长虹。","立取上将头，万夫摧折冲。","解围谢曹氏，绝婚诟吴侬。","巨浪渰七军，襄樊列艨艟。","禁俘德亦虏，大江血流红。","威声赫华夏，皦日悬晴空。","陆浑亘许洛，壶浆若云从。","讵意肘腋间，包藏剧群凶。","蚩蚩众狐蜮，发奸维逊蒙。","轻舟袭南郡，九仞隳成功。","麦城困孤旅，临殂徼元戎。","讵云彼苍酷，况乃炎精终。","昭昭玉泉宇，肸蚃侔层穹。","河山峙壮节，尸祝盈寰中。","姓名走妇孺，位号歆儿童。","伊余肃遗像，飒爽来英风。","嗟彼操与权，死生细螟蠓。","累累两国贼，紫阳笔何公。","遐哉九朝祀，元运偕无穷。","刚肠俨对越，三叹钦前踪。"]},{"t":"观察林公尝感异梦于忠义以左辖赵公之辑侯志也索题其像爰继此篇","f":"古风","c":["汉统遘桓灵，县宇互分裂。","卓布首倾危，操权晚猖獗。","矫矫中山胄，风尘缔材杰。","猛气雄万钧，危途历九折。","下邳阨羊肠，官渡奋鼠穴。","生平为刘念，俄顷报曹节。","大呼枭敌元，干将路明灭。","全师镇荆楚，威名愈腾掣。","孟起标卢前，汉升耻灌列。","长驱出汉沔，舟航泰山压。","禁俘若羊豕，德磔等蠓蠛。","先声震华夏，壶箪道填咽。","高光四百基，克复俨眉睫。","汉贼肝胆惊，吴歈梦魂摄。","外交托姻㜕，内忌迥秦越。","阴谋剧魍魉，狙伺锐饕餮。","艛?藏戈矛，烽屯虏间谍。","侯也天日衷，迄堕群小策。","峥嵘两岩郡，望风授凶孽。","遂令盖世功，弹指恨□□。"]},{"t":"婺中三子诗 其一 刘参军孝标","f":"五言古诗","c":["嵯峨婺女郡，星斗垂寒芒。","寥寥旷千载，气运开齐梁。","刘生实天启，乳哺随高堂。","翩然自北来，烨若孤凤凰。","读书紫薇岫，一目逾十行。","山栖表远志，绝交廑中肠。","千言走珠贝，七录披琳琅。","含毫策锦被，倏忽惊岩廊。","遂令世主忌，坎壈终词场。","龙蛇谅斯在，鸿鹄讵可量。","矫矫七尺躯，耻为万乘降。","胡然际悍室，妖牝啼朝阳。","潜身叹孤犊，跛足追亡羊。","太息敬通论，今古为徬徨。"]},{"t":"婺中三子诗 其二 骆侍御宾王","f":"五言古诗","c":["仙李方二叶，九庙摧妖狐。","刳剥尽生灵，宇内无完肤。","岳岳临海公，奋袂起菰芦。","义旗举大泽，百万当一呼。","虹霓切云汉，雨泽滂泥涂。","操我七寸管，问彼六尺孤。","片言嚇淫牝，一战枭群奴。","惜哉下阿战，倒甲如摧枯。","奇功固罔立，大义差足扶。","披缁入灵隐，觅句酬跏趺。","金锤隐博浪，钜轴流江湖。","固知艺文杰，讵曰器识疏。","一辞道王辟，无忝令伯徒。","至今读遗草，激懦开顽夫。"]},{"t":"婺中三子诗 其三 沈仆射休文","f":"五言古诗","c":["六代更废兴，文士故不乏。","奋迹惊才贤，乘时见髦杰。","猗欤沈隐侯，文章何烨烨。","骋望游中台，违情守东越。","佩玉辞岩廊，鸣金下阊阖。","沿泳双溪流，迟徊三洞穴。","会圃临春风，登台望秋月。","旌旆俄飞扬，剑履倏腾踏。","一代怀龙门，千秋仰骥秣。","四声启后流，八病表先达。","尽剖洪荒秘，卓为艺林筏。","儒生互雌黄，志士竞鈇钺。","寥寥数千载，风流竟谁越。","岂伊腐草流，尘土共澌灭。"]},{"t":"二怀诗 其一 玄真子张志和","f":"五言古诗","c":["有唐迄元和，畸流尚不乏。","翩翩玄真子，百代恣渔猎。","雅志游松乔，奇踪轨庄列。","嗒尔柱下言，超然谢津筏。","富贵轻鸿毛，轩冕等澌沫。","一辞世主聘，浮家老苕霅。"]},{"t":"二怀诗 其二 禅月大师贯休","f":"五言古诗","c":["唐末缁流空，休公崛然起。","卑卑局晚调，兀兀吐玄旨。","冥心师楚圆，苦思叶齐已。","禅启天竺诠，画妙应真理。","片言忤大帅，脱身钱塘汜。","一钵游岷峨，逍遥入无始。"]},{"t":"婺七贤诗 其一 吕太史伯恭","f":"五言律诗","c":["于越称上游，婺实文献域。","唐末何式微，宋南复中辟。","太史虽儒宗，词华蔚天植。","惜哉掩艺成，端居圣门籍。"]},{"t":"婺七贤诗 其二 陈状元同父","f":"五言律诗","c":["同甫真人豪，矫矫谢拘局。","宁为跃冶金，肯作瓦全玉。","四上阜陵书，十返紫阳牍。","至今华川阳，英气贯岳渎。"]},{"t":"婺七贤诗 其三 唐刺史与正","f":"五言律诗","c":["与正颇负奇，翩翩孝皇代。","作吏弘风流，经国纪乡遂。","世尊考亭疏，迄掩干城锐。","细行诚足矜，大德岂终累。"]},{"t":"婺七贤诗 其四 黄侍讲晋卿","f":"五言律诗","c":["侍讲起胜国，举代推词场。","高踪峙虞揭，遗躅开宋王。","遂令婺女颠，光焰万丈长。","惜哉骆刘绪，缅邈空梁唐。"]},{"t":"婺七贤诗 其五 柳文肃道传","f":"五言律诗","c":["文肃兴闾阎，挥毫走当代。","文事既渟泓，儒宗亦映带。","毫濡瀫川涘，研涤浦阳濑。","一传太史公，粘天决千派。"]},{"t":"婺七贤诗 其六 吴山长立夫","f":"五言律诗","c":["金华本学薮，渊颖弥锵锵。","潜心事大业，奋志游羲皇。","一命讵足荣，千秋在文章。","鸱鸢亦奚事，腐鼠矜鸾凰。"]},{"t":"婺七贤诗 其七 陈隐居君","f":"五言律诗","c":["元季多奇人，出语必惊众。","山川纵吞吐，造物时簸弄。","魂梦游玉楼，敲推入醋瓮。","嗟彼龙豹姿，甘为鬼才用。"]},{"t":"采邑三贤诗 其一 范隐君茂明","f":"五言律诗","c":["濯濯香溪流，汀洲杂兰芷。","之子怀清芬，南渡勃然起。","大隐弘高风，真修味玄旨。","遗文讵必多，一脔见嚆矢。"]},{"t":"采邑三贤诗 其二 金文安吉父","f":"五言律诗","c":["吉父英雄姿，夙负济时略。","不受帝王知，遂工贤圣学。","著述逾三车，卧游历五岳。","至今尚典刑，遗像俨丹雘。"]},{"t":"采邑三贤诗 其三 吴礼部正传","f":"五言律诗","c":["煌煌礼部公，执戟隐金马。","怜才若饥渴，片善必挥洒。","馀日酬诗歌，居然振大雅。","世无扬子云，谁为好玄者。"]},{"t":"读国初四君遗集 其一 宋学士景濂","f":"五言律诗","c":["猗与太史公，振代见才杰。","百氏勤雕锼，二典恣渔猎。","雄章发天造，大手扬帝烈。","至今艺士林，冠世推阀阅。"]},{"t":"读国初四君遗集 其二 王忠文子充","f":"五言律诗","c":["忠文起草昧，弱冠宣王猷。","雄才动宸宁，大节扬蛮陬。","肝肠凛铁石，毛发如悬疣。","巍巍文士烈，烨烨垂千秋。"]},{"t":"读国初四君遗集 其三 苏内翰平仲","f":"五言律诗","c":["奕奕空同生，名家出华右。","雕龙擅制作，绣虎威百兽。","才启北地先，裔属颍滨后。","遂令赤松顶，峨眉郁同秀。"]},{"t":"读国初四君遗集 其四 胡教授仲申","f":"五言律诗","c":["才贤萃吾婺，仲子维吾宗。","双溪濯蘅杜，三洞扪芙蓉。","霜蹄絷百里，天门恨九重。","寥寥信安集，一脔窥良工。"]},{"t":"宋王二隽篇","f":"五言律诗","c":["浦阳既龙跃，华川亦鷟起。","有雏必九苞，为驹日千里。","飞翰洒玉楼，重茧历金齿。","太息承家风，寥寥坠兰芷。"]},{"t":"存没篇四首 其一 黎秘书惟敬","f":"五言律诗","c":["黎公产岭表，宛若荆山璞。","沉湎偕步兵，滑稽类方朔。","一官寄长安，十载卧玄阁。","悠然太古民，相对忘寥廓。"]},{"t":"存没篇四首 其二 徐方伯子与","f":"五言律诗","c":["嘉隆振雅道，徐君实天纵。","翱翔五子间，烨如九霄凤。","维昔平原馆，如渑为余颂。","倏为岱岳游，能无山阳恸。"]},{"t":"存没篇四首 其三 欧博士桢伯","f":"五言律诗","c":["烨烨欧桢伯，人伦挺奇迈。","宦游三十年，囊惟一毡在。","大隐留金门，遐悰寄尘外。","把臂惭后时，论心乃前代。"]},{"t":"存没篇四首 其四 梁内史思伯","f":"五言律诗","c":["太息平生交，梁鸿遂长夜。","忆昔长安游，屡命千里驾。","遗冢邻要离，修文佐卜夏。","罗浮四百峰，望尔涕交下。"]},{"t":"寄吴门四子诗 其一 周文学公瑕","f":"五言律诗","c":["公瑕布衣侠，夙习游钟王。","珠玑耀千裔，琬琰被八荒。","诗篇匪细事，一一追三唐。","希声岂谐俗，太息云门章。"]},{"t":"寄吴门四子诗 其二 王山人承父","f":"五言律诗","c":["东吴菰芦中，乃有如此人。","形骸若象罔，富贵轻浮云。","含毫役万汇，混迹游风尘。","笑我何太拙，白首攻玄文。"]},{"t":"寄吴门四子诗 其三 曹山人子念","f":"五言律诗","c":["曹生滑稽雄，自称子建后。","须髯河朔豪，翰墨江左秀。","康伯惟令甥，杨恽实贤舅。","为忆两琅琊，哀涕泫清昼。"]},{"t":"寄吴门四子诗 其四 王茂才世周","f":"五言律诗","c":["艺士工浮儇，末俗寡淳质。","自与王郎游，恍入华胥国。","锦里馀角巾，临邛有立壁。","一诵次公言，千秋白虹泣。"]},{"t":"六公篇 其一 高太史季迪","f":"五言律诗","c":["四杰起江左，太史何琅琅。","一鸣骇万鸟，百中连双鸧。","朱弦奏上国，白纻歌明堂。","遂令十叶后，率土归吴阊。"]},{"t":"六公篇 其二 李观察献吉","f":"五言律诗","c":["河洛钟人龙，图书倏辉映。","文起八代衰，诗还四始盛。","坎壈虽当时，灵光独晚境。","突兀空同颠，犹怀广成问。"]},{"t":"六公篇 其三 何观察仲默","f":"五言律诗","c":["嵩岳降英灵，生申维仲默。","威凤抟紫霄，祥云捧丹日。","得岁劣陈思，齐年过王勃。","今古三少成，惜哉同六极。"]},{"t":"六公篇 其四 徐博士昌谷","f":"五言律诗","c":["斯人江左秀，朗若披云岑。","清风振玉佩，白雪鸣瑶琴。","应刘失前步，陆谢无遗音。","太息谈艺录，良工诚苦心。"]},{"t":"六公篇 其五 高参知子业","f":"五言律诗","c":["李何峙中原，顾盼失后辈。","高生稍晚出，如渑倏兴代。","清庙列尊彝，中天落空翠。","咄嗟有尽年，骤与飘风会。"]},{"t":"六公篇 其六 李廉访于鳞","f":"五言律诗","c":["嘉隆建大业，济南实前茅。","含毫有八极，耸翼无九霄。","遐心自皇古，傲骨宁中朝。","至今蛾眉雪，千仞留孤标。"]},{"t":"五君咏 其一 汪司马伯玉","f":"五言律诗","c":["桓桓司马公，文武实天授。","大笔摅云雷，穹碑揭宇宙。","横飞北地前，独步弇山后。","伟哉词人场，百代归领袖。"]},{"t":"五君咏 其二 吴参知明卿","f":"五言律诗","c":["明卿起南服，束发娴声诗。","一麾守岭海，三黜行罗施。","飞书问供奉，鍊句追拾遗。","谁能竭大海，尽出珊瑚枝。"]},{"t":"五君咏 其三 张中丞助父","f":"五言律诗","c":["张公江海客，丱角游天朝。","霜蹄躏千里，风翮抟九霄。","彩毫建安席，赤帜开元标。","遇我华阳馆，片诺成久要。"]},{"t":"五君咏 其四 欧水部桢伯","f":"五言律诗","c":["岭南维欧君，俨若饮醇酒。","拙宦三十年，工诗五千首。","黑发游中原，白头卧林薮。","惆怅兰阴台，落日共挥手。"]},{"t":"五君咏 其五 赵太史汝师","f":"五言律诗","c":["矫矫赵司成，风槩自天植。","胸腹罗星辰，肺肝秉铁石。","轮埋御史亭，座首司寇席。","蔚为文士光，宁彼九鼎力。"]},{"t":"八哀诗 其一 大司寇东吴王公世贞","f":"五言古诗","c":["洪荒忽中辟，宇宙钟人豪。","间气五百年，一旦开皇朝。","天挺琅琊公，河汉骑斗杓。","题诗恼玉帝，谪籍游尘嚣。","肝肠错锦绣，咳唾垂兰苕。","胸吞太湖水，笔涌耶溪涛。","九岁咏凤凰，十龄题宝刀。","十三作文赋，十九抟青霄。","高才聚东井，散秩同西曹。","广心出皇古，奋臂追前茅。","呜呼蓟门事，大纛摧鸣枭。","仓黄别上国，惕息还蓬蒿。","归来卧穷巷，削迹甘渔樵。","雄文凿混沌，大乐鸣英韶。","东瀛极沧海，南纪逾铜标。","北冥亘沙漠，西域穷荒要。","八埏走琬琰，九域飞琼瑶。","千金买只字，百镒酬挥毫。","瑰辞匹坟典，丽句骈风骚。","多闻失刘向，捷给凌枚皋。","帝心亦简在，日夜驰干旄。","东山乍一出，被发仍由巢。","竺乾叩真诠，漆园明逍遥。","香云拂几席，甘露流天瓢。","金棺下阊阖，玉树埋山坳。","中华折天柱，下界闻鸾箫。","双虬去广汉，八骏升岧峣。","玄丘见王母，白云和长谣。","乾坤失盟主，海岳颓高标。","安得跨大鹏，万里随神飙。"]},{"t":"八哀诗 其二 太常东吴王公世懋","f":"五言古诗","c":["清河维哲昆，颍川实难弟。","太常何英英，二十誇谒帝。","隽声走上国，唾手拾巍第。","居然棣花萼，烨并芙蓉蒂。","翩翻擅绮藻，韶瑩绝尘泥。","皎月悬春空，朝霞豁晴霁。","朗朗屋百间，虚舟了无系。","振佩游春曹，诗篇骤名世。","标新见玄理，汰俗起凡例。","纵横信阳筏，磊落济南契。","怜才贯金石，握手忘荼荠。","伊余实庸驽，公也口不啻。","扢扬亘古今，寄托深祢禘。","太息身后名，孤愤千载计。","神游贯八极，江海穷鼓枻。","飞泉漱三叠，大泽浮九漈。","徘徊华峰莲，厌饫闽岭荔。","一纡太常绶，清斋问真谛。","紫府翻丹经，绛宫候飞履。","洪崖拍右肩，金母拜左髻。","云軿下五浊，笙鹤遽迢递。","龙蛇发丹灶，鸡犬入霞际。","虚疑老成丧，坐惜典刑逝。","三叹杜陵诗，高才日凌替。"]},{"t":"八哀诗 其三 大司空江右朱公衡","f":"五言古诗","c":["猗与大司空，突兀起江右。","烨如匡庐颠，罗列千万岫。","弱冠登岩廊，老宿推领袖。","功名迄自致，建树必高厚。","历扬亘二纪，盘错靡不就。","嘉皇四十祀，八荒庆在宥。","河流倏奔突，淮泗若悬霤。","生灵困鱼鳖，巢窟杂猿狖。","大庭推司空，佥曰惟夏后。","一麾出飞云，百神互驰骤。","铁锁缠支祈，金书勒史籀。","大泽疏洪涛，长堤障罅窦。","三时督工匠，百里并延袤。","留城距济谷，一一置封堠。","白马沈宣房，玄圭锡华胄。","平成在天地，吐纳偕宇宙。","择言到刍荛，采纳及芜陋。","垂髫诧国士，煦燠若怀袖。","深知大海量，涓滴务兼受。","缅怀西山芝，愿纪南极寿。","胡为跨鹤羽，群真毕相候。","褒荣亘泉壤，雨泣遍耆旧。","尚忆驱龙蛇，至今贡橘柚。","明明大禹德，夐夐绝前后。"]},{"t":"八哀诗 其四 御史中丞闽中滕公伯轮","f":"古风","c":["维三十六峰，秀甲东南服。","笃生大中丞，如海王百谷。","夙偕武夷君，并主赤城箓。","沆瀣餐七台，明霞卧九曲。","一朝念黎元，曳杖下云陆。","孩提见异质，仪羽何郁郁。","虎头燕颔姿，万里飞食肉。","龙泉太阿锷，见者讵敢触。","意气干层霄，襟次苞岳渎。","皇王及帝霸，一一悟正鹄。","居邻紫阳宅，先觉窃自淑。","刚严继子厚，方雅表正叔。","三十登熙朝，历块徵骥騄。","岭海行花封，罗浮玩朝旭。","含香入铨省，造请绝苴牍。","当门忌兰?，故里蓺松菊。","明主念旧勋，飞诏起林麓。","朅来柄文衡，越士罄程督。","楼船汎沧海，蓝笋历天目。","浩荡窥人文，豪英听约束。","夜课三千徒，朝荐十六族。","泰山纳寸壤，渤澥收一掬。","伊余实驽蹇，盐车困驰逐。","顾盼超骊黄，立贡千里足。","世轻园令金，公拟卞和玉。","提携洞底里，邂逅吐肝腹。","峨峨翠虚亭，清燕几回瞩。","礼数捐苛烦，杯斝绝边幅。","潢池忽中扰，帝命驰大纛。","强弩横钱塘，朱旂镇三竺。","威严控豪右，字恤逮樵牧。","闾阎绝寇警，仓廒发馀粟。","遂令全越氓，比户胤膏沐。","仰父仍俯子，左餐更右粥。","凿凿元戎疏，宰司罄采录。","方酬大贤绩，永显儒效速。","胡为跨青鸾，倏尔谶妖鵩。","剧知勋庸盛，翻讶日月促。","譬彼南阳龙，尽瘁事兴复。","一朝殒大星，精爽尚肃肃。","缅怀涧中藻，已拱墓傍木。","吞声受恩士，血泪尽痛哭。","先民失懿范，遗统竟谁属。","惟应圣门业，永永耀斑竹。"]},{"t":"八哀诗 其五 大司马西蜀张公佳胤","f":"五言古诗","c":["张公产岷峨，夙抱文武略。","伟哉沈深度，宛若未雕璞。","通籍游皇都，浩气贯碧落。","出宰河阳县，解褐遘盘错。","奸萌起肘腋，万众互骇愕。","一顾摧凶渠，势若反掌握。","及乎任西曹，亟闯五子幕。","大敌逢李王，奋勇与之角。","遂登作者坛，文誉不落莫。","功名浸鼎盛，岁月旷著作。","三关树高牙，敌胆慑沙漠。","呜呼壬午事，大手睹挥霍。","潢池舞鳅鳝，白日走蜃鳄。","明廷廑南顾，大吏咸塞缩。","维公奋臂出，长虹耀千莫。","首刷闾阎忧，六街静鸣柝。","渊谋秘胸腹，远智运龙蠖。","声色了不动，从容卧帷幄。","一朝令辕门，群小悉面缚。","累累九青兕，一一就脯臛。","人怀顾复惠，士有更生乐。","武功既荡平，文事稍恢拓。","飞檄凌扶桑，露布入平乐。","长裾曳曹丘，敝屣接东郭。","帝嘉定边勋，飞诏下京洛。","本兵属运筹，九塞遵东约。","胡为殒长城，骤失北门钥。","回思瀫江涘，单骑访岩壑。","迓我钱塘郊，恍忽共濠濮。","诧我雍然音，一代恣腾攫。","手迹宛若新，足音遽寂寞。","矫首铜梁里，大树日萧索。"]},{"t":"八哀诗 其六 少保山东戚公继光","f":"五言古诗","c":["嘉皇三十载，薄海飞长鲸。","波涛蹴宇宙，势欲东南倾。","定远起列校，巍然任彭黥。","鸣枭树大纛，束马悬高旌。","转战日千里，刁斗竟夜鸣。","天山破强敌，白水歼骄兵。","三吴蹙徐海，五岭摧吴平。","初闻燧火息，再睹潢池清。","七闽共尸祝，俨若居神明。","武功固日揭，文艺时潜精。","娄江谒廷尉，蜀国游中丞。","翩翩左司马，金石偕同声。","飞扬将坛略，趺宕词苑盟。","随车尽貔虎，入幕俱豪英。","强敌躏西鄙，高牙驰北平。","双鞬绝大漠，横槊歌长征。","天山十月雪，一剑无留行。","夺彼贺兰山，筑我受降城。","勋高薄上赏，业就遗浮荣。","飘然策羸驷，投袂辞神京。","参差武林驿，遇我如生平。","恂恂见儒雅，讵曰曼胡缨。","惜哉赤松远，丹砂邈难成。","悲来诵双剑，海岳回光晶。"]},{"t":"八哀诗 其七 博士长洲文公彭","f":"古风","c":["江左弘风流，吴中盛才杰。","文章固挺出，翰藻弥不乏。","长洲一散吏，势乃倾六合。","画工启南理，书嗣京兆业。","馀工及篆隶，一一皆卓绝。","新诗亦韶润，旧典多博涉。","萧然卧穷巷，不减原宪侠。","徵求或匪人，绢素划中裂。","愧余生后时，未及睹先达。","京华遇伯子，忘年共颃颉。","真行嗣父风，隶草变家阀。","双钩幻唐晋，片楮贵燕粤。","尤工古印记，珉玉浩森列。","龟螭两京后，科斗三代末。","澹宕杯酒间，真致表疏越。","顾我何殷勤，十指不停跋。","云霞焕楣栋，星斗烂筐箧。","庞年及上寿，彭?冀相埒。","倏尔乘化终，飘然返六合。","遗迹俨若新，天路渺难越。","缅怀父子风，老泪堕阊阖。"]},{"t":"八哀诗 其八 秘书南海黎公民表","f":"五言古诗","c":["嶪嶪罗浮颠，上有瑶石台。","秘书起岭表，恍若登峨嵬。","古心亦古貌，多艺仍多材。","悠然葛天氏，醇朴逾婴孩。","青衫困一第，十上仍徘徊。","龙门实有策，狗监嗟无媒。","匏瓜讵足系，一命沾蓬莱。","拙宦三十年，羽毛日摧颓。","风骚炳一念，壮志浩不回。","高歌掩陆谢，丽赋酬邹枚。","梁欧日倡和，王李时沿洄。","馀工入翰墨，落纸皆琼瑰。","龙章剪薤叶，鸟迹行莓苔。","八分走夷貊，四体摅云雷。","邕斯有绝诣，锴铉无兼裁。","缅思穆皇世，京华盛游陪。","杯盂洞肝腹，土木馀形骸。","横当贺老盼，谓我青莲才。","三留瀫水棹，十寄罗浮梅。","老成倏凋谢，涕泗横蒿莱。"]},{"t":"四知篇 其一 新都汪司马伯玉","f":"五言古诗","c":["粤惟汉元封，司马两当轴。","宇宙皆文章，千载被芬馥。","明德洪唐虞，朝举十六族。","娄江洎新都，一网尽推毂。","弇州既龙奋，太函亦虎伏。","白昼临高台，狂歌击燕筑。","是时西曹彦，年少四五六。","诗篇甚张皇，文事稍局促。","丈夫志万古，不朽宁案牍。","经天纬地业，九代丧空谷。","英雄倏相遇，群起赴秦鹿。","上驷谁先登，遗编在斑竹。","丘坟并典索，乙夜朗披读。","列庄孟荀韩，檀左吕公谷。","先秦数作者，鞭弭恣驰逐。","当其神理辏，罔顾毫颖秃。","穹碑峙山陵，巨碣控河渎。","馀事拈风骚，不胫走遐隩。","烟涛涨渤澥，英声振獯鬻。","腾身上将坛，号令鬼神哭。","追奔极穷岛，蛟蜃碎屠戮。","华铭勒居胥，京观自天筑。","八翼摩丹阍，上谒九州牧。","帝命总六师，长城倏如矗。","大纛巡边疆，军吏道匍匐。","安危系中外，闽楚遍尸祝。","功成戒盛满，洞霄乞微禄。","戏彩娱高堂，孙枝竞蹙鞠。","仙人凤与麟，园居各洗沐。","居公季孟间，岁寒订松菊。","制作频赓酬，缄裁递往复。","交亲剧杵臼，调洽迥敔柷。","沾沾问兰阴，笑我甘韫椟。","相逢武林道，倾盖洞肝腹。","宛若平生欢，坐久屡更仆。","床头出双剑，光焰凛霜镞。","感公思缠绵，囊底叩馀蓄。","花生七百字，草坠三十幅。","公时奋苍髯，誇我才万斛。","眇论开醍醐，清言佐饘粥。","乘兴过弇山，诸峰插平陆。","仙翁绝顶下，执手道寒燠。","黄池挟日饮，代兴话濠濮。","巧匠无旁观，良工有预卜。","三人坐丙夜，相亲互以目。","曾参唯曷疑，季路诺庸宿。","含悽别英风，衣袂尽渗漉。","回瞻缥缈云，广厦遽倾覆。","轻舟发严滩，白榆讯孤独。","儿童若走卒，竞指司马屋。","公也闻余来，倾筐倒庋簏。","将余入后堂，明妆照罗縠。","椎牛擘黄熊，舆儓厌梁肉。","吴生歌落梅，谢生辨幽菽。","凭陵屋如椽，东归记草木。","五噫序穷愁，孤愤志幽鞠。","鸿章过十馀，晨夕骤登录。","睊睊啖名子，艺苑对颦蹙。","余也百八章，呻吟亦成轴。","河梁迄挥手，泪眼暮簌簌。","寥天仅一柱，灵光镇大麓。","将偕石羊君，吾里永辟谷。","胡然跨飞鲸，倏尔残妖鵩。","空观疑地文，神游恍天禄。","当年读书台，阑干长苜蓿。","名已擅八荒，声犹借四服。","良哉副墨子，百代称郁郁。","惟公晚遇余，盟契匪碌碌。","乾坤失遗老，病骨祇盈掬。","举头拘翼宫，钧天醉秦穆。","山香舞未竟，飞花堕如蹴。","知公究净业，不受转轮福。","追随无量寿，永劫住西竺。"]},{"t":"四知篇 其二 汝南张中丞助父","f":"古风","c":["明维嘉隆世，率土皆琳琅。","前茅奋历郡，大树标娄江。","东南并虎视，河洛谁鹰扬。","张公起汝邓，九尺须眉苍。","追风跃兹白，掣电飞乘黄。","腰悬两龙剑，绝代俱干将。","燕台际天起，黄金矗华阳。","公年十八九，掉臂排枫阊。","都人诧玉润，夹道观河阳。","含香入建礼，待漏趋明光。","明时甫释褐，吏部聊为郎。","青藜校中垒，画戟持东方。","一官等泡幻，千劫宁存亡。","维时西曹隽，六七争腾骧。","分麾轶两汉，授甲陵三唐。","张公奋臂入，操翰如长江。","流星控繁弱，贯月浮馀皇。","金膏丽若木，火齐明扶桑。","维扬怯旗鼓，下雉靡旌?。","高牙矗梁苑，巨纛悬徐方。","睊睊绛灌目，谤牍如螟蝗。","群雄一网尽，窜削盈遐方。","鹿冠挂玄武，一笑骑天狼。","天风拂两袖，被发还山冈。","渌波带瀍涧，翠黛萦嵩邙。","苏门扣真谛，王屋求仙方。","苍生半眼热，荐辟交岩廊。","丹青遍畏垒，无地潜庚桑。","驱车入函谷，紫气流咸阳。","琅琊遇次美，櫜鞬划相当。","曹刘倡邺下，苏李酬河梁。","英词错金石，逸调劘风霜。","庚辰计群吏，抠趋亦明堂。","伊余黑貂敝，青衫卧篷窗。","长安一倾盖，大叫呼元长。","名流本第一，国士元无双。","潦倒南皮社，分携剧黄粱。","寥寥二十载，复此聆篇章。","嘉隆数六子，吾汝成高阳。","矫矫琅琊钵，授衣命如螀。","平原十日饮，异味穷膏粱。","燕姬及赵女，寒鳖庖嘉鲂。","雄谭走蛮触，剧论惊蜩螗。","山川堕秀色，宇宙回精光。","帝心雅推毂，大府开平凉。","飞书走北塞，谕檄平西羌。","峨峨受降壁，三城夹银潢。","殊勋勒铜柱，万仞临要荒。","华名既海岱，钜迹仍疆场。","宁知息壤誓，不救中山创。","功成合身退，鸟尽知弓藏。","人生贵适志，岁月如沧桑。","筑宫近河渚，丹青俨成行。","金钗七十二，如花簇银缸。","赤松永辟谷，大隗遥舂粮。","途逢广成子，馈药盈筐箱。","时时发缄鲤，询我骑群羊。","庸知两孽竖，作剧蟠膏肓。","寥天逝双舄，玉楼路茫茫。","丹台易迁少，要秩居文昌。","中原二三子，振袂俱飞扬。","回眸盼尘世，鼯鼠跑空仓。","神州逐麟凤，阿阁驰鸾凰。","通都洎名岳，百代留青缃。","浚冲复少达，英风嗣王杨。","新声播琬琰，旧业呈圭璋。","鸡群睹野鹤，意气时昂昂。","伫看汝南族，奕奕传芬芳。"]},{"t":"四知篇 其三 盱眙李大保惟寅","f":"五言古诗","c":["于戏战国后，永绝原尝风。","五侯洎七贵，纨裤矜豪雄。","岐阳本懿戚，带砺盟元功。","惟寅奋甲胄，巨笔如长虹。","英英楚游集，弱冠推文通。","明霞传两颊，皎日流双瞳。","亭亭古玉树，百尺悬苍空。","腾身起宿卫，帝梦来飞熊。","晨趋景阳漏，夕儤承明钟。","馀晷辄赋诗，高吟月朣胧。","前镳逐济上，后乘驰江东。","丰姿寄朗润，句格谐纤秾。","怜才实天性，下士惟谦冲。","门庭盛交际，轩车沓云鸿。","倾心放崇伯，握发模姬公。","八荒并九域，踊跃归樊笼。","涓流赴溟渤，尺土依衡崧。","逡巡抱一艺，畴不怀登龙。","尤欣礼寒素，率土皆吾宗。","华名噪远近，帝眷弥优崇。","陪京借管钥，瓜步罗艨艟。","江流照横槊，彻底瑩青铜。","长驱白门道，夹路停花骢。","车前八驺列，一笑卑王融。","夜登凤凰台，谑浪青莲翁。","糟丘亘阡陌，云车盍相从。","朱旗闪碣石，七萃提兵锋。","貔貅八十万，操戈候元戎。","月支奉旧朔，日本祈新封。","狼烟绝张掖，猎犬回居庸。","胡床挟僚幕，羽扇摇清风。","当筵尽珠履，金钗错帘栊。","时邀四方客，大集华阳宫。","纤腰舞静婉，艳曲歌玲珑。","慈恩结永夏，景福逃残冬。","西山四百寺，寺寺悬诗筒。","贤劳动当宁，宠渥流宸衷。","勋阶埒师保，晋接何从容。","三朝宪吉甫，文武攀宗工。","登坛两突兀，推毂双穹窿。","安危系中国，绝徼传精忠。","有如汾阳令，华夏叨帡幪。","蛇分匣宝剑，鸟尽韬良弓。","参差薏苡谤，一夕流丹彤。","欣然释重负，长啸还隆中。","青门种瓜地，五色开蒙茸。","闭关却人累，习静眠高舂。","食经减何胤，饮量增卢仝。","交游遍宇内，若个娱幽悰。","维余二三子，旦夕携孤筇。","伊余夙邂逅，丱角游新丰。","当涂一倾盖，拍手呼终童。","名篇诵池草，绣句翻江枫。","君能汰礼法，余亦忘疏慵。","深盟三十祀，胶漆盘心胸。","河梁剧酬倡，流水鸣丝桐。","将因毕婚嫁，把袂寻韩终。","云胡玉棺下，冉冉移空同。","死生竟长诀，去住殊匆匆。","河山夐犹昨，九原邈难逢。","虚堂翳图籍，别牖扃笙镛。","天池涸大泽，日观颓孤峰。","千秋信陵谊，百代临淮踪。","吞声遍韦布，饮泣环章缝。","佳城甃白石，马鬣浮苍松。","灵虬逝天末，泪目悬孤蓬。","隽声逮嗣服，兰桂逾芊葱。","君看白雪调，奕世标芙蓉。"]},{"t":"四知篇 其四 温陵苏学使君禹","f":"五言古诗","c":["七台高刺天，九漈迥浮日。","真气蟠山川，逢时异人出。","矫矫苏君禹，天才实飞逸。","名宗自峨眉，源委继洵轼。","一目馀十行，填胸半缃帙。","弱冠升贤书，闽士归第一。","讲业嗤京房，穷经诮王弼。","隽声洽㝢内，光焰难具悉。","三呈大礼赋，彤庭授清秩。","西曹擅文衡，前辈曾六七。","居然蹑其后，功欲收蚌鹬。","督学来吾方，神明朗无匹。","纷纭簿书薮，推案风雨疾。","吾乡万青衿，手自标甲乙。","绛帷细雌黄，百中副名实。","衰风遂一变，彬彬有文质。","曰余抱沈冥，廿载废羸疾。","尘埃蔽行径，塞马忘得失。","推诚却卤簿，径草踏刍苾。","逡巡越三顾，瓮牖忍长窒。","衣裳剧颠倒，面貌恍亲昵。","雄心贯今古，风雅恣评骘。","扬马枚曹流，一一研学术。","烛花烂长筵，丙夜互前膝。","千秋覈本支，八代综作述。","调合饶笙镛，情投锐胶漆。","君诚左太冲，余愧皇甫谧。","河梁一倡和，乾坤对萧瑟。","翩翩临海丞，仗义讨凶泆。","邦人昧逆顺，背叛拟佛肸。","义激胡先生，昌言郑庄驿。","维君企英风，罔待齿牙毕。","移文下州郡，意气迥逾溢。","祀典贻明神，幽光播泉窟。","遂令谈艺士，赤帜树高密。","烨如开玄黄，俨尔脱梏桎。","君行五岭遥，余恋一丘佚。","美人隔蒹葭，志士掩蓬荜。","濠梁析庄惠，畴为吐奇崛。","三秦豪杰徒，强半坐扪虱。","去年闻子归，长斋事绣佛。","凿度推盈虚，元苞洞凶吉。","晨兴得双鲤，浑身欲翀翐。","举头望赤松，羊群政堪叱。","言寻十六天，幔亭访芝术。","轻红劈霞荔，重翠剖霜橘。","瓯宁拜滕师，龙门莽崒嵂。","凄凉国士泪，乱洒向沟洫。","古墓辞松楸，新居问粳秫。","登君读书堂，卧君玄草室。","淋漓金叵罗，灿烂银不律。","斫地偕飞扬，谈天斗真率。","三千大千界，微尘罔漏轶。","九十六圣君，贤愚任陟黜。","落落双干将，星河翳蒙密。","舂粮十日期，此会岂难必。","造物真小儿，文章引媢嫉。","白云乘帝乡，一老竟畴恤。","恸哭西州路，风雷鼓寒栗。","屠龙绝朱泙，穷鸟困赵壹。","玉树摧庭阶，神理殊惨慄。","惟应咸池奏，万古破蟋蟀。"]},{"t":"孤愤篇挽王山人叔承八百字","f":"五言古诗","c":["千秋布衣才，往往专一壑。","穷年觅五字，埳阱观海若。","唐维襄阳孟，间代推制作。","嵬峨洞庭句，元气摄林薄。","五季宋及元，馀音噪乌鹊。","非无二三子，天授惭磊落。","有明卢楠氏，骚些首恢拓。","途遵长卿辙，步蹑左徒躅。","幽鞠及拟招，囹圄盛删削。","诗歌遂非长，风雅久寂寞。","茫茫鹿门绪，一线缀寥廓。","王生起菰芦，名姓早飞跃。","弱冠游燕齐，强龄走京索。","长怀济时念，雅抱经世略。","无媒耻白玉，草莽甘落魄。","禹穴翻图书，尧天弄耕凿。","傲诞偕东方，曼衍类南郭。","敢为兰陵论，偏究漆园学。","神来把觚翰，六艺尽糟粕。","竦身出阛阓，攘臂脱篱落。","四唐入经营，六代佐伸缩。","大篇竞飞扬，短什互沈著。","星河昼璀璨，雷雨夕喷薄。","混沌迷雕镂，震旦困笼络。","铿锵鸾鹄鸣，突矫虎兕攫。","名姓聚倡楼，老将镇戎幕。","张公两神物，所向失盘错。","太华三芙蓉，秀色照广莫。","怀中但一刺，尘冠翳竹箨。","时无孔文举，竟尔徒入洛。","维时岁申酉，芒鞋试行脚。","访我兰阴陌，孤航载停泊。","披襟发长啸，搏帽吐清谑。","易水双湛沦，夷门两嚄唶。","结交讵同裴，登仙俨偕郭。","平原十日馀，绿尊间翠杓。","微诚泄中夜，万古对斟酌。","明时遘何李，天心寄鸣铎。","人豪琅琊公，乾坤纵挥霍。","继起维奉常，词林创新薙。","斯文幸未丧，大雅竟谁托。","吾意甘沈冥，君才实磅礴。","无双国士韩，常胜冠军霍。","鹿失馀中原，龙腾绝大漠。","历下穷高华，成都侈宏博。","勉哉曹溪钵，毋令一士谔。","沈吟感子意，踟蹰复前却。","明灯彻晓漏，撩乱烛花落。","仓皇嵇阮契，竟爽范张约。","垂虹亭下浪，浩淼阻越舶。","一别俄十霜，邂逅弇山阁。","尔衰背欲鲐，余瘦膝乘鹤。","吞声话故旧，丧逝捷飞藿。","起舞中自疑，放歌久仍愕。","眷言怀故栖，荏苒理归橐。","河梁白日堕，一苇迅雕鹗。","伊余骨伶俜，念汝神矍铄。","相期保玉体，赤松问灵药。","胡为两竖子，膏肓恣燔灼。","虚传段璋句，竟坐杜陵疟。","生平褐衣贵，不受帝王爵。","大鸟来沧溟，神虬去碧落。","百身定奚赎，九原亮难作。","嗟彼志与蜍，牖下饱狐貉。","维汝赋颂声，巀嵲表衡霍。","居然布衣雄，八面控繁弱。","修文亦地下，玉楼富丘索。","遮须奉新盟，眭邃赴前诺。","缅余昔遇汝，臭味恍荃药。","玄宗各讽咏，妙理递酬酢。","濠上回周施，江东析昉约。","朱弦断流水，阳春咽冥漠。","荒阡月三尺，破冢云半椁。","参差迹已陈，宛转梦如昨。","夜台觅青莲，携手共杯勺。","老柏鸣鸺鹠，枯松照熠爝。","谈天怅邹衍，掷地怆孙绰。","生刍愧晚暮，永闭石门钥。","白杨号悲风，万叠斗萧索。","昆崙眇何处，南面醉王乐。"]},{"t":"庚辰夏五月念之二日余三旬初度也碌碌尘土加以幽忧之疾靡克自树俯仰今昔不胜感慨信笔抒怀六百字","f":"五言古诗","c":["浮生寄天地，瞬息如风霆。","回首尘埃中，倏已三十龄。","家人庆初度，浆酒罗前庭。","宁知志士怀，百忧中坐并。","粤惟肃皇世，婺女流星精。","休祯兆前梦，抱送锡嘉名。","三冬学颇足，抽翰预时英。","才非正平敌，赋夺文考声。","垂髫谒帝里，弱冠栖神京。","散发昭王台，万象愁凭凌。","悲歌问屠狗，击筑偕荆卿。","郭隗岂佳士，乐生徒老兵。","登高望幽蓟，长啸卢龙营。","风吹大漠雪，乱洒寥天青。","盛时方罢战，绝塞无王庭。","徒令终童策，默默不得鸣。","萧条对裋褐，激烈投长缨。","飞书入词社，授简罗簪缨。","群公竞识面，大匠遥寻盟。","清谈堕玉尘，剧饮呼长鲸。","华阳莽空阔，碣石高峥嵘。","千言照白日，只字悬青冥。","风尘一朝异，聚散如流萍。","衣冠竞祖道，却出长安城。","含凄问歧路，息驾还林坰。","袖中两龙剑，错落埋寒星。","穷年卧深巷，白眼横柴荆。","时人不解识，往往呼狂生。","咄嗟大运谬，采药寻仙灵。","翛然负瓢笠，独往事遐征。","绝壁耸天姥，飞梁横赤城。","千花镜湖绿，万树钱塘明。","金华最咫尺，兰阴穷绝陉。","道逢牧羊子，恍忽黄初平。","将随赤松去，永与尘世冥。","宁知浣纱地，物色来娉婷。","飞扬腼前事，佔毕起浮名。","低头拂残蠹，眯目囊流萤。","虽勤伯乐顾，岂投国士情。","匪乏钟期知，流水难为音。","迟回十年内，强半居敧倾。","雌黄逐儿辈，粉黛随优伶。","南宫籍初上，东山意弥醒。","横金亦何有，拖王非吾诚。","逡巡计偕岁，屏迹留家庭。","为园寄莽苍，凿沼浮清泠。","含菽奉高堂，酿秫邀同盟。","芳春怆庭树，雪夜怀原鸰。","宁乖四方志，实恐壮节零。","遘兹悬弧始，涕泪摧生平。","恋旧迹已往，感来念逾婴。","昔居少年坐，今为强者形。","容颜渐凋落，齿发非神明。","千秋竟何以，百岁讵足营。","茕茕六尺躯，皇皇五鼎荣。","岂无箕山穴，亦有谷口扃。","逝将守初服，毕世穷遗经。","鸿裁列琬琰，大业垂丹青。","藏书遍五岳，濯足凌沧溟。","却招两黄鹄，万里还瑶京。"]},{"t":"忆在京洛遇鸣皋游契甚洽一别五载鸣皋既赴召玉京余亦轗轲家难偶祝生如华携所业印正门下诗以勖之","f":"五言古诗","c":["昔余寓京华，红颜发垂腰。","翩然遇祝生，里闬同游遨。","矫如长空鹤，清唳闻九皋。","呻吟落珠贝，咳唾飞璚瑶。","奇情两突兀，衣被长飘飘。","青箱破万卷，白眼持双螯。","调笑谪仙人，骑鲸堕烟霄。","悲伤杜陵叟，二顷荒衡茅。","马迁下蚕室，相如困中消。","东方枉设难，子云徒解嘲。","造物真小儿，役我随尘嚣。","黄土抟下愚，茫茫若蟭蛲。","南阳贵宾客，什九横金貂。","盗蹠葬东陵，高坟郁嶕峣。","伯夷饿西山，腐骨湮蓬蒿。","陶朱窃西子，黄金压波涛。","屈原有何罪，委身饲鱼蛟。","为善福安厝，为恶刑安逃。","长当毕吾愿，痛饮歌离骚。","狂思捧北斗，醉欲呼天瓢。","玉女令鼓瑟，仙童使餔糟。","穷年谇司命，真宰为嗷嗷。","以兹诉上帝，帝怒驰神飙。","雷公击天鼓，屏翳嘘风潮。","青天拆龙剑，易水寒萧萧。","吞声出京洛，洒泣沾河桥。","一与此生别，三年隔东郊。","煌煌白玉楼，倏已升岧峣。","山阳怆邻笛，玉洞闻鸾箫。","归来瀫川上，一室藏鹪鹩。","俗子遍阛阓，可人费招邀。","尘埃闭穷巷，草色盈疏寮。","科头诵四部，赤脚翻缃缥。","蟭螟鉴止足，偃鼠明逍遥。","皇天未悔祸，家门日煎熬。","慈亲悴霜露，稚子埋山椒。","晨牝噪高堂，孽狐瞰林巢。","戚戚类冯衍，皇皇逾孝标。","人生亦何乐，七尺徒烦劳。","逝将弃家室，六合穷荒要。","翩然挟大鹏，九万腾扶摇。","嗟咨念良友，宿草迷荒坳。","阳春慨永绝，白雪空长谣。","欢言遘之子，兴文自垂髫。","飞扬慕古昔，跌宕扳贤豪。","沾沾问奇字，片语为神交。","斯文久沦谢，玄阁长寥寥。","尔志亮金石，遗风未全凋。","抽毫述往事，赠汝为虔刀。","勖哉丈夫子，努力追前茅。"]},{"t":"将入金华诸山述游五十韵","f":"五言古诗","c":["昔我游昆崙，长啸望玄圃。","手拍浮丘肩，濩落还下土。","帝阍不可扣，频为世人侮。","苍茫五龙蹻，旦夕无所伍。","飘风从东来，吹我向齐鲁。","徘徊岱宗侧，万象划争吐。","遥空势崔嵬，大块色消沮。","幽燕各罗列，梁宋但仰俯。","龟蒙与凫绎，培塿不得数。","昏黑留天门，海日正可睹。","白云封中出，片片堕梁父。","晨窥金银阙，玉佩遍廊庑。","警跸怀祖龙，銮舆忆汉武。","调笑七十君，空名竟何补。","荒碑亦磨灭，遗迹半尘土。","回首徂徕松，亭亭尚堪抚。","恍惚秦时官，苍然大夫五。","何来安期生，相对形貌古。","携我登云车，纵横擘麟脯。","掀髯但一笑，东瀛复斥卤。","却下丈人峰，行行至南楚。","鼓棹浔阳流，吹箫洞庭浦。","三湘亘七泽，茫茫散楼橹。","放歌答鱼龙，怀才吊鹦鹉。","初闻黄鹤游，忽睹冯夷舞。","九疑何芊绵，离立向平楚。","宛转双蛾眉，恸哭摧肺腑。","万古苍梧云，不散黄陵浒。","缅思向衡岳，改辙望岩户。","里足扪嵚岑，决策穷龃龉。","绝壁栖鸾凤，层峦撄虬虎。","石留娲皇炼，崖豁巨灵斧。","嵯峨大禹碣，窈窕祝融府。","千峰既腾掷，众壑亦旁午。","举头触支机，侧身见河鼓。","海月明冠簪，天星拂綦组。","朅来归东皋，屏迹偕溺沮。","薜荔交岩房，蓬蒿翳环堵。","灌园事于陵，饭牛狎五羖。","短褐岁载阴，长镵日卓午。","感激何时平，形骸亦良苦。","咫尺金华山，洞天列吾婺。","霞气连赤城，霜华拂天姥。","石室函金书，丹台秘鸿谱。","瑶草纷可飧，青精剩堪咀。","壮哉神秀区，逖矣灵仙坞。","翩然羽翼生，白昼还紫府。"]},{"t":"李生归东阳益肆力千载手札寄余几数十返推挹过甚弥非所安报赠六百字","f":"五言古诗","c":["曰余抱遐尚，念载卧玄阁。","逍遥榆枋下，矢志游广莫。","一室罗青缃，万卷恣栖托。","门无问奇客，与世久枘凿。","匡床起亭午，发散仍赤脚。","空斋垂藤萝，兀坐数花落。","苔痕闭重关，何自来剥啄。","有美东阳生，意气本卓荦。","夙昔瑚琏姿，弱龄自追琢。","上下三千年，珠玑吐错落。","雅志亲典谟，玄悰揽坟索。","庄骚逮左马，一一穷橐籥。","远甘杜陵豪，迩向弇州博。","矫首金华颠，谁其嗣述作。","后起凌宋王，先驱并刘骆。","片刺怀十年，名姓渐凋落。","愿言申末契，一过倾伯乐。","维日大火流，空檐噪鸟雀。","清风惠然来，潇洒动林薄。","感汝缠绵意，褦襶亦何恶。","倒屣迎嘉宾，衣裳不遑著。","呼童割菘韭，班荆坐篱落。","涤釜燔枯鱼，提壶劝清酌。","殷勤效明珰，缱绻斟翠杓。","舄履何缤纷，觥筹亦交错。","把臂游鸿濛，悬心契冥漠。","欢来不知疲，软语间清谑。","淋漓契肝胆，郑重吐然诺。","雄文诧鹦鹉，丽句诵鳷鹊。","狂歌发清商，中夜互踊跃。","嗷嗷曼倩齿，泯泯五鹿角。","典衣困鹔鹴，掩袂叹龙蠖。","十载丰城剑，漶漫斗文剥。","一朝遇张公，紫气贯碧落。","努力追前修，遗编在先觉。","吾衰亦已久，豪举徒岳岳。","头颅遽如许，精爽渐销铄。","缅思少年日，挟策走京洛。","荆山并韶润，姑射方绰约。","人惊士龙笔，世许袁豹学。","昔苞鸾凤文，今愧犬羊鞟。","薜荔怀佳人，菰芦忆高躅。","登门遘国士，况乃同一壑。","万斛吞馀皇，千钧控繁弱。","邂逅盖己倾，纵横思仍拓。","望望琅琊云，瑶池断笙鹤。","乾坤泣大老，海岱遇韶箾。","典刑四部存，巍巍见遗矱。","中原失秦鹿，上国谁宋鹊。","旧社纷摧颓，新知乍忻乐。","照乘隋侯珠，连城卞和璞。","平生实怜才，见汝难落落。","酌汝青玻瓈，佩汝锦芍药。","赠汝五色翰，如虹跨寥廓。","汝实河宿精，吾宁北海若。","小道未足观，大方讵难作。","瀫江一杯水，彷佛共濠濮。","翩翩李公子，毌爽代兴约。"]},{"t":"昔游篇钱塘舟中作赠董观察","f":"古风","c":["秋风肃肃鸿雁鸣，南斗参差北斗横。","孤客迢遥过越水，旧游憔悴隔燕城。","燕城越水三千里，忆昔声华满人耳。","藉草曾留太液旁，看花误入明光里。","明光太液连西苑，往往游人驻雕辇。","杨柳春风七贵门，梧桐夜月诸王馆。","王家贵里不相亲，联裾握手尽词人。","凤凰原上题诗处，鳷鹊宫前草赋晨。","纷纷冠盖争驰逐，载酒笼灯过辇毂。","缓辔同看白玉京，扬鞭醉入黄金屋。","秦筝赵管春不休，歌声缭绕碧云愁。","香尘百里昌平道，飞雪千门易水流。","五夜论心传彩翰，珠玑满把皆堪羡。","衣袂扬扬逼九霄，剑锋耿耿流双电。","谁言潘陆是才人，肯与王杨作后尘。","格调迥追天宝上，风期直与建安邻。","銮坡凤阁多相值，铁券金貂总欢昵。","群中忽睹三楚豪，坐使琼瑶惊四席。","豸冠绣服光陆离，片语如金山可移。","暮携奏草归青琐，晓对封章下赤墀。","赤墀青琐生风彩，手握芙蓉佩兰?。","元礼声华动阙庭，陈登意气倾湖海。","匆匆识面比南金，惭愧论文契未深。","欲携短刺通华馆，忽棹扁舟出汉阴。","荷衣蕙带还乡国，回首交游成太息。","落日长歌玉树词，浮云远蔽金台色。","落日浮云梦转长，却乘烟水下钱塘。","徘徊殿阁迷仙署，寂寞川原望帝乡。","帝乡仙署空辽绝，何意輶轩到吴越。","欲向西湖访画图，暂辞北斗离阊阖。","双峰缈缈插烟霄，三竺苍苍引画桥。","清风暗拂苏堤柳，壮气平吞浙海潮。","朅来问讯蓬蒿士，远思幽情何楚楚。","短褐长裾谒上官，麻鞋布袜从泥滓。","屈指并州几故人，嗟咨往事转伤神。","虚传异日山阴棹，无复当时洛水春。","山阴洛水俱陈迹，会见飞腾返京邑。","乍经薇省布阳和，更上枫宸扶赤日。","几年骐骥阨盐车，矫首长鸣气不舒。","孙阳造父俱垂盼，肯使奇才卧草庐。"]},{"t":"昆崙行送大司空朱公驰驿还豫章并呈唐太常万直指","f":"古风","c":["君不见黄河之水来昆崙，浊流万里经龙门。","环嵩绝华不少息，吞吐日月排乾坤。","天吴扬澜九河溢，大泽龙蛇起原隰。","洪荒不解尧舜忧，平成却藉司空力。","自从大禹作司空，百川四渎俱朝宗。","锁压支祈镇淮甸，至今玉策垂神功。","国家定鼎幽燕北，财赋实仰东南域。","河渠一线廑帝衷，维时首赖平江伯。","二百年来飞挽停，肃皇之末何邅迍。","千艘莫进饷道阻，临朝南顾嗟群臣。","我公崛起江之右，列星显化神明胄。","匡庐彭蠡毓精华，西山南浦钟奇秀。","早年通籍谒承明，中岁翱翔汉两京。","一朝起任虞庭事，九官四岳咸推能。","沛渠已淤徐方塞，巨浪滔天势难遏。","两岸洪波迥莫分，百年故道谁能识。","神功实始南阳口，夏村既道留城走。","报国难将宠辱惊，乘时大展经纶手。","栉风沐雨卧不宁，追逐魍魉驱玄冥。","八年胼胝勋绩就，青天不动黄流平。","东连扬子息江涛，北望天津散海潮。","车书万国看王会，玉帛群方贺圣朝。","隆庆之中河再决，帝谓元臣有遗烈。","一麾暂驻淮泗清，风雷寂静波涛绝。","飞廉导车屏翳从，冯夷海若应潜踪。","金书鸟篆迹灵秘，异时彷佛岣嵝峰。","大禹功高古来少，姬旦才多心转小。","门下争看桃李荣，车前肯使骅骝老。","纷纷制作悬丹霄，驰驱阮陆追风骚。","元和文誉斗山重，天宝才名今古豪。","三朝出入方垂注，投簪忽拥南归骑。","苍生常恐谢公閒，黄阁难留疏广去。","楼船箫鼓出皇州，锦缆牙樯作胜游。","群公祖帐灞陵晚，万姓环看渭水秋。","迢递关城望乡邑，浮云渐送匡山色。","暂舣兰舟水驿滨，故老相逢话胸臆。","酒阑倚剑心飞扬，语及前朝俱感伤。","丈夫报国志犹在，星辰错落双干将。","旌旗明发川原阻，著绣昼行谁与伍。","滕王阁上几留宾，孺子亭前频吊古。","即今廊庙求贤急，肯使元勋卧黄石。","绿野堂开祗暂留，终须勉为苍生出。","五老东南势转尊，三台佳气正氤氲。","鸾笺倘逐蒲轮到，极目燕台五色云。"]},{"t":"送朱可大还万安","f":"七言古诗","c":["自从战国更王风，屈原师弟俱称雄。","西京苏李复继作，遗篇十九真宗工。","黄初七子各有得，勃兴杜李文章伯。","此道凌迟大历还，世代纷纷转荆棘。","千年大雅几茫然，信阳北地何翩翩。","力剪榛芜继唐汉，恍揭日月悬高天。","眼中作者难尽数，戛玉敲金事奇古。","相逢海内俱贤豪，奋迹前茅追步武。","看君意气何昂藏，十九谒帝趋明光。","胸蟠万卷破幽眇，手鍊五色回天章。","藉甚声华满京洛，咫尺云霄见孤鹤。","司马仍传太史书，拾遗颇负襄阳学。","飘然遇我燕市中，河梁邂逅双飞龙。","高歌击筑白虹断，剑花欲堕青芙蓉。","莽苍风尘遽相别，美人迢递音容绝。","五年空睹芳草生，万里长看碧云合。","云泥自分随升沉，岂料重逢瀫水滨。","咄嗟往事如梦寐，解衣共拂京华尘。","五夜论文思逾壮，浊酒淋漓对惆怅。","天地迟回秉烛间，星河磊落孤舟上。","眼看世变随江河，悯时愤事忧弥多。","百川砥柱赖公等，异时讵肯扬其波。","伯乐张华古难得，时乖暂敛图南翼。","燕雀宁争世上名，蛟龙岂是池中物。","一朝变幻乘风霆，磅礴六合摩昆崙。","卞和之玉讵三刖，季子金多安足论。","高天黄叶连乡国，大艑乘风度秋色。","短歌送汝不成声，握手临岐泪沾臆。","千秋杰阁倚清沙，百尺珠帘挂晚霞。","兹行定拟滕王赋，一寄兰州孺子家。"]},{"t":"幔亭云气歌为督学滕公作","f":"古风","c":["君不见武夷之峰高插天，幔亭玉女腾苍烟。","层峦列嶂三十六，相传秦代巢真仙。","狂风怒号沧海立，海水蹴日日欲没。","峰头云雾长晦冥，青虬赤鲤当昼集。","蓬莱东望若可招，贝阙珠宫浮巨鳌。","纷纷群帝持绛节，扬雷激电朝丹霄。","兹山形势实奇绝，紫气迢迢亘吴越。","扶桑万丈渤澥低，齐州九点乾坤狭。","溪流屈曲环清沙，绯桃夹岸蒸红霞。","鸾鹤翱翔度空谷，猿猱寂历啼山家。","危岩绝磴倚石壁，去天冉冉不盈尺。","仰视列星河汉垂，下窥飞鸟松萝黑。","药炉经窟多遐踪，苏门高步随韩终。","霞光半落锦绣座，日色返射金银宫。","仙居缥缈隔人世，环佩飘飖落云际。","半夜天鸡绝顶鸣，清秋石马凌空系。","杂花幽草何芊绵，松枝柏叶皆堪餐。","洞前三女不相待，彷佛麻姑留翠鬟。","祝融梁父空郁律，太乙终南自腾掷。","遍观岂若兹山奇，寥泬清虚閟灵迹。","真人度世三千秋，俯看人代如浮沤。","朅来欲济生民困，拂衣长啸离丹丘。","金书玉检秘空麓，鹤驭鸾骈罢驰逐。","一朝乘蹻来东南，手挽江河障平陆。","眼中轩冕如埃尘，葛洪王远时相闻。","清梦常随岩际月，幽怀每逐洞中云。","即今宇宙须真宰，拭目经纶横四海。","漫劳黄帝访空同，暂借庚桑居畏垒。","武夷山，何苍苍，真人下阊阖，草木无辉光。","他时簪笏升岩廊，致君尧舜追虞唐。","却驾白鹿还仙乡，天齐地久长无疆。"]},{"t":"题铁干回春图山阴刘世儒工画梅以巨幅贽余乞诗为赋","f":"七言古诗","c":["吴绡七尺铺寒玉，幻出名花照幽独。","微霜淡月春朦胧，何处佳人卧空谷。","画梅自昔传华光，擅奇更有王元章。","千秋绢素渐零落，古色黯黯留虚堂。","迩来刘生最殊绝，十载含毫走燕越。","一榻常栖剡水云，双帆忽下桐庐月。","看君落墨如有神，解衣盘礴随天真。","淋漓数笔生意动，阴崖顷刻回阳春。","林危径仄飞鸟绝，偃蹇虬龙锁深穴。","彷佛罗浮万丈峰，孤根倒挂千年雪。","大枝诘屈粘莓苔，小枝蜿蜒花乱开。","虢国蛾眉逞疏淡，寿阳妆额矜徘徊。","风台月观遥相望，园林更染孤山样。","绝艳惊从汉苑来，冰肌更出唐昌上。","吁嗟刘生画己仙，坐令铁干摩苍烟。","高屏巨障欲飞动，素册单条绝可怜。","长安五侯招不得，王家珍重走书乞。","何缘好博胡生诗，乱洒琳琅向蓬荜。","阴铿不作何逊亡，人间佳句何茫茫。","暗香疏影亦长语，后来谁复传篇章。","嗟余潦倒笔力弱，细嚼琼朵搜枯肠。","刘生刘生勿悽蹙，自古高流混凡俗。","即今且作潇湘游，坐观瀑布匡山麓。","他时问讯子猷船，倘寄鹅溪三百幅。"]},{"t":"舟次钱塘谒滕公值风雨夜作解所佩为宝剑歌","f":"古风","c":["江潮十月如山丘，北风轗江江倒流。","星河一片落寒铁，暗中擎出蛟龙愁。","君不见丰城狱里百鍊钢，精灵埋没三千霜。","当时不遇雷与张，至今神物终潜藏。","又不见曹沬手中三尺水，却制桓侯轻管子。","一朝坛上行奇谋，百代声华耀青史。","胡生宝剑人不识，十千买自邯郸邑。","朅来持赠归滕公，绕座虹光流四壁。","忆昔干将初铸时，睥睨欧冶麾风胡。","低回天地鍊精气，喷薄宇宙烹洪炉。","泰山为镡渤海铗，神锋指石石欲裂。","绿柄犹沾苔藓文，赤花半堕芙蓉匣。","有时夜啸风雨声，千夫辟易万马惊。","山中魍魉昼摧绝，水底鲸螭寒不鸣。","湛卢飞景亦凡俗，纯钩巨阙皆碌碌。","取次横裁丽水金，纷纭碎割昆吾玉。","一挥四国如建瓴，挽回日月轰雷霆。","朝携赤堇鬼神伏，暮宿苍梧涛浪青。","荆轲孺子本无术，匕首苍皇挑强敌。","片言枉杀樊将军，易水悲风转乌邑。","项王智力何豪雄，废书苦学仍无功。","垓下谁知万人敌，时哉不利嗟重瞳。","岂若胡生磨此剑，寸心耿耿横孤电。","十年坎坷意不平，提与滕公肝胆见。","滕公豪气凌穹苍，一朝睹此神飞扬。","愿持此物登朝堂，时时拂拭生秋霜。","蚩尤遁迹魑魅藏，周游八极还大荒。"]},{"t":"虔州歌送大中丞江公之南赣","f":"七言古诗","c":["东南海色何苍苍，旌旗夹岸澄清光。","迢迢斧钺自天下，帝遣中丞巡朔方。","铜符玉帐分千里，画甲雕鞍围绣绮。","三军鼙鼓寂无声，万灶风烟晴不起。","中丞自是河宿精，乍窥人世辞蓬瀛。","流沙咫尺不可越，怒鞭海若驱长鲸。","停车忽傍黄山麓，笑揖浮丘跨䨥鹿。","晓逐霞光度赤城，暮餐云气离天目。","胸中远思凌泬㵳，却来湖海称人豪。","单词只语露肝胆，白日不动苍旻高。","猿韬豹略多奇迹，早握兵符穷战术。","八阵常翻鱼复图，千言自献龙门策。","策名飞步登皇州，纷纷簪笔皆儒流。","斗边夜啸䨥龙剑，天上春开五凤楼。","贾生意气本英发，终军才调何颖脱。","兵锋直欲款匈奴，尺组恒思絷南粤。","华衮朱轩出未央，竹马壶浆迓道傍。","已见褰裳临蓟野，还看赐服下南阳。","再岁超迁左冯翊，凤凰神雀咸来集。","声名从此播寰区，二省三台劳涉历。","东南财赋日徬徨，一麾承诏来馀杭。","唐代征输属刘晏，汉家平准羞弘羊。","政成绩奏多清燕，越水吴山自游玩。","酹酒初登武穆祠，飞书忽下明光殿。","匆匆督府推贤臣，九重焕烂传丝纶。","陇西黎庶望充国，河内军民嗟寇恂。","虔州形势本四塞，渺渺川原开郡邑。","波涛半蹴闽海青，瘴疠斜连惠潮黑。","汀漳诸府列犬牙，纡萦四省藏千家。","穷乡绝峒锁魑魅，深岩大泽盘龙蛇。","庙堂抚髀思经济，时来崛起风尘际。","三苗方略从便宜，九姓羌浑随节制。","轩车杂遝送离觞，十月江城满路霜。","大将楼船横浙水，元戎队伍出钱塘。","钱塘浙水俱秋色，回首严陵瞻故国。","白岳崚嶒带雨寒，苍岩兀突齐云立。","云岩白岳望不停，番阳彭蠡江溟溟。","千年滕阁迷丹嶂，万仞匡庐削翠屏。","历历关河度章浦，缓辔停骖问风土。","送客应过孺子亭，提兵却入中丞府。","中丞号令何雄哉，指挥叱咤行风雷。","将军列戍秦城远，壮士长歌汉壁开。","建牙吹角观游猎，士气军声腾百粤。","铁马骄嘶海月寒，雕戈乍举岩云裂。","海月岩云壮品题，登坛横槊思清凄。","慷慨宁论班定远，风流不减庾征西。","缓带时时临绝域，纶巾羽扇何閒寂。","骠骑空驰大漠烟，词人枉勒燕然石。","崔巍铜柱镇封提，缥缈珠崖接五溪。","分耕坐使阳春布，讲武俄看太白低。","讲武分耕严纪律，泸夷永靖先零辑。","主恩时赐鹔鹴袍，兵气潜消狐兔窟。","津亭黄叶转纷纷，肠断骊驹不可闻。","晚思苍茫盈落日，愁心悽切驻寒云。","男儿意态元磊落，抗手何须怨离索。","指日威名虎豹关，他时事业麒麟阁。","雨露沾濡大海滨，溪山随处净烟尘。","更令文字流荒服，行见衣冠入紫宸。"]},{"t":"题黄初平叱石图","f":"七言律诗","c":["古木苍藤挂风雨，白石峨峨洞门倚。","黄家儿曹不解事，叱作群羊遍空起。","胡生较汝差长年，俯窥五岳石五拳。","他时一叱五羊起，白云飞尽罗浮巅。"]},{"t":"题何仁仲甘露园","f":"七言古诗","c":["园林旧说何将军，应门稚子俱能文。","即今盛世宁好武，登坛载睹鸿胪君。","别起楼台眺三楚，冠盖章华总非伍。","九疑七泽天茫茫，千秋屈宋垂文章。","何日玄亭借高卧，乘风会鼓潇湘柁。"]},{"t":"梅窗歌寿何处士作","f":"古风","c":["吾闻罗浮之山四万八千丈，绝顶仙葩隔尘壤。","铁干斜撑大海滨，霜梢乱插遥天上。","江南十月寒信来，雪花如席飞瑶台。","千枝万枝冻欲折，凌风一树何奇哉。","清标雅质真绝俗，为谁移向孤山麓。","东阁曾闻杜陵句，西湖更入林逋目。","道人自是姑射仙，几年采药罗浮巅。","参差老态看不足，却窥春色来湖边。","满屋琳琅坐相对，五夜虚窗月光碎。","夜永宁知素影单，酣歌绝胜红妆醉。","缟衣鹤氅何翩翩，况有逸思凌开元。","有时兴到起濡墨，阴铿何逊皆陈言。","只今尚作梅花主，甲子一周还二纪。","山房乍夜春意回，彷佛枝头闻翠羽。","绣屏朱户罗婵娟，孙枝绕膝才且贤。","折花浸酒为翁寿，清香习习来华筵。","王母安期世谁识，玉桃丹枣空陈迹。","岂若冰肌耐岁寒，破臈含春映朝日。","梅窗叟，且莫吟，繁苞落羌笛，国艳传幽琴。","遥望罗浮隔南粤，玉宇雕梁迥清绝。","耸身欲去重徘徊，冉冉云軿下天末。","且挥白鹤留人寰，几番渤海成桑田。","更卧梅花三百年，一筇长啸凌苍烟。"]},{"t":"褒忠祠祀礼成代直指萧公作","f":"古风","c":["一夜并州赤龙起，浩荡风尘播疆宇。","捲甲朝降十万师，夕悬烽照三千里。","真主初还建业东，储君却下金陵宫。","群臣骈首甘就戮，至今正气吞长虹。","忆昔齐黄在帷幄，首絷亲王入京洛。","书生坐失应变机，遂使貔貅暗沙漠。","同时抗节练与陈，壮怀凛凛雄三军。","伟哉正学十族死，精贯日月开浮云。","全师仅见南阳铁，独守危城破坚甲。","暴昭姚善两激昂，视死如归徇鈇钺。","皇皇周子百鍊钢，题诗自缢太学堂。","景清枉效渐离术，势孤不得抽鱼肠。","纷纷义士难悉数，力挽颓波示今古。","投河直欲拒成汤，扣马宁辞谏周武。","大厦难将一木支，江城白昼飞旌旗。","鄗南正位大统集，剑阁巡行天命移。","沉吟往事空愤切，耿耿英魂岂终灭。","四海同悲东市刑，旷代犹瞻首阳烈。","百年祀典何寥寥，明良继起登熙朝。","首录忠诚建祠宇，天书五色垂丹霄。","峨峨遗像表忠赤，报礼殷勤慰悽恻。","西日含窗鸟自过，北风吹树声犹急。","阴虫夜促霜露零，群公恍惚来精灵。","九原遗恨岂堪说，天空月落秋冥冥。","我行睹此重太息，后世谁传董狐笔。","海滨义士何足论，洛邑顽民真再出。","英英壮气摩乾坤，流光竹帛垂丹青。","千秋万代鉴往辙，君臣大义如日星，于戏君臣大义如日星。"]},{"t":"河洛篇督学滕公夜邀斋中谈道命赋","f":"七言古诗","c":["茫茫太始谁开辟，耿耿元精贯三极。","自从河洛生图书，中华首肇文明迹。","羲皇手抉天地心，罗列八卦标乾坤。","轩农尧舜复继出，垂衣万古开人文。","夏商体格多浑噩，遗风未散鸿蒙朴。","成周一代首尚文，纬地经天传制作。","纷纷侯国隳王纲，宣尼崛起称素王。","七十二表擅灵异，骖逐五帝驰三皇。","神游岱宗憩梁父，下瞰日月相吞吐。","三千弟子咸抠趋，从此儒冠盛东鲁。","穷年赞易评羲周，诗书礼乐勤删脩。","至今大盗屏不发，凛凛鈇钺严春秋。","渊舆资禀实玄奥，独冠诸生闻至道。","惟时游夏得精华，散入南方布文教。","游梁崛起孟氏贤，乘车列鼎何翩翩。","公孙万章不足数，岩岩气象谁其传。","荀卿议论本该博，时乖废死兰陵郭。","后来蜀国空草玄，白首苍黄坠高阁。","河汾自是王佐才，曳裾献策窥蓬莱。","昌黎夙负斗山望，路途二鸟重低徊。","千年至道转寥落，重见周程起濂洛。","紫阳之巅异人出，一扫蓁芜继绝学。","我明设教崇成均，十三学政分儒臣。","七经训诂行海宇，彷佛云汉垂星辰。","关中江右两督学，景明献吉真间作。","才名气节天下传，渺渺斯文未有托。","武夷之山何嶙峋，丹梯百尺连高旻。","我师笃生任斯道，挽回一发伸千钧。","周情孔思实天纵，玉质金相本梁栋。","年少亲承明主知，时来却为苍生用。","三吴才士集如云，帝遣真儒下汉庭。","伏生晁错岂知道，丁宽孟喜空谈经。","一麾暂驻吴山麓，已见清风走南服。","坐席江声走具区，褰帷海色明天目。","鲁国生徒遍品题，当筵彩笔飘虹霓。","漫拟真人过函谷，共看夫子在关西。","王良造父本精识，雷焕张华渺难及。","台上俄看万马空，狱中解使双龙出。","麟符绣钺行高秋，追步琬琰披琳球。","纵横礼乐三千士，缥缈弦歌十二州。","弦歌礼乐连薇省，片善微长劳接引。","百川齐赴沧海流，抔土同登太行岭。","泗水尼山迹未湮，升堂入室多奇珍。","西施尚作浣纱女，和氐犹为抱璞人。","马卿自昔工铅椠，终军意气空凌乱。","照乘连城世所希，夜光明月谁能辨。","葱葱紫气绕三台，遥见徵书落上台。","更闻黄阁收桃李，会看青衿出草莱。"]},{"t":"董生行赠中秘董体仁","f":"七言古诗","c":["远游昔登梁父巅，天门突兀摩苍烟。","秦碑汉碣半寥落，万家封禅俱茫然。","忆从苍颉制文字，六书灿烂星辰悬。","八百年来阳冰死，邕斯体制谁其传。","董生今年政三十，曳裾笑指长安日。","论心遇我游侠场，意气翩翩指金石。","自言家住沧海东，曾入禹穴探奇踪。","门外寒山挂苍玉，青天削出䨥芙蓉。","朅来挟瑟齐门老，客子形容半枯槁。","黄金台馆天茫茫，系筑悲歌和穷鸟。","兴到长镌石鼓文，快剑长戟秋森森。","突兀虬龙起幽壑，翱翔鸾鹄回高林。","金薤琳琅遍筐箧，螺画虫书互惊绝。","白石烟销苔藓凝，寒云海冻珊瑚裂。","年来徵仲数八分，长沙小篆称通神。","生也雕虫不自惜，往往制作追前人。","偏傍颇肖韩择木，风格时兼蔡有邻。","十载都门困旅食，短衣匹马随风尘。","吁嗟董生何仆仆，归去犹堪友麋鹿。","携尊傍我吴山麓，饱看秋潮落天目。"]},{"t":"霞林樵隐歌为梁太学赋","f":"古风","c":["七闽孕奇秀，秀出壶公山。","壶公悬壶住绝顶，云霞万叠供朝飧。","玉宇琼楼架天末，翠葆丹旂互明灭。","高寒可望不可亲，一片晴光堕林樾。","林中大隐梁伯鸾，飞身直上凌崭岩。","苍精之龙不肯佩，却从杜甫歌长镵。","长镵朝持柄白木，伐木丁丁向空谷。","竦身乍可亲猿猱，跂足时堪友麋鹿。","峰回岫转兴不穷，壶公绝顶寻壶公。","高霞万叠餐不尽，担头五色纷葱茏。","荷担归来石床畔，两腋风生体轻健。","金茎底事月底寻，石髓无劳洞中玩。","君不见赤城之下吾所庐，霞标突兀千仞馀。","兴公丽赋久埋没，桃花流水空踟蹰。","又不见武夷之蹊君咫尺，霞幔为亭驻征跸。","天孙懒织云锦裳，邂逅梯仙竟谁识。","愿君大隐留人间，长林筑室三千年。","春来倘挟汝南费，一筇历探壶中天。"]},{"t":"夜饮喻邦相署中酒酣邦相诸郎君出见咸朗朗玉立可念也因戏成短歌一章为赠","f":"古风","c":["自从管鲍交游不再见，世人结交徒结面。","南昌喻侯青云客，邂逅逢余偏恋恋。","丈夫意气凌青冥，契合宁论越与秦。","弟兄异姓古来有，一呼尽出诸郎君。","大儿今年才十二，霜毫日扫五千字。","差肩两郎亦其匹，八法淋漓照湘帙。","抱中小者尤绝奇，玉为肌骨云为眉。","毛诗三百不离口，气槩似欲吞虹霓。","看君四子并英物，朗朗寒空挂奎壁。","徐卿两儿那得比，王氏三珠总非敌。","人生有儿百不忧，况复满眼俱骅骝。","乔当及卿髦讵减，湛既难兄纪更优。","君不见胡生今年政三十，日夜明珠探骊窟。","大儿文举小德祖，徒尔相亲不相识。","此时尽阅君诸郎，使我临风重悽恻。","谓生好饮勿复言，且尽三百青铜钱。","生儿蚤晚会有命，何用蹙蹙愁心颜。","君不见喻侯膝下四男子，行年三十初得此，至今玉树森庭庑。"]},{"t":"钟室行题淮阴侯传后","f":"古风","c":["黄河倒流日东转，地坼天摧钟室晚。","志士千秋空扼腕，谁为淮阴明不反。","忆提利剑追重瞳，邂逅关前隆准公。","登坛片语定刘项，岂须垓下知雌雄。","井陉战血飞长虹，齐城七十如飘风。","当时楚汉在掌握，磊落千言辞蒯通。","固陵长驱三十万，手挈神器归真龙。","泰山为砺河为带，欲齐伊吕称元功。","宁知隆准猜忌主，畏信雄图如畏羽。","旌旗夜入定陶壁，警跸朝行云梦渚。","朝行云梦夕出迎，天日可照微臣情。","纵虎诚难缚虎易，青冥咫尺飞雷霆。","列侯朝请亦奚忌，隐若大泽居长鲸。","陈豨相过理则有，舍人上变谁当明。","遂令身首异都市，九族并命咸阳城。","嗟嗟吕姥岂办此，固知汉主行叮咛。","即豨不反信亦族，欲加以罪宁无名。","呜呼季也实凉德，万古愁云吊钟室。","史臣徒赞宽大辞，百代枭雄定谁匹。","君不见三雄死，三吕立。","厕中爱姬人作彘，掌上佳儿血盈席。","天道好还如一日，长信宫深辟阳入。","愧杀长陵一抔土，冢中强魄无颜色。","君不见亚父当年赐骸骨，虞姬效死阴陵侧。","壮士至今犹悼惜，千秋为季宁为籍，嗟乎千秋为季宁为籍。"]},{"t":"吴章两门士后先以新作至咸精进迥出余读之勖之以歌","f":"七言古诗","c":["吴充远示林屋诗，读之使我兴飞越。","沾沾欲度骅骝前，不减观潮诵枚发。","章生近投诗百篇，敏而好学吾所怜。","昌龄我师花蕊妇，肯与王建论媸妍。","何哉世谓两生鲁，中夜闻鸡解起舞。","异日英雄起俦伍，不用登临叹广武。"]},{"t":"嵩山歌","f":"古风","c":["君不见嵩高之山，高高出天半。","万古扶舆结葱旧，孤标突兀回日星，秀出苍茫界河汉。","恍疑帝遣夸娥负中岳，掷向东南镇磅礴。","又疑巨灵一夜排风雷，空中掣此青崔嵬。","仰观宇宙豁，俯瞰沧溟开。","天倾锦绣壁，地涌金银台。","飞鸟不敢度，猿猱为之摧。","层峦叠崿何奇哉，倒影下坠扶桑隈。","会稽秦望相去但咫尺，赤城天目左右罗列如浮埃。","绝壑迤逦，飞梁萦洄。","空青水碧，划然蓬莱。","天仙跨鸾鹄，时时下九垓。","遥峰插天更奇绝，天柱嵯峨象纬列。","云是嵩高列峰三十六，其一飞来堕吴越。","参差太华十丈莲，重叠娥眉万年雪。","云中之君纷纷拾瑶草，散发长歌弄明月。","朝来忽见黄帝车，方明前导昌㝢趋。","七圣尽迷襄城辙，却望天坛寻故庐。","顷刻笙歌起岩际，白鹤凌空舞瑶砌。","乃是缑山王子乔，金支翠旗朝玉帝。","真人一去不复还，玉书灵笈埋空山。","俗流往往轻飞仙，不见此后三千年，少室山人结庐长啸卧其巅。","峰头一室但盈丈，大易黄庭坐相傍。","紫芝空谷纷葳蕤，真气关门浩排荡。","朝飧玉池露，夜濯金屑泉。","明霞翼我体，白云怡我颜。","山灵候余户，跂息不得眠。","一行卧此三十载，上元夫人时往还。","俯视城郭真嚣烦，缟衣素氅何翩翩，乘风几欲凌苍烟。","胡为羽驾尚踯躅，惆怅孤峰夕阳落。","仰天大笑寒风生，徙倚青藜望名岳，无乃未践三花诺。","寄言广成子、浮丘公，吾将跨白鹿、骑苍龙，访尔三十六峰中。","横绝具茨凌空同，归来却卧此峰上，千年一视轻鸿濛。"]},{"t":"金华山三洞歌","f":"古风","c":["薄游金华山，信足支短筇。","长啸黄初平，蹴踏金芙蓉。","芙蓉峰头白云起，天风习习两腋举。","相传古来洞天三十六，乃是赤松真人之所理。","千岩拔崔嵬，万壑亘迤逦。","高欲凌空同，侧若摧鸟鼠。","括苍与台雁，琐细不足拟。","帝鸿既长逝，雨师邈难招。","回看昔日讲堂洞，却忆当时刘孝标。","九龙蜿蜒读书处，穹岩怪石摩苍霄。","荒坟突兀葬彩笔，至今词客何寥寥。","讲堂信郁纡，朝真益弘敞。","天门划然开，石洞豁榛莽。","恍然坐我金银台，昆丘玄圃恣来往。","青虬赤鲤尽罗列，三仙七圣时俯仰。","幽怀转轶荡，胜槩杳莫穷。","飞梁百尺下窈窕，举足却堕冰壶中。","冰壶跨山腹，气势何其雄。","何年虎豹穴，置此蛟龙宫。","水帘参差直下五千尺，银河宛转倒泻双白虹。","天孙云锦织璀璨，鲛人珠箔垂玲珑。","飞流溅沫日夜不得息，惊涛涌雪六月迷长空。","耸身出冰壶，倚杖息馀峭。","举头万松巅，隐隐落斜照。","石羊纷纷望不穷，突见双龙挂寒峤。","恍惚初平兄弟骑，蜕骨遗此青天貌。","俯窥曲涧仅容膝，解衣燃烛渡深黑。","行行不尽一线明，万乳荧煌喷苍壁。","玉树罗青葱，芝田烂金碧。","谁持巨灵斧，凿此灵仙窟。","真人渺何许，瑶草纷可拾。","枰间数子势飞动，细看尚记当年弈。","人言此穴穿四明，天窗万叠开蓬瀛。","摩挲仰视众仙箓，隐见若有胡生名。","吁嗟我今胡为在下土，青鞋布袜濩落如流萍。","乃思昔日玉皇侧，看花醉卧芙蓉城。","木公徘徊向我怒，授简谪余离太清。","一落人间五千载，沧溟浩劫会巳盈。","顾瞻灵境但咫尺，奋身欲飞还不能。","倚杖还悲歌，壮心浩难遏。","却忆云门期，瓢笠候明发。","回望金华山，兹游信奇绝。","馀霞映袍袖，岚翠尚明灭。","何当蹑苍虬，长揖众仙列。","提携两赤松，永与尘世别。"]},{"t":"寄三衢易使君惟效约秋深为烂柯之游并怀蔡景明苏以脩","f":"古风","c":["易侯意气天下无，蚤年宦籍通皇都。","豸冠绣服天咫尺，风裁落落长安途。","一朝使酒忤权贵，凭陵太白歌呜呜。","埋轮有疏不得上，拂衣大笑游江湖。","潇湘云梦长在目，却来东海谈乘桴。","五花暂辍御史马，百里仍蹑仙郎凫。","江郎峨峨三片石，屹立千仞东南孤。","题诗洒墨登绝顶，白眼瞋视天模糊。","桑田沧海倏变易，九重特诏还金铺。","梅花遍咏水曹雪，清源皂盖停菰蒲。","忆昔扁舟驻东郭，蓦然见我心神孚。","卤簿江州却群从，胡床明月邀呼卢。","苏别驾，蔡大夫，十日九日黄公垆。","夜击青萍唾壶碎，昼拈绿玉楸枰枯。","清源明妆十万队，红裙翠袖骄相扶。","淹留卒岁不忍别，春风拂面吹屠苏。","云萍忽尔摧浪迹，平原河朔成虚无。","踟蹰苏蔡各分手，闽山蜀道难追呼。","君侯政绩何炜烨，立驱千骑来东吴。","穷交念我宛如乍，飞书往往寻屠沽。","一丘独卧子真谷，入门三径嗟荒芜。","雕虫小技何足论，眼空六合成狂夫。","青霞之君日候我，斧柯欲烂三蓬壶。","玉局纵横众仙列，云浆一吸三千觚。","使君倘许岸帻过，秋风八月来高舻。"]},{"t":"章生持所业游余门诗勖之","f":"古风","c":["火云峥嵘照林薄，赤日团空坐如灼。","高堂褦襶者谁子，云是香溪少年章敏学。","少年十九能作诗，沾沾欲问扬云奇。","先生四十发种种，抗颜肯受庸人嗤。","新诗读女吾动色，东野穷愁浪仙僻。","电光雷铗双芙蓉，烂漫苔痕土花碧。","君不见神物不遇张司空，万古丰城白虹泣。"]},{"t":"小园杏花烂漫与客携酒酌其下至醉","f":"古风","c":["墙头昨夜春风颠，醉著接䍦花下眠。","东方欲曙忘晨飧，应门何客来翩翩。","城东郭君履欲穿，手持三百青铜钱。","要我为客开琼筵，水晶之壶白玉盘。","银筝翠管张哀弦，吴姬度曲越女弹。","相将载酒临西园，西园万树红照天。","杏花朵朵含春烟，随风故落苍苔前。","恍如红雪堆青钱，摘花浸酒酬清酣。","主人劝客客不言，人生岂得长朱颜。","眼前有酒不尽欢，参差白发来相缠。","君不见相如卧病归文园，笑杀长安群少年。","又不见子云寂寞耽草玄，日暮何人回酒船。","何如醉挟双婵娟，玉山酩酊长花前。"]},{"t":"秋日泛舟钱塘观潮放歌","f":"古风","c":["黑风夜簸沧溟水，冯夷却走海若靡。","素车白马来何方，璇室琼楼遍空起。","玉龙垂地五千丈，银河驾天一百里。","三军钜鹿战始酣，万甲长平溃难止。","胡生此时归适越，醉挟扁舟离江渚。","鼓柁初疑月窟中，旋身已入冰壶里。","雪山恍见释迦坐，一苇聊将达摩拟。","波翻魍魉泣，浪跋天吴语。","长鲸鼓鬣如峻山，电掣云愁堕飞雨。","舟人渔子袖手不敢出，篷底仓皇掩其耳。","是日胡生气无比，轻桡在手疾于矢。","白眼茫茫向天际，欲乘长风破万里。","回瞻圆峤若咫尺，东望扶桑聊徙倚。","即如鲁连蹈岂得，便逐灵均兴难已。","君不见越王宫，吴王宇，寂寞空厓半颓圯，日夜寒涛浸荒址。","满眼豪华遽如许，人生龌龊胡为尔。","乘槎八月差快意，击楫中流竟何以。","天寒日暮风转疾，彷佛鸱夷共相语。","朝来更泛若耶棹，会挟西施从范蠡。"]},{"t":"钓台谒严祠作","f":"古风","c":["高台倚空双突兀，钓丝下坠桐江石。","客星惨淡呼不应，片片飞云向人立。","忆昔真龙起新野，百万昆阳碎如瓦。","朝端但访赤伏符，泽中那问羊裘者。","逍遥建武垂裳初，乃有物色来菰芦。","新衔乍可授谏议，故态宁肯回狂奴。","长啸还归富春濑，采药桐君坐相待。","石上明霞照秋水，峰头雪瀑飞寒籁。","箕山颍阳杳莫睹，太息斯人遂千古。","方干谢翱两小子，废宅荒坟强为伍。","胡生抗志五岳前，中岁偶落风尘缘。","钓竿倘拂紫薇坐，归来与尔共拄东南天。"]},{"t":"夜饮芙蓉馆大醉放歌寄黎惟敬康裕卿李惟寅朱汝脩","f":"古风","c":["初平骑羊去不返，沈侯八咏空嶙峋。","刘生老死骆生窜，谁令大壑回阳春。","君不见兰州胡元瑞九龄，学仙已成癖。","欲乘长风游八极，大鹏扶摇不肯骑，几度鞭羊复成石。","十五更作咸阳游，五花笑脱青貂裘。","酒阑大叫呼李白，雪花飞堕长安楼。","是时真龙御皇极，双阙嵯峨象纬辟。","作赋宁论狗监知，曳裾自许龙门客。","人前白眼双飞扬，谁其握手黎惟康。","李侯晓散禁庐直，停车数过朱生堂。","相看意气谁肯下，握尘含毫破深夜。","万象淋漓碣石宫，千人辟易华阳社。","五陵轩车春不开，狂歌独上黄金台。","拔剑起舞长虹摧，睥睨燕昭王，竖子非仙才。","荒碑零落翳榛莽，其人白骨随尘埃。","剧辛郭隗岂壮士，汝曹自为千金来。","当时乃公用齐国，临淄岂得同蒿莱。","前瞻涿鹿野，左瞰卢龙隈。","浮云万叠飞不尽，但见太行山色青崔嵬。","入洛声名晚差著，掉头忽出新丰市。","拂袖初辞上苑花，持竿欲挂沧溟树。","吕梁震泽天茫茫，扁舟一叶飞钱塘。","镜湖剡溪咫尺不得渡，十月寒涛如雪霜。","孤峰指点严陵宅，古木槎牙向人立。","羊裘客子双眼青，分我桐庐半江碧。","高台祗合长垂纶，谁知物色来衡门。","天阍突兀帝星远，十年五上空沉沦。","萝薜归来手还葺，一笑文君壁空立。","生计犹馀二顷田，谋身岂必千头橘。","五侯七贵俱浮云，邺侯万卷堪横陈。","男儿大业在金石，那令七尺随风尘。","醉墨苍茫浩歌发，紫气东来照吴越。","文章得失心自知，肯向朱门傍先达。","唾壶击碎歌转长，美人天外空彷徨。","眼前龌龊谁相望，大儿刘孝标，小儿骆宾王。","后生不死亦前辈，九原可作同翱翔。","遥遥八咏楼，楼空竟何有。","楼中之人今在否，袛今谁是东阳守。","会叱群羊起太空，卧看扶桑日西走。"]},{"t":"赋得赤松宫为东阳卢祠部","f":"古风","c":["君不见赤松宫前赤松色，夭矫轮囷际天碧。","霜皮不减三万株，铁干宁论二千尺。","初平骑羊去不回，药炉丹灶空崔嵬。","山中白石乱无数，何人叱咤飞风雷。","君不见东阳卢君大奇绝，前身曾受长生诀。","往来三洞蹑明霞，啸傲双溪弄明月。","朅来欲作人间游，苍生六合攒眉头。","帝傍玉女不敢留，飞行独下昆崙丘。","挟书却走明光殿，跃马天街谁不羡。","柳色阴浓彭泽车，桃花锦簇河阳县。","一朝鸣佩趋南宫，炉香画省追夔龙。","退食羞为素餐士，愿将直笔回宸聪。","五夜排云叩阊阖，凛凛孤诚照丹阙。","丘埴宁增泰山峻，微丝愿补衮衣缺。","九关䆗窱环苍龙，燕台白昼飞长虹。","曳裾止辇亦臣职，拂衣神武来秋风。","衡门却返东阳旧，落落松阴浮远岫。","已见声名重斗山，更欲栖迟终宇宙。","名山咫尺黄初平，石羊成阵来相迎。","天王明圣臣愿足，富贵浮云何足论。","卢君卢君真丈夫，直节祗今天下无，从我且酌黄公垆。","漫学三闾赋沅水，肯令董相淹江都。","一朝当宁思良弼，飞诏东山起安石。","会教霖雨遍遐荒，取次天门生八翼。","赤松之宫君暂居，高吟抱膝聊吾庐。","三洞宁为长往客，九重行问治安书。"]},{"t":"题岳阳楼图","f":"七言古诗","c":["危楼倚空欲千尺，阑干下瞰洞庭色。","狂风尽捲苍梧云，万顷潇湘照空碧。","江花冥冥日欲冷，岸芷纷纷翠犹湿。","参差忽睹冯夷舞，缥缈疑闻帝妃泣。","七泽纵横渺难数，九疑如黛尊前出。","舟人渔子棹空旷，薄暮波涛归不得。","楼中骑鹤谁者流，此事恍惚曾同游。","凭阑试诵杜陵句，日夜乾坤相对愁。"]},{"t":"岁杪送郑茂才北上","f":"古风","c":["北风动地捲行色，郑子辞家赴京邑。","蹇驴欲踏东华尘，手挈空囊行不得。","亲知遍谒乞斗水，往往白眼谁相识。","男儿意气轻王侯，有身七尺那用忧。","溪头握手拚一醉，骕骦且付黄公留。","君不见来岁长安百花发，银鞍拥簇歌姬楼。"]},{"t":"闫蓬头歌","f":"古风","c":["闫先生，羽客流，发蓬蓬不裹头。","身骑两白鹿，手掣䨥青虬。","前生七圣相追游，飞翔八极横九州。","朝升大罗顶，暮宿昆崙丘。","木公授宝箓，王母发清讴。","飞琼弄玉众仙女，行厨上食罗珍馐。","桃花万树核如瓮，东方小儿不敢求。","何来醉闯拘翼座，脱巾露顶眠琼楼。","雷公轰轰上帝怒，谪向下土称蓬头。","长身大腹状殊绝，赤颧红颊惊庸流。","方瞳射空碧电烱，紫髯拂地苍虹流。","终朝一食气逾王，终夜不寝神长游。","严冬雪片大于席，寒冰十丈风飕飗。","先生此时赤双足，单衣不御青貂裘。","道旁观者色沮丧，真仙出世谁能俦。","和光颇类柱下史，玩俗或比蒙庄周。","仰天大笑暮云碧，茫茫下土皆蜉蝣。","朅来偶过勾曲洞，乘鸾跨鹤三峰头。","乖龙左耳割不得，飘然一苇来南州。","众中遇我心莫逆，片言立使千金投。","微辞奥旨发中夜，变化恍惚难先筹。","时时诧我骨毛异，青城仙伯行相求。","三生石上事非远，努力缮性穷熏修。","愧我中年薄闻道，尘埃碌碌随轩輶。","神明凋谢鬓发改，岂将七尺图封侯。","感君便欲逐君去，乾坤万事同浮沤。","三公七贵竟何物，五阴四大俱悬疣。","何如长啸出寥廓，霍然尽豁平生愁。","闫先生，且莫行，为我留，谪期未满堪夷犹。","吾家别业武夷上，铁船丹灶悬高丘。","幔亭之君日来下，三山九曲随冥搜。","他年挟尔棹歌去，坐看大海天咫尺，巨鳌赑屃浮中流。","珠宫贝殿耀金碧，清都绛阙喧琳球。","鹍鹏一卧九万里，鸿鹄一举三千秋。","玉皇香案倘相忆，羽翰白日飞神州。"]},{"t":"赋得灵隐寺飞来峰赠卢祠部","f":"古风","c":["灵隐门前千岁松，夹堤九里来青葱。","何年突兀金芙蓉，削成四面摩苍穹。","恍疑夸父移空同，一拳掷向沧溟东。","日月东西悬混濛，云霞上下披蒙茸。","周遭刻画非人功，象王鹤驾行虚空。","投身直入蓬莱宫，丹楼雪乳垂玲珑。","流泉百道声琤琮，有如仙乐呜笙镛。","金书玉简潜奇踪，䆗窱恍与银河通。","灵威丈人不得穷，古来传是飞来峰。","万古壁立青霄中，何人散发携孤筇。","扪萝直上乘天风，金华有客真豪雄。","孤高大节将无同，少年挟策游新丰。","五花蹀躞长安骢，出宰百里花为封。","鸣珂入候甘泉钟，握兰典礼称儒宗。","素飧耻学凡夫容，织成云锦蟠心胸。","要将琬琰垂勋庸，直排阊阖陈孤忠。","曳裾折槛惊天聪，轰轰天鼓鸣雷公。","覆盆不照微臣悰，精诚贯日飞长虹。","挂冠神武何匆匆，回头却望丹宸枫。","血泪乱洒征衫红，归帆正值钱塘风。","六桥三竺春溶溶，不学留侯师赤松。","且邀白傅寻苏公，振衣千仞聊从容。","朝飧沆瀣追冥鸿，暮拾海月鞭虬龙。","六丁撝呵玉女从，俯视六合俱螟蠓。","朅来遇我东阳东，竹林把臂心神融。","仰天大笑横双瞳，欲骑箕尾还长空。","卢君劝汝满釂黄金钟，且为拂拭朱丝桐。","万事人间如转蓬，古来直道多难容。","即今吾道宁终穷，丝纶竹帛行遭逢。","一朝前席明光宫，谁其稳卧飞来峰。"]},{"t":"醉中放歌赠祝生并寄司马汪公","f":"古风","c":["祝生家无担石储，短衣掩肘不愿馀。","生年三十走牛马，世人攘臂争揶揄。","胸中壮气何磊落，眼看俗子如蘧篨。","欲从翰墨树勋绩，耻结黄绶悬金鱼。","自言太古重三立，文章功德原无殊。","朅来叩我草玄宅，殷勤片刺通前除。","先生崛起刘骆后，华名岳岳天南隅。","泰山宁择土壤细，沧海讵惜涓流潴。","兰台高揭并二酉，龙门咫尺悬桑榆。","阶前尺地倘少假，令我一脔尝天厨。","伊余谢客事焚扫，闭关长日扶潘舆。","亲知宇内半凋落，豁然见汝心神愉。","忆汝新都谒司马，太函突兀开云衢。","无殊字汝岂无谓，树勋努力操长殳。","汝兄汝侄并潇洒，问奇往往来吾庐。","古今词赋厄阳九，先生身试不汝愚。","怪汝胡为蹈前辙，甘心赵瑟忘齐竽。","腰缠万贯亦不恶，三槐九棘垂騊駼。","沾沾五字作何状，黄金不逐贫相如。","生乎大笑掩余口，先生戏我犹群儿。","天生七尺当不朽，大千世界皆蘧庐。","倘来富贵宁足论，电光石火同须臾。","一朝腐骨委草莽，醉生梦死随沟渠。","秦宫汉阙走狐兔，公卿未必赢樵渔。","男儿大业在金石，要令天壤留迂儒。","先生两耳濯清渭，十年不受凡人谀。","终朝隐几吾丧我，一听汝言良起予。","雄谈五夜剑花落，绿尊翠杓行茱萸。","高歌赠汝兔毫秃，唾壶击碎青?毹。","长风吹云入广座，欲蹑象纬淩蟾蜍。","生乎生乎汝勿疑，古今不朽真无殊。","好读离骚饮美酒，便作名士追三闾。","莫将狂简讶年少，仲尼大圣思归欤。","即今名姓已不朽，先生笔底开璠玙。","他时藉手见司马，为我捧腹当轩渠。"]},{"t":"潇湘座为祝无殊题","f":"古风","c":["我筑潇湘岛，斗室悬竹中。","汝搆潇湘座，千竿舞秋风。","我岛舟可沿，汝座车难通。","一朝乘兴来子猷，直造竹所聊优游。","主人莫作辟疆态，仰天大笑风飕飗。"]},{"t":"送郭汝冲游吴中","f":"七言古诗","c":["郭生有父鸿胪君，自言东野之后身。","飧风卧月三十载，至今词笔留长春。","生也学书仍学剑，抱玉无媒羞自献。","延宾雅有郎罢风，典尽鹴裘不咨怨。","时时问字来门墙，先生为汝开玄堂。","五月南风稻苗熟，扁舟一叶飞钱塘。","生平不识琅琊里，特向娄江吊兰芷。","中原万里失麟凤，宇宙文章孰盟主。","江阴亦有朱鸿胪，结交四海雄菰芦。","沙头把袂询父友，孤帆八月来三吴。"]},{"t":"忆章云","f":"七言古诗","c":["去年送子城之北，北风怒号天惨戚。","浓霜密雪洒岐路，若个绨袍话相识。","今年忆子城之东，落花烂漫飞春红。","人生好游游亦得，五见社燕迎归鸿。","岳阳楼头秋万顷，醉杀杜陵呼不醒。","何时挟汝荆门涛，狂歌痛饮赓离骚。"]},{"t":"哭祝鸣皋","f":"古风","c":["吁嗟祝生谁谓而年仅止此，尔胡以生胡以死。","文章独抱掩夜台，寂寞寒山饿妻子。","忆生束发负奇尚，壮气凌云薄金紫。","绳枢瓮牖穷彻骨，耻向豪门谒涓涘。","世人妒生狂欲杀，白眼纵横半睚眦。","青衫一领不得消，掷向齐东营耒耜。","胡为复作长安游，瞰?芒鞋污泥滓。","呜呼大块亦忘才，玉折兰摧繄谁使。","昔余与生初结交，邂逅尘埃双国士。","拂衣初上西山巅，万岫回青八陵紫。","峥嵘高论骇俗流，磊落雄心付良史。","生今已矣宁再得，泪目淋漓傍桑梓。","酸风落日华阳宫，素旐翩翩潞河涘。","孤坟三尺暮云白，白马生刍者谁子。","我歌薤露生莫悲，自昔贤豪并如此。"]},{"t":"寄张伯起","f":"七言古诗","c":["去年我病维扬邸，日望琴高骑赤鲤。","一朝起色乘江潮，朔风狂雪吹绨袍。","吴门邂逅张伯起，万卷纵横列湘几。","蓬蒿夹径春不开，焚香永昼眠苍苔。","翩然为我倒屣出，握手论心称莫逆。","烹熊炰鳖出丰膳，绣虎雕龙指金石。","男儿七尺当自强，巢由岂必攀虞唐。","千秋大业在竹素，胡为燕雀讥鸾凰。","抽毫日纂文选注，恍入梁台试精骑。","倘来富贵讵足论，避世墙东有深意。","阳春堂上横朱弦，子夜歌成兴杳然。","他时倘慕兰陵宅，日候山阴访戴船。"]},{"t":"登大云山望瀫水寄李允达","f":"七言律诗","c":["忆昨曾携李仲子，酾酒遥登瀫江渚。","美人一去秋水寒，望望蒹葭隔烟浦。","朝真洞口饶白云，尺书天际时相闻。","山栖倘续孝标志，与尔同栖麋鹿群。"]},{"t":"祝太学逊之五十始为诗戏作短歌赠之","f":"古风","c":["君不见天宝词人高达夫，行年五十执金吾。","一朝作诗遇杜老，声华奕奕留吾徒。","君不见成均胄子视懋学，五十无闻甘寂寞。","一朝坛上逢胡君，奋臂词林问前矱。","沉吟二事迹颇奇，千载何当复遇之。","汝为常侍理或有，我说杜甫人争嗤。","丈夫有志未可轻，古人讵必皆无成。","杜陵四十始献赋，当时颇遭俗子淩。","脱身锦里拾橡栗，长镵短褐徒悲鸣。","达夫青云本自致，高牙大纛悬长城。","呜呼后世两寂寞，惟有只字留其名。","我今四旬汝五十二，子之年巧相值。","焉知异代无子云，未信东山少安石。","男儿致身苦不蚤，发短心长恨何及。","我歌杜陵念已灰，汝效达夫志当立。","不见宁越师诸侯，努力馀年莫轻掷。"]},{"t":"琵琶行","f":"古风","c":["李将军，虬髯戟列横秋冥。","当关壁立万夫勇，扫空大漠无王庭。","一朝谢事东海上，皓首华颠气逾王。","醉归叱咤灞陵尉，长揖嫖姚不相让。","欲将雄剑卖黄金，却把琵琶弹素心。","凄清激烈风雨过，高楼五月如山阴。","君不见贺怀智，石槽铁拨云雷气。","唐家供奉推第一，青史流传誇绝艺。","君不见康昆崙，指下鏦铮捷有神。","玉盘骊珠千百转，春冰拆裂河流浑。","将军岳岳起当代，手挈二子成三人。","即今狼居尽款塞，九边铁骑閒黄云。","明妃奉帚长信殿，娥眉不踏燕山尘。","山西老将亦无用，金甲苔生土花重。","笳声寂静刁斗寒，但把琵琶学三弄。","华堂秋空月满楹，朱弦翠幕流明星。","觞行乐奏豪兴发，快剑长戟纷争鸣。","为君慷慨弹入塞，莫作琵琶亭下听。"]},{"t":"寄邺中王孙灌父时约余为嵩少之游","f":"七言古诗","c":["昔我年少思远游，飞行八极寻浮丘。","梦寐三花映绝壁，昆崙倒挂黄河流。","主人况有淮南术，要我峰头鍊金液。","石林万仞扫空翠，念载无人白云湿。","亭亭孤鹤来缑山，王乔有约予当还。","今年曳杖定偕汝，三十六峰秋月圆。"]},{"t":"岭南祁羡仲以诗见贻赋答并问惟敬秘书","f":"七言古诗","c":["南海祁生何卓荦，题书远寄吴天鹤。","开缄恍对四百峰，片片罗浮白云落。","年来岭表多词人，黎欧以后谁其伦。","丈夫寸心在万古，那能龌龊随风尘。","闻汝好吟兼好酒，一釂千钟世希有。","黎生夙昔称酒狂，对汝还能剧饮否。","高阳酒徒气若虹，有兴倘过兰陵东。","不信今时酒殊绝，试问琅琊王长公。"]},{"t":"余在娄江日孙齐之徐孟孺同日先后过访余以行迫不及报谢追忆二君辄成短歌","f":"七言古诗","c":["孙郎已老徐郎少，一日娄江逢二妙。","赵家白壁总连城，海上明珠双照耀。","孙郎发短垂六旬，徐郎三刖仍干秦。","余亦狂歌称隐沦，虎溪相别成大笑，满眼人间失意人。"]},{"t":"两得欧桢伯书及致西署秣陵二集走笔寄谢询其苍头李英","f":"七言古诗","c":["王生手持双鲤鱼，剖之中有明月珠。","鲛人夜泣魑魅走，珊瑚十万罗前除。","美人吏隐金陵畔，金马铜龙谁不羡。","缓辔晨过莫愁里，鸣珂夜入明光殿。","秦淮千里心悠哉，瀫水兰桡那得开。","君家摩勒有佳句，祗今何似郗方回。"]},{"t":"题潇湘烟雨图","f":"七言律诗","c":["桂树丛生石嵓侧，万仞寒云挂苍壁。","穷阴大泽龙蛇走，绿萝蒙茏楚天黑。","行吟泽畔者谁子，日暮欲归归不得。","黄陵美人把瑶瑟，杜宇啼烟鹧鸪泣。"]},{"t":"詹东图有茶癖即所居为醉茶轩自言一饮辄可数百杯书来索诗戏成短歌寄赠","f":"七言古诗","c":["吾闻卢同有茶癖，七碗清风生两腋。","吾闻陆羽称茶仙，铜瓶细酌中泠泉。","古来知味但如此，咄咄新安詹仲子。","胸吞云梦蟠潇湘，一饮百碗消枯肠。","虎丘之产茶仅斗，尽采遗君不盈口。","蒙山石上青槎牙，咀嚼那能烦齿牙。","斟酌建溪三百饼，巨杓长瓢堪酩酊。","风炉竹几罗庭除，大铛贮月来中厨。","松风才过鱼眼发，玉乳盈缸喷香雪。","鲸吞鳌吸如有神，淋漓醉墨驰风云。","一饮一挥三百首，若个能诗复能酒。","胡生十载戒饮茶，金茎日夜烹黄芽。","天瓢一滴欲冲举，刺刺文君未相许。","羡君豪兴为汝歌，歌成掷溯桐江波。","明年倘忆吾乡茗，谷雨前朝赴龙井。"]},{"t":"夜集郭鸿胪馆偶闻邻室有使酒相虐者余为解纷竟戏作短歌示鸿胪","f":"古风","c":["古人饮酒戒沉湎，一石萧然神不乱。","今人饮酒如沐猴，脱巾狂叫无时休。","双眼茫茫向天白，知交侧目成愆尤。","清音软谑有何意，白波平地如山丘。","君不见张旭满引挥云烟，李白一斗诗百篇，遇汝那得开心颜。","又不见刘阮朝朝竹林醉，当日高谈遇此辈，大白流离玉缸碎。"]},{"t":"谢文度年八十馀而步履轻健如少新秋棹小舟千里过访且拉余往闽中曰武夷君迟子久矣余大壮其矍铄于其行也赋短歌以订后期","f":"七言古诗","c":["谢君束发湖海狂，飞腾若木窥扶桑。","只今九十健于虎，白眉红颊双瞳方。","伯阳我师吕公友，玉笈云章佩星斗。","人间独好胡生诗，千里拿舟瀫江口。","自知名姓在瑶京，尘世蜉蝣那得闻。","朝来共跨赤虬去，玉笙吹向武夷君。"]},{"t":"夜同方吴两生集汪士能宅留宿作新都豪士歌","f":"古风","c":["君不见新都侠客汪士能，意气磊落形骸真。","须髯如戟鬓如猬，泰山一掷轻千钧。","大腹便便亦何有，半生但贮宜城酒。","日倒青莲三百杯，家藏白堕五千斗。","暮春三月日颇长，杏花半落梅子黄。","先生白眼空四海，却来岩市登君堂。","堂上吴生宛如玉，座右方生迥超俗。","博山炉中沉水香，玳瑁玻璃照?醁。","相看一笑轻王侯，长鲸跋浪风云愁。","主人尚醒客已醉，荧荧华烛开朱楼。","绣缛纱茵迥奇丽，一卧明窗不知曙。","感君意气为汝歌，赠汝狂名在天地。","吁嗟乎，世途局促难为容，卖浆隐博甘途穷。","身后荣华竟谁是，眼前尺蠖嘲蛟龙。","生家伯兄文且武，骠骑才名驾千古。","二兄三兄咸楚楚，生也第六之名讵减五。","城东红妆十万家，朱唇翠袖争朝霞。","相逢不饮漫成别，参差笑杀千桃花。","君不见杜陵布衣老且拙，典尽春衣兴逾发。","黄四娘家花满蹊，大白携生醉明月。"]},{"t":"翌日仝集方羽仲宅则王生为大力者负之而趋戏作短歌题汪氏壁并示汪吴二子","f":"七言古诗","c":["丰干里畔方干宅，乔木森森向人立。","高堂净扫无纤尘，片片明霞傍檐入。","主人古貌仍古心，市隐蓬蒿甘陆沉。","片言遇我心欲醉，鹔鹴立解千黄金。","春日春盘荐春韭，白粲鲜鳞无不有。","乍可朝眠杜曲花，那能夜欠新丰酒。","溪南两岸烟树深，美人不见愁人心。","暮雨朝云杳何处，明月香车返岩市。"]},{"t":"夏日同吴叔思东陂观莲","f":"七言古诗","c":["若耶之溪五十顷，绿晕红酣画船暝。","吴王宫中十万妆，明霞为佩风为裳。","箫鼓参差棹歌发，隔岸清波照罗袜。","年少谁家双紫骝，坐看玉腕明中流。","日暮香风四天起，恼杀金陵谪仙子。"]},{"t":"题山房梅花帐","f":"七言律诗","c":["剡藤为簟湘为帘，十幅吴绡更奇绝。","罗浮狂客刘世儒，一扫赠我千峰雪。","主人清夜眠其中，羽衣恍惚来相从。","参横斗落不知曙，一枝醉抱春朦胧。"]},{"t":"送张英甫归永嘉因询康山人裕卿","f":"七言律诗","c":["两年不见张山人，阮公眼白谁相亲。","草堂何来下孤鹤，青山岁暮回嶙峋。","长揖辞余复行迈，指点龙湫白云外。","语汝山中康裕卿，万尺飞流好相待。"]},{"t":"题宣和帝御制楚江秋晚图","f":"七言古诗","c":["当年曾挂潇湘席，历历云山似相识。","长忆江头红树村，千林落照催行色。","隔岸人家草屋深，凭阑浩啸舒尘襟。","长天茫茫鸟飞绝，潮落汀洲龙夜吟。","隐见渔舟泊沙阜，莎径寒烟莽回互。","群仙可望不可招，虚阁凌空挂烟雾。","两翁矍铄巢许俦，崇冈之北茅堂幽。","登登回顾蹇驴客，撩乱瀑花天际流。","何人笔底开层巘，貌此江南秋一片。","瘦金书法了可验，恍惚似入宣和殿。"]},{"t":"严陵晚泊","f":"古风","c":["严公昔未遇，耕钓日沉冥。","一朝动人主，始识少微星。","余亦任公子，垂竿三十龄。","被发上高台，浮云空翠屏。","双矶拳石那可坐，却望三山游四溟。","袖里虹霓一千尺，手掣鳌鱼归帝庭。"]},{"t":"白纻歌二首 其一","f":"七言古诗","c":["葡萄之酒琥珀缸，金罍玉斝春茫茫。","博山炉焚沉水香，翠屏朱户罗笙簧。","援琴鼓瑟流清商，洞箫遏云声飞扬。","珠帘不捲凝夜霜，千花万花夹华堂。","明星烂烂出东方，左挟安陵右龙阳。","美人翠袖娇红妆，秦城卫女纷成行。","愿君一盼生辉光，清歌盈盈绕画梁，夜如何其夜未央。"]},{"t":"白纻歌二首 其二","f":"七言古诗","c":["黄金为堂白玉椽，翠屏珠户罗婵娟。","流苏帐煖春茫然，鸳鸯锦被裁合欢。","明眸皓齿娇相怜，三星煌煌月在天。","灯长烛明兴未阑，都梁甲煎焚华轩。","茱萸苏合纷缠绵，非烟非雾非人间。","引宫刻羽鸣幽兰，昆崙之觞斗十千。","美人垂手临风前，回身杂佩何珊珊。","珊瑚火齐间木难，腰围尺六芙渠鲜。","惊鸿宛转飘琼筵，双成弄玉俱神仙，夜如何其夜漫漫。"]},{"t":"行路难六首感事作 其一","f":"古风","c":["君不见竿头鸢，乘风浩荡游九天。","君不见栋头雀，百尺凭虚俯寥廓。","君子雌伏安蓬茅，小人雄飞势挥霍。","乞哀中夜如鸺鹠，志意满极惊庸流。","时移事改恶声播，遗臭墦间万夫唾。","君不见公孙张仪称丈夫，至今行乞羞庸奴。"]},{"t":"行路难六首感事作 其二","f":"古风","c":["君不见盘中蝇，变幻黑白如丹青。","君不见市中虎，利口纷纭捷桴鼓。","君子推诚洞腹肝，小人柴棘横肺腑。","谗言交搆四国哗，贝锦百匹张云霞。","邦家覆败手足露，绝膑刳肠示行路。","君不见江充举族无极歼，有北陈诗盈简编。"]},{"t":"行路难六首感事作 其三","f":"古风","c":["君不见帐前蚊，侵肌啑肉无时停。","君不见襟前虱，饮血?膏罔休息。","君子守道甘困穷，小人聚敛恣胸臆。","溪壑之欲浩无涯，狼贪蚕食肥私家。","祸盈孽满罹刑辟，昆冈火延灰玉石。","君不见梁冀籍赀元载诛，黄金满谷成丘墟。"]},{"t":"行路难六首感事作 其四","f":"古风","c":["君不见波间蜃，吞吐楼台倏千仞。","君不见岩间蛛，四张罗网迷空虚。","君子行善苦不足，小人济恶才有馀。","沉机伏弩绊飞走，变幻诪张何不有。","术穷数尽来天刑，青冥白昼飞雷霆。","君不见林甫剖棺桧丑缪，千秋永劫昭大戮。"]},{"t":"行路难六首感事作 其五","f":"古风","c":["君不见墙畔蝎，猛刺如山蚀金铁。","君不见泽畔蛇，恶氛涌雾张狞牙。","君子乘时沛膏泽，小人并日行凶邪。","一朝无处肆酖毒，馀愤凭陵螫草木。","噬人既尽阴祸延，刀锯鼎镬快意飧。","君不见阳由弃市俊臣族，天道好还如转毂。"]},{"t":"行路难六首感事作 其六","f":"古风","c":["君不见海中鳄，利齿如山逞凶虐。","君不见穴中狼，巨口如城当道傍。","君子好生戒苛慝，小人毒害盈刚肠。","积尸累累血成堑，意气扬扬了不变。","神人共愤罪恶盈，百骸分裂宇宙腥。","君不见董卓然脐侯景灭，万古元凶戒车辙。"]},{"t":"围棋歌赠黄生应魁","f":"七言古诗","c":["嘉隆奕者师鲍髯，敌手燕台惟小颜。","琅琊门下角程李，斧柯欲烂天东南。","四明岑乾出稍后，自说髫龄遇神授。","一时诸子皆偏师，何能突过颜鲍右。","迩来国手归维扬，方生日新最擅场。","天马行空绝蹊径，喧啾百鸟鸣鸾凰。","会稽黄生名较晚，负局携家傍天苑。","蹇驴破帽春明门，落落乾坤孰青眼。","当时奕道颇有声，十年贾勇争时名。","一朝神理洞仙著，骅骝独步长安城。","落子潜思动移日，梦入巴邛四仙窟。","有时大敌交中原，往往一枰竟秋夕。","兵锋所指无群雄，铮铮剑戟摩苍空。","虚堂棐几对剥啄，晴天雨色交长虹。","猛若重瞳战钜鹿，奇如邓艾收西蜀。","槎山通道捷有神，斩壁开关恣腾逐。","即当死地偏用奇，背水援桴号令驰。","俄看赤帜树高垒，股弄强敌如婴儿。","倏忽长驱走雷电，太白经天助鏖战。","全齐陡下七十城，雄赵一坑四十万。","长安五侯不乏材，连云甲第朱门开。","高轩驷马竞延致，争先结袜黄金台。","黄叶盈庭仆夫卧，风雨萧萧烛花堕。","斧柯几烂局未终，不觉晨钟彻高座。","唐时供奉誇积薪，生岂冢嫡繄后身。","荒丘仙妪姑若妇，九枰口诀留千春。","丈人耽奕自蚤岁，飞将词林绝无对。","茂弘五品输江郎，遇尔那能不心醉。","嗟嗟黄生意气豪，岂徒覆局兼含毫。","上书无路谒明主，狂吟易水风悲号。","世人沾沾事酒肉，高盖峨冠耀流俗。","生徒工奕仍工诗，老向金华走碌碌。","黄生黄生歌莫哀，三公九列俱尘埃。","不见东南八万仞，寥天石室青霞开。","奕罢两奁收白黑，局上亏成总虚掷。","乘云且逐胡先生，跨鹤鞭龙访太乙。"]},{"t":"后围棋歌再赠黄山人","f":"古风","c":["隆万以来攻奕者，歙有小吕闽小蔡。","黄生崛起禹穴中，倏忽时名共当代。","丈人丱角游长安，国手何人不针芥。","鲍颜二李卢及岑，次第携枰入东岱。","中原豪杰屈指空，晚得方生最称快。","方生巧思凌古今，游戏神通了无碍。","永嘉方生并时出，名姓俱同剧堪怪。","少年复有六合王，浸浸渑池欲兴代。","黄生善战尤自负，夙昔疆场构吕蔡。","方生之下三子优，叱咤登坛勇莫逮。","有如孟德肩孙刘，鼎足三分建旗盖。","棋虽小道实可观，生也精进迥不懈。","并吞割据弘霸图，劫杀侵渔尽变态。","楸枰落子大势分，先著纷纷布要害。","吾观此道与兵合，一一为子陈梗槩。","攻城略地创都邑，背水依山列营砦。","发纵元勋首帷幄，指画奇谋洞蓍蔡。","援桴击鼓事征讨，跃马横戈奋骄怠。","湘东一目宁久长，大舜重瞳迄推戴。","三千牧野行造基，百万昆阳坐奔溃。","大军涿鹿平蚩尤，孤卒鸿门闯樊哙。","混壹区夏秦有权，表里河山晋无害。","成皋坚壁控土宇，函谷封泥距关隘。","含枚定陶袭项梁，卷甲阴平走邓艾。","七纵七擒启荒服，八战八克定边塞。","岁时吴魏争长江，日夜梁唐斗夹寨。","乘风帅众下井陉，冒雪潜师抵淮蔡。","晋阳三版浸难没，即墨残都守无奈。","阖闾贪欲甚蛇豕，勾践阴谋桀蜂虿。","推锋白起劲若飞，持重廉颇老能耐。","卢狻李密王世充，鹬蚌高欢宇文泰。","东西并举骋全力，南北中分各两大。","气盈量满隳成功，忿削贪亡示明戒。","入神入圣穷幽微，为虏为王决成败。","棋与兵合种种然，始作何人世沾溉。","相传放勋教丹朱，上圣无缘发机械。","或言战国尚雄略，馀习纵横此流派。","丈人髫岁负棋癖，铮铮铁中号亡赖。","一枰悬榻昼夜攻，寝食俱忘减腰带。","回光返照念载馀，四大部洲任成坏。","胡来遇尔重作歌，见猎浑忘喜心汰。","下车搏虎众欣悦，拍手其如士林訾。","尚忆斐旻舞剑时，道子挥毫摄千界。","崔家延伯每临阵，亦藉僧超鼓豪迈。","雄才绝艺两间值，怜汝求言日瞻拜。","虚堂洒墨元气流，万壑寒风度天籁。","君不见休仁中正蚤已没，待诏师言近谁再。","仲甫四篇差足存，伯祥三路逝安在。","由来一局尘世空，底事妻儿溺贪爱。","君不见巴邛仙橘大于斗，商山四翁乐相待。","九枰输我愿未酬，会擘龙肝了馀债。","他时负局寻先生，洞壑金华乱峰外。"]},{"t":"武林大雪程太学仲凯邀同张总戎黄刺史徐司理钱文学吕山人汎棹湖中泊南岸放歌徒步入龙井汲泉瀹茗延赏至暮乃归","f":"七言古诗","c":["雪花夜半飞三竺，万壑千岩恍如玉。","新都程生太好事，曳杖清晨叩茅屋。","手持三百青铜钱，要我湖头豁尘目。","茂先叔度钱及吕，斗笠芒鞋恣追逐。","伟长诗思亦横发，首御肩舆入穷谷。","觞行到手不暂停，鹦鹉鸬鹚互相属。","人比竹林差有馀，客方莲社宁不足。","阶前奇石叠层巘，洞底流泉吐深麓。","山僧瀹茗作清供，色香味美迥可掬。","蒲团棐几媚优钵，竹院明窗照薝卜。","幽深若与尘世辞，昏黑将求上方宿。","或言狞虎山下过，吾意神龙井中伏。","诸君先发余少留，为语平头免刺促。","四百八十金银台，会策黎眉入天目。"]},{"t":"钱象先过访深雪中往报不克短歌柬之","f":"七言古诗","c":["武林夜半北风疾，雪片垂天大于翼。","孤山老梅僵欲死，跨蹇呼舟漫寻觅。","东吴钱生住昭庆，拥褐高眠送长日。","吟成字字敌琼瑶，皎若天花堕禅席。","忆生三月来武林，啸傲西泠事琴奕。","怜才总称陆士衡，好士亦有徐元直。","穷愁骨相自古然，典尽鹴裘壁徒立。","沾沾访我空巷中，把赠明珰示亲昵。","风尘勃窣倦奔走，咫尺钱塘梦瓢笠。","朝来策杖拟寻汝，泥泞阶除没双屐。","美人娟娟隔湖水，一望云山思无极。","登坛大老俨欲尽，艺苑今谁占名籍。","羡君咳唾饶珠玑，下里千夫走辟易。","文通老朽叹才尽，形秽那能不趋匿。","醉拈秃管书短章，小刺聊当正平掷。","他年把臂姑苏台，倘许忘年订金石。"]},{"t":"仙橘行赠吕生","f":"七言古诗","c":["吕生好奕良有年，口如悬河决百川。","凭陵负气双眼白，强项肯伏公卿前。","自言勍敌止方蔡，三人海内季孟间。","楚中近有朱氏子，黄王以下知无前。","朅来武林四阅月，室中薪尽晨无烟。","临安富儿不好事，日夜空囊扪酒钱。","一朝遇我湖水曲，脱巾大叫狂呼天。","先生名姓久岳立，愿得片语垂人寰。","忆乍持刺远谒我，蹇驴薄暮西长安。","尘埃碌碌不称意，云萍此地仍周旋。","试生伎俩果精绝，疾风飞雨鸣华轩。","唐时待诏宋供奉，齐梁中正俱流传。","胡为终世仅布素，江湖老大垂华颠。","吕生吕生勿复言，才高自古多迍邅。","煌煌国匠抉天巧，造物小儿宁汝怜。","不见先生坐诗癖，百忧万恨攒眉端。","荒丘姑妇两奇绝，橘中四叟吾忘年。","他时芒屩会挈汝，一枰柯烂青霞天。"]},{"t":"汤阴王翁年百八十矣而肌肤绰约若处子且豪饮数斗不酲座间出诸名流赠章邀余继作","f":"古风","c":["王仙翁，发如孤鹤颜如虹。","大腹便便贮河汉，鲸吞鳌吸三千钟。","龟纹蹙起隐胸后，玉璜炯炯横双瞳。","眉毫耳毫灿霜雪，时人不识呼社公。","步轻履坦疾于箭，周行五岳携孤筇。","自言今年百八十，九朝旧事盘心胸。","高谈弘正俨目睫，信阳北地俱儿童。","大还曾受柱下老，素书亦从河上公。","王母瑶池燕周穆，仙源几度桃花红。","昆崙阆风不肯住，脱身混迹游寰中。","朅来瓢笠武林逍，湖光山色聊从容。","飘然遇我云水窟，谪仙大叫呼人龙。","初平骑羊去不返，子岂有意仍前踪。","金盆玉壶亦咫尺，翩翩奇骨宁凡庸。","感君意气为君歌，参差两腋乘长风。","却忆玉皇香案侧，丹台恍惚曾相逢。","尘埃堕落经几劫，欲骑鲸背飞寒空。","大鹏希有俨相值，遨游八极追鸿蒙。","他时再赴易迁约，仰天大笑扶桑东。"]},{"t":"李大将军惟寅得唐吴生观自在菩萨真迹长裾跣足天男相一洗世人称谓之谬且庄严妙好六法具备非五代宋元诸名家所办因手勒心经其上而属余长歌识之","f":"七言古诗","c":["画师崛起开元日，万象毫端鬼神泣。","前无顾陆曹卫张，二李阎韩总非敌。","胸中六法参群灵，解衣盘礴流风霆。","斯须宇宙落指掌，茫茫大块愁凭陵。","曾画玄元皇帝庙，隐见人工夺天造。","杜陵老子笔扛鼎，恣写篇章豁怀抱。","金茎碧瓦扶雕梁，旌旗冕黻争飘扬。","词锋绘事两突兀，恍揭日月悬宫墙。","裴旻将军号大侠，力恳丹青荐冥业。","干将起舞烂白虹，倒掷寒空日星裂。","尔时逸气横须眉，狂墨乱洒秋淋漓。","辟支罗刹俨飞动，旁观辟易惊神奇。","吴生一去八百载，后起何人划真宰。","徒闻写照推扬光，未信登坛属王霭。","脱壁庸庸孙梦卿，五朝人物传虚名。","宋元能事著山水，开元遗迹如晨星。","此帧大士最殊绝，妙好庄严种种列。","珠玑璎珞被四体，咫尺天人共颃颉。","高堂十仞云婆娑，彷佛朱阑临普陀。","俯窥渤澥仅涓滴，青莲一瓣扬洪波。","劫风万古吹不动，金身丈六天嵯峨。","大悲显化遍五浊，宰官帝释随呼呵。","有时幻相示闺閤，世人眯目谈娉娥。","即今看画岂待说，幅巾长带垂山阿。","谁其摹勒事琬琰，侯也功德真江河。","忆侯夙世住灵鹫，金粟如来本身后。","阎浮一念偶下移，暂寄貂蝉曳华绶。","将坛文苑双张皇，八荒九域传琳琅。","鸡林百金买只字，往往逸调追河梁。","生平宝此若垂棘，树下杨枝宛曾识。","焚香手篆般若经，照耀丛林炯双璧。","朅来示我令作歌，欲嘘甘露回沉疴。","才枯思竭腕力弱，仰天白眼空摩娑。","惟余与侯深肺腑，意气铿铿迈今古。","侯能射虎过裴旻，余非雕龙愧杜甫。","吴生千载若有缘，三生裴杜重周旋。","安得再起斯人貌，君虎头燕颔相堂。","堂九尺玉立麒麟，前他年云台烟阁。","第一书姓氏为君，大挥十丈之如椽。"]},{"t":"易水垆头放歌怀庆卿","f":"古风","c":["君不见高渐离，举杯击筑天淋漓。","君不见鲁句践，叱咤干将起雷电。","十载荆卿游酒人，褐衣短后随风尘。","一朝匕首刺秦国，白虹千丈垂嶙峋。","貔貅万亿夹广陛，阊阖眈眈虎狼睨。","羸躯五尺掉臂入，勇慑孟贲走庆忌。","世儒刺促计成败，胡不身履斯人地。","君不见十三杀人秦舞阳，死灰踯躅秦宫傍。","当时孺子果怯死，捧图胡以来咸阳。","乃知鼎镬良可蹈，一时感激轻毫芒。","豆羹箪食色陡变，况持白刃游朝堂。","天门峨峨九重辟，六师七萃纷张皇。","从容步履若无事，俯视政也如蜩螗。","图穷督亢刃乃见，至今神貌犹扬扬。","伟哉大勇旷百世，共工项籍争雄强。","八创嬉笑总馀事，沾沾俗士徒称扬。","君不见聂政大呼本仓卒，专诸进食元潜藏。","豫生毁形伏桥厕，谁哉十目交嵓廊。","三人视卿孰难易，一死虽同蹈死异。","吁嗟太史传刺客，百代何人奋高义。","我来易水吟悲风，萧萧匹马随征鸿。","当时壮士岂复得，黄金台馆徒穹窿。","为卿作歌酹卿酒，恍忽精灵下携手。","田光鞠傅渺何处，独往城南问屠狗。"]},{"t":"醉中放歌五章 其一","f":"古风","c":["君不见北斗精，天瓢湛露浮金茎。","君不见酒泉域，甘醴瀼瀼地中出。","三浆沆瀣盈帝壶，觞泛昆崙尽红液。","从知大造亦耽酒，不乐人间复何有。","笑杀移封唐汝阳，两缶能令风伯狂。","西园公子号无忌，一醉瞢腾小天地。"]},{"t":"醉中放歌五章 其二","f":"古风","c":["君不见放勋尧，千钟一饮常逍遥。","君不见重华舜，百觚一举受天命。","袗衣鼓琴二女果，多寿多男祝神圣。","谁云至禹衰帝德，旨酒千秋肇仪狄。","鄙哉巢父及许由，一瓢不保箕山头。","何似携将贮?醁，荡荡巍巍九州牧。"]},{"t":"醉中放歌五章 其三","f":"古风","c":["君不见秦祖龙，布衣十日咸阳宫。","君不见汉高帝，击筑登台望天际。","驱山鞭石魑魅走，素媪云中夜流涕。","威加四海卷六合，匍匐平城命如叶。","不因大风沛上歌，千秋胡颜较仲多。","博浪沙中副车碎，底似平原浃旬醉。"]},{"t":"醉中放歌五章 其四","f":"古风","c":["君不见鲁仲尼，圣德巍巍穹壤齐。","君不见姬公旦，赤舄忠勤古今擅。","有孚濡首系易终，惟汝无量不及乱。","呜呼周孔两大圣，欢伯时时见亲幸。","胡为屈子游江潭，独醒反被蛟龙餐。","谅为名士传不朽，但读离骚饮美酒。"]},{"t":"醉中放歌五章 其五","f":"古风","c":["君不见东王公，金茎琼醴延青童。","君不见西王姥，高宴瑶池万妆舞。","白云在天丘陵出，青雀翻飞报汉武。","列仙群圣三百六，笑揖天姝美如玉。","东方小儿下界游，蟠桃三熟仍三偷。","暂解貂裘换云液，我欲乘风上八极。"]},{"t":"后醉中放歌五章 其一","f":"古风","c":["君不见陈孟公，席间壮气嘘长虹。","君不见孔文举，座上宾朋剧风雨。","金罍玉尊酒满堂，跋扈飞扬恣豪举。","才疏志大差足惜，投辖楗关政堪语。","人生倏忽同蜉蝣，夜长昼短秉烛游。","千秋饮者传异代，汉魏王侯竟谁在。"]},{"t":"后醉中放歌五章 其二","f":"古风","c":["君不见阮嗣宗，竹林白眼天朦胧。","君不见陶元亮，破帽东篱漉家酿。","五斗何如归去来，长啸垆头兴逾王。","谢公双屐嵇公琴，明哲胡为异霄壤。","步兵臧否吾所师，柴桑三径嗟无资。","当时一官不自保，百代声华擅文藻。"]},{"t":"后醉中放歌五章 其三","f":"古风","c":["君不见张季鹰，放浪江东称步兵。","君不见晋吏部，醉倒瓮头笑行路。","衣冠龌龊徒槛猿，富贵斯须草头露。","奸雄窃国中华乱，日月何如醉中度。","鲈乡亭下风飕飗，高标想像垂千秋。","不因酣卧遭束缚，后世何缘有毕卓。"]},{"t":"后醉中放歌五章 其四","f":"古风","c":["君不见太白翁，鲸吞鳌吸三千钟。","君不见少陵叟，蝉腹龟肠三百首。","狂歌痛饮差快意，典尽春衣漫回首。","身后河山千载名，生前宇宙一壶酒。","人生有钱付酒家，十日五日倾流霞。","今辰何辰夕何夕，试问耒阳与采石。"]},{"t":"后醉中放歌五章 其五","f":"古风","c":["君不见王长公，彩毫万古称人龙。","君不见汪伯玉，一醉颓唐倒千斛。","太常斋日不禁酒，岁岁如泥三百六。","金华邂逅赤松子，潦倒乾坤洞肝腹。","弇园澹园及太函，悲风宿草俱茫然。","当时把臂谁上坐，老泪河山夕阳堕。"]},{"t":"长安僧舍邂逅庄山人静父余初未之识也静父独以意契邀余啜茗禅榻中翛然竟日垂别问姓名乃相顾大笑赠以此歌","f":"七言古诗","c":["黄金台下庄静父，啸弄云烟天尺五。","烹葵拉我远公社，错落芙蓉剑花吐。","经年作客咸阳东，浩歌击筑飞长虹。","貂裘敝尽归不得，五见黄叶号西风。","何日相将武夷去，桃花九曲流春红。","丹青楼殿四百八，醉谒上帝金银宫。"]},{"t":"晋陵夜泊寄怀张总戎黄刺史","f":"古风","c":["君不见黄叔度，胸次汪汪千顷波。","君不见张茂先，襟怀朗朗百间屋。","萍踪邂逅天东南，把臂论心洞肝腹。","张公僦舍宗阳宫，生平侠气摩苍穹。","高牙大纛屏一壑，十年钓艇横西风。","黄君卜筑紫阳岫，四壁图书坐清昼。","雌雄二剑巧相值，错落寒光映袍袖。","一朝遇我肺肝亲，青天散发成三人。","把杯白眼望晴昊，寒冬大壑回阳春。","围炉煖阁坐深夜，弹棋覆局流星文。","形骸不将尔汝隔，往往一诺悬千钧。","邀我湖头结新社，春花秋月长为邻。","何意风波起仓卒，转盼交游异南北。","脂车秣马发中路，把袂河梁壮夫泣。","青衫潦倒困一经，俯首王门弄齐瑟。","平津相君差快意，吐哺延宾近东壁。","客星帝座宁久眠，梦入桐江钓鳌窟。","吕梁震泽天茫茫，极目飞云横太行。","遥看亲舍宅其下，霜鬟雪鬓垂高堂。","功名富贵果何物，经时乞米留长杨。","扁舟便作五湖客，重孥十口歌沧浪。","黄河浊浪浩无际，支祁魍魉争豪强。","大鲸如山奋鬐鬣，参差一叶浮沙棠。","穷途历尽抵淮甸，南下维扬疾于箭。","却忆张黄两故人，宿昔河梁涕沾面。","男儿有身百不忧，千秋大业宁公侯。","三孤九列亦馀事，荣华倏忽同蜉蝣。","君不见张公英雄盖一世，烟阁云台了无系。","忘却麒麟第一人，独往寒山问真谛。","君不见黄君意气横青霄，一麾海上游逍遥。","垂天大翼六月息，中林往往嗤鹪鹩。","我今胡为尚泥滓，布袜青鞋共吾子。","四百八十金银台，割据湖山誓从此。"]},{"t":"闻清源王孝廉得第将归戏为短歌寄讯","f":"七言律诗","c":["王郎再谒甘泉殿，一日声名满畿甸。","中天百尺黄金台，走马看花亦堪羡。","清源柳色萦啼鸦，红妆十万娇明霞。","若个新知莫愁女，独倚高楼望宋家。"]},{"t":"燕中日闻文仲使君手书寄余不达而返短歌讯之","f":"七言古诗","c":["忆昔仙凫下东国，种露栽云遍城邑。","至尊召见明光宫，上考吴公书第一。","含香郎署五载馀，大府却拥专城居。","黄堂赫赫五马贵，翻令尺素来樵渔。","宛转双鱼瀫江畔，为复浮沉付殷羡。","美人如花若耶岸，迟我同开越王殿。"]},{"t":"蟠桃歌为大学士赵公赋","f":"古风","c":["君不见大罗之天天尽头，峨峨五城十二楼。","金银台殿四百八，瑶池阿母乘苍虬。","上有蟠桃枝，下拂昆崙丘。","托根层城顶，倒影弱水流。","一花三千春，一实三千秋。","一花一实递开落，沧桑亿万增牙筹。","成周穆满慕长世，飞黄騄骥凭空游。","西华设燕坐树下，欲啖此果不敢求。","元封武帝候青鸟，行厨玉女罗天球。","贪心欲植上林苑，讵知人代同蜉蝣。","东方本是谪仙子，三熟三偷混尘滓。","巨灵一见呼儿曹，函谷于今气长紫。","池头又阅三千年，几看渤澥成桑田。","玉桃偷得不自饱，却来东阁登华筵。","玳瑁筵开近平乐，南斗为樽北斗杓。","中使传觞太液亭，大官行馔甘泉幕。","五陵冠盖何絪缊，八荒一气旋洪钧。","三年三月十三日，河清海宴飞祥云。","老人星见紫微侧，百辟趋锵酬相君。","相君世胄本清献，琴鹤风流谁不羡。","焚香告天天下听，炯炯灵台绝欺谩。","龙头晚达升长杨，要将只手扶纲常。","触喉时宰甘播弃，一麾南海趋衡阳。","采药罗浮巅，折梅庾岭旁。","朱门凿䆗窱，勾漏扪丹方。","拂衣却返严子濑，六洞三山迥相待。","背城十里金台尖，买断寒崖碧霄外。","嵯峨绝壑悬飞龙，白云紫霞涌雪同。","流泉百尺清见底，喷珠漱玉声玲珑。","灼然灵境果奇绝，彷佛藏书神禹穴。","初平骑羊当昼过，大士双林话禅悦。","东山一壑宁久扃，应图处处悬丹青。","南阳抱膝卧岂得，玄纁东帛来缁軿。","乾纲再振寰宇辟，左列夔龙右垂益。","一朝百揆司盐梅，万姓欢呼荷天力。","和衷协德居承明，正笏垂绅临大廷。","帝心默感九重上，划然天地回清宁。","维时西夏变仓卒，奋臂凶渠一呼集。","包藏祸心结狂狡，当宁皇皇食为昃。","东方岛夷弥陆梁，篡窃故主图开疆。","玉京一鼓平壤破，揕胸车辙矜螳螂。","中原旱魃播灾祸，十家九家望门饿。","三方大难丛一时，奸豪所在盘蛟螭。","谁其帷幄运奇策，太阿白日飞丹墀。","天威咫尺强敌下，汛扫妖氛出宁夏。","两宫赈给十郡全，民忘旱魃为丰年。","总戎经略度鸭绿，敌骑仓皇军尽覆。","朝鲜故主仍复都，稽颡西飞乞臣伏。","区区鹿蠡左右王，纠集万众窥辽阳。","王师一出尽瓦解，橐驼千队俱奔藏。","南北东西尽安辑，伟哉相业不世出。","驱除咸谓参等劳，发纵伊谁匪相国。","宫府一体忘喧嚣，皇储出阁安勤劳。","一人元良万邦肃，功百房杜追夔陶。","俯仰天心念良弼，五福煌煌厥躬集。","越裳翡翠日夜输，肃慎波臣到重译。","即今寿域开明堂，桑弧蓬矢罗圭璋。","十方翘首望霄汉，含哺鼓腹歌陶唐。","天子传宣下丹阙，尚方亲赐浑羊设。","金钱粲烂内府储，品馔珍羞路填咽。","维时春暮百卉荣，梅李杏柰俱生成。","牡丹今岁尤蚤发，烨如云锦披仙城。","独有蟠桃隔瀛海，玄圃蓬丘断樵采。","乍宵东走过吉云，偷得持觞献真宰。","真宰年才七十强，丰颐广颡形貌康。","四聪四目明且达，俨如威凤游岩廊。","孙枝绕膝百千指，兰玉盈庭照罗绮。","面前罗拜但点头，乐事世间谁更比。","愿公酌我酒，听我蟠桃歌。","不为万间厦，奈彼寒士何。","听我蟠桃歌，愿公酌我酒。","大庇寒士颜，还须栋梁手。","蟠桃歌，莫浪嗟，愿公岁岁倾流霞。","姜公八十造王室，卫公九十勤王家。","阿衡百岁佐商运，云台烟阁传无涯。"]},{"t":"金坛邓孺孝以易诠见寄赋答时舟过京口","f":"七言古诗","c":["垂髫梦入华阳洞，耳割乖龙兴飞动。","茅家兄弟骑赤虬，握手胡生唤珍重。","金坛坛上邓伯羔，谪籍何年离大茅。","三山长啸俯六合，濯足瀛海霜空高。","点易研朱闭蓬户，尘世浮荣瞥朝露。","韦编几绝不肯休，恍惚羲文案头晤。","成书寄我十万言，言言尽抉参同诠。","丹霄择日待冲举，何物黄金称大还。","还山高拄九节杖，一见初成讶神王。","传语山中白衣相，屈指相逢大罗上。"]},{"t":"洛阳春色图题陈道复水墨牡丹","f":"七言古诗","c":["二百年来画花卉，吴中沈周称第一。","颉颃并数陈生淳，不事丹青祗水墨。","天机一派掌上流，尽扫铅华露风骨。","家鸡曩昔厌馀子，迩岁声名陡籍籍。","吾家此卷尤绝奇，不向长安市中得。","南海黎君夙遗我，把袂河梁示亲昵。","牙签锦轴题八分，四字犹存故人迹。","忆生袒裸盘礴时，颐指群工若役。","中山大管操如椽，半醉掀髯见真率。","桑皮丈八横高堂，元气茫茫堕几席。","姚黄魏紫信手拈，瞥眼千花万花出。","须臾四座回春风，媚李秾桃总辟易。","青油翠幕张层阶，十二雕阑护倾国。","天然富贵压尘土，底事珊瑚斗玉石。","盘行玛瑙夜色殷，屏敞琉璃曙光湿。","琼楼特起明朱霞，玉佩低垂映红日。","女英妫汭偕娥皇，飞燕昭阳倚合德。","廊开响屧西子游，亭俯沉香阿环立。","霏烟绾雾态不禁，握雨携云状难悉。","枯枝断干若草草，嫩蕊繁英转奕奕。","芳菲恍度洛水头，烂漫如栖上林侧。","咄嗟陈生何太奇，十指参差幻帝力。","含毫肯避造物嗔，落楮翻令化工泣。","经时顾凯笔欲飞，旷代徐熙品推逸。","赵昌形似真儿曹，黄监精工讵伦匹。","为拈老句题册终，跋扈飞扬迥相敌。","连城十五差足偿，美锦三千复何惜。","卧观旬月仍卷还，笑杀明诚录金石。"]},{"t":"于生歌赠凤鸣","f":"七言古诗","c":["齐东于生太奇绝，草就征西才十八。","万言落笔风雨惊，白眼青天对明灭。","忆生年少歌远游，兴到扁舟夜中发。","娇妻稚女了不顾，一苇苍茫汎吴越。","会稽秦望攀嶕峣，回首山阴正飞雪。","四百八十金银宫，湖上烟波若涂抹。","移舟却向姑苏台，扬子涛声暮填咽。","石城城南访莫愁，画栋雕甍管弦列。","平康巷陌人如花，散尽黄金等尘屑。","万金散尽归故乡，斑烂菽水娱高堂。","三冬文史业颇富，骅骝騄駬争腾骧。","一经耻逐蠹鱼老，摩挲石鼓临钟王。","解衣盘礴得画理，朱栏澒洞浮潇湘。","禽鱼小景各生动，飞鸣宿食交林塘。","明窗净几拂缣素，虎丘细酌焚清香。","名流满座挥大白，百觚一饮雄高阳。","酣来如意舞精铁，双龙错落回精光。","一朝遇我庄岳底，飘然挟刺来茅堂。","念年魂梦走瀫水，龙门渺邈如天阊。","先生牙颊肯终惠，蟭蛲努力追飞黄。","嗟余濩落拙且蹇，江淮一旅徒披猖。","中原屈指故老尽，即今二仲谁求羊。","邂逅逢生竹林下，有如阮籍偕嵇康。","淋漓曲糵岂无意，仰天大笑神飞扬。","男儿事业在十指，述功纪德皆文章。","高冠大盖等澌沫，电光石火徒张皇。","生今二十甫逾八，声华烨烨悬乡邦。","歌处呻吟总金石，赋成咳唾俱琳琅。","山东英妙孰卿比，长缨直欲蒐穷荒。","他时掉臂走双阙，天人三策摅岩廊。","名成弹指竟大业，肯将肉食移青缃。","春风乍夜变杨柳，娟娟别思盈河梁。","念子殷勤若胶漆，纷披大雪携壶浆。","男儿抗手讵足论，新秋计日来馀皇。","芒鞋布袜吾共尔，翩翩结束穷齐方。","云霞万仞蹑梁父，七十二帝骖翱翔。","磨崖绝顶勒名姓，卧看海日生扶桑。"]},{"t":"读汉寿亭侯庙志歌","f":"七言古诗","c":["芒砀天开九州牧，白水中兴符赤伏。","炎精四百运数终，海㝢瓜分魏吴蜀。","巍巍忠义起解良，精忠大义扶三光。","南权北操两巨猾，侯也睥睨如蜩螗。","忆破袁军访昭烈，十万貔貅俱胆裂。","飞身立取上将头，掷向曹瞒血犹热。","荆州坐镇推元戎，恢图汉室除奸雄。","举襄围樊势破竹，七军电扫如秋蓬。","禁俘德枭两雉兔，大泽艨艟莽回互。","天崩地坼华夏惊，六合几完汉时故。","自许以南遥受盟，壶浆箪食傒汤征。","笑杀曹瞒挟汉帝，中原无穴逃长鲸。","苦恨东吴众蟊贼，割据河山骋诈力。","阴谋秘计日夜萌，举国昏昏效鬼蜮。","贼蒙诡避逊嗣兴，甘言密饵藏戈兵。","侯也胸怀豁云梦，那知故穴潜分崩。","樊围不没仅三版，赤手荆州竟徒返。","麦城困守临沮悲，今古英雄递扼腕。","侯亡逾月蒙亦亡，流芳遗臭垂青缃。","汉统兴衰实侯系，蒙身百斩宁堪偿。","权本狼贪逊狐媚，凶德于时偶参会。","皇天有意灰炎精，讵曰群奸志能遂。","玉泉之山紫气屯，侯今世世为明神。","童孩走卒竞瞻拜，万年庙食昭君臣。","皇皇左伯亦蒲产，异代同心帝猷展。","执鞭想像回英风，欲起侯躬诉悽惋。","九原不作空踟蹰，拮据往事垂璠玙。","青缃触目睹颜面，侯也恍惚来前除。","云旗飘空互明灭，铁马金戈俨腾踏。","纷纷成败论后人，矇瞽何由睹双睫。","东阳腐儒史笔流，褒诛只字严阳秋。","为侯作歌侯俯读，掀髯一笑诸吴牛。"]},{"t":"逍遥篇为袁履善八秩赋","f":"七言古诗","c":["国初词人袁海叟，白燕篇章脍人口。","风流文藻二百年，载睹当今沔阳守。","沔阳刺史真人豪，弱冠雄心蟠巨鳌。","射策曾同弇州榜，三山彩笔飞寒涛。","白氎青衫走燕市，杜曲东风绾游骑。","黄金台馆千尺强，击筑狂歌五侯避。","长杨执戟甘沉冥，一麾出守辞神京。","朱幡皂盖列先后，峨㞹大舳浮江城。","江城八月天茫茫，九疑七泽连高唐。","岳阳楼头唤杜甫，乾坤万古留诗狂。","吏事纷纭苦拘束，回首家林梦松菊。","拜迎官长折腰领，鞭挞黔黎碎肝腹。","文人拙宦自古然，丈夫讵乞儿曹怜。","区区五斗若毛发，肯将一饱酬如椽。","步兵江东兴飞越，两屐秋光路明灭。","为园半割三泖云，筑室全邀九峰月。","九峰三泖长逍遥，飘然越海来轻桡。","金银梵宇四百八，烟霞石屋攀岧峣。","畴昔逢余大堤上，拂拭楸枰互神王。","持杯恍缔竹林友，醉眼朦胧豁霄壤。","四腮鲈熟归兴浓，河梁对拆双飞龙。","重来握手瓦棺寺，烛花夜半流残红。","闻道今年政八十，步履康庄捷蚊翼。","家家拂席延林宗，处处携觞候安石。","嗟余落魄雅好游，夙生药物攒眉头。","看君耄耋若孺子，香山洛社同优游。","玳瑁筵开虎丘畔，矍铄廉颇老能饭。","芝兰玉树森庭阶，舞綵含饴剧堪羡。","何来初度地藏符，孟秋晦日悬桑弧。","今年七月月小尽，安期一夜来蓬壶。","太白浮公为公寿，尘世浮华孰先后。","灵光一柱海岱间，屈指君王问耆旧。","冥灵琐琐未足誇，瑶池几见飞桃花。","春秋载阅大椿历，青牛相逐还流沙。"]},{"t":"布帆行寄徐使君","f":"古风","c":["吾家大罗上，绝顶增城楼。","醒逐东方生，窃桃瀛海头。","罡风起八极，吹堕苍精虬。","支机隔银汉，织女忘牵牛。","男儿意气凌千秋，如椽十丈轻王侯。","兰陵美酒三万斛，百觚一饮眠糟丘。","吴娃越童两绰约，妆成累月弹箜篌。","参差狂态发中座，不告妻子乘扁舟。","山阴夜半六花绽，雪片纷纷堕高岸。","戴家慵夫唤不应，载得西施若耶畔。","五湖汎宅天茫茫，九疑合沓连高唐。","巫娥握手呼宋玉，朝云暮雨啼英皇。","北望宸居建章起，西笑长安兴难已。","大江东下飞寒涛，南顾洪河疾流矢。","乱山芒砀寻真龙，咄咄新丰亭长公。","甘言鼎镬绐父老，弯弧反躬如逢蒙。","谷城酹留侯，缅怀游赤松。","胡颜教隆准，背约追重瞳。","侵寻楚事去，垓下贪天功。","时无轩辕帝，竖子皆英雄。","乃知畴昔广武叹，步兵衡鉴悬秋空。","丈夫白眼甘恸哭，忍将涸辙行途穷。","彭城困阨古来有，踯躅徐卿望余久。","尊前片诺肝胆倾，苦忆忘年竹林友。","楼船一借张孝廉，勃窣犹堪事奔走。","齐滕鲁卫遵遗墟，极目黄河蓟门柳。","蹇驴蹩躠窥蓬莱，华阳碣石俱尘霾。","道傍叱咤鲁句践，白虹怒吼昭王台。","左掣雕龙右屠狗，乾坤嚄唶双青鞋。","俗流惊怪颇欲杀，先生玩弄如庸孩。","故园松菊渺何处，拂衣长啸吟归来。","亲舍夷犹太行麓，抱膝躬耕事樵牧。","长镵谷口时逍遥，点缀鱼虾伴麋鹿。","石羊成队闲金华，丹崖翠壁流胡麻。","支机却访鹊桥畔，寻源直驾昆崙槎。","长洲宫阙闭荒苑，潮打空城秣陵晚。","垆头谁问太白星，六代残碑吊苍藓。","夕阳伫桃叶，双桨沿前溪。","莫愁卢家妇，邀我长干西。","临春结绮蔓狐兔，白门禾黍空高低。","笑杀当时景阳井，三人贯索如连鸡。","瓜步旌旗迥回合，灯火邗沟互明灭。","珠帘十里歌吹浓，一派箫声广陵月。","青楼宿紫薇，绣幕围罗衣。","征夫念长路，明发临淮圻。","使君弹指诧历岁，大纛高牙坐相慰。","布帆不厌长康痴，安稳行人出徐沛。","嗟余畏路频远游，羡汝急流真勇退。","挂冠神武殊匆匆，黯淡乡心入鲈鲙。","砍鲈鲙，匀秋霜，张锦席，浮沧浪。","大姑迓客来南康，小姑送客过浔阳。","武昌黄鹤为君下，阑干百尺摩青苍。","买得秦人避秦地，夹堤红树回渔郎。","拂衣偃息武陵洞，白云如絮萦轩窗。","人生俯仰贵适意，筑宫冲漠朝羲皇。","危亭四顾象纬列，九玄琼笈罗缥缃。","噫吁使君卧岂得，绿野平泉漫营室。","苍生四海唇嗷嗷，翘首经纶帝三锡。","司空治水魍魉愁，太尉登坛鬼神泣。","降生名世讵偶然，突兀麒麟候颜色。","庙堂计日诹雄图，扫除日本平海隅。","天吴窜迹海若徙，鸡林重译来长途。","勋庸奕奕树彝鼎，飘然一苇还菰芦。","三千行圆八百就，刀圭入口升蓬壶。","此际胡生满谪籍，香案仍居玉皇侧。","大鹏希有行相逢，浩荡扶摇骋八翼。","营营下土同蜉蝣，天上宁知总旧识。","蟠桃尽摘玄圃霞，烂漫瑶池醉千日。"]},{"t":"寄俞声父广文俞君六十而意气壮甚投余万言之书愧无以报报以短歌","f":"古风","c":["俞翁六十形貌苍，胸中壮气何昂藏。","唾壶击碎铁如意，独夜悲歌神慷慨。","素书双鲤乍遗我，剖之字字皆琳琅。","丰城双剑久埋狱，谁从石匣提干将。","载读名山两游记，雄词直上追班扬。","琴声四壁响空翠，云霞万叠流青缃。","兴来便欲远寻汝，青鞋布袜双翱翔。","丛霄绝顶跨鹏背，侧身南斗呼琼浆。","晨风不假子安便，滕王高阁天苍茫。","珠帘画栋永寂寞，何人百代垂文章。","参差念汝袖中刺，片帆计日来浔阳。","琵琶亭下遇商妇，荻花枫叶吟秋江。","洞天携手三十六，醉鞭乱石成群羊。","王门鼓瑟让儿辈，沾沾白雪弹清霜。","谁云烛武非少日，即今圣主开明堂。","魏尚云中阨群吏，楼船十丈横扶桑。","一朝谈笑生羽翼，至尊投袂呼冯唐。","君不见公孙片言合武帝，千秋爵位高明光。"]},{"t":"度辽行再送万中丞","f":"七言古诗","c":["山西万侯真丈夫，豪名七世闻匈奴。","虎头燕颔铁作肤，弱龄猛气吞于菟。","担簦挟策游天都，赤手欲把苍生扶。","九重含笑留操觚，一麾重镇分铜符。","念年大白挥酡酥，雄心日夜驰伊吾。","渔阳鼙鼓动地呼，至尊辍饭思良谟。","仓皇颇牧勤朝晡，玺书十道飞平卢。","紫貂三锡来屠苏，清酒黄封传玉壶。","酒酣耳热声呜呜，掷杯慷慨登长途。","貔貅十万听援枹，鹅鹳三千随渡泸。","八百家丁操仆姑，甲光耀日天模糊。","朝鲜箪食歌来苏，王京一扫空萑苻。","楼船鸭绿江平铺，长驱海若縻侏儒。","釜山对马风摧枯，西飞清政魂先徂。","六十六岛追逃逋，行长骨碎行头颅。","生擒关白如蝼蛄，金人夹道陈休屠。","至尊前殿临赐餔，子孙奕奕封金吾。","河山带砺名公孤，一编黄石垂孙吴，山西万侯真丈夫。"]},{"t":"昌世孝廉有子记诵绝人十二游泮倾动侪辈为作阿咸行","f":"古风","c":["阿咸七岁工临池，眼如点漆肤凝脂。","九龄大书扫秋叶，墨花往往堆涟漪。","十二青衫走黉校，十五胸腹蟠珠玑。","千言一挥河汉溢，万卷一目风云驰。","矫若金茎擢云际，亭亭百尺无傍枝。","君不见杨收十三擅文藻，乞言尽日窥籓篱。","男儿堕地山岳动，岂与氓庶同蚩蚩。","又不见子安十四序滕阁，落霞秋水标神奇。","低昂造化在掌握，寸管立泄玄元机。","区区富贵果何物，百代声华迥难匹。","古今名士多少成，大业终须汝曹立。","况复而翁字彦国，载世文光炯奎壁。","他时税驾讵可量，汗漫扶摇待风翼。","嗟余潦倒病且愁，倏忽流年近高适。","王家玉树空寤寐，一子呱呱尚衽席。","苍茫睹汝思欲飞，那得宁馨在蓬荜。","后生可畏亦可虞，电火人身讵金石。","少时我亦王杨徒，此际何由发重黑。","含毫为汝聊作歌，努力韶光莫虚掷。"]},{"t":"繁弱行王世叔通侯圃中观射作","f":"古风","c":["王侯腰悬铁裲裆，雕弧手挽五石强。","竦身注目捷风电，左射右射迥莫当。","大旆高牙矗云际，戈鋋甲胄纷飘扬。","观者如山尽辟易，九兕却走千夫僵。","岩呼谷应地汹涌，砂奔砾舞天苍茫。","羲和惨沮白日匿，飞星十道流扶桑。","一发旄头落，再发连双鸧。","三发定天山，筑城连受降。","连珠四五六，七八纷相将。","九发九日坠，百发百穿杨。","巧若甘蝇教飞卫，勇如养叔携潘尪。","雀儿只目讵足拟，牛心片胾差堪尝。","丈夫夙昔四方志，桑弧蓬矢悬高堂。","登坛仗钺挂金印，英风八面驰戎羌。","棱棱霜气辏羽筈，秋空俊鹘争翱翔。","吁嗟君侯绝技有如此，历数古来名将畴能双。","忆昔文成挽宗社，元勋茂烈标旂常。","河山带砺国同永，丹书奕叶传貂珰。","侯也登朝在髫丱，朱颜绿发骄琳琅。","昼摄衣冠扈銮辂，夜鸣刁斗驱龙骧。","临淮座上倏相值，轩轩霞举明朝阳。","骅骝騄駬讵凡骨，声华藉甚蜚天阊。","帝谓河漕实司命，九重特诏来淮阳。","艨艟巨舰载刍粟，旌旄络绎浮长江。","黄流徐沛忽中断，一麾立度千馀皇。","干城独坐镇寰宇，巍峨天堑雄金汤。","八年贡篚输上国，天子设燕开明堂。","安危华夏赖公等，张公神物真干将。","宝弓玉把帝三锡，雅称大白呈中黄。","太平无事罢征战，绿芜生戟苔沉枪。","酒酣耳热壮心发，唾壶击碎敧胡床。","矢锋贯虱总浮诞，弓弦落鸟徒誇张。","纵观侯射果殊绝，饮羽穿札谁低昂。","吁嗟侯技讵止此，弱龄海内传篇章。","词锋笔阵两挥霍，将坛文苑俱辉煌。","即今侯年但强仕，威棱烨烨传遐荒。","他时累叶事明圣，二十四考追汾阳。","麒麟第一镌姓氏，万年繁弱流芬芳。"]},{"t":"南都留赠谷元厚之并寄别文明玉吕静父长方至卿燕孺七子","f":"古风","c":["君不见燕昭王，高车大帛招贤良。","黄金台馆矗天际，乐生掉臂来华阳。","又不见渐离子，白眼酣歌竞睚眦。","囊无担石那复论，手拉荆卿誓生死。","豪华极目俱荒丘，萧萧易水长东流。","何人筑宫馆材杰，何人击筑追名流。","先生濩落沧海上，蒙茸七尺披羊裘。","虹霓为竿月为饵，六鳌夜掣珊瑚钩。","飧霞懒逐赤松卧，驭风屡学青莲游。","长鲸鳞鬣差快意，挥斥八极同浮沤。","狂来拍手惊帝座，失足偶堕天南头。","天南台殿四百八，金银观阙连神州。","一游一月不知返，胜槩欲尽仍淹留。","浮槎溯溟渤，泊宅凌沧洲。","名娃拥骏骑，调笑轻王侯。","遥遥去扬越，望望来燕幽。","长安富儿不解事，如山酒肉供俳优。","长裾不曳朝贵第，却来易水聊优游。","翩翩二仲巧相值，片言顿觉平生投。","雄心总向剧孟吐，侠节肯使朱家羞。","名园爽垲背北郭，粲烂珠帘护油幕。","轩窗屈曲萦莓苔，户牖周遭艺兰若。","炉烟澹宕逐挥洒，茗椀清泠恣斟酌。","绿尊翠杓春茫茫，指点明星月西落。","青丝挈盒游南郊，王蔡追随恣欢谑。","紫髯静父雅好文，风雅场中主画诺。","蹇驴夜入长安城，一粲徐卿手重握。","徐卿意气天下无，蚤排阊阖嬉皇都。","铁冠豸绣等长物，玩世暂逐金门徒。","陈生元方美冠玉，雕虫刻鹜酬操觚。","仓皇七贵招不得，为我日写秋山图。","钱塘散僧尚留发，孤山旧社追林逋。","滦州黄生年最少，担簦共入黄公垆。","一时衣袂把群彦，仰天被发歌呜呜。","起舞那知夕阳落，飞谈直遏行云徂。","呼卢覆局兴逾锐，淋漓身世随屠沽。","更长漏永列红烛，十千醪醴穷清壶。","人事纷纭百忧集，哀乐相乘岂终极。","别离忽动阳关愁，柳色青青遍畿邑。","丈夫耻学儿女颜，万里比邻叶金石。","吁嗟两生良好仇，为我分携泪沾臆。","君不见昭王台馆屹天际，衰草寒烟幕荒埭。","岂若胡生五亩宫，邺苑梁台遘明世。","又不见渐离击筑徒悲号，匣中一掷空铅刀。","岂若茅生把柔翰，峥嵘碣石攀吾曹。","即今尘霾暗四野，吾曹岂是蝇营者。","卧龙管乐畴贤愚，屠狗荆高并潇洒。","大河冰澌竹箭流，燕姬送客临高楼。","骊驹唱彻渭城畔，悲风万壑晨飕飗。","人生会晤邈河汉，功名何物真蜉蝣。","作歌郑重别二子，为我历讯诸同游。"]},{"t":"宋榻兰亭赵文敏临本真迹歌","f":"古风","c":["永和九年岁癸丑，典午衣冠尽南走。","临池崛起王右军，万古乾坤落书薮。","江东胜槩标兰亭，轩窗乱叠群山青。","流觞曲水修禊事，一樽随意酣沉冥。","道服逍遥坐亭子，认是当年会稽史。","寻山玩水不解愁，屡向人前誇乐死。","含毫是日如有神，飞天历历来仙真。","峥嵘只字启八法，快剑长戟劘星辰。","诸贤词翰尽压倒，兴公蛇足徒夭矫。","垂头大令甘罚觥，奕叶琅琊传至宝。","云礽智永历辨才，屋梁伏槛丛蒿莱。","文王百计命萧翼，逡巡玉匣沉泉台。","馀子纷纷竞摹勒，掌指烟煤半狼藉。","率更棐几抚硬黄，来世争传定武石。","胜朝妙迹仍浮屠，北禅老僧秘若无。","吴兴转乞独孤本，十三跋语题长途。","穷年两腕追步伐，牝牡骊黄较丝发。","双雕比翼翔太空，势极扶摇贯阊阖。","此?旧榻真宋前，五字未损湍流天。","奚潘墨沈俨如漆，澄心素札铺纯绵。","朅来燕市裹敝箧，瞥见寰中眼双热。","倾囊购得置案头，不减西方贝多叶。","龙盘凤翥何纷披，三百馀字字字飞。","乾坤万古但一帖，含毫落笔皆天机。","吴兴临本推冢嫡，中郎虎贲貌如壹。","谁哉帖尾联王羊，展卷狂呼胜和璧。","古今二绝偕遭逢，茅斋气色干长虹。","将无一夕雷电入，六丁下索还鸿濛。","沉吟却忆永和世，举代清谈误真际。","虚闻一统俪汉唐，大业三途骤凌替。","犹馀八法悬高旻，墨池滉漾雄千春。","汉文唐律遂鼎峙，至今免诮秦无人。","腐儒往往嗤小技，贤劫畴令重晋氏。","欧虞薛褚匪上乘，吴兴入室世无异。","一觞一咏乐奈何，醉来故帖重摩挲。","恍入山阴坐修竹，拍浮流水观群鹅。"]},{"t":"王元琳伯远帖真迹歌","f":"七言古诗","c":["自从兵入宣和殿，晋人真迹世罕见。","二王之外尤无闻，胡乃此帖传王珣。","四十二字斗奇绝，字字精芒射天阙。","萧疏逸宕转姿态，牝牡骊黄半明灭。","当年宣武称黑头，谁其大笔东亭侯。","至今江左仅兹帖，如椽恍忽存风流。","铮铮伯远隶书谱，妙迹宣和旷今古。","右军大令俱尘埃，灵光一柱犹蒿莱。","九百馀年秘云笈，暗中神鬼互呵斥。","何论宝玉与大弓，茅斋白日飞长虹。"]},{"t":"颜鲁公祭侄草歌","f":"七言古诗","c":["渔阳播乱飞黄尘，旄头月黑缠妖氛。","常清血战弃全陜，二十四郡虚无人。","平原鲁公眦双裂，一麾猛气雄三军。","疾呼河北倡忠义，普天率土知君臣。","帝心未灭安史祸，杲卿碎舌投天津。","巢倾卵覆季明死，举宗三百遭坑焚。","乌鸢饱食蝼蚁妒，毒痡四海同酸辛。","鲁公惋愤掩胔骼，哭兄哭侄嘘愁云。","生平正气塞宇宙，淋漓一帖犹千春。","乾元元年岁戊戌，昊苍有意开斯文。","摛章吮笔笔欲舞，墨池一派流天真。","肝肠寸寸委波磔，纵横䟤跋超群伦。","长风巨浪鼓淜澎，泰山乔岳盘嶙峋。","夭矫虬龙赴幽壑，缤纷鸾鹄翔高旻。","十行遒婉尚含怒，五行浡郁逾生嗔。","卒章沉痛彻心髓，恍疑汲冢窥三坟。","如椽一扫二百六，一言一字皆千钧。","即令涂抹迥姿态，西施倾国加双颦。","当时鲁公岂匠意，精诚烈烈悬风斤。","相传一草历元宋，太空磊落垂星辰。","二陈跋语差可玩，文家待诏弥津津。","鲜于困学传累世，即今妙迹来江濆。","凌晨揽诵竖毛发，斋头什袭藏家珍。","君臣大义贯星日，矧兹八法尤通神。","作歌郑重寄仰止，墨林万古飏清芬。"]},{"t":"米南宫误恩帖歌","f":"七言古诗","c":["张颠老死米颠出，好手中原斗狂逸。","南唐宝石作研山，三十六峰舞寒碧。","低头拜石石不语，袍笏蹒跚笑儿女。","一朝把换薛公鹤，泣向蟾蜍泪如雨。","兴来刷笔扫孤愤，十万材官破坚阵。","青城侠客挥剑锋，夜叉飞天云雾中。","宣尼常笑由也谚，颠也淋漓逞豪健。","此帖数字亦怒张，儿驹泛驾不可当。","五百年来米颠子，绝倒当年颠长史，钟王节制安事此。"]},{"t":"题李龙眠二十七祖图歌","f":"古风","c":["丹青国手吴道玄，眼空万古当开元。","沿流晚季六法尽，中兴十指传龙眠。","何人携此?，佛祖遍罗列。","马鸣众大士，历历具颠末。","袈裟挂膝右肩袒，妙相人天俨对越。","二十七祖仅九帧，十八应真徒耳闻。","云是吴侬利厚值，舆图剖析成三分。","朱门贵戚万与柳，募置斋头数各九。","兰阴措大?鼎足，尽典商彝鬻汉卣。","瓦棺寺壁画久亡，僧繇卫陆俱渺茫。","荆关递得山水趣，谁持大笔描空王。","参差绢素裂强半，鱼口横纹欲糜烂。","人言画理出唐世，远即楞伽近霭瓘。","即今宋代宁庸工，龙眠绘事真人龙。","诸天帝释尤冠绝，青狮白象行虚空。","阿难陀下九尊宿，一一披图认眉目。","或眠树底修四禅，或坐林中断五欲。","或拈圣果庵没罗，或把灵花给孤独。","或看涧壑浮清涟，或听岩峦坠飞瀑。","或从长爪證缘觉，或遇狞牙验调伏。","或开甘露广法门，了了根源绘身毒。","忆昔李侯盘礴时，胸中壮气横须弥。","大千世界摄毫翰，狂墨乱洒天迷离。","逡巡群祖真相出，虎头金粟争神奇。","惜哉贾竖巧垄断，吉光片羽犹分持。","复忆龙眠好画马，笔力曹韩较多寡。","骊黄注想马胎入，足堕泥犁若飘瓦。","以兹忏悔写佛门，丹青烨烨留乾坤。","香灯高阁互供养，天龙八部如云屯。","乃知古德真善诲，只语单词系成毁。","祇今名迹六百秋，夜夜光芒护神鬼。","二十七宗瞥眼过，东土祖师来达摩。","面壁形模竟何以，寰中试见龙眠李。"]},{"t":"题赵千里真逸图歌","f":"七言古诗","c":["吴郎示我真逸图，生绡半幅云雾裂。","高堂挂之夏六月，飒飒寒风堕林叶。","纵横乱瀑坠高崦，千峰万峰路明灭。","峰回路转天欲尽，似有孤亭架木末。","其下巨石盘长松，枫丹栗黄秋事浓。","松间讲易三两翁，秦时四皓须眉同。","一翁击阮一坐啸，其一恍似东园公。","斟酌兹图定谁笔，神品铮铮世无匹。","细看树石用勾法，人道王维字摩诘。","或言近出赵千里，往往抽毫弄金碧。","呜呼王赵不可作，纵复天工繄谁识。","须臾暝色来朱栏，耳边潏潏来飞泉。","吾将追逐黄与绮，坐占孤亭号角里。"]},{"t":"题李唐雪山游骑图歌","f":"七言古诗","c":["阴崖冻雪霾乱石，谁其画者李唐笔。","万仞寒山挂崒嵂，恍见当时大斧劈。","何人布裘裹竹笠，款段婆娑入高壁。","后有苍头挈双屐，太华路南望咫尺。","欲陟其巅叩拘翼，帝座罘罳俨呼吸。","十二琼楼众仙集，鹤氅缤纷互长揖。","白昼乘风绕八极，我欲从之路昏黑。","未满丹台谪来籍，策蹇言归故井邑，灞陵桥头句堪觅。"]},{"t":"题赵承旨野岸呼舟图歌","f":"七言古诗","c":["高堂飞瀑十丈寒，青山四面浮朱栏。","绕砌霜枫坠红叶，恍忽城居在林樾。","吴兴画手真杰特，人巧天工擅开辟。","细看此水与此石，非画五日即十日。","紫衣抱膝坐渡头，苍头弛担遥呼舟。","清溪万顷隔孤棹，隔崦人家落斜照。","山深树黑径险崎，石床天畔云迷离。","归樵谷口冉冉入，似有柴门挂苍壁。","标题轴尾了可寻，集贤学士孟頫临。","今古令人叹三绝，惜哉二字遭鼠齧。"]},{"t":"题黄公望西泠烟霭图歌","f":"古风","c":["大痴老人黄子久，涂抹丹青号名手。","名呼大痴画不痴，此图气韵尤淋漓。","危峰突起矗霄汉，迤逦横冈折层巘。","其下澄湖八万顷，金碧楼台挂天半。","芙蓉及菡萏，艳色何纷披。","恍如若耶溪，并浴千西施。","飞鸥明灭傍沙际，挟雌抱子群翔飞。","第六桥南入灵隐，此去南屏尚多景。","岳王墓倚金沙滩，竺色三天浮髻鬟。","隔崦人家夕阳落，破帽骑驴出东郭。","寻诗何处携丝桐，美人迟我飞来峰。"]},{"t":"题黄监柳塘禽鸟图歌","f":"七言古诗","c":["五朝画笔推黄荃，徐熙之后昌友前。","禽鱼花鸟落掌指，即今绘事仍流传。","十亩方塘浸寒碧，高柳繁阴弄斜日。","夹堤荷叶青连钱，翠盖亭亭万妆出。","蒹葭藻荇翻缟带，隐映清波漾盘石。","沙头浴鹭拳八九，石上双鸥俨相识。","鱼虾泼刺明镜中，迫视浑疑手可拾。","黄鹂紫燕语深树，点缀精神著颜色。","临池谁唤王右军，池头一白俱鹅群。","大鹅仰吭鸣向人，小鹅数十何纷纷。","天时淑风清气媚，野鹜家鸡各求配。","一雄前引众雌后，宿食飞鸣宛成队。","嗟嗟荃也得妙理，意匠经营入无始。","挥毫众羽倏生动，造化真机在十指。","尔时徐熙亦化工，两贤相阨悲途穷。","祗今无论黄监手，杂埒赵□□□□。"]},{"t":"双剑篇","f":"古风","c":["君不见新都司马公，手提三尺驱群雄。","文章落笔掩左马，出将入相称人龙。","又不见山东戚少保，结发从军事征讨。","高牙大纛海岱间，南北王庭净如扫。","两公文武真奇才，中原相遇神徘徊。","片言握手肝胆合，白日莽苍青冥开。","帝遣将军获精铁，铸作纯钩两奇绝。","一携自佩一赠公，绕夜虹光对明灭。","相逢则合离则分，雄飞雌逐流风霆。","合如双龙挂宇宙，离如独鹗横秋冥。","何来胡生客武林，蹑两芒屩登龙门。","长揖将军拜司马，瞥然睹此惊心魂。","蜃饰蛟装迥奇丽，土花半蚀芙蓉腻。","三秋太白横亘天，万丈银河寒压地。","飞霜喷雪魍魉愁，掣电扬飙神鬼避。","武林八月天茫茫，白波两岸飞钱塘。","天目东西八万仞，势压大海摩青苍。","此时双剑坐中合，神锋咫尺相低昂。","纵横壮气摄五岳，浩荡精魄回三光。","将军百战挺奇节，司马百代留馀芳。","丈夫树立固当尔，那令异物长潜藏。","君不见蒙庄周，平生说剑干诸侯。","穷来斗水不自觅，咄嗟文士真蜉蝣。","又不见淮阴侯，仗剑从戎追沐猴。","武士知几古来少，未央落日风飕飗。","岂若公遭明盛世，文武雄才更相济。","壮烈同标天地间，淳风直挽周秦际。","东海胡生不自量，蚤年侠气飘鱼肠。","长缨欲系玉门敌，寸管拟轶开元章。","只今三十尚碌碌，尔发胡短心胡长。","呜呼两钜公，绝代真罕有。","干将与莫邪，世世长共守。","灵物由来异人得，青萍讵落凡夫手。","笑杀狂生一蒯缑，歌罢无鱼厌奔走。","谓生且饮勿复言，天生七尺宁徒然。","剧孟曾倾亚父坐，侯芭亦受扬雄玄。","名山石室岂辽绝，会令大业流青编。","胡不为公一扫五千字，珠光照耀双龙泉。","渴病年来废书久，茂苑西风重搔首。","寂寞公孙剑器行，一代雄才我何有。","睹公神物心飞扬，醉墨淋漓忘妍丑。","篇成一笑还自歌，错落寒空堕牛斗。","倘勒丰城双玉函，万古雷张同不朽。"]},{"t":"蚤春苦雨邦相明府见过留饮斋中竟夕走笔放歌为今雨行并怀燕社诸子","f":"古风","c":["白龙夜挂钱塘渚，两岸嵯峨雪山起。","狂风忽捲大海流，散作东南万家雨。","兰阴一雨俄经旬，茅斋独卧愁晨昏。","剥啄何人驻高盖，传呼喻侯来扣门。","喻侯意气天下无，结交平生尽酒徒。","五载空淹茂陵秩，一官再问长安途。","忆乍停车瀫江涘，邂逅逢余誓生死。","片语平将白雪投，雄心真向青冥吐。","汝自分符出建章，余亦携书上帝乡。","掉头不入金华殿，却忆山中寻石羊。","风尘道路巧相值，宛转兰阴旧相识。","把臂宁论白璧双，酬知顿掷黄金百。","人间彩笔何纷纭，相看吾汝真忘形。","乍可经年对叔度，那能一饮无公荣。","蚤春人日差可赏，尘尾玄言豁尘坱。","轻云忽妒上元节，穷阴骤入花朝想。","衡门独掩空莓苔，白眼四望青天摧。","飞凫忽报故人至，拂衣大笑愁颜开。","曲径回轩迥幽寂，面面雕阑护奇石。","珠帘十二清昼垂，一尘不到胡生宅。","博山炉中沉水香，兰陵之酒双玉缸，蒲团对酌春茫茫。","居然一息破万古，那知雨色来虚堂。","漆园无人左迁没，屈宋曹刘俱寂寂。","千言欲起杜陵歌，四部重翻弇州集。","人生瞬息同埃尘，碌碌谁怜身后名。","日月空悬古今照，宇宙不补东南倾。","何如雄饮呼大白，百川一吸飞长鲸。","匕首纵横雪花乱，唾壶错落浮云惊。","酒间起舞真态出，元气淋漓袖双湿。","轻薄何由嗔祢衡，磊块政须浇阮籍。","高山流水尽知己，授简含毫仍促席。","沉冥不辞真宰怒，跌荡犹堪鬼神泣。","紫气丰城暝不流，寒芒婺女纷相射。","回首华阳夙昔交，十年侠气摩苍霄。","黎子归耕大庾侧，梁生草没罗浮坳。","刘侯李侯差振翮，朱生但乞夷门食。","康胡咫尺招不得，眼底何人寄肝膈。","吁嗟吾汝自一时，越吟楚调俱称奇。","飞扬总让少年贵，嚄唶从教行路疑。","邺侯满架差足乐，长孺淮阳岂云薄。","种秫聊耕彭泽田，草玄绝胜扬雄阁。","喻明府，歌莫悲，汝是豫章一男子，余亦岂俛首低眉世间士。","浮荣一代安所希，大业千秋竟谁俟。","丈夫会合自有神，肯将鸾翮随鸡群。","孙阳造父一朝值，騄駬骅骝双绝尘。","歌莫悲，喻明府，我欲乘云归太清，汝但为霖佐真主。","异日中原共鞭弭，肝肠一寸久相许。","漏尽银虬雨声歇，萧飒如闻二龙语。","为君作歌聊尔女，无论笔落惊风雨。"]},{"t":"折槛行送沈纯父北上","f":"古风","c":["北风动地捲霜雪，沈子严装候明发。","白马银鞍走燕市，天子召见黄金阙。","忆昔丁丑年中事，呜呼已往难陈说。","纲常万古忽如线，沈子旁观眦双裂。","三年忍蔑父母爱，七尺自与妻儿诀。","飞书一夜上明主，百辟苍皇胆俱慑。","宫闱动色问忠悃，乞得残躯傍南粤。","茫茫大海天欲尽，野魅山魈共生活。","铜柱频更伏波戍，铁衣乱洒羁臣血。","桄榔叶底托馀荫，豆蔻枝前赋鶗鴂。","鬓毛五载凋欲尽，意气千钧莽难折。","离骚熟读引斗酒，怒击青萍唾壶缺。","云雾朝披博罗顶，星斗夜摸空同峡。","归来笑拥绿衣女，卢橘杨梅照红颊。","朝云已去学士还，瘴雨蛮烟护荒碣。","精忠大节岂重睹，文藻风流颇颃颉。","乾纲一振壬午岁，地辟天开走狐孽。","徵书九道发燕邸，尽起龙干布朝列。","是时沈郎奉明诏，长啸扁舟返西浙。","逡巡故国拜丘垄，问寝高堂痛离阔。","县官日夜戒行李，驿使交驰讯车辙。","男儿肯作里中老，直臣更树台端节。","同时吴赵艾与邹，騄駬飞黄并腾踏，沈郎讵得终岩穴。","天上仙查溯河汉，腰下刀环耀明月。","扬鞭再过五陵豪，击筑重招蓟门侠。","蓟门楼殿花三千，尚记公车抱长铗。","对策明光亦草草，敝履短衣行䠥?。","中原邂逅吾共尔，白眼红颜寸衷合。","诵余连璧心已醉，示我郊居思横发。","苍茫大雪华阳街，拂袖徐生馆中别。","风尘倾盖古则有，宇宙论心近谁洽。","即今汝燕余复越，抗手胡能不悲咽。","沈伯子，酌汝蒲萄之美酒，系汝珊瑚之宝玦。","一言赠汝中自知，此去中外望掀揭。","儿童走卒尽道汝，凛凛刚肠石与铁。","腰金拖玉宁汝事，义胆忠肝岂虚设。","三公九列贵易保，万姓千秋口难辍。","重华尚纳大禹戒，仲甫亦补周王阙。","朝多善政禄可飧，事有当言槛仍折。","风云况遇大行日，努力群龙树勋业。","竹帛旂常两光绝，一旦抽身蚤林樾。","丈夫出处须伟烈，呜呼丈夫出处须伟烈，异日儒生秉鈇钺。"]},{"t":"长歌行送方翁恬游武夷","f":"楚辞体","c":["方生尧治太古孙，丘壑流风今尚存。","敝衣掣衿动见肘，负气不肯干豪门。","自言知交遍海宇，输肝伏胆惟三人。","新都汪伯玉，兴国吴明卿，里中胡元瑞，三子者，令我寤寐劳心魂。","丈夫壮志在不朽，要今竹帛垂乾坤。","升堂入室即先达，眼底穷通安足论。","忆汝前年走兴国，云梦潇湘眼双碧。","吴郎跳梁空一世，赠汝篇章朗奎壁。","忆汝去年入新都，司马文名天下无。","如椽立草处士传，坐令气色高菰蒲。","两公声誉冠天下，汝得璠玙重增价。","先生龌龊类楚囚，汝何所见何所求。","方生大笑笑余懒，惟我与公交不浅。","柴门相去十里强，溪上时时达鸡犬。","自君总角才已闻，我向何人不道君。","大苏小陆长在口，王后卢前讵足云。","曹刘李杜亦男子，见君敢谓秦无人。","君或未知我，我实深知君。","君也歌诗遍林樾，恍揭大吕悬云门。","珠玑万斛落謦欬，世人畴不攀青云。","胡为靳我无一字，如挟九鼎持千钧。","即今便欲武夷去，寸心耿耿当谁陈。","秋风布袍寒彻骨，愿得片语回阳春。","我闻生言亦大笑，过诚在我不在君。","不见杜陵赠端复，文章有道交有神。","家鸡野鹜种种好，大鹏斥鴳何疏亲。","醉中狂笔歌赠汝，朱弦白日飞梁尘。","忆生年少气横发，世世纶竿受家业。","学书学剑三十年，学得新诗动吴越。","青鞋半踏天竺雨，白纻全骄武林月。","我谓汝诗胜汝祖，汝得余言欲起舞。","先生片诺岂偶然，立榜余名在今古。","高堂飒沓来寒风，绕夜芙蓉电光吐。","干将莫邪自有灵，谁其拂拭华阴土。","呜呼穷鬼实伺人，五亩经营生计阻。","连年旱魃满山谷，赤日横天跨平陆。","十家九家鬻婴孺，生也宁免妻儿哭。","昼扪甑釜多游尘，晓摸瓶罂绝馀粟。","床头魍魉时揶揄，屋上鸺鹠多刺促。","任使喉端喙三尺，不博车前薪一束。","以兹欲作闽中游，幔亭峨峨天尽头。","云璈玉佩纷上界，铁船丹灶悬中流。","一遇灵仙蜕凡骨，脱弃妻子如蜉蝣。","先生较汝穷更甚，蹉跎四十谈封侯。","老亲稚子倏抛掷，一身宇宙如悬疣。","浮名鸡肋果何用，百年强半居穷愁。","作歌赠汝慰汝意，仰天长啸风飕飗。","三山九曲会寻汝，竹枝桂棹行夷犹。","武夷君兮倘相值，挟汝烂醉金银楼。"]},{"t":"二酉山房歌","f":"古风","c":["君不见昆崙高高阆风出其上，下视扶桑弱水相去几千丈。","傍开四百四十门，日月东西互相望。","传闻大酉小酉双名山，乃在昆崙阆风二岳之中间。","帝遣藏书号群玉，金庭石室森钩连。","白虹璀粲映缃帙，朱霞错落垂琅函。","自从轩辕来，窅绝殊人寰。","灵威丈人过，缩足不敢前。","成周穆满驱八骏，蹑电乘风到灵境。","岚深谷峭黯莫留，却携王母升蓬丘。","祖龙炎威扫六合，秦人留书闭空峡。","至今玉洞开桃花，仙源可望不可涉。","坑灰未冷汉社兴，大儿中垒小子云。","藜然天禄下真宰，烂漫七略罗天人。","阮家居士重蒐录，蠹简纵横委胸腹。","湘东再火一不留，七万瑶华烬荒簏。","聚书崛起开皇朝，缥囊璚笈摩丹霄。","累累三十七万卷，嘉则之殿高岧峣。","诸儒雠校汰冗杂，正本亦止三万饶。","开元八万最奇绝，往往玄珠出岩穴。","宋时群主竞好文，一日三诏何缤纷。","后来马郑诸子出，摩娑论列亦已勤。","好武遍中华，马上为生涯。","诗书匪故习，文具徒矜誇。","鸿荒重剖大明域，九曜含辉聚东壁。","天开地辟恢雄风，雾涌潢流映朝日。","吾乡文宪达最先，高文大册挥如椽。","青萝读书四十载，钻研法藏窥重玄。","云间子渊嗜缀辑，断简残萤映墙壁。","成都用修雅好奇，索摸科斗成嗔痴。","南阳陈卿负综博，一生惟折五鹿角。","北海冯君推殚精，歌谣委屑烦经营。","突兀琅琊起文苑，力挽颓风究坟典。","尔雅楼中四万轴，金石斋头五千卷。","须弥磅礴宛委深，吐纳宇宙横古今。","张王陆沉驱左席，何因物色来兰阴。","兰阴胡生负书癖，早逐刘郎卧岩石。","髫年已绝轩冕好，壮岁偏耽穷鬼力。","北走燕台东走吴，金陵闽越穷江湖。","僦居寄庑录馀烬，负薪织履偿追逋。","陆则惠施水米芾，昏黑忘眠昼忘食。","乍可休粮饿途路，讵肯空囊返乡国。","二十四庋罗山房，二千四万堆琳琅。","黔娄妻子困欲死，君山箧笥富可量。","上距羲农下昭代，触手牙签宛相待。","圣神贤哲穷吁谟，帝伯皇王罄元会。","一榻一几横疏寮，一琴一研祛烦嚣。","焚香独拥四部坐，南面王乐宁堪骄。","黎生八分称好手，夜宿山斋笑如斗。","纵观丘索盈前除，大叫狂呼题二酉。","琅琊作记当代传，姓名已睹琬琰悬。","触目伤心故交尽，却寻司马来新安。","司马心胸旷千古，夙昔图书探天府。","三坟二雅勤雕锼，一笈五车劳缀补。","太函峨峨云际开，恍入东观窥兰台。","众中誇我好玄者，撑肠拄腹谈天才。","寂寞萤窗守残雪，揽镜苍茫见华发。","声华岂必专穷愁，著述总知成灭裂。","侧身六合中自疑，异代乾坤未堪说。","感公国士知，肝肠为公竭。","幔亭十日饮，驱车复成别。","回看二酉山，崚嶒渺天末。","昆崙阆风定何处，弱水扶桑杳难越。","底似从公居太函，副墨煌煌恣翻阅。","君不见太函五城十二楼，金银城阙天尽头。","陶公八翼不得上，梯仙岂合凡人留。","孤帆且返越江涘，俛仰竹素聊优游。","异时四部读已尽，玄关或许停苍虬。","君不见兰阴下，瀫水流，轮囷古木枝相缪。","瓮牖绳枢闭荒径，荜门蓬巷悬清秋。","夜夜红光烛星斗，兀兀陈编柳生肘，短铗长檠竟何有。","醯鸡瓮里真自笑，蠹鱼架上安足友。","竺乾本来一物无，柱下青牛亦西走。","函中领取五千言，赤脚流沙寻二酉。"]},{"t":"白榆歌别司马汪公归婺中","f":"古风","c":["天上何所有，历历种白榆。","光辉烂绛阙，照灼青云衢。","白榆花开银汉傍，千枝万叶垂琳琅。","干拥西池翳若木，根盘东旭凌扶桑。","何来太乙精，骑龙游八荒。","折花戏阊阖，竦身朝紫皇。","帝命携青童，下界聊徜徉。","时维乙酉岁，元会呈嘉祥。","长虹百道飞紫阳，胃娄奎壁交寒芒。","巍然名世降空谷，九州四海垂文章。","文园消渴太史腐，宇宙何人策高步。","千秋再起司马公，鼎足中原共驰骛。","司马当年年甫髫，食牛吞虎心雄豪。","试宰乌伤动当宁，立驱五马行春郊。","蕞尔倭酋躏中国，流血膏原胔横隰。","九重拊髀思长城，大开幕府罗群英。","馀皇乱蹴沧海上，只手尽补天南倾。","伟哉司马文且武，左挈夔龙右方虎。","琅琊兄弟中颉颃，一字凭陵斗今古。","如椽大笔流风霆，落落迥与元化并。","差肩檀孟走公谷，扬班十辈无留行。","馀事为诗歌，格力尤矫绝。","宵驰历下军，神交大梁侠。","棱嶒健骨摩苍霄，烨如威凤升岧峣。","有时掉臂浣花宅，杜陵野夫不得骄。","岳岳龙门并真宰，却向溪头问兰茝。","怜才意气贯金石，下士声名亘湖海。","胡生双刺怀十年，姓名磨灭甘尘烟。","参差一泛洞庭棹，极目练水心茫然。","山阴乍夜雪三丈，立呼舴艋来新安。","新安山水何奇哉，巨石林立高厓摧。","奔流溅沫望不极，恍若吕梁悬水三十仞。","庐山之瀑，滟滪之流，砰訇触怒争喧豗。","长年捩舵不遑息，转入危滩势逾急。","穷幽历阻到梁下，翘首天都倚绝壁。","天都去天不盈尺，云门隐隐云气入。","两袖乘天风，苍茫踏云中。","举头见太函，疑是轩辕宫。","轩辕不肯谒，却谒司马公。","公也倒屣出，一笑心神融。","中厨饾丰膳，炰鳖羞黄熊。","玄谈叩无始，高论探鸿濛。","醉中吐豪气，四坐惊元龙。","不知天河落盏底，但见蓬莱旭日荏苒悬城东。","城东陌上春风来，十里五里桃花开。","飘然蓝舆扪崔嵬，红霞纷纷落绿苔。","明眸皓齿临高台，恍如瓢笠行天台。","吴生曼声振林木，谢生悬河笥充腹。","美人临邛得王四，豪士扶风见汪六。","曲江观涛病色扬，龙山落帽饶清狂。","山公倒著接䍦坐，相看一一俱高阳。","定瓷博山焚妙香，蒲萄之酿琥珀光。","大叫酣眠竹林下，下视六合天茫茫。","大白频挥不知数，斗酒宁论百篇富。","文章乍可穹壤齐，富贵真如草头露。","拂衣东望生离愁，我欲东归公苦留，为君且解青貂裘。","山灵入梦幽思发，单车竟作齐云游。","齐云巀嶪天尽头，何年赤县开神州。","蹊回谷转划然一窍透混沌，香炉紫烟缭绕五城十二昆崙丘。","憩公无量阁，宿公文昌楼。","羽人跨白鹿，道士骑青牛。","五老岩岩立霞际，环佩高翔隔尘世。","三姑亭亭若可招，蕙裳罗带长飘摇。","回瞻巨碣峙寥廓，科斗虫鱼籀文剥。","云是元封封禅碑，帝遣神书镇名岳。","朝辞白岳下，暮宿岩市溪。","如花六七辈，秉烛相招携。","华灯荧荧夹明月，笳鼓煌煌众星列。","忽看紫气屯关门，走卒儿童竞欢悦。","曳杖扶天孙，徘徊登幔亭。","周遭列岩岫，綵绘飞银屏。","观者盈道傍，叹息难具陈。","有如武夷君，挥手辞世人。","幔亭登乍毕，还寻上池室。","浮筏溯空明扬帆，弄春碧沙棠为楫。","绣幕悬金罂，玉瓶置我前。","百壶荡漾如流泉，翠眉蝉鬓纷婵娟。","觞行乐奏雷电作，回桡转向濠梁泊。","清沙锦石俨可数，细雨斜风亦不恶。","李姬拂袖拥高浪，赵女褰裙映林薄。","漫忆岑郎吟渼陂，欲效陈思赋河洛。","昏黑归来兴逾逸，玳瑁芙蓉众宾集。","红牙按拍催鸾笙，紫笋攒箫和龙笛。","痛饮淋漓将至石，主人留髡向西席。","吁嗟乎今晨何晨夕何夕，人生快意差已极。","乐极悲来将奈何，登山临水哀情多，倚风老泪双滂沱。","公为我楚舞，我为公越歌。","丰城两神物，会合长蹉跎。","眼前岁月东逝波，青青柳色明关河。","明发牵衣强余住，咫尺芳洲断春树。","欲行不行行且留，未忍匆匆别公去。","公不见琅琊布衣十日饮，琅琊之人渺何处。","当时太白配残月，此日中流仅孤柱。","何如片鹢飞严陵，生刍泂酌浇吴城。","白玉之楼缥缈孤悬大罗上，弇州之山五彩之鸟，八翼四足仰天矫首而长鸣。","定知精爽为公下，辎軿杂沓来秋冥。","旁观客有骑羊者，彷佛生平共杯斝。","如渑之酒迹已陈，此臂宁堪少年把。","俯仰乾坤但公在，磊落肝肠为公写。","已从孔祢申末契，底事桓文论兴谢。","愿作灵光千万年，白首同公白榆社。"]},{"t":"题赵相国斋头中天一柱图","f":"七言古诗","c":["老干凌空舞秋色，大泽龙蛇耸千尺。","何年夸父移昆崙，撑拄东南半天碧。","画师名姓闻国初，郭熙远裔留荆吴。","平生画松三百本，此图卓荦传皇都。","丈八桑皮白云蓊，落墨含毫势生动。","恍忽秦时大夫五，其一飞来挂高栋。","崚崚皱鬣横崔嵬，霜皮何止四十围。","绝壁孤悬蔽岩岫，太空直上挐云雷。","松下为谁独箕踞，白眼科头坐深树。","迥疑叔夜挥五弦，目送飞鸿暮来去。","毕宏韦偃纷难俦，生枝秃蘖惊凡流。","笑杀杜陵褐衣破，拮据绢素摹青虬。","黄扉元老真柱石，落落岩廊为时出。","朝端祇服公旦勤，海内浑忘帝尧力。","念年怀山归梦长，一朝睹此神扬扬。","纵横丽句洒胸臆，如椽巨笔垂琳琅。","回望兰阴旧松径，几欲乘风赴清荫。","畴当大厦庇寒饥，孰向明堂佐神圣。","踟蹰且阅三万秋，蟠桃岁岁红丹丘。","八蛮顿颡九土服，剡溪却泛鸱夷舟。","巀嵲芙蓉乱峰紫，涌雪餐霞伴周史。","无劳辟谷追前人，自是重来赤松子。"]},{"t":"赵侯汝申以学术兴起一方怜才下善阖邑推其长者兹以七贤图属余赋之倘亦有王阮忘年之意乎敬题短歌","f":"七言古诗","c":["赵侯款我城南屋，堂上高悬画一幅。","是时六月凉飙生，万个琅玕照新筑。","衣冠不类河朔豪，船舫曾非剡溪曲。","细看乃是晋诸贤，醉倚长林弄修竹。","疏枝的皪横潇湘，密叶珑葱卷淇澳。","珠帘粉阁坐相对，尽日明窗看不足。","彷佛当时六七公，持螯白眼横霜空。","脱巾露顶挂石壁，仰天大笑来清风。","匆匆典午事难说，烟尘澒洞盈寰中。","此时不醉欲何事，眼看浮世真虚空。","步兵睨树啸声发，浚仲清言宛如屑。","子期鼓鞲仍著书，伶也携壶更荷锸。","阮生拨阮嵇生弦，目送飞鸿游太玄。","就中山公最长者，百觚在手情颓然。","南阳赵侯世希有，满腹珠玑贯牛斗。","偷桃偶堕方朔缘，谪向人间卧岩薮。","生平饮酒但数巡，座中宾客长千人。","何人把赠周昉画，跃然对我融心神。","胡生晚得酒中趣，跋扈飞扬有深意。","一朝睹此形貌亲，恍若诸贤把余臂。","为君作歌还赠君，生绡落笔飞玄云。","何时买断筼筜谷，共作林中避世人。"]},{"t":"偃卧俞公临榻上戏题","f":"七言律诗","c":["俞郎一榻长安市，破衲蒙茸裹布被。","狂来坦腹呼元龙，蹴蹋星辰动天地。","华胥国小安足游，君家赤舄双琳球。","大鹏希有俨相值，飞行八极眠琼楼。"]},{"t":"西山十咏同陈沈二太史黎秘书杨祠部丘计部李环卫朱光禄安茂才童康邓朱四山人作 其一 晚至碧云寺","f":"五言律诗","c":["梵刹金银布，花香绕碧栏。","断崖交桧柏，飞瀑洒琅玕。","霞起天台暮，云生岳麓寒。","钟声似迎客，时出远林端。"]},{"t":"西山十咏同陈沈二太史黎秘书杨祠部丘计部李环卫朱光禄安茂才童康邓朱四山人作 其二 香山寺饭初上人禅院","f":"五言律诗","c":["梵阁千寻起，雕坛一径斜。","僧归迷翠巘，客至扫青霞。","竹里分香积，松间转法华。","遥看层砌上，缥缈堕天花。"]},{"t":"西山十咏同陈沈二太史黎秘书杨祠部丘计部李环卫朱光禄安茂才童康邓朱四山人作 其三 玉泉","f":"五言律诗","c":["飞流望不极，缥缈挂长川。","天际银河落，峰头玉井莲。","波光迥太液，云气引甘泉。","更上遗宫顶，千林起夕烟。"]},{"t":"西山十咏同陈沈二太史黎秘书杨祠部丘计部李环卫朱光禄安茂才童康邓朱四山人作 其四 功德寺望景陵","f":"五言律诗","c":["宣皇游幸日，千骑转晴沙。","殿绕骊山树，窗开绣岭花。","星辰留御辇，云雾锁仙槎。","北望龙蟠气，飘飘想翠华。"]},{"t":"西山十咏同陈沈二太史黎秘书杨祠部丘计部李环卫朱光禄安茂才童康邓朱四山人作 其五 登碧霞宫阁","f":"五言律诗","c":["槛立孤峰上，窗开万岭西。","霞光流紫极，日影抱丹梯。","绮树三春长，金芝五色齐。","蓬莱宫殿里，笙鹤旧曾携。"]},{"t":"西山十咏同陈沈二太史黎秘书杨祠部丘计部李环卫朱光禄安茂才童康邓朱四山人作 其六 玄贞观","f":"五言律诗","c":["万山苍翠合，流水晚潇潇。","雾里瑶台出，云中绛节朝。","桃花开绝涧，松影落层霄。","时听群仙度，天风引玉箫。"]},{"t":"西山十咏同陈沈二太史黎秘书杨祠部丘计部李环卫朱光禄安茂才童康邓朱四山人作 其七 秋日同诸子登望湖亭","f":"五言律诗","c":["殿隐芙蓉外，亭开薜荔中。","山光寒带雨，湖色净连空。","作赋携词客，行歌伴钓翁。","夕阳沙浦远，北雁起秋风。"]},{"t":"西山十咏同陈沈二太史黎秘书杨祠部丘计部李环卫朱光禄安茂才童康邓朱四山人作 其八 小憩圆通寺题","f":"五言律诗","c":["说法闻初地，题名到上方。","砌幽松子落，林远叶声长。","夜雪飘山磬，秋云洒石床。","坐来千嶂里，岚翠满衣裳。"]},{"t":"西山十咏同陈沈二太史黎秘书杨祠部丘计部李环卫朱光禄安茂才童康邓朱四山人作 其九 洪光寺听真上人诵经作","f":"五言律诗","c":["地入空王宇，山藏释子筵。","白云流五岳，青壁俯诸天。","象外烟花丽，空中色界悬。","为将忘世念，一诵法华篇。"]},{"t":"西山十咏同陈沈二太史黎秘书杨祠部丘计部李环卫朱光禄安茂才童康邓朱四山人作 其十 宿翠岩寺","f":"五言律诗","c":["晨风遥策杖，夕露几沾衣。","礼佛青山塔，逢僧白石扉。","悬萝山鸟集，亚竹水萤飞。","为爱西窗宿，泉声出翠微。"]},{"t":"仲秋同祝鸣皋诸文学再游西山得诗四首天 其一 寿山谒诸陵","f":"五言律诗","c":["紫殿衣冠肃，玄宫剑玺遥。","天回群后集，地迥百灵朝。","文字垂羲画，声歌咽帝韶。","万年沾洒处，寒雨动青霄。"]},{"t":"仲秋同祝鸣皋诸文学再游西山得诗四首天 其二 湖上","f":"五言律诗","c":["积水湖天合，泠泠帝阙西。","逶迤云色净，掩映日华低。","凤吹临高岸，龙舟出大堤。","桃花源咫尺，洞口夕闻鸡。"]},{"t":"仲秋同祝鸣皋诸文学再游西山得诗四首天 其三 游玄真观","f":"五言律诗","c":["积翠三天迥，飞梁百尺横。","星河浮玉砌，云雾揽金茎。","羽客青泥饭，仙人赤石英。","何年生羽翼，尘外访蓬瀛。"]},{"t":"仲秋同祝鸣皋诸文学再游西山得诗四首天 其四 携尊翠微阁晚坐","f":"五言律诗","c":["振锡千林暮，移尊片月秋。","不辞青嶂远，聊共白云游。","洗钵花台静，悬灯竹径幽。","朝来挈小朗，乞食向牛头。"]},{"t":"答李惟寅病中见寄","f":"五言律诗","c":["岂是趋朝懒，风尘损壮颜。","闭门芳草合，高枕白云闲。","柳色溪南棹，莺声郭外山。","遥怜作赋客，魂梦屡跻扳。"]},{"t":"题朱山人汝修卷","f":"五言律诗","c":["石磴烟云起，仙源费独寻。","碧山玄晏宅，沧海尚平心。","岁月留斑管，阳春抱玉琴。","几年嵩洛思，倏尔一开襟。"]},{"t":"丘谦之招游崇善寺分得云字","f":"五言律诗","c":["竹院名香起，花台积翠分。","双松寒挂雪，一榻晚生云。","画想沧洲迹，经传白马文。","平生许玄度，何事恋人群。"]},{"t":"康裕卿山人移居","f":"五言律诗","c":["燃桂生涯尽，飞蓬旅迹多。","地偏馀水石，乡远隔关河。","夜帐悲猿鹤，春山怨薜萝。","萧条剡溪宅，风雪近谁过。"]},{"t":"送人还秣陵","f":"五言律诗","c":["献书辞北阙，仗剑出西京。","落日沧江远，孤帆万里征。","烟霞淮口寺，风雨石头城。","别后相思处，关山候雁鸣。"]},{"t":"春日送人之剑南二首 其一","f":"五言律诗","c":["大泽冰初解，长途雪正晴。","孤帆送尔去，千里独含情。","竹翳湘妃馆，花明蜀帝城。","当垆人好在，不浅旧逢迎。"]},{"t":"春日送人之剑南二首 其二","f":"五言律诗","c":["蜀道难犹乍，湘潭去若何。","青天浮滟滪，白雪涌岷峨。","宅问扬雄隐，堂携杜甫过。","锦官城外路，翠柏几婆娑。"]},{"t":"送吴广文之岭南","f":"五言律诗","c":["寂寞青毡地，何当事远游。","问人还剑浦，寻雪上罗浮。","海岸飞花尽，蛮天落木愁。","粤台时眺览，万里见高秋。"]},{"t":"渡江望金陵宫阙四首 其一","f":"五言律诗","c":["望望吴天迥，遥遥越客来。","万山京口立，孤舶海门开。","蜃噏风雷起，龙吟日月回。","凤城回首处，佳气满蓬莱。"]},{"t":"渡江望金陵宫阙四首 其二","f":"五言律诗","c":["上国堪萍梗，长江动旅愁。","天浮扬子树，日照广陵舟。","驾浪鼋鼍语，飞空蜃鳄游。","五云看咫尺，台殿拥神州。"]},{"t":"渡江望金陵宫阙四首 其三","f":"五言律诗","c":["绀宇三山近，皇畿万堞遥。","云藏佳丽国，地拱圣明朝。","玉辇扶双凤，金瓯奠六鳌。","秦淮今夜月，愁倚木兰桡。"]},{"t":"渡江望金陵宫阙四首 其四","f":"五言律诗","c":["摇落江天上，秋风度李膺。","来槎真汗漫，击楫岂飞腾。","紫气扶天阙，明霞拱孝陵。","钟山旧游地，梦绕白云层。"]},{"t":"金山","f":"五言律诗","c":["兀立江心寺，芙蓉万古看。","孤峰留杖锡，绝峤锁阑干。","碧涌高天浪，青浮大海澜。","妙高台上客，日暮转盘桓。"]},{"t":"焦山","f":"五言律诗","c":["何年云雾里，卧此少微星。","地拥幽人宅，天藏处士灵。","一峰齐北固，双井象中泠。","向暮风涛起，谁寻瘗鹤铭。"]},{"t":"夜同裕卿话旧","f":"五言律诗","c":["万里相逢日，那能不黯然。","移家当暮雪，行乞傍寒烟。","赋岂三都后，心犹五岳前。","向来溪水曲，频系子猷船。"]},{"t":"答文父见怀之作","f":"五言律诗","c":["不见江西客，相望鬓欲丝。","十年沧海梦，千里碧云思。","寥廓南华论，飞扬左尉辞。","但令龙剑合，那复问雄雌。"]},{"t":"红云坞","f":"五言律诗","c":["几夜瑶台上，移来十亩春。","笼烟千树密，照水万花新。","环佩堪留阮，衣冠不避秦。","扁舟如可再，长此谢迷津。"]},{"t":"病中文父过访兼携近作见示二首 其一","f":"五言律诗","c":["岂谓伊人至，能令倦客狂。","千秋谁陆谢，一径且求羊。","夜色青藜短，秋声白苧长。","朝来还奏赋，不拟步长杨。"]},{"t":"病中文父过访兼携近作见示二首 其二","f":"五言律诗","c":["遥遥风雪里，对语欲忘眠。","尔擅游梁赋，余惭入洛年。","天浮鳷鹊影，城绕凤凰烟。","何限金茎色，相期汉苑前。"]},{"t":"闻大参滕公擢任岭南有寄二首 其一","f":"五言律诗","c":["鼓角炎荒外，旌旗大海傍。","九霄悬宠渥，万里倚翱翔。","郡古罗浮雪，天空粤峤霜。","祗因将雨露，沾洒尽扶桑。"]},{"t":"闻大参滕公擢任岭南有寄二首 其二","f":"五言律诗","c":["五岭看乘传，千峰引佩刀。","春随南极迥，云拥太微高。","雾鳄先移瘴，溟鲸已息涛。","独怜吴越士，泪满别时袍。"]},{"t":"送刘从事之成都","f":"五言律诗","c":["翩翩游客旆，去指蜀门斜。","夜宿巫山雨，朝行剑阁霞。","古碑丞相庙，蔓草拾遗家。","驲路留题满，频将寄海涯。"]},{"t":"寄沈山人嘉则二首 其一","f":"五言律诗","c":["异代看黄绮，明时更许巢。","乾坤长作客，湖海半论交。","卧忆鲲鹏起，吟从蝘蜒嘲。","玄亭奇字遍，吾梦亦衡茅。"]},{"t":"寄沈山人嘉则二首 其二","f":"五言律诗","c":["四海闻高适，中林得阮咸。","岳云依短屐，山雪洒长镵。","梦断真千里，书空漫百函。","何当明月夜，一试剡溪帆。"]},{"t":"寄李本宁督学二首 其一","f":"五言律诗","c":["自失华阳社，长怀渭水滨。","传闻秦博士，犹借汉词臣。","弦诵千花色，襜帷万柳尘。","若过中垒宅，藜火定谁亲。"]},{"t":"寄李本宁督学二首 其二","f":"五言律诗","c":["闻道三秦使，烟花夹道看。","天高扪太华，日近倚长安。","散吏趋经幄，诸生侍讲坛。","上林应有赋，时寄五云端。"]},{"t":"寄汪仲淹伯仲","f":"五言律诗","c":["二仲何为者，翩翩邺下流。","白云裁楚服，明月揽吴钩。","并握扬雄草，长陪谢傅游。","碧山空咫尺，魂梦使人愁。"]},{"t":"寄汪献于","f":"五言律诗","c":["自返金陵客，何方定卜居。","七哀应著咏，孤愤蚤成书。","卧榻芙蓉在，衡门薜荔馀。","碧云怀望久，一怅剡溪鱼。"]},{"t":"过吴门不及访弇州王公寄怀十首 其一","f":"五言律诗","c":["屈指中原业，谁登大将台。","千秋王粲起，一代子长来。","日远龙楼梦，天留兔苑才。","吴阊云雾里，相望首重回。"]},{"t":"过吴门不及访弇州王公寄怀十首 其二","f":"五言律诗","c":["逸驾开元上，雄风正始邻。","云霄谁北斗，天地此阳春。","作赋三都客，传诗四海人。","未应双剑老，雷电起延津。"]},{"t":"过吴门不及访弇州王公寄怀十首 其三","f":"五言律诗","c":["谕蜀传司马，还吴忆士龙。","万峰吟薜荔，一径把芙蓉。","月落干将倚，云飘太乙从。","异时成握手，白眼坐高舂。"]},{"t":"过吴门不及访弇州王公寄怀十首 其四","f":"五言律诗","c":["渺邈违芝宇，风流忆草堂。","蓝田聊卜筑，绿野暂浮觞。","日避长庚色，天回大酉藏。","十年翘首地，葭菼倍苍苍。"]},{"t":"过吴门不及访弇州王公寄怀十首 其五","f":"五言律诗","c":["虎观才俱屈，鸡林望转高。","千言无彩笔，片诺有绨袍。","梦隔蓬丘树，吟残阆苑桃。","何年携手遂，相对咏离骚。"]},{"t":"过吴门不及访弇州王公寄怀十首 其六","f":"五言律诗","c":["曳杖辞三岛，投簪傍五湖。","九丘穷倚相，片语失潜夫。","鹤唳天门远，鹏抟海色孤。","近来秋兴剧，散发卧菰芦。"]},{"t":"过吴门不及访弇州王公寄怀十首 其七","f":"五言律诗","c":["日月回真想，乾坤入梦游。","晓风吴苑屐，寒雨石湖舟。","匣底双龙卧，毫端万象愁。","亦知三径好，咫尺负羊求。"]},{"t":"过吴门不及访弇州王公寄怀十首 其八","f":"五言律诗","c":["贝锦看如昨，牛衣卧转深。","洞庭寒濯足，林屋远论心。","落日天边气，浮云海上吟。","吴王台北望，作者自如林。"]},{"t":"过吴门不及访弇州王公寄怀十首 其九","f":"五言律诗","c":["此日云门笠，平生汉殿冠。","一时谁把袂，万古独登坛。","岳色崆峒晓，河流砥柱寒。","尚思燕北社，风雨动长安。"]},{"t":"过吴门不及访弇州王公寄怀十首 其十","f":"五言律诗","c":["帝惜悬车蚤，人看杖钺雄。","青山郧子国，白雪楚王宫。","杜甫名差著，灵均曲未工。","岘台遗迹在，千古擅流风。"]},{"t":"寄张茂才","f":"五言律诗","c":["闻道安仁鬓，秋风半欲华。","青囊犹隐市，白帢屡移家。","竺色三天雨，湖光万岫霞。","绝怜挥袂日，相对武林花。"]},{"t":"赠颙上人","f":"五言律诗","c":["几岁游天姥，经秋住越台。","万山灵隐锡，斜日海门杯。","出定逢花雨，传灯悟劫灰。","何因偕尔去，结宇卧飞来。"]},{"t":"送周少参督饷还楚","f":"五言律诗","c":["万舸通淮泗，双旌傍海涯。","筹边王相国，经世贾长沙。","雾拥春皋佩，云停野庙花。","遥看下车日，题咏遍章华。"]},{"t":"哭童山人子鸣二首 其一","f":"五言律诗","c":["海岳谁高蹈，丘园有独醒。","下帷头自白，避俗眼长青。","日惨延州碣，风寒郑圃灵。","夜台人近远，徙倚少微星。"]},{"t":"哭童山人子鸣二首 其二","f":"五言律诗","c":["石户真高隐，云卿此后先。","一家犹紫阁，万恨已黄泉。","禅岳无遗草，藏山有太玄。","向来携手地，悽绝子期弦。"]},{"t":"寄戚总戎","f":"五言律诗","c":["闻道嫖姚将，提兵大漠间。","旌旗行汉壁，鼓吹出秦关。","白日双雕下，黄云万骑闲。","时同投笔吏，乘胜过天山。"]},{"t":"怀欧桢伯博士","f":"五言律诗","c":["藉甚中原誉，浮沈异代踪。","青衿聊宦辙，绛帐自儒宗。","冷日华阳筑，高天汉殿钟。","祗园春草外，犹记昔相逢。"]},{"t":"送王山人游秦中","f":"五言律诗","c":["斗酒山城暮，东风怅别离。","天青游华日，地紫入关时。","博望千年苑，昆明万古池。","平生飞动兴，合遣杖藜知。"]},{"t":"送张茂才北上","f":"五言律诗","c":["烨烨张公子，乘轺意气新。","万言看谒帝，千里独宁亲。","柳折长安暮，花吟太液春。","寄言关外吏，能识弃繻人。"]},{"t":"夏日同诸子宴郭鸿胪池亭分韵得凉字","f":"五言律诗","c":["背日山堂午，含风石径凉。","閒来松桂下，各把芰荷觞。","地称南州隐，天容北海狂。","坐深渔唱发，白眼对沧浪。"]},{"t":"寄徐大参","f":"五言律诗","c":["西署初迥辙，南天复拥符。","飞刍传九塞，转饷出三吴。","海色摇冠佩，江云照舳舻。","不堪携手梦，明月洞庭孤。"]},{"t":"秋日送陈山人还江右赋得庐山瀑布水","f":"五言律诗","c":["万丈庐山瀑，经行照客衣。","昼看银海立，晴望玉虹飞。","激浪回丹壑，分流出翠微。","凭谁唤匡续，一酌共忘机。"]},{"t":"寄方山人","f":"五言律诗","c":["忆尔辞家久，秋高客况增。","帆当鄱水挂，屐遍楚山登。","夜宿随沙鸟，朝吟伴岳僧。","九疑风雪外，何处吊黄陵。"]},{"t":"送艾都阃督饷淮上","f":"五言律诗","c":["九边刍挽急，飞将岂辞劳。","独坐黄龙舸，长驱白鹭涛。","江花明绣箙，海日拥征袍。","横槊风流在，遥天伫彩毫。"]},{"t":"赠弘上人","f":"五言律诗","c":["昔事崔罗什，今逢帛道猷。","存思驯象下，漱齿毒龙愁。","衲绽三天雪，杯悬万里流。","吴中四百寺，烟雨遍曾游。"]},{"t":"送天台二僧还西域","f":"五言律诗","c":["挂锡同霞峤，归帆并海涯。","云侵秦碛远，路转蜀台斜。","翠竹空中相，青莲定里花。","谁知双大士，持钵渡流沙。"]},{"t":"奉寄王江州六首 其一","f":"五言律诗","c":["绝胜匡庐郡，分曹暂岁年。","高牙三楚外，巨舳九江前。","日抱香炉上，天齐瀑布悬。","东林秋咫尺，一问远公禅。"]},{"t":"奉寄王江州六首 其二","f":"五言律诗","c":["棨戟开雄镇，旌旗列上游。","猿声千嶂色，雁影万峰秋。","散怢聊公事，褰帷即胜游。","祗应明月夜，长啸庾公楼。"]},{"t":"奉寄王江州六首 其三","f":"五言律诗","c":["岂为干城驻，能将一壑专。","郡僚携白傅，地主借青莲。","岳色含杯堕，江流卧榻悬。","转看牛斗近，双照莫耶前。"]},{"t":"奉寄王江州六首 其四","f":"五言律诗","c":["极目登高处，淹留汉大夫。","万家南斗近，千里北辰孤。","虎豹分流徙，鱼龙夹岸呼。","可容王勃赋，今古擅洪都。"]},{"t":"奉寄王江州六首 其五","f":"五言律诗","c":["但觉官曹胜，宁知吏牍饶。","白云匡岭树，红日海门潮。","酒送陶公醉，诗酬谢客招。","那能望乡日，不过虎溪桥。"]},{"t":"奉寄王江州六首 其六","f":"五言律诗","c":["飞动征西节，分违蓟北盟。","词人空碣石，才子暂江城。","綵笔千秋价，绨袍一代情。","向来挥手地，忍忆去帆平。"]},{"t":"寄华亭吴少府","f":"五言律诗","c":["伊昔回车日，囊空但一钱。","乞身三泖地，垂泪五湖天。","养鹤重开径，烹鲈独扣舷。","茂陵余亦病，忆尔思茫然。"]},{"t":"题松","f":"五言律诗","c":["离离摇碧涧，落落俯苍郊。","拔地虬龙偃，中天鹳鹤巢。","涛声寒月上，野色乱云交。","寂寞徂徕顶，秦封只浪嘲。"]},{"t":"徐方伯子与将之江右过访有赠二首 其一","f":"五言律诗","c":["岂谓看山地，能令结驷来。","人非中散卧，客是伟长才。","把袂淹萝薜，行觞藉草莱。","夜中占紫气，云拥豫章台。"]},{"t":"徐方伯子与将之江右过访有赠二首 其二","f":"五言律诗","c":["弭节过严濑，褰帷问楚皋。","北风千骑发，南斗片鸿高。","抚字声先著，登临思独豪。","万年滕阁赋，行矣待抽毫。"]},{"t":"送寿山人","f":"五言律诗","c":["飘然沧海客，曾事紫阳君。","袖里黄庭字，囊中赤伏文。","放舲三泖月，携杖九峰云。","后夜华亭梦，应同鹤唳闻。"]},{"t":"寄李季宣二首 其一","f":"五言律诗","c":["盖忆曾倾地，樯移远别年。","千花淮浦浪，独树海门烟。","白苧吴郎曲，青娥楚客筵。","广陵桥上月，相望几婵娟。"]},{"t":"寄李季宣二首 其二","f":"五言律诗","c":["最忆真州夜，临岐解鹔鹴。","江风停去鹢，海月伴离装。","柳谢君平曲，花饶杜牧狂。","吴姬三百辈，若个擅平康。"]},{"t":"徐铨部过访不值二首 其一","f":"五言律诗","c":["何因丛桂下，驷马值仙郎。","日驻金珂影，星流玉剑光。","登龙馀顾盼，题凤愧行藏。","伫听东山起，含香入建章。"]},{"t":"徐铨部过访不值二首 其二","f":"五言律诗","c":["传呼鸾掖吏，来访鹿门樵。","曲径俄双屐，空山祗一瓢。","白云寒自倚，紫气暮谁招。","好去蓬莱殿，千花待汉轺。"]},{"t":"游横山庵","f":"五言律诗","c":["白马何年到，名山敞梵筵。","坛空诸佛下，洞古一僧禅。","钵与龙俱卧，灯将虎并传。","真如祗自得，谁为问青莲。"]},{"t":"寄陆太史敬承二首 其一","f":"五言律诗","c":["濩落吾能返，飞腾尔故频。","自为三馆客，谁共五陵春。","白日流金掌，红云护玉宸。","故园芳草外，曾否念垂纶。"]},{"t":"寄陆太史敬承二首 其二","f":"五言律诗","c":["尔作承明客，吾归已判年。","花香鸾掖底，柳色凤池前。","醉任眠中秘，閒仍草太玄。","燕姬无限好，犹记琵琶弦。"]},{"t":"哭唐太常二首 其一","f":"五言律诗","c":["乍辍金华讲，长投海岸簪。","中涓谁冀北，太史竟周南。","襚道黄泉启，关门紫气含。","平生携手客，泪尽百花潭。"]},{"t":"哭唐太常二首 其二","f":"五言律诗","c":["袛谓焚鱼卧，真成跨鹤游。","千秋谁挂剑，万事已藏舟。","夜壑星辰远，重泉日月愁。","独将知己泪，恸哭洒西州。"]},{"t":"送王大行使岭外","f":"五言律诗","c":["迢递双旌色，朝行大海东。","天垂鹏翼尽，日照蜃楼空。","玉节诸番卫，金函万国同。","归来铜柱畔，题赋尉陀宫。"]},{"t":"荅汪茂才","f":"五言律诗","c":["尺素天俱远，芳尊日暂同。","自怀和氏璧，谁问楚王弓。","昼卧苍龙偃，宵谈白马雄。","青云太史在，宁复念途穷。"]},{"t":"夏日同诸子登望衢亭作呈赵明府","f":"五言律诗","c":["剧兴真飞动，层台半斗牛。","天空疑不夏，地迥欲生秋。","峡色双龙抱，山形万马留。","异时怀赋客，吾岂仲宣俦。"]},{"t":"李生西游久不得问因寄","f":"五言律诗","c":["西游去何日，念尔独离群。","履绽秦山雪，筇飞蜀岭云。","乡心寒狖落，客思夜鸿闻。","记取岷中事，南归报右军。"]},{"t":"送赵太史之岭南五首 其一","f":"五言律诗","c":["一麾辞禁阙，万里赴长沙。","地入蛮王垒，天浮汉使槎。","乱山梅岭树，绝徼夜郎花。","永夜罗浮顶，谁同眺日华。"]},{"t":"送赵太史之岭南五首 其二","f":"五言律诗","c":["贾傅章才上，王褒命已传。","飞霜随剑舄，大海傍楼船。","客梦梅花里，乡谣桂酒前。","坐看公府暇，白雪满南天。"]},{"t":"送赵太史之岭南五首 其三","f":"五言律诗","c":["献纳纡青琐，驱驰恋紫宸。","珠厓百蛮路，铜柱九夷春。","郡邑横天起，旌旗截海陈。","祗应宣室夜，万里召孤臣。"]},{"t":"送赵太史之岭南五首 其四","f":"五言律诗","c":["豸服层霄下，麟符夹道光。","万峰行瘴色，独马度炎荒。","暮雪秦关拥，春城粤海长。","转将金掌露，移洒向扶桑。"]},{"t":"送赵太史之岭南五首 其五","f":"五言律诗","c":["暂辍兰台讲，言乘桂水桡。","牙旌驰绝域，绣斧出中朝。","瘴压高凉晚，山通大宛遥。","莫嫌文字癖，干羽遍三苗。"]},{"t":"送何山人游边","f":"五言律诗","c":["悠然尊酒别，秣马问渔阳。","汉碛连天紫，边沙拥日黄。","列营随骠骑，分险驻龙骧。","会挟金城策，长缨请建章。"]},{"t":"送人还桐庐","f":"五言律诗","c":["不远桐江路，归帆候月牵。","赤霞晨际海，青壁午连天。","鸟道从人问，猿声傍客悬。","钓台千尺倚，谁伴子陵眠。"]},{"t":"送人入蜀","f":"五言律诗","c":["客畏蚕丛路，君仍驷马过。","白波三峡满，青嶂九疑多。","绝栈移旌节，层台梦绮罗。","海棠花在眼，烂漫倚高歌。"]},{"t":"秋晚灵隐寺小憩","f":"五言律诗","c":["咫尺东林寺，栏干不厌凭。","万山回卓锡，一水护传灯。","梵室偕龙树，经坛接惠能。","上方钟磬发，晚傍白云登。"]},{"t":"送李逸人西游","f":"五言律诗","c":["一骑西游远，双鸿北望饶。","雪深眠太白，云起问中条。","汉碛名偏古，秦碑字半销。","已无婚嫁累，何地不渔樵。"]},{"t":"方伯滕公由岭南过访不值二首 其一","f":"五言律诗","c":["翩翩岩穴畔，千骑远从东。","剑履周方伯，轩輶汉上公。","花看薇省近，竹讶草堂空。","万古夷门道，谁论意气雄。"]},{"t":"方伯滕公由岭南过访不值二首 其二","f":"五言律诗","c":["小队行春日，华镳问俗时。","孤亭留皂盖，万户拥朱旗。","气色函关绕，星辰汉殿移。","未应题凤字，曾受子云奇。"]},{"t":"壬午秋以家君命北上舟过严光先生祠戏作","f":"五言律诗","c":["不向长安去，何人奏客星。","物情违偃蹇，吾道寄飘零。","大泽寒收钓，高天暮放舲。","羊裘谒明主，归卧万峰青。"]},{"t":"舟次槜李寄王承父山人","f":"五言律诗","c":["痴绝王摩诘，何时出辋川。","迷花孤洞里，采药乱峰前。","剧饮留真态，长斋断俗缘。","虎头新使者，曾乞卖文钱。"]},{"t":"再游焦山","f":"五言律诗","c":["尺地开龙象，遥江浸画图。","排云千寺立，涌雾一亭孤。","叠岭藏钟磬，中峰过舳舻。","凭谁买山色，把钓作潜夫。"]},{"t":"夜宿金山作","f":"五言律诗","c":["叠浪天浮玉，中流地布金。","寺围孤岛面，亭插万波心。","日候晨钟出，潮将夜梵沈。","妙高寒独上，风雨过龙吟。"]},{"t":"金陵杂诗二十首 其一","f":"五言律诗","c":["宛洛飞龙地，岐丰下凤年。","河山西控蜀，象纬北朝燕。","玉殿淩霄出，金城截海悬。","嵯峨帝京色，万古镇江天。"]},{"t":"金陵杂诗二十首 其二","f":"五言律诗","c":["宝鼎成周奠，灵符大夏开。","日当濠水上，云傍孝陵来。","百辟瞻黄屋，千灵扈绛台。","时看青琐客，鸣玉凤池回。"]},{"t":"金陵杂诗二十首 其三","f":"五言律诗","c":["虎豹天都近，鱼龙地轴閒。","穿壕瓜步水，锁岸秣陵山。","上苑明冠盖，新亭集佩环。","徘徊承露掌，百尺暮云间。"]},{"t":"金陵杂诗二十首 其四","f":"五言律诗","c":["帝阙三秋到，人烟四望平。","城闉盘海气，市井杂江声。","翠管吴讴发，牙樯越舶行。","未央宫万户，恍忽见蓬瀛。"]},{"t":"金陵杂诗二十首 其五","f":"五言律诗","c":["禁苑花如织，离宫树作行。","虹桥悬太液，凤管集昭阳。","日丽雕甍动，云穿碧槛藏。","翠华双掩映，犹记六龙翔。"]},{"t":"金陵杂诗二十首 其六","f":"五言律诗","c":["画戟三千队，雕戈十二营。","貔貅严左翼，熊虎列前旌。","草木环滁动，蒹葭到海平。","越裳重译至，何事问长缨。"]},{"t":"金陵杂诗二十首 其七","f":"五言律诗","c":["树色东华远，钟声大内开。","红云长乐观，紫雾柏梁台。","帝座罘罳拥，仙城睥睨回。","蒋山青不断，百里挂崔嵬。"]},{"t":"金陵杂诗二十首 其八","f":"五言律诗","c":["画槛排空立，飞甍逐望低。","观危鳷鹊度，台古凤凰栖。","海日千门上，江云万堞齐。","大堤杨柳色，彷佛旧乌啼。"]},{"t":"金陵杂诗二十首 其九","f":"五言律诗","c":["巷陌连松桂，园亭翳薜萝。","人家王谢旧，佛寺晋梁多。","北固晨钟断，西陵夜舶过。","紫骝浑欲住，无奈客愁何。"]},{"t":"金陵杂诗二十首 其十","f":"五言律诗","c":["大道开平乐，名姝傍狭斜。","黄鹂交坐柳，白马竞穿花。","翠箔通云气，珠帘上月华。","画梁双燕子，遥认莫愁家。"]},{"t":"金陵杂诗二十首 其十一","f":"五言律诗","c":["玄武湖边路，西风载酒行。","中流藏滟滪，叠岛象昆明。","落日喧沙雁，回风动石鲸。","楼船三十万，犹记汉皇营。"]},{"t":"金陵杂诗二十首 其十二","f":"五言律诗","c":["胜绝南朝地，淹留北上程。","石城看虎踞，萧寺听鸡鸣。","岫锁吴云暗，江飞蜀雪明。","诘朝关外路，真作弃繻行。"]},{"t":"金陵杂诗二十首 其十三","f":"五言律诗","c":["寂寞空三殿，豪华记六朝。","齐梁频禅代，支许竞招要。","只字神飞动，千言思泬寥。","昔人吾倘遇，玉麈向谁骄。"]},{"t":"金陵杂诗二十首 其十四","f":"五言律诗","c":["杰阁凭虚上，回瞻帝阙西。","城开千巷陌，刹涌万招提。","灵谷青松合，钟山碧树齐。","朝来渡江去，击楫为闻鸡。"]},{"t":"金陵杂诗二十首 其十五","f":"五言律诗","c":["落日长干道，青丝照玉壶。","碧桃双系马，绿柳半藏乌。","濩落堪词客，飞扬问酒徒。","纵邀金谷侣，长夜斗摴蒱。"]},{"t":"金陵杂诗二十首 其十六","f":"五言律诗","c":["衮衮牛头路，青山极望同。","天开吴楚地，寺锁晋隋宫。","宿雾萦窗白，朝霞出户红。","异时飞锡到，阐化大江东。"]},{"t":"金陵杂诗二十首 其十七","f":"五言律诗","c":["句曲山中树，华阳洞口云。","玉楼千地涌，金铎四天闻。","老鹤传丹诀，乖龙护赤文。","五芝容客采，长揖大茅君。"]},{"t":"金陵杂诗二十首 其十八","f":"五言律诗","c":["结绮誇前代，临春忆大家。","清歌传宝瑟，丽藻掷瑶华。","殿倚千门月，楼飘万井霞。","即今商女恨，悽绝后庭花。"]},{"t":"金陵杂诗二十首 其十九","f":"五言律诗","c":["屈指前朝事，悲凉旧迹存。","金瓯长日月，玉殿自朝昏。","野雀栖朱桁，啼乌过白门。","柳花香满店，愁绝送王孙。"]},{"t":"金陵杂诗二十首 其二十","f":"五言律诗","c":["献赋趋鸾掖，题诗寄凤台。","自呼狂客饮，谁问谪仙才。","步忆金莲下，歌听玉树回。","三山吾欲去，万仞卧蓬莱。"]},{"t":"欧水部招同张太学刘大理顾司勋夜集徐园迟李临淮不至同用心字二首 其一","f":"五言律诗","c":["华馆夜沈沈，追随惬素心。","佩环三署合，灯火万家深。","白苧翻吴曲，青萍动越吟。","征西期不至，愁绝露华侵。"]},{"t":"欧水部招同张太学刘大理顾司勋夜集徐园迟李临淮不至同用心字二首 其二","f":"五言律诗","c":["名园仍北郭，小径入东林。","地忆先皇赐，天回上客吟。","当尊荷芰色，满座薜萝心。","冉冉长安月，飞光下翠岑。"]},{"t":"区用孺以端研见贻索余一诗为报","f":"五言律诗","c":["邂逅罗浮客，论心卫水傍。","红丝劳把赠，青玉烂生光。","偃月窥芸案，涵星动草堂。","输他阿环丽，捧立在昭阳。"]},{"t":"哭黎惟敬秘书四首 其一","f":"五言律诗","c":["此日朱明洞，谁同对浊醪。","宦途穷执戟，人代绝抽毫。","鸡犬闻天路，鱼龙泣海涛。","传家大令在，忍睹凤凰毛。"]},{"t":"哭黎惟敬秘书四首 其二","f":"五言律诗","c":["骤得天涯讣，真成地下游。","罗浮残月堕，碣石断虹留。","惨淡青黎阁，嵯峨白玉楼。","梅花一万树，何处挂吴钩。"]},{"t":"哭黎惟敬秘书四首 其三","f":"五言律诗","c":["石室瑶华閟，泉台玉树遥。","神游今八极，宦迹旧三朝。","客竞传中论，人谁赋大招。","那堪潞河望，风色暮萧萧。"]},{"t":"哭黎惟敬秘书四首 其四","f":"五言律诗","c":["邂逅为玄日，踟蹰射策年。","飞觥桃叶下，授简竹林前。","调已中华绝，名应大海传。","乱山铜柱外，若个是新阡。"]},{"t":"寄观察金公","f":"五言律诗","c":["按部双旌远，行边一剑雄。","图书观鲁殿，谣颂采齐风。","泰岱浮空紫，蓬莱上日红。","登临时极目，作赋许谁同。"]},{"t":"秋日湖庄八首 其一","f":"五言律诗","c":["幽栖只数椽，野水十家连。","静室长生白，閒亭独草玄。","蒹葭湖北路，禾黍郭西田。","理就沧浪曲，吴歌日扣舷。"]},{"t":"秋日湖庄八首 其二","f":"五言律诗","c":["湖阔疑青草，原荒近赤松。","微名藏一壑，大业寄千峰。","户牖岚光满，阶除露气浓。","楼高才十尺，莫拟卧元龙。"]},{"t":"秋日湖庄八首 其三","f":"五言律诗","c":["素发垂垂近，青阳去去多。","霜檐飘橡栗，雨壁上藤萝。","越女红莲棹，吴侬白苧歌。","翛然车马绝，曳杖步山阿。"]},{"t":"秋日湖庄八首 其四","f":"五言律诗","c":["野色看逾近，秋光澹欲无。","凄风回大壑，骤雨入平湖。","碧树通樵径，丹枫系钓舻。","江东步兵后，潇洒见吾徒。"]},{"t":"秋日湖庄八首 其五","f":"五言律诗","c":["六尺鸱夷舫，萧然系短篱。","乱山明隔垞，积雨暗空陂。","身世鸬鹚老，行藏雁鹜知。","五湖秋万斛，点缀著西施。"]},{"t":"秋日湖庄八首 其六","f":"五言律诗","c":["大野黄云熟，平湖白露凉。","菰芦环笠泽，薜荔翳柴桑。","落雁啼沙汭，流萤度石房。","寒花缀篱落，作意近重阳。"]},{"t":"秋日湖庄八首 其七","f":"五言律诗","c":["穷巷回车辙，柴门尽日幽。","杜陵歌大厦，玄德卧高楼。","地许凫鹥占，天容鹿豕游。","虞卿懒成癖，点笔为春秋。"]},{"t":"秋日湖庄八首 其八","f":"五言律诗","c":["此日游仙梦，当时结客情。","玉绳鳷鹊观，金钥凤凰城。","白眼长安卧，红颜上国行。","十年湖海气，疏阔傍柴荆。"]},{"t":"送萧司空之南都四首 其一","f":"五言律诗","c":["剑履新南国，旌旗旧朔方。","一麾移细柳，万舸静扶桑。","虎豹军容肃，麒麟帝眷长。","异时书太史，宁复论平阳。"]},{"t":"送萧司空之南都四首 其二","f":"五言律诗","c":["灿烂熊车度，逶迤凤阙来。","戈鋋千堠列，卤簿百城开。","日近司空座，星移上将台。","大廷推相国，谁并酂侯才。"]},{"t":"送萧司空之南都四首 其三","f":"五言律诗","c":["组练过吴会，衣冠入汉宫。","日光摇画戟，霞色射彤弓。","渤海三秋静，潢池四望空。","未应劳梦卜，天意属非熊。"]},{"t":"送萧司空之南都四首 其四","f":"五言律诗","c":["鼓吹出江皋，前驱意气豪。","射潮收万弩，横海列千舠。","日月瞻黄屋，云霞护锦袍。","秣陵花似绮，烂漫待抽毫。"]},{"t":"赠赵茂才","f":"五言律诗","c":["言开绿萝径，却访赤松游。","枕簟依山僻，琴书入洞幽。","姓名文苑客，身世醉乡侯。","莫羡侯芭业，玄亭易白头。"]},{"t":"李逸人西游寄讯","f":"五言律诗","c":["一壑容高卧，频年赋远游。","卜居秦望顶，长啸越台秋。","海日低龙屩，山风绽鹿裘。","钱塘潮渐长，乍夜放扁舟。"]},{"t":"秋日题唐惟良山房二首 其一","f":"五言律诗","c":["郭外千峰色，翛然堕草堂。","挂冠三径蚤，高枕一丘长。","夕露团幽砌，朝霞宿画廊。","门添五杨柳，何异在柴桑。"]},{"t":"秋日题唐惟良山房二首 其二","f":"五言律诗","c":["结宇双松下，为园万竹中。","壮年歌老骥，长日送飞鸿。","露浥琴丝润，星摇剑色雄。","看余五游毕，绝顶卧空同。"]},{"t":"寄灌父","f":"五言律诗","c":["怅望西亭客，沈吟北海筵。","玉笙王屋顶，珠履邺台前。","桂树先秋发，藜灯入夜悬。","异时双鹤语，归问大罗天。"]},{"t":"怀邓孺孝兼讯周山人","f":"五言律诗","c":["忆汝龙门过，苍茫鹤驭分。","暮归句曲洞，晨谒大茆君。","把钓吴江雪，传书越海云。","草堂人独卧，谁勒稚圭文。"]},{"t":"吴叔通以四诗见贻赋答 其一","f":"五言律诗","c":["寂寞乾坤事，归来一敝裘。","云山成独卧，海岱见名流。","璧已三年抱，珠仍万里投。","白蘋洲上路，曾试木兰舟。"]},{"t":"吴叔通以四诗见贻赋答 其二","f":"五言律诗","c":["何处怀同调，飞书问独醒。","乍回双眼白，犹阻万峰青。","惨淡垂纶石，栖迟载酒亭。","异时新论就，能赏太玄经。"]},{"t":"吴叔通以四诗见贻赋答 其三","f":"五言律诗","c":["病肺荒园外，潜身大海傍。","青阳驰翰墨，白雪照行藏。","一水兰苕近，千岩薜荔长。","夜来星斗色，明灭傍干将。"]},{"t":"吴叔通以四诗见贻赋答 其四","f":"五言律诗","c":["梦寐延陵客，风流故不群。","千秋曾和雪，片语欲凌云。","柳隔青丝笮，花生白练裙。","浮家何日事，来往霅溪云。"]},{"t":"句曲道中奉怀王司马先生寄讯八首 其一","f":"五言律诗","c":["帝梦思良弼，天书问老臣。","彤弓分雨露，赤舄上星辰。","虎豹千营合，熊罴百卫陈。","何妨文武略，第一画麒麟。"]},{"t":"句曲道中奉怀王司马先生寄讯八首 其二","f":"五言律诗","c":["夙世元戎业，明时上将材。","大开貔虎幕，长啸凤凰台。","记室班扬聚，胡床陆谢陪。","昨宵江上笛，飞尽帝城梅。"]},{"t":"句曲道中奉怀王司马先生寄讯八首 其三","f":"五言律诗","c":["凤德元千仞，熊飞自一时。","河山分玉帐，日月绕牙旗。","错落霜毫动，荧煌露布驰。","共知莘野出，宁畏草堂移。"]},{"t":"句曲道中奉怀王司马先生寄讯八首 其四","f":"五言律诗","c":["暂辞三教主，聊作万夫雄。","横槊长江上，挥毫大海东。","阴徐非赋侣，鲍庾岂文工。","晋宋齐梁业，何人不下风。"]},{"t":"句曲道中奉怀王司马先生寄讯八首 其五","f":"五言律诗","c":["谭天曾帝问，缩地旧仙才。","未论青牛出，真成彩凤来。","毫端穷宇宙，匣底閟风雷。","戏作梁陈句，犹堪长玉台。"]},{"t":"句曲道中奉怀王司马先生寄讯八首 其六","f":"五言律诗","c":["寂寞千秋事，踟蹰六代间。","新亭新日月，旧馆旧河山。","柳色停车骑，花香杂佩环。","吴姬年尚少，劝客亦酡颜。"]},{"t":"句曲道中奉怀王司马先生寄讯八首 其七","f":"五言律诗","c":["豪华非昔日，罗绮尚前朝。","侠少黄金勒，名姝赤玉箫。","花明新院髻，柳学故宫腰。","今夜扬州月，平分十二桥。"]},{"t":"句曲道中奉怀王司马先生寄讯八首 其八","f":"五言律诗","c":["石头城外路，光色度青骢。","说法寻支遁，参禅叩懒融。","塔花晴日映，潭影暮天空。","拟逐三车去，西方问大雄。"]},{"t":"渡江有怀秣陵旧游八首再寄王长公 其一","f":"五言律诗","c":["六代风流地，豪吟兴未涯。","层台花宿凤，故堞柳藏鸦。","海日笼丹雾，江天照绮霞。","春光何太蚤，先到莫愁家。"]},{"t":"渡江有怀秣陵旧游八首再寄王长公 其二","f":"五言律诗","c":["投闲沧海上，阅胜大江濆。","老树齐梁雪，飞蓬楚蜀云。","帝城双凤下，官路八驺分。","怅望前朝事，含杯几夕曛。"]},{"t":"渡江有怀秣陵旧游八首再寄王长公 其三","f":"五言律诗","c":["金波怜旧句，玉树待新题。","夜宿寻高座，春游出大堤。","残僧留晋宋，古佛辨隋齐。","明日楼船上，谁同教水犀。"]},{"t":"渡江有怀秣陵旧游八首再寄王长公 其四","f":"五言律诗","c":["由来佳丽地，本是帝王州。","绿浪邀卢女，青山抱蒋侯。","桃花双阙路，柳色万家楼。","总道官如屣，那知宦是游。"]},{"t":"渡江有怀秣陵旧游八首再寄王长公 其五","f":"五言律诗","c":["幕府三千客，辕门十万兵。","登龙环海岱，候骑半江城。","画甲飘云气，珠帘上月明。","夜来清啸发，双鹤下瑶京。"]},{"t":"渡江有怀秣陵旧游八首再寄王长公 其六","f":"五言律诗","c":["玉洞留仙棹，金陵问帝都。","野花朱桁雀，霜树白门乌。","晏寝团牙戟，宵吟击唾壶。","能教奇伟客，白首卧菰芦。"]},{"t":"渡江有怀秣陵旧游八首再寄王长公 其七","f":"五言律诗","c":["青鞋曾碧落，彩仗乍丹霄。","大雅追三代，雄风扫六朝。","帆樯扬子驿，卤簿秣陵桥。","但作文章客，宁知武略饶。"]},{"t":"渡江有怀秣陵旧游八首再寄王长公 其八","f":"五言律诗","c":["柱下书堪著，壶中术已传。","三花留野寺，一苇渡江天。","浪息沧溟外，尘消大漠前。","何须片石上，辛苦勒燕然。"]},{"t":"病卧原口长公以诗见存遂有起色赋谢四章 其一","f":"五言律诗","c":["骨立乾坤外，呻吟岁月过。","片言回大造，孤榻起沈疴。","骤觉头风愈，宁论肺病多。","观涛定何日，飞棹广陵波。"]},{"t":"病卧原口长公以诗见存遂有起色赋谢四章 其二","f":"五言律诗","c":["病卧空搔首，文成剧赏心。","乍回燕客梦，初理越人吟。","白雪流空馆，青阳动绝琴。","片言千古在，底事论飞沈。"]},{"t":"病卧原口长公以诗见存遂有起色赋谢四章 其三","f":"五言律诗","c":["一札长干里，悠然病目开。","讵知垂烬烛，犹作复然灰。","赵璧初还邸，燕金任筑台。","朝来沧海上，咫尺见蓬莱。"]},{"t":"病卧原口长公以诗见存遂有起色赋谢四章 其四","f":"五言律诗","c":["无媒宁逐鹿，有路任亡羊。","朗诵陈琳檄，高悬杜甫章。","神明开混沌，鬼魅失膏肓。","濩落馀生在，犹堪王夜郎。"]},{"t":"渡淮","f":"五言律诗","c":["拂曙淮堤上，垂杨渐可攀。","雾浓孤客舫，云浅八公山。","不作投珠去，真成抱玉还。","十年牛马走，端合鬓毛斑。"]},{"t":"自严滩至新安途中纪兴十首呈司马汪公 其一","f":"五言律诗","c":["四百滩头路，峰峦面面青。","路疑行绝栈，滩似泊空舲。","平地飞千瀑，高天突万星。","不因司马在，吾岂别玄亭。"]},{"t":"自严滩至新安途中纪兴十首呈司马汪公 其二","f":"五言律诗","c":["一滩高一丈，滩尽到天都。","叠嶂云飞动，阴厓日有无。","辛夷残紫落，踯躅乱红敷。","独少行云庙，分明入峡途。"]},{"t":"自严滩至新安途中纪兴十首呈司马汪公 其三","f":"五言律诗","c":["明发寒逾甚，羊裘当锦袍。","争风帆力猛，破雪橹声豪。","闇谷迷红树，悬厓露碧桃。","居然丘壑底，不用武陵逃。"]},{"t":"自严滩至新安途中纪兴十首呈司马汪公 其四","f":"五言律诗","c":["悬水三千仞，奔流落大川。","片帆危欲堕，群缆急争先。","石险时栖鹘，峰高欲跕鸢。","兹游信奇绝，点笔漫成篇。"]},{"t":"自严滩至新安途中纪兴十首呈司马汪公 其五","f":"五言律诗","c":["树色逶迤合，山光次第来。","岸疑夸父坼，厓似巨灵开。","蜀客迷三峡，闽人话七台。","移舟傍鸥鹭，此夕漫惊猜。"]},{"t":"自严滩至新安途中纪兴十首呈司马汪公 其六","f":"五言律诗","c":["嵯峨探虎穴，䆗窱入龙宫。","百丈飞湍下，双篙巨石中。","地危真破冢，天近欲乘风。","恰称诗怀壮，长歌万虑空。"]},{"t":"自严滩至新安途中纪兴十首呈司马汪公 其七","f":"五言律诗","c":["密缆纷如织，高樯望若攒。","怒涛翻绝壑，飞浪叠层峦。","不雨青天润，无风白日寒。","苍松植何代，百尺架㠝岏。"]},{"t":"自严滩至新安途中纪兴十首呈司马汪公 其八","f":"五言律诗","c":["片石俱飞动，千山竞送迎。","地真游黯淡，天似入蓬瀛。","缆束高厓度，樯穿绝壁行。","谁呼谪仙至，白日跨长鲸。"]},{"t":"自严滩至新安途中纪兴十首呈司马汪公 其九","f":"五言律诗","c":["白岳新游快，青溪旧迹存。","乱山冲虎过，奇石象狮蹲。","贾舶环枫社，渔梁护荜门。","飞鸿渺天末，消息信乾坤。"]},{"t":"自严滩至新安途中纪兴十首呈司马汪公 其十","f":"五言律诗","c":["十年怀命驾，千里棹孤航。","大壑行严濑，飞流涉吕梁。","猿猱晨作伴，豺虎夜成行。","咫尺龙门在，无劳叹望洋。"]},{"t":"惊猿峡","f":"五言律诗","c":["不见啼猿树，孤峰划翠屏。","峭逾扪太华，危欲堕中泠。","鸟道悬空阔，龙潭伏杳冥。","笑他韩吏部，勒石向山灵。"]},{"t":"伏虎岩","f":"五言律诗","c":["何年飞滟滪，百尺挂崔嵬。","绝壁盘飞电，高梁划迅雷。","樯危三老惧，缆急万人摧。","日暮雄心发，狂歌兴未回。"]},{"t":"柬汪仲淹时以足疾居肇林去太函三十里","f":"五言律诗","c":["方丈维摩室，翛然物外踪。","花馀天女散，果剩法王供。","白日流禅榻，青天落梵钟。","何当问神足，白眼对长松。"]},{"t":"赠片云片云者司马公所命王姬名也","f":"五言律诗","c":["窈窕尊前态，娉婷画里颜。","客疑游洛水，神似降巫山。","夜月辉眉黛，朝霞动髻鬟。","不应撩宋玉，名字落人间。"]},{"t":"仲嘉携酌过箕台四首末篇怀汪献于 其一","f":"五言律诗","c":["信步南冈上，寒松一径斜。","浮杯当柳色，促席坐桃花。","古殿明丹壑，方塘漾彩霞。","红妆晚成队，拾翠傍晴沙。"]},{"t":"仲嘉携酌过箕台四首末篇怀汪献于 其二","f":"五言律诗","c":["步步春原色，寻芳意自閒。","石枰疏竹里，金铎乱松间。","一壑停苍佩，千峰峙翠鬟。","平生双屐在，天阔任跻攀。"]},{"t":"仲嘉携酌过箕台四首末篇怀汪献于 其三","f":"五言律诗","c":["远天横霁色，箕踞坐莓苔。","竹露晨犹滴，松风午渐来。","翠微悬绝壑，苍霭覆平台。","十日犹能客，将无典绿醅。"]},{"t":"仲嘉携酌过箕台四首末篇怀汪献于 其四","f":"五言律诗","c":["潦倒悲华发，追随暂少年。","煖风抽麦日，微雨拗花天。","游女矜环佩，居民竞管弦。","维扬好春色，何地著丝鞭。"]},{"t":"士能斋头阻雨仲淹舆疾来会一律迟之","f":"五言律诗","c":["风雨催寒食，残花闭小楼。","丁香空结恨，红豆故生愁。","梦隔青绫被，春迟绿绮裘。","观涛今起色，迟汝万峰头。"]},{"t":"同盛山人垆头话旧作","f":"五言律诗","c":["一骑吴关外，悲歌脱畏途。","残生馀海峤，万死得江湖。","盆底冤谁烛，垆头兴未徂。","十年携手泪，相对湿菰芦。"]},{"t":"春日司马公同携王姬入紫霞洞观桃花时少连太宁仲嘉仲淹并集司马以桃花源美人家为韵分得桃字","f":"五言律诗","c":["烂漫西郊外，肩舆度碧桃。","春生武陵洞，病起曲江涛。","日彩摇纨扇，天香袭锦袍。","绝崖仍独上，谁似谢公豪。"]},{"t":"得花字","f":"五言律诗","c":["十里春山色，芳菲乱水涯。","瑶池迷故迹，玉洞斗新葩。","野豁千林雾，川明万树霞。","不知刘阮辈，何事到仙家。"]},{"t":"题老蚌生珠图","f":"五言律诗","c":["几夜骊龙颔，偷携径寸游。","芜城双月上，合浦一星流。","影似悬鲛室，光疑发蜃楼。","未须惭老蚌，照乘诧诸侯。"]},{"t":"汪参军邀饮作","f":"五言律诗","c":["画拱摇丹日，雕阑驻彩云。","榻延徐孺子，吟接鲍参军。","午馔行山蕨，春羹荐野芹。","醉归浑不解，萝月渐纷纷。"]},{"t":"休宁道中四首 其一","f":"五言律诗","c":["百里休宁道，肩舆度夕阳。","川原明翠黛，阛阓斗红妆。","玉佩时相亚，金钗尽作行。","何方犊车至，夹路烂生光。"]},{"t":"休宁道中四首 其二","f":"五言律诗","c":["拂曙征人起，苍云抱郭流。","落红依小径，深绿涨平洲。","竹色偏萦辇，松阴直过楼。","天然对图画，底事唤营丘。"]},{"t":"休宁道中四首 其三","f":"五言律诗","c":["白堕家家酿，黄梁处处舂。","飞泉悬薜荔，远岫削芙蓉。","晚日前村旆，春烟隔寺钟。","玄天看咫尺，紫气欲成龙。"]},{"t":"休宁道中四首 其四","f":"五言律诗","c":["望望山疑近，行行路转遥。","依冈梅子熟，夹路豆香飘。","翠幕萦朱户，红妆簇画桥。","百钱犹挂杖，烂醉在今宵。"]},{"t":"同汪士能入丰干路逢仲淹寄诗舆中口授用原韵","f":"五言律诗","c":["泠然遗俗累，曳杖到仙家。","布帽扳名岳，荷衣弄太霞。","吾宁驱白石，君已饭丹砂。","纵有天台遇，能如萼绿华。"]},{"t":"阿四既留溪南士能命更呼刘生佐酒亦以事羁赋此嘲之","f":"五言律诗","c":["咫尺玄英宅，朱弦试一弹。","中原留上驷，蓬岛隔飞鸾。","酒压荼蘼瓮，春迟苜蓿盘。","美人期不至，惆怅月华残。"]},{"t":"宜男堂为汪氏题","f":"五言律诗","c":["阶前植瑶草，芳色暮离离。","艳入三姬座，香飞百子池。","冰桃偕献实，玉树并生枝。","旦夕佳男兆，华堂事事宜。"]},{"t":"槃楼","f":"五言律诗","c":["何年硕人住，结搆傍蒹葭。","睨柱千山月，推窗万壑霞。","青藜中垒阁，绿绮少文家。","好著元龙卧，翛然世虑遐。"]},{"t":"赠高深甫二首 其一","f":"五言律诗","c":["最忆高常侍，生平乐事饶。","千金求騄駬，十院贮红绡。","古迹留三代，新声和六朝。","湖头明月满，无夜不吹箫。"]},{"t":"赠高深甫二首 其二","f":"五言律诗","c":["自惬逍遥理，谁同汗漫游。","异书中秘得，名墨太清留。","夜月渔阳鼓，春山燕子楼。","六桥杨柳色，无处避骅骝。"]},{"t":"夜集刘将军即席作示孙徐两生","f":"五言律诗","c":["聊同珠履客，共此岁华徂。","潦倒青丝盒，淹留白玉壶。","寒风回击筑，骤雨促呼卢。","不道嫖姚贵，犹能事博徒。"]},{"t":"读季孝廉匡庐诗卷题","f":"五言律诗","c":["彭蠡扬帆近，匡庐纵目长。","高峰悬紫翠，乱瀑洒青苍。","竹隐文殊座，莲空慧远堂。","攒眉何处客，不远是柴桑。"]},{"t":"挽赵别驾汝申四首 其一","f":"五言律诗","c":["神武门前路，何人复挂冠。","华阳閒鹤驭，瀫水罢渔竿。","冷日黄金灶，寥天白玉棺。","君看鸡犬去，已到赤城端。"]},{"t":"挽赵别驾汝申四首 其二","f":"五言律诗","c":["频年嗟伏枥，此日叹藏舟。","世阀传中垒，乡闾问太丘。","朱弦俄入夜，素翣正逢秋。","好在蓬池顶，题诗遍十洲。"]},{"t":"挽赵别驾汝申四首 其三","f":"五言律诗","c":["玉局留丹界，琳宫寄碧霞。","渐荒陶令菊，难觅邵侯瓜。","雾里三天舄，云中八月槎。","椒浆聊一奠，陇树乱栖鸦。"]},{"t":"挽赵别驾汝申四首 其四","f":"五言律诗","c":["蘧然孤蝶寝，忽到夜台傍。","别墅丛青桂，空斋翳白杨。","星沈南极杳，天入大罗长。","一尉何须恨，修文正拜郎。"]},{"t":"萧含誉自楚中来访留集二首 其一","f":"五言律诗","c":["下榻仍松桧，移尊更薜萝。","星当雄剑聚，云傍彩毫多。","客计留天目，乡书问汨罗。","五游他日遂，相逐老岩阿。"]},{"t":"萧含誉自楚中来访留集二首 其二","f":"五言律诗","c":["狂歌青桂下，醉舞绿筠前。","越绝书犹著，湘累赋已传。","风葭云梦笛，雪苇洞庭船。","归路甔甀近，能无问太玄。"]},{"t":"访张伯起煖阁小集夜同过幼于园","f":"五言律诗","c":["伐木怀同调，连枝惬共吟。","围炉冬阁煖，秉烛夜堂深。","月倚孤城棹，风交万户砧。","龙唇弦绝久，拂拭为知音。"]},{"t":"幼于园中听歌","f":"五言律诗","c":["一径蓬蒿入，层台面绿波。","客携桑落酒，人倚柘枝歌。","夕露更衣堕，晨星襆被过。","五湖花照眼，蚤晚著渔蓑。"]},{"t":"赠钱将军","f":"五言律诗","c":["属国儒风远，轻车将略长。","侍童青玉案，前队绿沈枪。","北府晨开席，南楼夜据床。","邵陵游猎处，白马映丝缰。"]},{"t":"题吴肇成清波碧玉图","f":"五言律诗","c":["亭亭开素面，袅袅出朱唇。","水畔疑西子，波心似洛神。","浣纱犹倚石，移袜乍生尘。","那得相携去，馨香赠远人。"]},{"t":"闻王问伯领解南都喜而有作","f":"五言律诗","c":["此夕庭阶树，真成奕叶光。","赋曾标五子，名欲擅三王。","客礼龙门下，神交雁塔傍。","百年兄弟好，同日奏长杨。"]},{"t":"舟次槜李寄王承父山人","f":"五言律诗","c":["邂逅兰溪约，秋风望未涯。","地违青雀舫，天靳白鸥沙。","虎阜看茶近，乌程问酒遐。","春来定寻汝，酩酊万桃花。"]},{"t":"泊姑苏寄吴文仲","f":"五言律诗","c":["寂寞寒山寺，钟声只自听。","高云随去舄，夜雪到空舲。","竹色谁分座，花香独扣扃。","太湖峰七十，历历傍愁青。"]},{"t":"访曹子念戏赠","f":"五言律诗","c":["幽居仍薜荔，雅兴旧菰芦。","一榻悬东海，孤航领太湖。","须髯疑大侠，骨相异潜夫。","何事吴阊底，频年侣博徒。"]},{"t":"长干道中书事 其一","f":"五言律诗","c":["金波鳷鹊下，玉管凤凰调。","晋帐延双隗，吴妆出二乔。","柘枝频度曲，桃叶旧传谣。","欲认相寻处，城南十五桥。"]},{"t":"长干道中书事 其二","f":"五言律诗","c":["紫雾藏金屋，丹霞间玉楼。","那能佳丽地，不作狭斜游。","江女名无畏，卢家字莫愁。","徐娘虽老去，象管不停讴。"]},{"t":"过淮上读贞烈沈氏实编作沈为侍御吴公妾余丙子吴公所取士也 其一","f":"五言律诗","c":["匪石心难转，如山诺竟酬。","馀生宁九地，一死为千秋。","壮节长淮远，贞魂大海留。","预看彤史笔，灿烂照松楸。"]},{"t":"过淮上读贞烈沈氏实编作沈为侍御吴公妾余丙子吴公所取士也 其二","f":"五言律诗","c":["忆昔吴公赏，真同贾傅看。","凄凉神武阙，早挂惠文冠。","旧事悲桃李，高风想蕙兰。","酬知万行泪，愧汝大江干。"]},{"t":"渡黄河","f":"五言律诗","c":["九曲黄河水，奔流下夕阳。","芦根渔网集，树杪客帆张。","巨石撑淮浦，高洪压吕梁。","黄姑频岁约，击楫上扶桑。"]},{"t":"宿良乡","f":"五言律诗","c":["小市良乡驿，征人暂解鞍。","空林万木落，孤馆一灯残。","旅色逢秋暮，乡心入夜阑。","那知百里外，明日是长安。"]},{"t":"家大人七秩恭贺四首 其一","f":"五言律诗","c":["粲烂长生箓，高悬瀫水阳。","中元秋届节，南极夜生光。","黄鹤吴天外，青鸾越海旁。","惟应双瑞曲，永送万年觞。"]},{"t":"家大人七秩恭贺四首 其二","f":"五言律诗","c":["懿行三千就，遐龄七十延。","竹宫观礼日，兰署校文年。","六传巡滇骑，双旌入楚船。","讴歌犹咫尺，拜舞大椿前。"]},{"t":"家大人七秩恭贺四首 其三","f":"五言律诗","c":["华堂开寿域，瑞霭接瑶池。","十地来菩萨，三天降辟支。","名犹喧隶卒，化已洽边陲。","何限朋游集，千花照玉卮。"]},{"t":"家大人七秩恭贺四首 其四","f":"五言律诗","c":["慎默藏身宝，圆明应物踪。","年高黄叔度，世拟郭林宗。","日月迟玄草，云霞恋赤松。","八千春共祝，宁羡渭滨封。"]},{"t":"寄居曲水园柬张氏伯仲二首 其一","f":"五言律诗","c":["自爱新居僻，宁论故业贫。","伯通能借庑，仲蔚已为邻。","茂苑花淹客，吴门药赠人。","苍茫太湖底，生事起垂纶。"]},{"t":"寄居曲水园柬张氏伯仲二首 其二","f":"五言律诗","c":["独有陶公径，能停谢客舆。","陆浑虚旧宅，阳羡觅深居。","水木孤轩外，云萝四壁馀。","何如传舍客，日月敝长裾。"]},{"t":"岭南陈孔信贽其诗来谒报赠二章 其一","f":"五言律诗","c":["何物元龙少，囊携绝妙词。","百篇难汝弟，一字愧吾师。","剑击要离冢，壶倾泰伯祠。","钱塘万家雪，只棹慰相思。"]},{"t":"岭南陈孔信贽其诗来谒报赠二章 其二","f":"五言律诗","c":["骤发扁舟兴，佯狂到海涯。","诗成筒寄草，梦断笔生花。","把赠罗浮雪，回看茂苑霞。","鲈乡亭下馆，归路欲栖鸦。"]},{"t":"过张水部新居","f":"五言律诗","c":["负郭成三径，郊原带草堂。","飞甍摇海气，画槛纳江光。","花色吴门近，棠阴越里长。","中朝思大厦，未许醉清商。"]},{"t":"过娄江载宿弇园时囧伯逸季并以事留云间独房仲在下榻款留亡异长公存日感赋此章","f":"五言律诗","c":["十日欢犹洽，千秋态未忘。","开尊怜仲子，下榻梦中郎。","旅色停孤棹，歌声咽后堂。","屋梁明月满，惆怅夜何长。"]},{"t":"小袛园怀囧伯逸季","f":"五言律诗","c":["寂寞双林下，迟回一杖过。","盛名犹宇宙，陈迹已山河。","落月连枝远，悲风大树多。","独将知己泪，烂漫洒青萝。"]},{"t":"澹圃访王闲仲及二弟渊季征叔留集作","f":"五言律诗","c":["夜久尊偏绿，更阑烛尚红。","云霄三隽在，海岱二难空。","旧业东陵异，新欢北海同。","那将季札剑，两地挂悲风。"]},{"t":"陆楚生新居在弇园澹圃间邀余斋中啜茗即席赋","f":"五言律诗","c":["爱尔新居僻，令余世事忘。","一瓢寒树里，四壁浣花傍。","鸿渐馀茶灶，龟蒙但笔床。","坐闻邻笛起，涕泪满山阳。"]},{"t":"再过陆楚生","f":"五言律诗","c":["小筑娄江畔，萧然四壁空。","断桥流水外，茆屋乱云中。","有意交胡质，长歌问陆通。","犹怜傅舍客，弹铗卧秋风。"]},{"t":"夜卧沈子书斋出素笺索题信笔赋","f":"五言律诗","c":["褥许分青锦，厨仍卧碧纱。","浓香熏柏子，清梦杂梅花。","未觉仙家好，浑忘客路赊。","异时怀仲举，湖水渺云沙。"]},{"t":"伯隅童子冶卿持扇索题走笔一律赠之","f":"五言律诗","c":["偶遇张公子，频年拥素琴。","貌堪酬白璧，名已铸黄金。","肯作调鞭老，时为捧剑吟。","红绡遇何日，倩汝入花阴。"]},{"t":"送吴刺史之桂林","f":"五言律诗","c":["莫作炎荒叹，骞腾识凤麟。","棠阴流皂盖，桂实堕朱轮。","雨润遐陬俗，风驰绝徼尘。","好将南国化，沐浴瘴乡人。"]},{"t":"陈方伯自闽中移蜀寄柬","f":"五言律诗","c":["奏事驰仙阙，除书下圣朝。","杨舲江树合，行部海棠娇。","云暗三峨寺，天长万里桥。","浣花溪上路，词客可重招。"]},{"t":"蔡生移居城北招饮作","f":"五言律诗","c":["咫尺城东寓，相寻路未遐。","怀人闽海荔，留客武夷茶。","几席凝香雾，杯盘散绮霞。","成行儿女在，袛合老天涯。"]},{"t":"过郭翌之故居有感","f":"五言律诗","c":["尚忆鸿胪第，淹留白日斜。","新坟俄宿草，旧圃更残花。","地迥悲邻笛，天清咽暮笳。","异时风雪满，孤棹问谁家。"]},{"t":"赠张真人","f":"五言律诗","c":["何年赤松子，羽节到皇家。","步蹑飞云履，游乘贯月查。","珠宫浮紫贝，绛阙炼黄芽。","应笑唐供奉，仙裙滞九华。"]},{"t":"寿郭隐君","f":"五言律诗","c":["苍茫翠微半，突兀见孤亭。","大壑悬真气，高天卧客星。","桐江标胜迹，庐阜毓英灵。","不尽名山色，东南万古青。"]},{"t":"题孙生别墅","f":"五言律诗","c":["小筑寄林泉，萧森十数椽。","苏门飞啸日，郢国和歌年。","室静飧霞饱，窗虚卧月便。","溪兰一以撷，为汝拂冰弦。"]},{"t":"题朱茂才孝行卷","f":"五言律诗","c":["千古朱家侠，芳声异代留。","蒸梨知孝行，瀹茗见清修。","乌鸟心长切，羔羊愿未酬。","君看彤史笔，卓荦下螭头。"]},{"t":"寄何稚孝","f":"五言律诗","c":["邂逅清源下，差池易水濆。","心期元独许，意气本无群。","六翮排青汉，孤踪傲白云。","春风上林苑，击节子虚文。"]},{"t":"少宰赵公还北寄送","f":"五言律诗","c":["饯别列鹓鸿，悬腰剑色雄。","台垣三殿近，冢宰二京同。","禁树连云紫，庭花傍日红。","扫门饶赋客，宁复叹飘蓬。"]},{"t":"少宰赵公拜相寄贺八章 其一","f":"五言律诗","c":["一夜求贤诏，欢呼万国同。","谟谋咨大老，启沃仗元功。","绝域车书会，中天剑舄崇。","异时评太史，何羡帝臣风。"]},{"t":"少宰赵公拜相寄贺八章 其二","f":"五言律诗","c":["翊运逢明主，匡时倚上材。","尊荣逾四岳，宠渥重三台。","瀫水初调鼎，华阳已筑台。","早知霖雨泽，六合净炎埃。"]},{"t":"少宰赵公拜相寄贺八章 其三","f":"五言律诗","c":["玉铉调贤佐，金瓯扈圣朝。","群龙齐捧日，双凤各凌霄。","大业皋夔近，荣名稷契遥。","蓬莱云五色，烨烨近人飘。"]},{"t":"少宰赵公拜相寄贺八章 其四","f":"五言律诗","c":["满目乾坤事，关心社稷臣。","八荒悬密勿，九域藉经纶。","煖阁调羹夜，平台赐宴辰。","好将司马业，传播外番人。"]},{"t":"少宰赵公拜相寄贺八章 其五","f":"五言律诗","c":["六馆推名德，三司备羽仪。","麻宣鳷鹊殿，草辍凤凰池。","礼乐重兴日，诗书再睹时。","太平方有象，宁讶庙堂迟。"]},{"t":"少宰赵公拜相寄贺八章 其六","f":"五言律诗","c":["凤诰辉纶綍，龙光切冕旒。","坐调中极鼎，永作大川舟。","八表清风被，三朝壮节留。","长安贵游满，处处撤行驺。"]},{"t":"少宰赵公拜相寄贺八章 其七","f":"五言律诗","c":["尚记临轩日，龙头曳佩环。","帝心悬北斗，人望切东山。","燮理阳春布，论思乙夜閒。","万方伊葛想，翘首玉宸班。"]},{"t":"少宰赵公拜相寄贺八章 其八","f":"五言律诗","c":["上相同心日，真儒佐命年。","白麻初翊圣，黄阁骤招贤。","吐握回三代，吹嘘动八埏。","肯教扬马辈，头白卧林泉。"]},{"t":"长至后三日幼于斋头对菊同张使君陈文学周山人陆孝廉即席分赋得寒字","f":"五言律诗","c":["节已过长至，花犹耐早寒。","似忻彭泽采，偏称汨罗餐。","袅袅团霜砌，亭亭立露盘。","何当撷千朵，烂醉赤栏干。"]},{"t":"过王氏小隐同陆山人周上舍閤中小集","f":"五言律诗","c":["信步绿萝庄，春波夹画墙。","壶中藏滟滪，盆底著潇湘。","曲折花为径，纵横竹绕廊。","乘风时一到，好是白云乡。"]},{"t":"夜过周懋脩馆中月色盈庭皎如霜雪即席口占","f":"五言律诗","c":["咫尺周郎馆，衡茅葑水傍。","披襟流素月，把袂落繁霜。","逸调阳春远，清歌乙夜长。","预愁明发路，枫叶乱金阊。"]},{"t":"西林汎舟即席作","f":"五言律诗","c":["谷口肩舆入，悠然兴未穷。","尊前五湖尽，槛外十洲通。","削壁笼丹雾，飞梁挂彩虹。","坐闻天籁发，兀兀万缘空。"]},{"t":"赋得壮士乐长征","f":"五言律诗","c":["言从汉飞将，结发隶行间。","列戟秋乘障，扬旗夜出关。","双雕婆勒渡，独马贺兰山。","宁忆空闺下，梅花树树攀。"]},{"t":"过沈材叔留卧斋中作","f":"五言律诗","c":["华亭疏雨过，小阁乱云流。","榻为延徐下，船因问戴留。","春光回枕簟，寒色驻衾裯。","十日犹能客，从君笑薄游。"]},{"t":"赠钱将军","f":"五言律诗","c":["征马去飘飘，将军旧度辽。","运筹推武库，横槊羡英标。","转粟三吴尽，飞刍六郡遥。","烦君持大纛，取次静氛妖。"]},{"t":"司马汪公以仲淹讣至寄挽二章 其一","f":"五言律诗","c":["消渴真怜汝，幽忧竟若何。","一尊犹水曲，万事已山阿。","旧业荒兰芷，遗文照薜萝。","异时轩冕贵，较仲定谁多。"]},{"t":"司马汪公以仲淹讣至寄挽二章 其二","f":"五言律诗","c":["濩落词人长，飞扬侠客俦。","生宁惭一诺，死欲擅千秋。","失弟怜司马，从师困伯牛。","天都乱山色，何处挂吴钩。"]},{"t":"寄丁元父","f":"五言律诗","c":["闻道丁元父，筵倾邺下才。","政成初百里，名动已三台。","岸帻寻芳草，弹琴坐落梅。","尚思风雪里，并马立蓬莱。"]},{"t":"题章氏木假山","f":"五言律诗","c":["早谢樵人斧，悠然野客家。","双峰寒宿雾，列干迥撑霞。","埋没沟中断，飘零海上查。","逢时千载事，为尔一长嗟。"]},{"t":"苏君禹留集翠虚亭共赋二首 其一","f":"五言律诗","c":["一径双松里，孤亭万竹旁。","高秋全障日，盛暑欲凝霜。","箨自翻龙虎，枝从宿凤凰。","画帘清绝处，浑拟坐潇湘。"]},{"t":"苏君禹留集翠虚亭共赋二首 其二","f":"五言律诗","c":["百尺烟霄上，千竿雾雨馀。","绿阴浮枕簟，苍霭净庭除。","寂寞王猷驾，萧森杜甫庐。","何如偕筱簜，取次贡乘舆。"]},{"t":"易惟效署中避暑同赋四首 其一","f":"五言律诗","c":["逃暑仍河朔，寻幽到习池。","青丝行共挈，白帻坐频攲。","密竹团书舍，疏花照奕棋。","黄鹂似相识，恰恰在高枝。"]},{"t":"易惟效署中避暑同赋四首 其二","f":"五言律诗","c":["落日孤亭上，微风动碧梧。","净疑开雪槛，凉似浴冰壶。","茗灶供新瀹，楸枰覆旧图。","吟馀爇沈水，云起博山炉。"]},{"t":"易惟效署中避暑同赋四首 其三","f":"五言律诗","c":["竹树参差绿，葵榴烂漫红。","径幽长蔽日，林密尽含风。","白羽高谈洽，青萍醉色雄。","大夫饶酒德，无拟笑山公。"]},{"t":"易惟效署中避暑同赋四首 其四","f":"五言律诗","c":["旧识燕台下，新知越水滨。","乾坤双傲吏，海岱独归人。","薄有骑羊骨，能同跃马身。","万山严子濑，秋色未全贫。"]},{"t":"送友人游边","f":"五言律诗","c":["怜君随汉将，策马度燕台。","六郡风沙合，三边雨雪催。","边笳秋色远，羌笛夜声哀。","来岁看花节，还听草檄回。"]},{"t":"送李从事之南康","f":"五言律诗","c":["十载京华陌，还为故国行。","岸花飞客舫，江草问王程。","晓梦匡山月，春烟白下城。","谁堪万里外，尊酒动离旌。"]},{"t":"壬申夏生日途中作","f":"五言律诗","c":["此日还初度，葵榴照绮筵。","鲲鹏聊息翼，犬马渐增年。","贾傅书难上，终童策浪传。","平生四方志，览镜一茫然。"]},{"t":"寄题王中丞小袛园二首 其一","f":"五言律诗","c":["欲问西天乐，聊同北谷愚。","山围迦叶坐，水净法兰居。","藏室栖龙象，经文蚀蠹鱼。","慈航容并载，吾亦慕真如。"]},{"t":"寄题王中丞小袛园二首 其二","f":"五言律诗","c":["万古乾坤意，居然见草堂。","净心超大士，弹指谒空王。","永悟三生劫，时翻二酉藏。","何如浣花叟，白首杜陵庄。"]},{"t":"金山寺","f":"五言律诗","c":["绝顶开楼殿，中流见画图。","云霞千界合，宇宙一山孤。","远浪晴连蜀，奔潮夜到吴。","向来舟楫念，寂寞对江湖。"]},{"t":"钱塘秋望","f":"五言律诗","c":["郡国三秋迥，烟波四望开。","潮深吴相庙，山绕越王台。","远树天边没，孤帆日下来。","安期如可遇，指点向蓬莱。"]},{"t":"寄朱汝修兼讯李惟寅","f":"五言律诗","c":["不见朱生久，新篇近若何。","云山孤鹤在，江海断鸿多。","筑室移青桂，鸣琴掩绿萝。","李侯诗句好，骑马日相过。"]},{"t":"寄朱在明","f":"五言律诗","c":["独有金门客，频年隐未回。","扳花游汉殿，驻马上燕台。","梅福神仙吏，相如赋颂才。","五云空极目，何处是蓬莱。"]},{"t":"送人游燕中","f":"五言律诗","c":["乱山霜色里，行客迥添愁。","万里看黄鹄，孤心寄白鸥。","高风沙塞晚，明月海天秋。","莫以刘叉剑，狂歌对五侯。"]},{"t":"暮行桐庐道中","f":"五言律诗","c":["纳纳驱行旆，遥遥泛客槎。","万山藏鸟道，一水护渔家。","束峡天形小，奔崖地脉斜。","严陵矶畔月，蚤已著芦花。"]},{"t":"泊舟登钓台作","f":"五言律诗","c":["峡口抱云汀，中流坐放舲。","亭高双逼汉，台迥一窥星。","海气吞江白，山光压濑青。","纶竿千尺在，吾计渐沈冥。"]},{"t":"寄蔡侍御","f":"五言律诗","c":["宪节初临蜀，征轺旧出秦。","襜帷开气色，斧钺静风尘。","峡口云迎客，峨眉雪照人。","海棠花万树，夹路待西巡。"]},{"t":"送蒋祠部北上","f":"五言律诗","c":["岂意青云客，飘然过草堂。","龙门留问字，凤阁待含香。","万树长杨外，千花太液傍。","何人年弱冠，议礼动明堂。"]},{"t":"闻裕卿移居山中寄询","f":"五言律诗","c":["移家仍绝峤，秋色满垂藤。","磴袅云千尺，峰回月半棱。","龙湫寒独卧，雁宕晓频登。","我亦耽奇客，寻君愧未能。"]},{"t":"喻邦相迁守括苍寄贺二首 其一","f":"五言律诗","c":["袛缘香阁吏，领郡亦仙都。","重镇初移节，名山独剖符。","儿童迎彩鹢，父老认青凫。","不奈溪头别，桃花覆酒垆。"]},{"t":"喻邦相迁守括苍寄贺二首 其二","f":"五言律诗","c":["试县名方藉，专城宠骤加。","符分苍岭月，绶结赤城霞。","吏散朝行郭，官閒午放衙。","何如迁客泪，九载湿长沙。"]},{"t":"朱在明初至长沙诗以问之","f":"五言律诗","c":["浩渺银河色，孤槎起壮游。","乱山云梦泽，斜月武昌楼。","解佩湘娥去，鸣笳楚客愁。","尺书能远寄，回雁满高秋。"]},{"t":"闻蝉二首 其一","f":"五言律诗","c":["白雁将秋至，玄蝉入暮催。","清吟随落叶，密响度高槐。","暑觉帘栊断，凉俄枕簟回。","日长堪听汝，无拟抱琴来。"]},{"t":"闻蝉二首 其二","f":"五言律诗","c":["客醉秋山底，蝉吟白露时。","凄清流古木，断续倚高枝。","静逐凉飔转，低含夕照移。","枋榆吾自适，九万欲何之。"]},{"t":"秋日过王世周寓逢汪仲嘉潘景升赋赠","f":"五言律诗","c":["逍遥孤客邸，邂逅二豪吟。","面貌誇联璧，风期得断金。","琴书云阁迥，杖屦雪房深。","后夜芙蓉色，湖头次第寻。"]},{"t":"题野鹤孤云卷赠闫道人","f":"五言律诗","c":["科头无一事，松下日盘桓。","骨相堪鹏背，生年异鹖冠。","月轮天柱顶，云色洞庭干。","薄暮扬舲去，相携问大丹。"]},{"t":"秋日溪南晚眺适赵生携酒共酌村店中","f":"五言律诗","c":["行行随杖履，徙倚夕阳斜。","野寺明枫叶，山篱著豆花。","飞鸥过浅濑，浴鹭上浮查。","之子期方到，悠然问酒家。"]},{"t":"寄大司空朱公六首 其一","f":"五言律诗","c":["德望三朝旧，勋名八座馀。","庙堂周太保，剑履汉尚书。","翼矫丹霄凤，鳞潜碧海鱼。","惟应并南斗，万古照匡庐。"]},{"t":"寄大司空朱公六首 其二","f":"五言律诗","c":["赐履优前代，乘桴记昔年。","龙蛇驱大陆，蛟鳄奠长川。","宦绩昆崙外，神功碣石前。","试看淮渎庙，禹碣至今传。"]},{"t":"寄大司空朱公六首 其三","f":"五言律诗","c":["社稷忧仍在，中华问转频。","帝能优大老，史已传名臣。","紫气偏南极，青云自北辰。","无论汉宫远，玉树正嶙峋。"]},{"t":"寄大司空朱公六首 其四","f":"五言律诗","c":["里闬知司马，乾坤识卧龙。","为园名独乐，抱膝寄孤悰。","瀑布檐前水，香炉坐右峰。","大江西望处，愁绝暮云重。"]},{"t":"寄大司空朱公六首 其五","f":"五言律诗","c":["长日东林下，看花自闭关。","绿偏裴相野，青占谢公山。","啸傲藜床静，登临竹杖閒。","独馀忧国梦，时到紫宸班。"]},{"t":"寄大司空朱公六首 其六","f":"五言律诗","c":["尚忆风尘际，能高物色情。","吹嘘惭国士，吐握为儒生。","山水孤琴合，虹霓一剑鸣。","含珠十年梦，无路报投琼。"]},{"t":"王孙贞吉以手镌印章寄惠走笔奉谢","f":"五言律诗","c":["遥遥双玉佩，赠我意何勤。","石鼓周王篆，金泥汉帝文。","蛟螭寒压雾，科斗暗藏云。","万古岣嵝碣，何时一对君。"]},{"t":"雪夜邦相过斋中小集四首 其一","f":"五言律诗","c":["寂寞幽人卧，追寻茂宰贤。","飞觞临夜雪，把袂坐高天。","剡曲三更棹，梁台万古筵。","异时吾党事，兰水定谁传。"]},{"t":"雪夜邦相过斋中小集四首 其二","f":"五言律诗","c":["不谓山斋雪，能来侍从臣。","谈诗双郢客，和曲几巴人。","玉笛生春早，金尊促夜频。","晓来飞舄处，瑞气满枫宸。"]},{"t":"雪夜邦相过斋中小集四首 其三","f":"五言律诗","c":["彩笔寒相对，朱弦晚故留。","飞仙谁鹤氅，野客自鹴裘。","拥坐城云立，窥筵海月流。","预愁新赋出，人拟兔园游。"]},{"t":"雪夜邦相过斋中小集四首 其四","f":"五言律诗","c":["此夜平原醉，人间更有无。","乾坤悬玉阙，日月坐冰壶。","磊落新词社，萧条旧酒垆。","灞桥回首处，凄绝断云孤。"]},{"t":"与惟寅一别淹冉五载消息不复相闻春来忽得手书新刻见寄赋怀五首 其一","f":"五言律诗","c":["赐履传周室，分符卫汉京。","白虹悬结客，紫电照论兵。","四百西山寺，三千大内营。","几因飞檄暇，出郭遍题名。"]},{"t":"与惟寅一别淹冉五载消息不复相闻春来忽得手书新刻见寄赋怀五首 其二","f":"五言律诗","c":["带砺中朝望，诗书上将才。","佩刀初制阃，横槊自登台。","万骑长城合，孤鸿大漠回。","河梁人渐老，吟望独徘徊。"]},{"t":"与惟寅一别淹冉五载消息不复相闻春来忽得手书新刻见寄赋怀五首 其三","f":"五言律诗","c":["长啸青油幕，雄谈白氎巾。","射雕新骠骑，图象旧麒麟。","雪照梁园夜，风高瀚海晨。","遥遥双鲤下，犹忆尚玄人。"]},{"t":"与惟寅一别淹冉五载消息不复相闻春来忽得手书新刻见寄赋怀五首 其四","f":"五言律诗","c":["忆昔长安骑，相逢狭路间。","乾坤双彩笔，吾汝各红颜。","万感归来集，千秋病后閒。","惟应别时梦，绕夜向燕关。"]},{"t":"与惟寅一别淹冉五载消息不复相闻春来忽得手书新刻见寄赋怀五首 其五","f":"五言律诗","c":["一代华阳社，平生碣石游。","坐携鹓鹭侣，吟傍凤凰楼。","梦寐犹青眼，形容渐白头。","尺书聊写寄，涕泪尽南州。"]},{"t":"寄朱在明光禄","f":"五言律诗","c":["夙昔长安社，朱家兴独豪。","深杯传竹叶，艳曲度樱桃。","宦拙从鸡肋，身闲付蟹螯。","近来偏忆汝，愁望大江涛。"]},{"t":"寄丘谦之","f":"五言律诗","c":["底事丘灵鞠，年来复罢官。","惊心吾道左，落魄世途难。","月过衡峰近，星离益部寒。","九歌何日就，洒泣傍南冠。"]},{"t":"寄朱汝脩山人","f":"五言律诗","c":["掌露偏谁得，秋风各未苏。","骨仍沧海立，魂傍碧山孤。","白帢名先后，青囊术有无。","几时携竹杖，燕市问悬壶。"]},{"t":"再寄在明","f":"五言律诗","c":["见说休官后，乡园乐更饶。","屏开张静婉，坐列董娇娆。","紫电黄金勒，红霞白玉箫。","兴来应载酒，时醉广陵桥。"]},{"t":"膝汝载先生卜筑武夷邀余过访余以家慈卧床褥尚孤此约感念今昔不胜怅惘敬赋小诗奉寄凡八章 其一","f":"五言律诗","c":["北极声华久，东山气象新。","乍辞文苑秩，初乞武夷身。","辟地连三岛，看天卧七闽。","惟应幔亭月，时傍紫纶巾。"]},{"t":"膝汝载先生卜筑武夷邀余过访余以家慈卧床褥尚孤此约感念今昔不胜怅惘敬赋小诗奉寄凡八章 其二","f":"五言律诗","c":["九曲移家近，三山入望遥。","楼台临碧汉，户牖逼青霄。","坐叩梅仙诀，行逢木客谣。","袛疑尘世隔，无路问渔樵。"]},{"t":"膝汝载先生卜筑武夷邀余过访余以家慈卧床褥尚孤此约感念今昔不胜怅惘敬赋小诗奉寄凡八章 其三","f":"五言律诗","c":["游神近何所，三十六峰前。","鸟下谈经榻，猿窥问字船。","飞萝悬白日，古树拂苍烟。","彷佛秦人住，桃花隔涧泉。"]},{"t":"膝汝载先生卜筑武夷邀余过访余以家慈卧床褥尚孤此约感念今昔不胜怅惘敬赋小诗奉寄凡八章 其四","f":"五言律诗","c":["胜许庞公擅，名应善卷逃。","挂瓢沧海阔，倚杖碧山高。","万事留青鬓，孤忠藉彩毫。","无嗟塞翁意，天地一鸿毛。"]},{"t":"膝汝载先生卜筑武夷邀余过访余以家慈卧床褥尚孤此约感念今昔不胜怅惘敬赋小诗奉寄凡八章 其五","f":"五言律诗","c":["柳色吴天梦，梅花粤峤情。","吏才高汉代，儒术重周京。","雾泽南山豹，云寒北海鲸。","无言帝阍隔，咫尺是蓬瀛。"]},{"t":"膝汝载先生卜筑武夷邀余过访余以家慈卧床褥尚孤此约感念今昔不胜怅惘敬赋小诗奉寄凡八章 其六","f":"五言律诗","c":["黼黻真王佐，丝纶暂钓徒。","中天仪凤杳，大海蛰龙孤。","入梦犹金钥，翻歌自玉壶。","向来门下士，桃李遍三吴。"]},{"t":"膝汝载先生卜筑武夷邀余过访余以家慈卧床褥尚孤此约感念今昔不胜怅惘敬赋小诗奉寄凡八章 其七","f":"五言律诗","c":["作赋惭鹦鹉，空群辨鹔鹴。","千人摧稷下，一士擅襄阳。","色借青云迥，心悬白日长。","惟应梦中路，惚忽到沧浪。"]},{"t":"膝汝载先生卜筑武夷邀余过访余以家慈卧床褥尚孤此约感念今昔不胜怅惘敬赋小诗奉寄凡八章 其八","f":"五言律诗","c":["九折王阳道，千秋大隐庐。","云山容负笈，宇宙碍驱车。","业岂门人尽，名犹国士馀。","凭将一掬泪，遍洒越山隅。"]},{"t":"得安仲子书却寄","f":"五言律诗","c":["叹息延陵客，清才独后时。","三都全入赋，五岳半题诗。","壮节摧青鬓，雄心狎翠眉。","吴天花欲尽，好订白云期。"]},{"t":"怀祝鸣皋","f":"五言律诗","c":["南归书札断，北望旧游孤。","一铩悲鸾翮，三年问狗屠。","汝才宁巷陌，吾道实江湖。","几夜狂歌发，寒云碎玉壶。"]},{"t":"奉寄司成许公二首 其一","f":"五言律诗","c":["一代崇周学，诸生侍鲁儒。","田何惭受易，伏胜早传书。","八座飞腾外，三垣怅望馀。","犹思问奇日，大雪满庭除。"]},{"t":"奉寄司成许公二首 其二","f":"五言律诗","c":["载籍穷金马，论思坐玉堂。","洪钧回稷契，大典翊成康。","日近尚书履，霞明学士裳。","生徒愧原宪，十载梦长杨。"]},{"t":"上元观灯有怀京华旧游时集邦相署 其一","f":"五言律诗","c":["山城逢令节，灯火暂同游。","月映千花上，星从万树流。","遗簪连紫陌，委佩出朱楼。","不是金吾地，无妨彻夜留。"]},{"t":"上元观灯有怀京华旧游时集邦相署 其二","f":"五言律诗","c":["远忆长安道，华灯正陆离。","云霞千蜃结，山嶂六鳌移。","玉佩邀春早，铜壶听夜迟。","即今天禄畔，太乙傍谁嬉。"]},{"t":"周公瑕书来索余赠言为赋二首 其一","f":"五言律诗","c":["作赋元惊坐，临池更擅场。","真行王大令，篆隶蔡中郎。","巨榜高天揭，穷碑绝域藏。","太湖花满目，斟酌欠书航。"]},{"t":"周公瑕书来索余赠言为赋二首 其二","f":"五言律诗","c":["诗名人自老，墨妙世谁如。","瘗鹤高风在，笼鹅逸兴馀。","藜然中垒坐，花浣少陵居。","最忆长安日，垂髫问子虚。"]},{"t":"顾朗生山人以四诗见贻赋答 其一","f":"五言律诗","c":["万感红颜尽，孤踪白眼馀。","何堪梁苑客，遥寄茂陵书。","雪色晴偏照，星芒昼不除。","太湖蓑艇畔，谁共觅鲈鱼。"]},{"t":"顾朗生山人以四诗见贻赋答 其二","f":"五言律诗","c":["意气尘埃外，心期梦寐间。","一尊违白社，十口共青山。","桂树幽人赋，莲花国士颜。","倘怀天姥雪，拂石候柴关。"]},{"t":"顾朗生山人以四诗见贻赋答 其三","f":"五言律诗","c":["极目皋桥客，长歌扣玉壶。","天藏林屋远，云压洞庭孤。","卜筑仍三径，浮家任五湖。","试探吴市女，能识姓名无。"]},{"t":"顾朗生山人以四诗见贻赋答 其四","f":"五言律诗","c":["不谓菰芦畔，频年见伟人。","高天容荷锸，大海傍垂纶。","一壑心长恋，千秋业未贫。","异时双剑合，谁谓白头新。"]},{"t":"寄谢宗伯何公四首 其一","f":"五言律诗","c":["十载瞻台座，三春佐秩宗。","文章空左马，礼乐擅夔龙。","邺下才偏盛，河南誉日崇。","殷勤大玄草，犹记昔相从。"]},{"t":"寄谢宗伯何公四首 其二","f":"五言律诗","c":["灿烂遗编在，峥嵘大雅留。","黄河龙马出，紫阁凤凰游。","李薛年谁少，徐边誉岂俦。","不辞扳逸驾，世业在瀛洲。"]},{"t":"寄谢宗伯何公四首 其三","f":"五言律诗","c":["少日游金马，平生近玉宸。","中天回雨露，绝域望星辰。","咳唾千秋迥，吹嘘万象春。","惭无杜陵句，池上赞丝纶。"]},{"t":"寄谢宗伯何公四首 其四","f":"五言律诗","c":["尚忆梅花下，飞觞醉玉堂。","先春大庾月，达曙广陵霜。","鬓惜年来短，情偏别后长。","绨袍今古泪，寂寞洒沧浪。"]},{"t":"寒食夜集邦相署中分韵得吟字","f":"五言律诗","c":["荏苒逢佳节，招携见苦吟。","乾坤双剑色，湖海一麾心。","柳密陶公署，花閒宓子琴。","兰陵今夜月，百里为谁深。"]},{"t":"又得卮字","f":"五言律诗","c":["万古山城畔，风流见此时。","署元方朔隐，亭更子云奇。","片月窥帘下，疏星抱席移。","袛应双白眼，兀坐把深卮。"]},{"t":"题大司空潘公芝林二首 其一","f":"五言律诗","c":["烨烨钟灵草，青葱发涧阿。","九光呈玉叶，三秀挺瑶柯。","滴露滋苔藓，蒸云映薜萝。","蚤知王佐出，寝殿有兴歌。"]},{"t":"题大司空潘公芝林二首 其二","f":"五言律诗","c":["丹崖藏淑气，白日涌灵葩。","百本俱擎露，千林竞照霞。","瑶池仙母住，勾曲羽人誇。","宁似商山客，成功翌汉家。"]},{"t":"闻裕卿卧病有怀","f":"五言律诗","c":["茆屋何年借，柴扉尽日扃。","已无人和雪，谁问客为星。","病骨留东海，雄心付北溟。","暮云回首处，寂寂万山青。"]},{"t":"得何仁仲书","f":"五言律诗","c":["旧事燕台下，看花汝亦狂。","双鸿俄越峤，匹马竟潇湘。","赋就人千里，书来泪八行。","向来神女约，早晚到高唐。"]},{"t":"题元旦早朝卷","f":"五言律诗","c":["玉殿春风起，金门曙色通。","佩声千柳外，旗影万花中。","凤历颁群后，鹓行列上公。","阳春才一曲，拟献大明宫。"]},{"t":"题大阅卷","f":"五言律诗","c":["剑佩中天出，旌旂大漠开。","风传青海戍，雾捲白登台。","列阵卢龙动，翻营涿鹿回。","九边销燧色，横吹莫兴哀。"]},{"t":"秋夜诸子过集","f":"五言律诗","c":["岂是谈玄宅，偏令问字过。","客当莲社满，人比竹林多。","霁月流丹嶂，飞星度绛河。","毋悲秋夕永，散发向藤萝。"]},{"t":"寄刘子大金吾","f":"五言律诗","c":["玉禁康侯宠，金吾上将荣。","潜消三辅侠，坐偃百蛮兵。","夜月雕弓满，秋霄画戟明。","共誇游猎暇，时入建安盟。"]},{"t":"怀刘观察仲脩","f":"五言律诗","c":["几夜怀高适，当年赋上林。","高虹流击筑，朗月堕鸣琴。","客散谁燕社，人归自越吟。","西山暮楼殿，极目蓟云深。"]},{"t":"寄宫詹陈公二首 其一","f":"五言律诗","c":["执戟元中秘，鸣珂更上公。","云霞流紫殿，日月扈青宫。","磊落燕台骏，飘零越峤鸿。","台垣何处切，五夜望寒空。"]},{"t":"寄宫詹陈公二首 其二","f":"五言律诗","c":["建礼抠趋近，延英进读劳。","露漙金掌重，云敛玉绳高。","苑树萦朱绂，宫花落彩毫。","尚思燕市夕，浊酒坐持螯。"]},{"t":"哭康裕卿五首 其一","f":"五言律诗","c":["摇落龙蛇岁，天南坠客星。","寒灯孤月白，遗冢万山青。","永闭高人宅，谁题处士铭。","伤心旧朋辈，十载递凋零。"]},{"t":"哭康裕卿五首 其二","f":"五言律诗","c":["宿草孀妻奠，遗编稚子留。","山阳愁听笛，剡曲恨回舟。","九死还初服，三生记旧游。","踟蹰季札剑，日夜梦东瓯。"]},{"t":"哭康裕卿五首 其三","f":"五言律诗","c":["忽跨辽东鹤，谁瞻蓟北鸿。","云山藜杖在，天地草堂空。","陇树经时碧，原花著处红。","终令石门谷，千古号愚公。"]},{"t":"哭康裕卿五首 其四","f":"五言律诗","c":["漂泊南游日，峥嵘北上年。","狂名悬楚越，侠气动幽燕。","大雪行歌外，长虹击筑前。","向来携手客，老泪尽江天。"]},{"t":"哭康裕卿五首 其五","f":"五言律诗","c":["垂髫游洛邑，识面记燕城。","问赋惊文考，投诗谒正平。","大鹏犹宿契，老骥忽悲鸣。","地下梁鸿在，应酬碣石盟。"]},{"t":"秋日送人之彭城","f":"五言律诗","c":["柴门乔木下，送汝一含杯。","大泽秋声早，长河曙色开。","阴风韩信庙，紫雾汉王台。","后夜芒山气，谁寻吊古才。"]},{"t":"为邦相题蕉石图图","f":"五言律诗","c":["寒蕉依怪石，仙液贮铜瓶。","日夜孤根老，冬春片叶青。","风疑摇凤尾，雨欲化龙形。","恍对张勾曲，星冠坐草亭。"]},{"t":"王长公寄惠集序赋谢四首 其一","f":"五言律诗","c":["字字风霜色，缄题向草庐。","百年双涕泪，万古一吹嘘。","附骥名难尽，屠龙业未虚。","异时歌九辨，宁敢忘三闾。"]},{"t":"王长公寄惠集序赋谢四首 其二","f":"五言律诗","c":["漶灭书生刺，迢遥国士恩。","片言犹海峤，三赋已乾坤。","道岂中原丧，交宁异代论。","尚拚双鬓在，垂白子云门。"]},{"t":"王长公寄惠集序赋谢四首 其三","f":"五言律诗","c":["家学三王上，时名二李前。","江河趋大壑，日月并高天。","业已回长夜，名犹借少年。","代兴聊一钵，默默少林传。"]},{"t":"王长公寄惠集序赋谢四首 其四","f":"五言律诗","c":["刻鹄纷难辨，鸣蛩独见知。","左迁元命世，扬马快同时。","一字人堪老，千秋客自迟。","会携孤剑色，东海傍要离。"]},{"t":"送金大参入滇","f":"五言律诗","c":["除目下枫宸，飞旌动去尘。","共看金马客，遥问碧鸡神。","草色穷南服，花香梦北辰。","到时薇省宴，犹记六桥春。"]},{"t":"寄董太史二首 其一","f":"五言律诗","c":["作赋俱青鬓，携书共赤墀。","我怀三秀草，君夺万年枝。","鸾鹤甘泉殿，鱼龙太液池。","当年六桥柳，能记共含卮。"]},{"t":"寄董太史二首 其二","f":"五言律诗","c":["世事甘余拙，时才羡尔长。","读书同左史，执戟异东方。","雾拥金门色，天回玉陛香。","深惭潞河鲤，万里到沧浪。"]},{"t":"送人之黔中","f":"五言律诗","c":["匹马冲寒雾，孤城问瘴烟。","花深罗鬼地，箐密夜郎天。","野戍传诸葛，丛祠赛谪仙。","五溪相望处，白日坠飞鸢。"]},{"t":"送人游边","f":"五言律诗","c":["严冬武林驿，一骑问京华。","大野霜飘树，长城雪作花。","櫜鞬迎属国，剑佩逐轻车。","早夺天山地，铭功入汉家。"]},{"t":"题东皋园亭卷","f":"五言律诗","c":["近卜东皋墅，推窗面面山。","榻悬双树底，亭锁万花间。","白鹤回孤啸，苍龙问大还。","异时丛桂发，尊酒定同攀。"]},{"t":"送张山人楚游","f":"五言律诗","c":["岩穴凭谁问，飘然赋远游。","风高云梦笛，月满洞庭舟。","短刺携孤客，长裾狎五侯。","蛾眉亭下泊，饱看荻花秋。"]},{"t":"南屏逢沈李二生谈道因约余游天台口号戏赠（）","f":"五言律诗","c":["越国奇男子，吴中伟丈夫。","游心出蓬艾，把臂入菰芦。","龙虎蟠金鼎，鸳鸯语玉壶。","天台八万丈，指点向虚无。"]},{"t":"夜集李景颖出土瓜佐酒成赋二章 其一","f":"五言律诗","c":["司理耽奇甚，甘瓜荐味长。","飞霜匀玉质，重露浥琼浆。","碧荔唐宫重，丹桃汉殿祥。","何烦方朔盗，袍袖溢芬芳。"]},{"t":"夜集李景颖出土瓜佐酒成赋二章 其二 赠孙国梁","f":"五言律诗","c":["谈玄吾不厌，问字尔相寻。","兴逸飞流赋，情高漱石吟。","春郊联玉勒，夜阁拥瑶琴。","二仲翩翩在，何烦觅向禽。"]},{"t":"题性天真孝卷","f":"五言律诗","c":["焚香星月下，一脔冀亲延。","讵意挥刀日，才同扇枕年。","孤诚回大造，至性彻重泉。","莫以昌黎论，雌黄孺子贤。"]},{"t":"潘翁九秩诗为望之茂才作","f":"五言律诗","c":["玉醴汎蓬池，琼枝焕陆离。","玄纁迟伏胜，带索异荣期。","种橘盈千顷，栽花但一篱。","不知柯几烂，犹阅洞中棋。"]},{"t":"题中丞滕公武夷精舍图","f":"五言律诗","c":["精庐聊十尺，坐啸建溪湄。","暂挂中丞笏，閒挥太傅棋。","野花苍鹿献，林果白猿持。","惆怅流风逝，徒瞻大树遗。"]},{"t":"送李内翰入都","f":"五言律诗","c":["一骑冲寒发，梅花照客颜。","乱云扬子渡，残雪皖公山。","旧直青绫被，新恩白玉环。","夜来前席梦，光到紫宸班。"]},{"t":"寄李允达二首 其一","f":"五言律诗","c":["底事翩翩客，长怀落落愁。","骥心犹五夜，鸡肋已三秋。","犊敝相如裤，貂残季子裘。","长门售何日，少妇绕机愁。"]},{"t":"寄李允达二首 其二","f":"五言律诗","c":["失意真怜汝，沾衣向薜萝。","屠龙人未识，买骏客频过。","投笔徒为尔，焚舟竟若何。","千秋吾道在，异日较谁多。"]},{"t":"吴郡金公应照令吾邑凡后先六载清风卓操绝代无伦黉士慕其遗爱将举祀名宦不佞恭窃门下敬赋二章 其一","f":"五言律诗","c":["当年武城令，故国近三吴。","睿识悬冰鉴，清标瑩玉壶。","琴遗何处鹤，舄化异时凫。","磊落循良传，千秋更有无。"]},{"t":"吴郡金公应照令吾邑凡后先六载清风卓操绝代无伦黉士慕其遗爱将举祀名宦不佞恭窃门下敬赋二章 其二","f":"五言律诗","c":["素丝传苦节，彩笔擅瑶华。","彭泽门藏柳，河阳县带花。","云霄馀宦辙，江汉逝仙查。","寂寂谈玄者，空悲隔绛纱。"]},{"t":"夜宿黄季主对奕决赌金伯韶为点筹酣饮达曙题壁间","f":"五言律诗","c":["念汝能悬榻，令余忘忆家。","香凝燕邸雾，烛袅汉宫霞。","仄径眠孤鹤，虚檐集乱鸦。","今宵橘中卧，极乐在天涯。"]},{"t":"送僧还赤城","f":"五言律诗","c":["春游秦苑外，夏返越台傍。","片石幽期远，千峰别梦长。","危杉饥鹘堕，古柏病猿藏。","问讯寒山子，题诗遍佛堂。"]},{"t":"宿狄明叔园亭二首 其一","f":"五言律诗","c":["閒来种瓜墅，门巷半垂藤。","石室藏金匮，星台控玉绳。","茶招阳羡客，饭供雪山僧。","下榻余将卧，清宵话大乘。"]},{"t":"宿狄明叔园亭二首 其二","f":"五言律诗","c":["自是词人社，虚疑上将坛。","清香浮画戟，异味荐雕盘。","五色瓜萦砌，千株橘绕阑。","黄梁炊渐熟，饱饭话邯郸。"]},{"t":"再过狄明叔园","f":"五言律诗","c":["咫尺将军第，重来日未衙。","径添何氏竹，畦蔓邵侯瓜。","曲榭微生月，层楼半纳霞。","一枰堪度世，何地更吾家。"]},{"t":"送徐廉访之虔州","f":"五言律诗","c":["为羡虔州路，依然借寇行。","关西群吏送，岭北大僚迎。","日拥雕戈艳，霞飘画毂明。","五羊天咫尺，高眺粤王城。"]},{"t":"破山寺老衲夜谈作","f":"五言律诗","c":["一径入苍翠，飞云袅袅屯。","危亭标木末，古刹翳松根。","海月时窥牖，山风日扫门。","凭呼野衲至，信宿共芳樽。"]},{"t":"过张伯起幼于园中二君各出小影索余题即席赋二首 其一 伯起","f":"五言律诗","c":["乾坤长啸客，林壑自由身。","蚤辟东山墅，閒垂北海纶。","新声传子夜，丽管握阳春。","我亦思逃世，貂裘再敝秦。"]},{"t":"过张伯起幼于园中二君各出小影索余题即席赋二首 其二 幼于","f":"五言律诗","c":["何年醉玉京，谪籍下蓬瀛。","方外唐徵士，江东晋步兵。","鹖冠云气入，龙剑雪花明。","异日投竿去，毋令帝座惊。"]},{"t":"次瓜步张别驾留酌署中","f":"五言律诗","c":["栏杆明月下，萝薜暮纷纷。","翠杓调甘露，香厨供彩云。","含毫春半入，剪烛夜平分。","更喜朝来约，三山跨鹤群。"]},{"t":"秋日游大慈岩作","f":"五言律诗","c":["薄暮肩舆到，归樵处处逢。","万寻开峭壁，千级上危峰。","树杪禅关出，萝阴梵刹重。","何当专一壑，绝顶卧长松。"]},{"t":"姬人有从行岩上者蹻捷之甚戏赠此诗","f":"五言律诗","c":["偶逐天台客，桃花照玉颜。","绣裙时绾雾，罗袜惯登山。","岭月生眉黛，峰云动髻鬟。","不因刘阮至，那得共追攀。"]},{"t":"题祝无殊栖云轩","f":"五言律诗","c":["小筑兰阴下，幽居瀫水濆。","八窗全受月，一榻袛栖云。","竹杖占龙气，蒲团卧鹿群。","何人日携酒，相对草玄文。"]},{"t":"挽吴封翁四章 其一","f":"五言律诗","c":["阀阅崇三世，丝纶贲九重。","行高黄叔度，名重郭林宗。","茂苑新枫落，苏台宿草茸。","异时双庑下，谁问伯鸾舂。"]},{"t":"挽吴封翁四章 其二","f":"五言律诗","c":["高踪悬石户，古行郁泉台。","海月长鲸去，天风大鸟来。","河南传治行，邺下绍词才。","世泽今何限，无烦叹草莱。"]},{"t":"挽吴封翁四章 其三","f":"五言律诗","c":["剑色丰城閟，书香茂苑长。","题铭符季子，树碣副中郎。","阁翳新玄草，斋繁旧白杨。","明珠遗集远，光照玉涵堂。"]},{"t":"挽吴封翁四章 其四","f":"五言律诗","c":["绿野承先世，苍生付象贤。","恩波填越海，涕泪咽吴天。","薤露丹旌外，松风素旐前。","袛应门下客，长废蓼莪篇。"]},{"t":"送僧游越东","f":"五言律诗","c":["穷年持戒律，行脚遍蒿莱。","碧海浮杯度，青山蹑屩来。","天台方广寺，雪窦妙高台。","匣底兰亭帖，相传自辩才。"]},{"t":"刘广文擢北司马诗送之","f":"五言律诗","c":["汉殿移官入，燕台谒帝行。","敦诗元郤縠，议礼旧荀卿。","海国朝霞丽，江城霁雪明。","题书频寄忆，翘首北鸿征。"]},{"t":"越岭瞻乔卷为易使君仲子题","f":"五言律诗","c":["公子旧翩翩，宁亲羡汝贤。","瞻乔离楚服，怀橘向吴天。","柯烂青霞斧，帆飞赤壁船。","太行他日望，重赋白云篇。"]}]};